-- Quest chronicle data (french). GENERATED by quests/build_q_lua.py from quests/text/*.json: edit those.
-- Installed as override/M_PSXQD.lua; read by M_PSXQ.lua.
PSXQ_DATA = {
[16202] = { g = [[bg2]], k = [[side]], o = 0, c = [[any]], w = [[Aucun (texte de journal résiduel)]], h = { [[Il s'agit du texte d'aide du journal, pas d'une vraie quête.]], [[La tâche du saphir étoilé pour Belt est une ancienne ligne de tutoriel que le jeu ne vous demande jamais d'accomplir.]] }, s = [[Rien à faire. La première entrée explique seulement les quatre sections du journal : quêtes en cours, quêtes accomplies, histoire et vos propres notes.
La seconde ligne (retrouver le saphir étoilé pour Belt) est un reste de tutoriel sans quête correspondante dans ce jeu. Vous pouvez l'ignorer.]] },
[66122] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde]], h = { [[Frère Odren, des Chevaliers Vigilants, cherche des héros assez forts pour resceller une ancienne prison.]], [[Au sommet de la tour, Frère Pol fournit le symbole sacré et le rituel ; Garlena vend du matériel.]], [[L'Emprisonné est Démogorgon, et Odren comptait vous laisser enfermé avec lui.]] }, s = [[Frère Odren vous aborde et vous demande d'entrer dans la Tour de Garde pour réparer les sceaux de son prisonnier. Si vous êtes trop faible, il vous dit de revenir plus tard.
Acceptez. À la tour, Odren vous montre l'entrée ; prenez le symbole sacré et le rituel auprès de Frère Pol, et achetez du matériel à Garlena.
Descendez niveau par niveau (voir les autres entrées de la Tour de Garde) et ouvrez le dernier sceau.
L'Emprisonné est Démogorgon. Au choix : le tuer (le combat le plus dur de la tour) ; accomplir le rituel pour le resceller et le tromper pour qu'il vous laisse sortir ; ou accepter de le libérer en faisant croire à Odren qu'il est mort.
Si Odren entre, un chevalier fantôme offre un parchemin de Helm pour sceller la prison à jamais.
Ensuite, confrontez Odren : pardonnez-lui ou punissez les Vigilants.]] },
[74295] = { g = [[bg2]], k = [[main]], o = 32, c = [[1-7]], w = [[Athkatla, Brynnlaw, Ombre-Terre, Suldanessellar]], h = { [[Évadez-vous du donjon d'Irenicus, puis réunissez de l'argent à Athkatla pour acheter de l'aide afin de retrouver Imoen.]], [[Choisissez un protecteur : les Voleurs de l'Ombre de Gaelan Bayle ou la vampire Bodhi ; tous deux réclament une grosse somme.]], [[Une fois à Brynnlaw, entrez dans l'asile, évadez-vous, traversez l'Ombre-Terre et reprenez la Rhynn Lanthorn à Bodhi.]] }, s = [[Chapitre 1 : libérez-vous dans le donjon d'Irenicus, récupérez du matériel et sortez par les niveaux supérieurs.
Chapitre 2 : Gaelan Bayle, dans les bas quartiers, demande 20 000 pièces d'or. Faites des quêtes secondaires (la Couronne de Cuivre est un bon début). Valen propose l'offre concurrente de Bodhi dans le quartier du cimetière.
Chapitre 3 : payez l'un des deux camps et accomplissez ses missions : pour Aran Linvail, gardez la cargaison avec Mook, voyez le recruteur aux Cinq Chopes, puis nettoyez l'antre des vampires ; pour Bodhi, interceptez la cargaison, compromettez Vulova, sauvez Palern Flynn et tuez Aran Linvail.
Chapitre 4 : à Brynnlaw, entrez dans l'asile (voir Accéder à l'asile), puis évadez-vous.
Chapitre 5 : en Ombre-Terre, aidez Goldander, faites-vous déguiser par Adalon et récupérez ses œufs à Ust Natha.
Chapitre 6 : tuez Bodhi dans son antre pour obtenir la Rhynn Lanthorn et apportez-la à Elhan.
Chapitre 7 : sauvez Suldanessellar, convoquez l'avatar de Rillifane, libérez Ellésime et vainquez Irenicus à l'Arbre de Vie, puis en enfer. Les entrées de Throne of Bhaal (Saradush, Yaga-Shura, Balthazar, Mélissanne) prolongent l'histoire.]] },
[74318] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartier des quais]], h = { [[Yoshimo est un voleur indépendant, et la guilde locale veut lui parler.]], [[Renal Scalpesang attend dans un bâtiment du quartier des quais.]], [[Emmenez Yoshimo voir Renal et laissez-les discuter.]] }, s = [[L'entrée apparaît la première fois que vous entrez dans le quartier des quais avec Yoshimo dans le groupe.
Trouvez Renal Scalpesang, chef local des Voleurs de l'Ombre, dans son bâtiment du quartier des quais, avec Yoshimo dans le groupe.
Parlez-lui : Yoshimo règle sa situation de voleur indépendant et l'affaire est close. C'est aussi Renal qui propose plus tard aux voleurs leur propre guilde.]] },
[74319] = { g = [[bg2]], k = [[main]], o = 34, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[C'est une remarque d'Imoen liée à l'histoire, pas une tâche à accomplir tout de suite.]], [[Suivez l'intrigue principale : la réponse viendra bien plus tard, d'Irenicus lui-même.]] }, s = [[Dans le donjon du début, Imoen vous apprend que votre geôlier prétend savoir comment libérer votre pouvoir d'enfant de Bhaal.
Aucune action n'est liée à cette entrée. Elle annonce l'intrigue principale : les expériences d'Irenicus et ce qu'il vous fait subir, à Imoen et à vous, à Brisesort au chapitre 4. Poursuivez simplement la quête principale.]] },
[74320] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, bas quartiers et quartier du gouvernement]], h = { [[Jaheira a proposé trois pistes : le tavernier de la Couronne de Cuivre, le bâtiment du gouvernement et les quartiers les plus pauvres.]], [[Bernard peut vous dire ce qu'est devenu son ami Belgrade, ce qui mène à l'est des bas quartiers.]], [[Tuez le Baron Ployer, prenez la mèche de cheveux de Jaheira qu'il porte, puis reposez-vous.]] }, s = [[Si Jaheira est dans le groupe, le Baron Ployer l'aborde et lui lance une malédiction qui l'affaiblit peu à peu.
Facultatif : allez au bâtiment du gouvernement, dans le quartier du gouvernement. Corneil ne vous aide pas, mais à la sortie, Terrece propose contre un pot-de-vin que les mages de Ployer l'abandonnent, voire se retournent contre lui.
À la Couronne de Cuivre, interrogez Bernard sur Belgrade : il a été tué par la même malédiction, à l'est des bas quartiers.
Trouvez la maison de Ployer dans ce secteur et tuez-le. Sans pot-de-vin, ses mages lui viendront en aide.
Prenez la mèche de cheveux sur son corps et reposez-vous : la malédiction est levée.
Si vous refusez d'aider, Jaheira quitte le groupe.]] },
[74321] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du temple et égouts]], h = { [[Écoutez le prêtre aveugle qui prêche dans le quartier du temple, puis acceptez l'offre d'un temple pour enquêter.]], [[Le temple du culte se trouve sous la ville, accessible par les égouts ; son dieu est un tyrannœil aveugle.]], [[Réunissez les deux moitiés de l'ancien sceptre et utilisez-le une fois contre le tyrannœil, comme le conseille l'avatar.]] }, s = [[Dans le quartier du temple, assistez au sermon du prêtre aveugle. Un clerc de Talos, de Helm ou de Lathandre vous invite alors à son temple ; acceptez la mission (Nallabir, Oisig ou l'Aubemestre Arval).
Entrez dans le temple du culte par les égouts sous le quartier du temple. Parlez à Gaal : pour être admis, vous devez rapporter un sceptre du donjon inférieur ; il vous donne une clef. Vous pouvez aussi attaquer directement, ce qui fait apparaître le tyrannœil.
Faites votre rapport à votre temple, puis revenez.
En bas, rencontrez les gardiens oubliés et l'avatar de leur dieu : prenez sa moitié du sceptre.
Sassar explique comment atteindre la chambre au trésor du tyrannœil ; son ami Tad indique la descente par la Fosse aux Infidèles (attention aux charognards).
Prenez l'autre moitié, assemblez le sceptre et utilisez-le contre le tyrannœil. Rendez le sceptre à l'avatar, puis revenez au temple pour votre récompense.]] },
[74322] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du gouvernement]], h = { [[Après la chute du culte, votre temple veut les services du sculpteur Sire Sarles, logé à la propriété des Jysstev.]], [[Sarles exige de l'illithium pur ; demandez à la marchande de minerais Jerlia, sur la Promenade de Waukyne, qui la fournit.]], [[Le vrai minerai a été volé par le gnome Neb, caché dans la maison abandonnée du quartier du pont.]] }, s = [[Votre contact au temple (le Talon Yarryl, Telwyn ou l'Aubemestre Sain) vous demande d'engager Sire Sarles.
Rencontrez Sarles à la propriété des Jysstev, au sud-est du quartier du gouvernement : il veut 200 livres d'illithium.
Parlez à Jerlia à son étal, au sud-ouest de la Promenade de Waukyne. Elle peut fabriquer un alliage bon marché (200 po, prêt en un jour), mais Sarles décèle presque toujours la supercherie.
Pour le vrai minerai, voyez son fournisseur, le duergar Kalher Sombremont, à la Couronne de Cuivre. Il vous envoie chez Neb, dans la maison abandonnée du quartier du pont. Neb est un tueur dangereux : combattez-le et prenez l'illithium.
Donnez-le à Sarles, puis faites votre rapport au temple pour la récompense.]] },
[74323] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines d'Umar, Imnesvale]], h = { [[Un Mage Cagoulé nommé Jermien construit un golem pour le village d'Imnesvale.]], [[Les mimiques sont des monstres qui se font passer pour des coffres ; c'est leur sang qu'il lui faut.]], [[Cette demande n'a qu'une entrée de journal et n'a peut-être aucune suite dans le jeu.]] }, s = [[Jermien, un Mage Cagoulé, demande du sang de mimique pour le golem géant qu'il construit à Imnesvale.
Le journal ne contient aucune autre entrée pour cette quête ; il s'agit sans doute d'un contenu inachevé : il n'existe peut-être aucun moyen de remettre le sang ni de la clore.
Si vous croisez une mimique en route, gardez ce qu'elle laisse et essayez de reparler à Jermien.]] },
[74324] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartiers du cimetière et du temple]], h = { [[Korgan veut le Livre de Kaza, caché dans une ancienne tombe sous le quartier du cimetière.]], [[Le livre a disparu ; filez chez le collectionneur Pimlico, dans le quartier du temple.]], [[Les anciens compagnons de Korgan font la fête sur le toit de la Couronne de Cuivre.]] }, s = [[Recrutez Korgan Hachesanglante (Couronne de Cuivre) et acceptez son contrat pour le collectionneur Pimlico.
Dans le quartier du cimetière, trouvez la crypte qui mène à une tombe plus ancienne. Traversez les morts-vivants : le livre a déjà disparu.
Allez chez Pimlico, dans le quartier du temple : il a été tué par les anciens compagnons de Korgan.
Montez sur le toit de la Couronne de Cuivre, dans les bas quartiers, et affrontez Fourretouffe et ses amis. Tuez-les tous avant qu'ils ne s'enfuient.
Gardez ou vendez le livre : l'or est pour vous. S'ils s'échappent, la quête échoue.]] },
[74325] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, bas quartiers]], h = { [[Après l'affaire du sculpteur, retournez voir votre contact au temple pour une nouvelle mission.]], [[Un voleur nommé Travin, dans les bas quartiers la nuit, sait où se trouve l'Anneau de l'Aube volé.]], [[Le receleur Borinall détient l'anneau, dans une maison de briques rouges au-dessus de la Couronne de Cuivre.]] }, s = [[Retournez voir votre contact (Yarryl, Telwyn ou Sain). Le temple de Helm vous envoie chez l'Aubemestre Sain, au temple de Lathandre.
Allez de nuit dans les bas quartiers et rencontrez Travin. Les talassiens veulent l'Anneau de l'Aube volé ; Helm et Lathandre veulent le récupérer.
Travin vous indique la maison de briques rouges au toit d'ardoises rouges, au-dessus de la Couronne de Cuivre sur la carte. Réglez le cas de Borinall, par la parole ou la force, et prenez l'anneau.
Apportez-le à votre temple (Talos le garde, Helm et Lathandre le rendent au temple de Lathandre) pour la récompense.]] },
[74326] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines d'Umar et ruines du temple]], h = { [[Delon, à Athkatla, cherche de l'aide ; rendez-vous à Imnesvale et parlez au maire, Lloyd.]], [[Les ogres de Madulf ne sont pas coupables ; la cabane de la rôdeuse Merella, à l'ouest du village, recèle les vrais indices.]], [[Le Seigneur des ombres se cache dans le temple en ruines d'Amaunator, à l'est, gardé par un dragon d'ombre.]] }, s = [[Delon (quartier du gouvernement) vous envoie dans les Collines d'Umar. À Imnesvale, parlez au maire Lloyd, au nord-est de la place.
Allez voir Madulf au nord du village, près de la rivière : discutez au lieu de combattre ; il est innocent et vous oriente vers la cabane de Merella (sud-ouest de la carte).
Dans la cabane, lisez le journal de Merella et le message de Mazzy. Tout près, le loup-garou Anath vous parle du Seigneur des ombres ; épargnez-le ou tuez-le.
Partez à l'est vers les ruines du temple. À l'intérieur, résolvez les énigmes des rituels de la statue pour obtenir un symbole d'Amaunator (il en faut trois pour la dernière porte). Aidez les deux fantômes en rapportant les os d'Amuana : elle vous donne une pierre-sésame qui vous cache du dragon d'ombre ; gardez-la et n'attaquez pas le dragon.
Libérez Mazzy de sa cage (elle peut se joindre à vous). Une ombre des cellules a caché une clef dans la sienne.
Tuez le Seigneur des ombres, qui occupe le corps de Merella, et détruisez son autel. Retournez voir Lloyd pour la récompense.]] },
[74327] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines d'Umar, Imnesvale]], h = { [[L'ogre Madulf, campé au nord d'Imnesvale, préfère parler que se battre.]], [[Il propose de protéger le village des orques en échange de la paix et d'un peu de commerce.]], [[Transmettez son offre au maire Lloyd, à Imnesvale.]] }, s = [[Pendant l'enquête des Collines d'Umar, rencontrez Madulf et sa bande au nord d'Imnesvale, près de la rivière. N'attaquez pas : les siens meurent aussi.
Acceptez de transmettre sa proposition : sa bande protégera le village contre les orques des collines si les villageois les laissent en paix et commercent avec eux.
Prévenez le maire Lloyd : il accepte de parler à l'ogre. Plus tard, si vous êtes le rôdeur-protecteur du village, Madulf tient parole lors de l'attaque des orques.]] },
[74328] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, égouts sous le quartier du temple]], h = { [[Un homme confus nommé Quallo, dans les égouts, parle d'une lame prisonnière et d'indices cachés.]], [[Trois objets vont dans trois tuyaux : la main de Vallah, un anneau pris aux squelettes et le bâton d'un chaman kobold.]], [[Ordre : la main d'abord, l'anneau ensuite, le bâton en dernier ; une erreur fait tout recommencer.]] }, s = [[Dans les égouts sous le quartier du temple, parlez à Quallo : il évoque une épée retenue par des sceaux et des indices près des écoulements.
Récupérez les trois objets dans les égouts : l'anneau des squelettes, la main de Vallah et le bâton du chaman kobold. Interrogez Quallo sur chacun.
Placez-les dans les tuyaux dans cet ordre : la main (la souffrance d'abord), puis l'anneau (ni premier ni troisième), puis le bâton (il scelle le marché). Une erreur oblige à recommencer.
Les sceaux se brisent et vous obtenez l'épée magique prisonnière.]] },
[74329] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines d'Umar, Imnesvale]], h = { [[Trois garçons désœuvrés d'Imnesvale veulent que vous leur achetiez des épées et de la bière.]], [[Le marchand Min Minling vend ce qu'ils demandent.]], [[Quoi que vous achetiez, vous recroiserez les garçons plus tard dans les collines.]] }, s = [[À Imnesvale, trois jeunes vous donnent de l'argent pour acheter trois épées bâtardes et de la bière de Baalor.
Achetez-les (ou seulement la bière, ou seulement les épées) chez Min Minling et remettez-les. Vous pouvez aussi refuser et leur rendre ou garder leur argent.
Plus tard dans les Collines d'Umar, vous les revoyez : ivres dans une grotte s'ils n'ont eu que la bière, poursuivis par un grouilleux s'ils ont eu les deux, ou presque tués par une créature de l'ombre s'ils ont eu les épées. Une petite quête surtout humoristique.]] },
[74330] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[Collines d'Umar]], h = { [[Les rôdeurs qui sauvent les Collines d'Umar se voient offrir la cabane de Merella et sa charge.]], [[Répondez vite aux appels de Delon et de l'esprit de la forêt Mairyn, sinon vous perdez le poste.]], [[Dernière menace : une sorcière se faisant appeler Umar, dans le donjon vidé du Portail de l'Ombre.]] }, s = [[Bastion du rôdeur. Après la mort du Seigneur des ombres, le maire Lloyd vous confie la cabane de Merella, à l'ouest d'Imnesvale. Reposez-vous-y entre les événements.
Mairyn vous demande d'empêcher des humains d'abattre sa forêt à l'ouest, près de l'ancien autel de l'Ombre. Le Seigneur Igen suspend ses travaux si vous trouvez la cache de mithral de son ancêtre : cherchez l'autre moitié du journal, sans doute dans le vieux donjon, et rapportez-lui ce que vous trouvez.
Delon annonce une attaque d'orques : rejoignez Imnesvale en moins de trois jours et repoussez-les. Madulf aide si son pacte tient ; délivrez-le dans une grotte voisine.
Plus tard, la fausse Umar menace le village depuis le donjon du Portail de l'Ombre : voyez le maire, entrez et tuez-la.
Mairyn vous offre un cadeau de Mielikki. Refuser ou arriver trop tard vous fait perdre la cabane.]] },
[74331] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[Château des de'Arnise]], h = { [[Un guerrier qui libère le château des de'Arnise peut le gouverner pour la famille de Nalia.]], [[Touchez vos revenus auprès du majordome et répondez à chaque messager en moins d'une semaine.]], [[Les Roenal finissent par attaquer en force : revenez à temps et vainquez le Seigneur Farthington.]] }, s = [[Bastion du guerrier. Une fois le château repris, Nalia vous confie ses terres ; le majordome les gère et vous garde environ 500 po par semaine. Augmenter les impôts mécontente le peuple.
Des messagers vous rappellent plusieurs fois ; revenez chaque fois en une semaine environ et parlez au majordome :
- Le Seigneur Farthington Roenal vient faire valoir ses prétentions.
- Une inondation ravage les terres : réglez les problèmes équitablement.
- Les troupes des Roenal marchent sur le château : organisez la défense et combattez. Tuer le Seigneur Farthington met fin à la menace.
Arriver trop tard ou perdre la bataille livre le château aux Roenal, et vous êtes banni.]] },
[74332] = { g = [[bg2]], k = [[main]], o = 42, c = [[2]], w = [[N'importe où (rêve au repos)]], h = { [[C'est une entrée de rêve, rien à faire pour l'instant.]], [[L'intrigue principale y répond, quand vous retrouverez enfin Irenicus.]] }, s = [[En vous reposant au chapitre 2, vous rêvez d'Imoen qui perd son identité et d'Irenicus qui vous promet du pouvoir si vous voyez au-delà de la douleur.
Aucune action n'est requise. Continuez à réunir l'argent pour votre protecteur et suivez la quête principale ; le rêve annonce ce qu'Irenicus fera à Brisesort.]] },
[74333] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Promenade de Waukyne]], h = { [[Quayle, l'ancien mentor d'Aerie, la fait appeler.]], [[Il se trouve sous le chapiteau de la Promenade de Waukyne.]] }, s = [[Si Aerie est dans le groupe, elle reçoit un message de Quayle qui demande de l'aide.
Allez au chapiteau de la Promenade de Waukyne avec Aerie et parlez à Quayle. Il transmet en général la demande d'une vieille amie, Raelis Shai, qui mène au théâtre sous les Cinq Chopes (voir Une amie de Quayle a besoin d'aide).]] },
[74334] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du pont]], h = { [[Une femme nommée Raelis Shai a besoin d'aide et a écrit à Quayle.]], [[Elle dirige le théâtre situé sous la taverne des Cinq Chopes, dans le quartier du pont.]] }, s = [[Quayle (ou, s'il est mort, Aerie grâce à sa lettre) vous oriente vers Raelis Shai.
Allez aux Cinq Chopes, dans le quartier du pont, et descendez au théâtre dans la cave. Parlez à Raelis : elle vous demande de délivrer son comédien Haer'Dalis du magicien Mekrath (voir Libérer Haer'Dalis des griffes de Mekrath).]] },
[74335] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du gouvernement]], h = { [[L'ancien groupe de Korgan avait une offre de travail en suspens d'un certain Madeen.]], [[Madeen se tient devant le bâtiment du Conseil, dans le quartier du gouvernement.]] }, s = [[Après l'affaire du Livre de Kaza, Korgan parle d'un travail proposé à son ancien groupe.
Emmenez Korgan au quartier du gouvernement et parlez à Madeen devant le bâtiment du Conseil pour entendre son offre.
Le journal ne contient aucune autre entrée pour cette quête ; son issue se limite peut-être à cette conversation avec Madeen.]] },
[74336] = { g = [[bg2]], k = [[main]], o = 46, c = [[4]], w = [[Brynnlaw]], h = { [[Commencez à la taverne du Singe Vulgaire et cherchez Sanik, qui fournissait l'asile.]], [[Après le meurtre de Sanik, renseignez-vous sur sa fiancée Claire, retenue dans la guilde des courtisanes de Dame Galvena.]], [[La piste de Claire ouvre deux voies : la pierre-sésame de Perth l'adepte, ou convaincre le Seigneur pirate Desharik de votre folie.]] }, s = [[Saemon Havarian vous dépose à Brynnlaw (côté Voleurs de l'Ombre : battez d'abord l'embuscade de vampires ; Sime vous aide).
Au Singe Vulgaire, parlez à Sanik ; un assassin de Dame Galvena le tue. Le barman vous parle de Claire.
Entrez dans la guilde des courtisanes, à l'ouest : engagez une courtisane, prenez le médaillon de maître à Chremy (qui surveille une certaine Ginia), ou entrez de force. À l'intérieur, faites droguer les gardes par la cuisinière, tuez Galvena et son sorcier, prenez sa clef et libérez Claire au bout du couloir.
Claire (ou le capitaine Golin, ou Saemon sur son bateau) révèle les deux façons d'entrer :
- Desharik, au nord-ouest de la ville : jouez la folie ; un bon Charisme ou Minsc aide. Hésiter fait échouer.
- Perth l'adepte : il est sous domination et attaque ; prenez sa pierre-sésame.
Montez ensuite par le col jusqu'à Brisesort, attention aux pièges et aux gardiens.]] },
[74337] = { g = [[bg2]], k = [[main]], o = 60, c = [[6]], w = [[Athkatla, quartier du cimetière (antre de Bodhi)]], h = { [[Elhan dit que Bodhi détient la Rhynn Lanthorn dans son antre, sous le quartier du cimetière.]], [[Si Bodhi a enlevé l'être aimé, le remède se trouve dans un livre que le temple d'Oghma a acheté à Imnesvale.]], [[Portez la victime et le cœur du maître vampire à la statue aux bras tendus du temple des Collines d'Umar.]] }, s = [[Chapitre 6 : Elhan vous donne de l'eau bénite et vous envoie à l'antre de Bodhi, dans le quartier du cimetière. Préparez-vous contre les morts-vivants (une protection contre l'absorption de niveau aide).
Près de l'antre, Bodhi vous tend une embuscade ; si vous vivez une romance, elle enlève l'être aimé (Aerie, Jaheira, Viconia ou Anomen) et en fait un vampire.
Dans l'antre, utilisez l'eau bénite d'Elhan là où Bodhi puise son pouvoir, puis vainquez-la avec ses vampires. Détruisez-la définitivement pour obtenir la Rhynn Lanthorn et son cœur. Imoen retrouve son âme.
Pour sauver l'être aimé : le conseiller de guerre elfe vous envoie au temple d'Oghma ; son responsable parle du libraire d'Imnesvale et du Vampiricus Omnibus. Allez ensuite au temple des ombres des Collines d'Umar, traversez le sol en forme de marelle et placez l'être aimé avec le cœur de Bodhi dans les bras de la statue d'Amaunator.
Rapportez la Lanthorn à Elhan.]] },
[74338] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, bas quartiers (sphère planaire)]], h = { [[L'étrange sphère des bas quartiers ne s'ouvre que pour un Corthala : il vous faut Valygar.]], [[À l'intérieur, les Chevaliers Solamniques prisonniers vous avertissent des dangers de chaque aile.]], [[Pour repartir, tuez Lavok, puis apportez un cœur de démon au grand golem qui alimente la sphère.]] }, s = [[Amenez Valygar (cabane des Collines d'Umar) à la sphère planaire des bas quartiers ; son sang l'ouvre.
À l'intérieur, rencontrez les trois Chevaliers Solamniques : Onvo signale la chambre d'un mage avec un golem endommagé, Reyna des créatures semblables à des petites-personnes à l'ouest, Ancan une salle marine au nord.
Facultatif : réparez le golem endommagé ; il part combattre le tyrannœil.
Atteignez Lavok et vainquez-le. Mourant, il redevient lui-même et explique que la sphère dérive entre les plans.
Sortez, tuez le démon qui s'y trouve et prenez son cœur, puis placez-le dans le grand golem ; Lavok règle le retour.
De retour à Athkatla, un protagoniste mage peut garder la sphère comme bastion.]] },
[74339] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla / Collines d'Umar]], h = { [[Le Mage Cagoulé Tolgerias veut qu'on lui livre le rôdeur Valygar Corthala.]], [[Il attend un cadavre, pas des indications.]], [[Prendre le parti de Valygar lui permet de vous rejoindre et mène à la sphère planaire.]] }, s = [[Tolgerias vous engage pour trouver Valygar, qui vit dans une cabane des Collines d'Umar.
Options :
- Tuer Valygar et rapporter son corps à Tolgerias : vous obtenez la récompense et quelques informations.
- Indiquer seulement à Tolgerias où se trouve Valygar : selon le cas, il vous paie et part le capturer, ou refuse et s'en va furieux, et les Mages Cagoulés risquent de vous en vouloir.
- Mieux : parlez à Valygar, apprenez la vérité sur la sphère et laissez-le vous rejoindre ; Tolgerias se retourne alors contre vous plus tard.]] },
[74340] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Cité des sahuagins]], h = { [[Capturé par les sahuagins, vous êtes salué comme un élu ; remportez le duel judiciaire du roi.]], [[La Grande Prêtresse Senityili soutient en secret le prince rebelle Villynaty ; la Dent de Sekolah ouvre le camp rebelle au sud.]], [[Aidez Villynaty avec un faux cœur, ou apportez son vrai cœur au Roi Ixilthetocal.]] }, s = [[Si vous quittez Brisesort par le bateau de Saemon, les sahuagins vous emmènent dans leur cité au chapitre 5. Vous pouvez tout refuser et vous frayer un chemin par les armes.
Rencontrez la Grande Prêtresse Senityili, puis le Roi Ixilthetocal. Acceptez le duel et tuez son monstre.
Le roi veut le cœur du chef rebelle. Senityili vous donne un orbe pour que les rebelles vous mènent au Prince Villynaty ; la Dent de Sekolah (dans un coffre gardé par un tyrannœil, au sud) ouvre les portes des rebelles.
Voie bienveillante : acceptez le plan de Villynaty, donnez un faux cœur au roi et attendez l'attaque des rebelles. Villynaty devient roi ; prenez la clef du trésor sur Ixilthetocal pour votre récompense.
Autre voie : tuez Villynaty et donnez son cœur au roi contre de l'or.
Dans les deux cas, on vous indique le chemin de l'Ombre-Terre.]] },
[74341] = { g = [[bg2]], k = [[main]], o = 62, c = [[7]], w = [[Suldanessellar, Arbre de Vie]], h = { [[Une image projetée d'Ellésime vous parle à l'Arbre de Vie.]], [[Les noisettes du jardin du palais font pousser des branches jusqu'aux trois parasites du tronc.]], [[Tuez les trois parasites, puis foncez au centre pendant qu'Irenicus est affaibli.]] }, s = [[Une fois le chemin dégagé par l'avatar de Rillifane, montez dans l'Arbre de Vie et parlez à l'image d'Ellésime.
Prenez des noisettes au jardin du palais et utilisez-les aux endroits indiqués pour faire pousser des branches jusqu'à chaque parasite qui draine l'Arbre. Tuez-les tous les trois, rapidement.
Ellésime est libérée et coupe Irenicus de l'Arbre. Rejoignez vite la plateforme centrale et affrontez Irenicus tant qu'il est désorienté. Reposez-vous et préparez vos protections avant le dernier parasite.]] },
[74342] = { g = [[bg2]], k = [[main]], o = 64, c = [[7]], w = [[Enfer]], h = { [[Chaque porte de cet enfer cache une épreuve de caractère et une Larme de Bhaal.]], [[Parlez au démon de chaque épreuve ; c'est votre choix qui compte, pas votre force.]], [[Avec toutes les larmes, la grande porte s'ouvre sur Irenicus ; les bons choix rapportent de meilleures récompenses.]] }, s = [[Après la mort d'Irenicus, vous êtes entraîné dans un enfer soumis à votre sang de Bhaal. Réunissez les Larmes de Bhaal derrière chaque porte, puis ouvrez la grande porte.
Épreuves (le démon explique chacune) :
- Altruisme : un chemin vous blesse, l'autre un innocent ou un compagnon. Prendre la douleur pour vous est le bon choix.
- Cupidité : un démon vous donne Rasoir Noir ; donnez-le au génie pour le libérer, ou tuez le génie.
- Peur : acceptez ou refusez la cape en peau de nymphe ; refuser est le choix courageux.
- Orgueil : questionnez le démon ; la créature peut vous céder la larme sans combat.
- Colère : Sarevok propose de vous apprendre la forme d'Écorcheur ; acceptez, ou refusez et combattez-le.
Chaque choix donne un bonus permanent qui dépend de sa sagesse. Enfin, vainquez Irenicus et ses démons derrière la grande porte.]] },
[74343] = { g = [[bg2]], k = [[main]], o = 49, c = [[4]], w = [[Brisesort]], h = { [[Dans le labyrinthe sous l'asile, la porte de sortie exige la main du créateur et le foyer du pouvoir.]], [[Dace Sontan est le créateur ; le cristal gît dans un tas d'ordures vénéré par des kobolds.]], [[En haut, libérez les mages internés pour attaquer Irenicus, puis partez sur le bateau de Saemon ou par le portail du sous-sol.]] }, s = [[Après le rituel d'Irenicus, Bodhi vous abandonne dans le labyrinthe sous Brisesort.
Résolvez les salles du labyrinthe ; un arbitre vous juge en chemin. Trouvez Dace Sontan : prenez sa main (la main du créateur), puis récupérez le cristal dans le tas d'ordures des kobolds. Utilisez les deux sur la porte de sortie.
Bodhi attaque avant votre départ ; vous vous transformez pour la première fois en Écorcheur et elle s'enfuit.
Saemon réapparaît et conseille de faire des internés une armée. Libérez-les ; ils attaquent Irenicus, qui s'échappe.
Choisissez ensuite : le bateau de Saemon vers le Téthyr (mène à la cité des sahuagins), ou la clef des appartements d'Irenicus, près de l'entrée de l'asile, pour le portail du sous-sol (Ombre-Terre).]] },
[74344] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, repaire de Mekrath (par les égouts)]], h = { [[Raelis Shai, au théâtre sous les Cinq Chopes, veut retrouver son comédien Haer'Dalis.]], [[Le magicien Mekrath le retient ; on atteint son repaire par les égouts.]], [[Mekrath échange Haer'Dalis contre un service, ou vous le prenez de force ; trouvez ensuite la gemme.]] }, s = [[Acceptez la mission de Raelis au théâtre sous les Cinq Chopes (quartier du pont).
Rejoignez le repaire de Mekrath par les égouts. Rendez-lui service (récupérer son miroir chez le diablotin, voir la quête liée) et il vous cède Haer'Dalis, ou combattez Mekrath.
Haer'Dalis se trouve dans la réserve nord de la tour. Parlez-lui : il retourne seul au théâtre ou rejoint votre groupe.
Fouillez le repaire de Mekrath pour trouver la gemme d'Haer'Dalis et apportez-la à Raelis pour une récompense. La lui remettre lance la quête de la prison planaire.]] },
[74345] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, égouts]], h = { [[Le diablotin de Mekrath s'est enfui dans les égouts avec son miroir.]], [[Il a peut-être invoqué quelque chose grâce à lui ; venez préparé.]], [[Rapportez le miroir et Mekrath vous offre son esclave en récompense.]] }, s = [[Dans son repaire, Mekrath vous demande de récupérer le miroir volé par son diablotin.
Fouillez les égouts voisins pour trouver le diablotin et ce qu'il a fait venir par le miroir, combattez-les et prenez le miroir.
Rapportez-le à Mekrath : il vous offre un esclave qui attend dans la réserve nord de sa tour ; c'est Haer'Dalis. Si vous combattez Mekrath ensuite, vous trouvez toujours Haer'Dalis au même endroit après sa mort.]] },
[74346] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, repaire de Mekrath / quartier du pont]], h = { [[Haer'Dalis a laissé une gemme précieuse quelque part dans le repaire de Mekrath.]], [[Fouillez soigneusement les pièces du magicien une fois Haer'Dalis libéré.]], [[Apportez la gemme à Raelis Shai, au théâtre sous les Cinq Chopes.]] }, s = [[Une fois Haer'Dalis libéré de Mekrath, il vous demande de retrouver sa gemme dans le repaire du magicien.
Fouillez la tour et les pièces de Mekrath jusqu'à la trouver (Haer'Dalis le confirme s'il est dans le groupe).
Allez au théâtre sous la taverne des Cinq Chopes, dans le quartier du pont, et remettez-la à Raelis Shai pour votre récompense. Elle s'en sert ensuite pour ouvrir ses portails, ce qui lance la quête de la prison planaire.]] },
[74347] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Prison planaire]], h = { [[Suivez les chasseurs de primes par le portail resté ouvert dans le théâtre.]], [[Le gnome évadé Tagget connaît la prison ; certaines marques au sol téléportent vers des salles de gardes.]], [[Détruisez l'orbe du Maître des Esclaves dans le brasero magique, puis affrontez le gardien.]] }, s = [[Quand vous remettez la gemme à Raelis, des chasseurs de primes arrêtent la troupe et l'emmènent par un portail. Suivez-les.
Dans la prison, battez les chasseurs de primes et parlez au gnome Tagget : il n'y a pas de sortie physique, il faut abattre le gardien. Méfiez-vous des marques de téléportation en allant droit au nord.
Suivez la route de Tagget vers l'est : trouvez le Maître des Esclaves. Son esclave nain vous conseille de brûler l'orbe dans le brasero magique d'une salle déjà traversée.
Détruisez l'orbe pour libérer les esclaves à collier, puis tuez le gardien dans la salle des cellules, au nord de votre arrivée.
Raelis ouvre un conduit pour rentrer. Haer'Dalis peut ensuite vous rejoindre.]] },
[74348] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartier des quais (Cercle des Ménestrels)]], h = { [[Une Ménestrelle nommée Meronia emmène Jaheira ; elle revient avec une convocation pour vous aussi.]], [[Rendez-vous au Cercle des Ménestrels, dans le quartier des quais, avec Jaheira.]], [[Galvarey veut vous emprisonner ; préparez-vous à un rude combat contre les Ménestrels.]] }, s = [[Si Jaheira est dans le groupe, Meronia la prend à part ; elle revient en disant que vous êtes tous deux convoqués au Cercle des Ménestrels, dans le quartier des quais.
Allez-y vite (Jaheira peut vous y attendre). Parlez à Galvarey : il veut enfermer l'enfant de Bhaal pour servir sa propre carrière.
Un combat éclate contre Galvarey et les mages Ménestrels. Selon ses sentiments, Jaheira se bat à vos côtés et rompt avec les Ménestrels, ou s'enfuit.
Fouillez ensuite le Cercle. Son histoire se poursuit plus tard avec les suites de cette affaire.]] },
[74349] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartiers du gouvernement et du pont]], h = { [[La sœur d'Anomen a été assassinée ; accompagnez-le chez son père, dans le quartier du gouvernement.]], [[Le seigneur Cor accuse le marchand Saerk ; vous pouvez conseiller la vengeance ou la loi.]], [[La magistrate Bylanna Ianulin, au bâtiment du gouvernement, s'occupe de la voie légale.]] }, s = [[Anomen apprend la mort de sa sœur Moira. Accompagnez-le chez le seigneur Cor, dans le quartier du gouvernement (si vous refusez, il part).
Cor réclame vengeance contre Saerk. Votre conseil décide de l'avenir d'Anomen :
- La loi : allez voir la magistrate Bylanna Ianulin au bâtiment du gouvernement. Si la justice ne peut rien, vous pouvez encore conseiller la vengeance. Rester patient donne à Anomen la chance de devenir un vrai chevalier de l'Ordre.
- La vengeance : allez au manoir de Saerk, au centre du quartier du pont. Anomen tue la fille de Saerk ; combattez Saerk et ses gardes (Yusef s'enfuit). Annoncez au seigneur Cor que c'est fait. Anomen devient amer et s'écarte de la voie de l'Ordre.]] },
[74350] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Cité des sahuagins, zone au sud]], h = { [[Un tyrannœil amical garde un coffre qui contient la Dent de Sekolah.]], [[Il garde le coffre, pas son contenu.]], [[Un orateur sage peut le convaincre de vous laisser l'ouvrir ; sinon, il faut combattre.]] }, s = [[Pendant La prophétie de Sekolah, Senityili vous envoie au sud de la cité des sahuagins chercher la Dent de Sekolah.
Le coffre est surveillé par un tyrannœil paisible. Parlez-lui avec votre personnage le plus sage en tête : faites-lui remarquer qu'il garde le coffre, pas son contenu.
S'il est convaincu, il vous laisse prendre la Dent et s'en va ravi. Sinon, vous devez le tuer pour ouvrir le coffre. La Dent ouvre les portes du camp rebelle.]] },
[74351] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2]], w = [[Château des de'Arnise]], h = { [[Nalia, à la Couronne de Cuivre, implore votre aide : trolls et yuan-tis occupent le château de sa famille.]], [[Entrez par la porte secrète derrière un buisson au nord de la palissade, et trouvez le serviteur Daleson.]], [[Réunissez les trois têtes de l'ancien fléau, tuez les trolls par le feu ou l'acide, et trouvez TorGal dans les caves.]] }, s = [[Rencontrez Nalia à la Couronne de Cuivre et rendez-vous au château qu'elle marque sur votre carte.
À la palissade, le capitaine Arat vous demande d'abaisser le pont-levis : le mécanisme est sur le mur au-dessus du pont. Entrez par la porte secrète derrière un buisson, au nord de la palissade.
Trouvez Daleson : il parle des trolls, des yuan-tis, des bêtes attirées par le civet de chien et des têtes du fléau du seigneur de'Arnise.
Le feu ou l'acide achève les trolls à terre. Libérez du charme le garde du corps Glaicus : il donne une tête du fléau et indique un panneau secret derrière l'armurerie. Sauvez Dame Delcia (à l'étage ; sa chambre cache le passage du donjon).
Assemblez le fléau, descendez aux caves et tuez TorGal.
Faites votre rapport à la palissade. Un guerrier peut ensuite gouverner le château.]] },
[74352] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[Bosquet des druides près de Franc-Marché]], h = { [[Un druide qui se repose dans le bosquet près de Franc-Marché reçoit la visite de son esprit.]], [[Première tâche : tuer la chamane troll Nilthiri dans le tertre troll voisin.]], [[Revenez dans les deux semaines ; ensuite, protégez le jeune Loren parmi les tentes hors de Franc-Marché.]] }, s = [[Bastion du druide, une fois réglés les troubles des druides de Franc-Marché. Reposez-vous dans le bosquet des druides et l'esprit du bosquet apparaît.
Acceptez son appel (refuser met fin à la quête).
Allez au tertre troll, à l'intérieur du bosquet, et tuez la chamane Nilthiri ; prévoyez feu ou acide.
Revenez en deux semaines environ et reposez-vous de nouveau au bosquet.
L'esprit vous envoie protéger Loren, descendant de Marek, parmi les tentes hors des murs de Franc-Marché. Détruisez la créature qui le possède.
Loren part se former au bosquet ; on ne vous rappellera que lorsque vous serez prêt à briguer le titre d'archidruide.]] },
[74353] = { g = [[bg2]], k = [[main]], o = 63, c = [[7]], w = [[Suldanessellar / Enfer]], h = { [[Elhan révèle enfin la vérité sur le passé d'Irenicus et de Bodhi.]], [[Sauvez Suldanessellar et arrêtez Irenicus à l'Arbre de Vie.]], [[Ensuite, en enfer, réunissez les Larmes de Bhaal et affrontez Irenicus une dernière fois.]] }, s = [[Résumé du dernier chapitre (le titre anglais parle du chapitre dix-neuf, le titre français du chapitre sept).
1re partie : apportez la Rhynn Lanthorn à Elhan ; il explique qu'Irenicus et Bodhi étaient des elfes bannis pour leur crime. Entrez dans Suldanessellar, trouvez Demin, réunissez le talisman de Rillifane, la lame de lune et la coupe d'or, et posez-les sur l'autel du temple pour convoquer l'avatar de Rillifane. Libérez Ellésime et vainquez Irenicus à l'Arbre de Vie.
2e partie : en enfer, passez les épreuves pour réunir les Larmes de Bhaal, ouvrez la grande porte et vainquez Irenicus pour reprendre votre âme.]] },
[74354] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[Athkatla, quartier du pont (théâtre des Cinq Chopes)]], h = { [[Un barde qui a sauvé la troupe de Raelis reçoit le théâtre sous les Cinq Chopes.]], [[Engagez le metteur en scène Higgold, financez la pièce et répondez à chaque appel que Meck vous apporte.]], [[Des choix judicieux en chemin, et remplacer Zaren le soir de la première, font de la pièce un succès.]] }, s = [[Bastion du barde. Après la prison planaire, Raelis vous cède le titre du théâtre. Samuel Éructonnerre vous envoie le metteur en scène Higgold.
Acceptez de monter une pièce et revenez au bout d'une semaine environ avec de l'argent à investir. Higgold choisit Le Fléau de l'Ensorceleur, réputé maudit.
Choisissez l'actrice principale : Jenna est facile, Iltheia est meilleure mais capricieuse.
Pendant les six à sept semaines de répétitions, Meck vient vous chercher pour divers problèmes : un acteur difficile, la musique, des phénomènes étranges liés à la malédiction, des barbares qui envahissent la scène. Allez-y chaque fois et réglez-les.
Assistez à la générale, puis à la première : Zaren ne peut pas jouer, prenez son rôle. Refuser ruine la pièce.
En cas de succès, gardez le théâtre pour un revenu régulier à récupérer auprès de Higgold, ou vendez-le-lui pour 10 000 pièces d'or.]] },
[74355] = { g = [[bg2]], k = [[main]], o = 56, c = [[5]], w = [[Ombre-Terre, Ust Natha]], h = { [[Rapportez à la Matriarche Ardulace le sang d'une race ancienne, puis répondez à la convocation de Phaere.]], [[Phaere veut échanger les vrais œufs de dragon contre des faux ; Solaufein, si vous l'avez épargné, vous en donne de meilleurs.]], [[Arrêtez le rituel, tuez Ardulace pour lever le sceau de la ville, puis fuyez vite avec les œufs d'Adalon.]] }, s = [[Ardulace demande le sang d'un orbe ancien (tunnels des tyrannœils), d'un géancéphale (cité des illithides) ou d'un prince kuo-toa (ruines à l'ouest), en trois jours. Rapportez-en un.
Elle scelle la ville pour son rituel. Phaere révèle alors le projet de sacrifier les œufs d'Adalon à un démon et vous ordonne de les échanger contre ses faux dans le trésor des Despana, au temple de Lolth.
Si vous avez épargné Solaufein, il vous donne une seconde série de faux œufs parfaits.
Options : donnez les faux à Phaere et gardez les vrais ; ou dénoncez Phaere à Ardulace. Le diablotin d'Adalon explique que le rituel doit échouer et qu'Ardulace doit mourir.
Au rituel, combattez : tuez Ardulace (et Phaere). Le sceau se lève et il vous reste quelques minutes avant la fin de votre déguisement : courez vers la sortie et rendez les œufs à Adalon.
Choix maléfique : donnez les œufs au démon contre une arme ou une escorte vers la sortie.]] },
[74356] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du gouvernement / quartier des quais]], h = { [[Quelqu'un dans le quartier du gouvernement sait comment Isaéa abuse de son grade.]], [[Les sales affaires d'Isaéa laissent des traces : un ivrogne sur les quais, un esclavagiste et sa propre maison.]], [[Réunissez assez de preuves, puis apportez-les toutes au commandant Corgeig, dans le bâtiment du gouvernement.]] }, s = [[Isaéa Roenal se sert de son poste dans l'armée pour faire arrêter Nalia, et personne ne sait où elle est détenue.
Dans le quartier du gouvernement, parlez au soldat Khellor : il vous donne le nom de Barg, un contact sur les quais, et vous indique la maison d'Isaéa au nord-ouest du bâtiment du gouvernement.
Dans le quartier des quais, faites parler Barg : il cite l'esclavagiste Dirth, à la Bonté Marine. Dirth vous attaque ; prenez le livre de transactions sur son corps.
Fouillez la maison d'Isaéa pour trouver ses registres.
Apportez le tout à Corgeig dans le bâtiment du gouvernement. Sans assez de preuves il vous renvoie ; avec tout, il libère Nalia et ouvre une enquête sur Isaéa.]] },
[74357] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines de Lancevent, donjon de Firkraag]], h = { [[La chasseuse de reliques du donjon de Firkraag tient beaucoup à vous laisser prendre tous les risques.]], [[Préparez-vous au combat quand vous rapportez à Samia ce qu'elle demande.]], [[Samia et ses compagnons attaquent dès que vous revenez avec les textes de la chambre funéraire.]] }, s = [[Dans le donjon de Firkraag, dans les Collines de Lancevent, Samia vous demande de rapporter des textes sur un roi téthyrien mort, depuis sa chambre funéraire, et vous donne sa clef.
La chambre est gardée par une créature invisible : prévoyez de quoi voir ou dissiper l'invisibilité.
Prenez les textes et retournez voir Samia. Elle dévoile son plan : laisser un naïf faire le travail, puis le tuer et garder le butin. Elle et ses compagnons attaquent.
Battez-les pour clore cette entrée. Les textes et le butin de la tombe vous restent.]] },
[74358] = { g = [[bg2]], k = [[main]], o = 40, c = [[2-3]], w = [[Athkatla, quartier du cimetière / quartier des quais]], h = { [[Bodhi, dans les cryptes sous le quartier du cimetière, vous confie des missions contre les Voleurs de l'Ombre.]], [[Il y a une cargaison gardée sur les quais, puis un sauvetage ou un meurtre, puis le Maître des Ombres en personne.]], [[Gaelan Bayle a la clef du repaire d'Aran, et Tizzak, à l'intérieur, explique les deux portes magiques.]] }, s = [[Rangez-vous du côté de Bodhi, dans les cryptes du quartier du cimetière. Les Voleurs de l'Ombre deviennent hostiles.
1. Quartier des quais : tuez les Voleurs de l'Ombre qui gardent une cargaison, prenez la caisse et rapportez-la à Bodhi.
2. Deuxième tâche, selon votre voie : sauver Palern Flynn vivant, au deuxième étage du quartier général des Voleurs de l'Ombre, ou tuer le marchand Vulova (quartier du gouvernement, entre la prison et le bâtiment du gouvernement) et laisser la cape et la dague de Bodhi dans sa fontaine. Laisser fuir Vulova ou échouer ici n'a pas d'importance.
3. Prenez la clef chez Gaelan Bayle, puis passez la porte secrète à droite de l'entrée du quartier général. Libérez Tizzak : appuyez sur le bouton au bout du couloir piégé au nord, prenez la seconde clef sur le magicien Haz, et tuez Aran Linvail.
Retournez voir Bodhi : elle a payé votre passage vers l'asile où Imoen est détenue.]] },
[74359] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, bas quartiers, sphère planaire]], h = { [[Le nécromancien Lavok est le maître de la sphère planaire des bas quartiers.]], [[Ramenez la sphère dans votre plan, et Lavok demandera une dernière faveur avant de mourir.]], [[Choisissez entre porter Lavok mourant à l'extérieur ou le laisser mourir dans la sphère.]] }, s = [[Entrez dans la sphère planaire des bas quartiers (avec Valygar, ou avec ce qui ouvre sa porte) et progressez jusqu'à affronter Lavok et ramener la sphère dans le plan d'Athkatla.
Le vieux nécromancien est mourant. Vous pouvez exaucer son souhait et l'emmener dehors pour qu'il meure sous son ciel natal, ou refuser et le laisser mourir à l'intérieur pour qu'il ne nuise à personne.
Si le protagoniste est un mage, Lavok vous lègue la sphère : elle devient votre forteresse, avec ses propres quêtes ensuite.
Dans tous les cas, la quête se termine avec la mort de Lavok.]] },
[74360] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines de Lancevent, donjon de Firkraag]], h = { [[L'enfant de Garren a été enlevé par les hommes de Firkraag ; cherchez un repaire caché dans les Collines de Lancevent.]], [[L'enfant est dans une cellule à serrure magique ; un mage du donjon en a la clef.]], [[Inutile d'affronter Firkraag : libérez l'enfant, puis retournez à la cabane de Garren.]] }, s = [[Après que Garren a prouvé votre innocence auprès de l'Ordre du Cœur Radieux, il découvre que son enfant a été enlevé.
Explorez les Collines de Lancevent pour trouver le donjon de Firkraag ; un orque à l'intérieur parle de Firkraag, signe que vous êtes sur la bonne piste. Vous pouvez aussi y croiser la chasseuse de reliques Samia, qui vous envoie dans une tombe (un piège, voir son entrée).
Trouvez l'enfant dans une cellule à serrure magique. Tuez le mage voisin qui porte la clef, ouvrez la cellule et l'enfant rentre chez lui.
Retournez à la cabane de Garren pour votre récompense. Firkraag est un combat facultatif et très dangereux contre un dragon rouge.]] },
[74361] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines d'Umar, Imnesvale]], h = { [[Un fermier d'Imnesvale aime bavarder sur ses voisins, les Hendrick.]], [[Les Hendrick ont caché le trésor de leur défunte fille dans un endroit inattendu de leur ferme.]], [[Un des poulets des Hendrick a avalé une gemme : achetez-la au fermier, ou prenez-la.]] }, s = [[À Imnesvale, parlez au fermier Jeb. Il soupçonne les Hendrick, des paysans réfugiés au village, d'avoir fait avaler quelque chose de précieux à un de leurs poulets ; leur fille aventurière l'avait rapporté avant de mourir.
Parlez au fermier Hendrick et proposez de lui acheter l'objet caché : à un prix honnête, vous obtenez une gemme beljuril et un fermier reconnaissant.
Vous pouvez aussi récupérer la gemme en vous occupant vous-même du poulet, ce qui est moins aimable.]] },
[74362] = { g = [[bg2]], k = [[main]], o = 54, c = [[5]], w = [[Ombreterre, Ust Natha]], h = { [[Sous l'apparence de Veldrin, présentez-vous à Solaufein à la société des Combattants et ne faites jamais attendre les drows.]], [[Chaque tâche vient de Phaere : retrouvez-la avec Solaufein là où elle le dit, dans le délai donné.]], [[Plusieurs tâches ont une issue sans massacre : la patrouille svirfneblin et Solaufein peuvent être convaincus de vous aider.]] }, s = [[Faites vite : tout retard éveille les soupçons et rend la cité hostile.
1. Retrouvez Solaufein à la société des Combattants (au nord, après la société des Combattantes). Rejoignez-le avec la vestale Imrae à l'entrée de la ville.
2. Sauvez Phaere des illithides, en retrouvant Solaufein près de leur cité au sud-est de la caverne principale. Revenez à l'entrée, puis voyez Phaere à la taverne.
3. Tuez la patrouille svirfneblin près de leur village, ou allez voir les gnomes et obtenez le heaume du chef sans combat. Apportez le heaume à Phaere à la taverne.
4. Tuez le tyrannœil contrebandier d'adamantite sur la plateforme de son navire spelljammer avec Phaere et Solaufein ; ne les blessez pas.
5. Retrouvez Phaere au temple de Lolth pour voir la matriarche Ardulace, puis dans ses quartiers de la tour de la société des Combattantes. Elle veut la mort de Solaufein : tuez-le dans ses quartiers ou convainquez-le de vous donner son piwafwi, et rapportez-le.]] },
[74363] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines de Lancevent]], h = { [[Le seigneur Jierdan Firkraag paie bien pour chasser les ogres de ses terres, dans les Collines de Lancevent.]], [[Les ogres ne sont pas ce qu'ils semblent être, et quelqu'un est témoin de la scène.]], [[Acceptez l'abri que Garren Lancevent vous offre dans sa cabane, au sud de l'embuscade.]] }, s = [[Le seigneur Jierdan Firkraag vous aborde et vous offre 10 000 pièces d'or pour tuer les bandits ogres de ses terres, dans les Collines de Lancevent.
Rendez-vous sur place. Les ogres sont des paladins de l'Ordre du Cœur Radieux sous illusion, et ils vous voient vous aussi comme des ogres ; le combat est inévitable.
Garren Lancevent en est témoin et vous offre l'abri de sa cabane, un peu au sud. Acceptez, ou revenez plus tard.
À la cabane, Garren explique que Firkraag a tout manigancé, et qu'il l'a ruiné lui aussi. Il part pour Athkatla clamer votre innocence. La suite est le sauvetage de son enfant.]] },
[74364] = { g = [[bg2]], k = [[main]], o = 61, c = [[6]], w = [[Suldanessellar]], h = { [[Cherchez la Grande Prêtresse Demin au sud-ouest de la cité elfique.]], [[Trois reliques volées au temple de Rillifane doivent retourner sur sa statue ; les monstres les plus forts les portent.]], [[La coupe, le talisman et la lame de lune sont répartis entre les envahisseurs, dont le dragon noir au nord-ouest.]] }, s = [[Le Rhynn Lanthorn révèle Suldanessellar, assiégée par les créatures d'Irenicus. Elhan reste à l'entrée.
Un elfe dit avoir vu Demin se battre au sud-ouest : trouvez-la dans un bâtiment de ce quartier. Irenicus a scellé le palais avec la reine Ellésime à l'intérieur.
Acceptez son plan : reprenez la coupe, le talisman et la lame de lune aux monstres les plus puissants de la cité, dont le dragon noir au nord-ouest, hors de la ville. Demin confirme quand vous les avez.
Placez les trois reliques sur la statue de Rillifane dans son temple. L'avatar de Rillifane Rallathil réveille les gardiens de la forêt et brise le sceau.
Entrez dans le palais ; il vous faudra la Harpe et le Cor de Pierre pour le traverser.]] },
[74365] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines d'Umar, Imnesvale]], h = { [[Tous les ogres des Collines d'Umar ne sont pas vos ennemis.]], [[Madulf et ses compagnons déserteurs préféreraient vivre en paix près du village.]], [[Parlez à Madulf au lieu de combattre, puis portez son offre au maire d'Imnesvale.]] }, s = [[Dans les Collines d'Umar, parlez à l'ogre Madulf au lieu de l'attaquer, lui et sa bande de déserteurs.
Acceptez de les aider à s'entendre avec Imnesvale, puis parlez au maire Lloyd au village.
L'accord : les déserteurs protègent le village et on les laisse en paix, avec peut-être un peu de commerce de temps en temps. Les tuer à la place supprime cette issue.]] },
[74366] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Promenade de Waukyne / quartier du gouvernement]], h = { [[Voyagez avec Cernd : un vieil ami a des nouvelles de la femme qu'il a quittée.]], [[Fennecia, l'ancienne servante de Cernd, sait ce qui s'est passé, mais parle mieux sans lui.]], [[L'enfant vit chez le noble Deril, dans la demeure la plus au sud du quartier du gouvernement.]] }, s = [[Avec Cernd dans le groupe, Igarol lui apprend que la femme qu'il a abandonnée était enceinte, et l'envoie à son ancienne maison de la Promenade de Waukyne.
Dans la maison, un mendiant dit que la servante Fennecia travaille maintenant comme nourrice chez elle ; sa maison est sur votre carte.
Fennecia dit seulement que Galia est morte tant que Cernd est là : parlez-lui seul. Galia s'est installée avec le noble Deril et est morte dans d'étranges circonstances ; le bébé est resté chez Deril, la demeure la plus au sud du quartier du gouvernement.
Allez-y et aidez Cernd à affronter Deril. Si vous refusez, cela tourne mal avec Cernd.
Cernd nomme l'enfant Ahsdale et l'emmène au bosquet des druides ; revenez un jour ou deux plus tard pour reprendre Cernd.]] },
[74367] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartier des quais / Collines d'Umar]], h = { [[Tolgerias, des Mages Cagoulés, veut Valygar Corthala ; commencez par sa maison du quartier des quais.]], [[Son serviteur Hervo, son amie Suna Seni et un employé du bâtiment du gouvernement parlent tous de terres familiales.]], [[Valygar se cache dans une cabane des Collines d'Umar ; écoutez-le avant de choisir qui aider.]] }, s = [[Tolgerias, au bâtiment du gouvernement, vous demande de ramener Valygar mort ou vif. Refuser fâche les Mages Cagoulés.
Dans la maison de Valygar, quartier des quais, Hervo vous laisse fouiller et parle des terres de la famille dans les Collines d'Umar et de son amie Suna Seni. Le clerc Llarsh confirme ces terres et relie Valygar à Lavok et à la sphère planaire des bas quartiers.
Trouvez Valygar dans sa cabane des Collines d'Umar. Il explique que les mages ont besoin de son sang pour ouvrir la sphère, où Lavok attend de voler le corps d'un descendant.
Choix : le recruter et entrer ensemble dans la sphère (voie bonne) ; le laisser partir (on le retrouve ensuite par Hervo) ; ou le tuer et apporter son corps à Tolgerias.
Mentir à Tolgerias échoue. Dans tous les cas, attendez-vous à ce que Tolgerias se retourne contre vous près de la sphère.]] },
[74368] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Franc-Marché]], h = { [[Après la cérémonie de Franc-Marché, deux nobles rivaux tentent chacun de vous engager.]], [[Les deux veulent le Manteau de Waukyne, dans une tombe hantée de la ville, pour prouver leur rang.]], [[Le Seigneur Logan vous demande le bandeau au nom de la paix ; le lui donner est l'issue la plus douce.]] }, s = [[Une fois les problèmes de Franc-Marché réglés, le Seigneur Logan Coprith organise une cérémonie. Dame Lilith Lurraxol et le seigneur Skarmaen Alibakkar viennent chacun vous voir ; rendez visite à l'un d'eux dans son domaine.
Votre employeur vous donne la clef de la tombe et vous prévient qu'elle est hantée. Le Seigneur Logan vous demande de lui apporter le Manteau de Waukyne à la place.
Nettoyez la tombe et prenez le bandeau en or. Issues :
Le donner à Logan : récompense moindre, les deux familles fâchées, mais la paix préservée.
Travailler pour une famille : vous êtes récompensé pour avoir tué le chef de l'autre, et Logan est mécontent.
Si les deux familles finissent par se battre contre vous et entre elles, tous meurent ; Logan ne vous en veut pas.]] },
[74369] = { g = [[bg2]], k = [[main]], o = 55, c = [[5]], w = [[Ombreterre, Ust Natha]], h = { [[Un dragon d'argent garde le chemin de la surface, mais elle ne peut rien faire tant que les drows ont ses œufs.]], [[Adalon vous donne l'apparence du drow Veldrin pour fouiller Ust Natha.]], [[Gagnez peu à peu la confiance des drows jusqu'à pouvoir prendre les œufs, puis rapportez-les à Adalon.]] }, s = [[Dans l'Ombreterre, rejoignez Adalon, le dragon d'argent. Irenicus et Bodhi lui ont volé ses œufs et les ont donnés aux drows.
Elle vous donne l'apparence d'un drow nommé Veldrin et vous envoie à Ust Natha. Jouez le jeu des tâches drows (voir la quête d'Ust Natha) sans vous faire démasquer, jusqu'à mettre la main sur les œufs.
Rapportez les œufs à Adalon : elle vous offre un objet de son trésor et vous ramène à la surface.
Si la cité se retourne contre vous, Adalon ne peut plus vous aider et il ne reste qu'un combat difficile. Détruire les œufs ou attaquer Adalon fait d'elle une ennemie, et il faut trouver une autre sortie.]] },
[74370] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla]], h = { [[Une foule d'Athkatla s'apprête à brûler quelqu'un sur un bûcher.]], [[La victime est une prêtresse drow dont vous vous souvenez peut-être, de la Côte des Épées.]], [[Faites fuir ou tuez les fanatiques autour du bûcher pour sauver Viconia.]] }, s = [[À Athkatla, un groupe de fanatiques a capturé Viconia et va la brûler sur un bûcher.
Parlez à leur meneur et intervenez ; les fanatiques attaquent, préparez-vous au combat.
Une fois qu'ils sont morts, parlez à Viconia : elle peut rejoindre le groupe tout de suite, ou vous dit qu'on la trouvera plus tard dans le quartier du cimetière.]] },
[74371] = { g = [[bg2]], k = [[side]], o = 0, c = [[4-5]], w = [[Cité des sahuagins]], h = { [[Deux diablotins surveillent six coffres et proposent un jeu avant que vous n'ouvriez le coffre verrouillé.]], [[Chaque figure illusoire vous donne un objet qui appartient à une autre ; rendez chaque objet au coffre de son vrai propriétaire.]], [[Résolvez l'énigme avant d'ouvrir le coffre verrouillé, sinon le spectre qu'il contient tue celui qui l'ouvre.]] }, s = [[Dans la salle aux six coffres, les diablotins préviennent que le coffre verrouillé renferme quelque chose qui vole les âmes. Ils vous protégeront si vous résolvez leur énigme.
Parlez à chaque figure illusoire : elle vous donne un objet. Trouvez à quelle figure appartient vraiment chaque objet et placez-le dans le coffre derrière cette figure.
Quand tout est bien placé, parlez aux diablotins. Si vous avez juste, ouvrez le sixième coffre : les diablotins chassent le spectre et vous gardez le trésor drow.
L'ouvrir sans résoudre l'énigme libère le spectre, qui tue celui qui l'ouvre et s'enfuit.]] },
[74372] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Franc-Marché / bosquet des druides]], h = { [[Après le bosquet des druides, le Seigneur Logan vous envoie voir la maîtresse de guilde Busya chez lui.]], [[Les génies Dao partiront dès qu'ils auront la rakshasa Ihtafeer, cachée hors de la ville.]], [[Les Voleurs de l'Ombre du coin soupçonnent la vieille marchande de potions de la hutte au nord-est du bosquet des druides.]] }, s = [[Une fois le bosquet des druides apaisé, le Seigneur Logan Coprith vous parle des génies. Voyez la maîtresse de guilde Busya chez lui : trouver la rakshasa ou tuer les génies.
Parlez au Khan Zahraa, chef des Dao. Il veut la tête de la rakshasa Ihtafeer, sans doute cachée près de la ville.
Itona, des Voleurs de l'Ombre, dit qu'Ihtafeer a pris la place de la marchande de potions Adratha, dans une hutte au nord-est du bosquet des druides. Allez-y, démasquez-la et tuez-la.
Apportez la tête au Khan Zahraa : les Dao repartent pour Calimshan. Combattre les génies règle aussi le problème.
Récupérez votre récompense auprès de Busya, puis faites votre rapport au Seigneur Logan.]] },
[74373] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines de Lancevent]], h = { [[C'est la triste fin de la recherche de l'enfant de Garren.]], [[L'enfant doit être libéré avant qu'il ne lui arrive quoi que ce soit dans le donjon de Firkraag.]], [[Libérez d'abord l'enfant de sa cellule ; ne pensez à Firkraag qu'ensuite.]] }, s = [[Cette entrée clôt la quête de Garren quand son enfant est mort dans le donjon de Firkraag.
Garren est anéanti et furieux, même si vous avez tué Firkraag, et il n'y a plus rien à faire avec lui.
Pour l'éviter, rechargez et sauvez l'enfant : tuez le mage qui a la clef de la cellule magique, ouvrez-la et laissez l'enfant rentrer chez lui avant de vous occuper du dragon.]] },
[74374] = { g = [[bg2]], k = [[main]], o = 38, c = [[2]], w = [[Athkatla, quartier du cimetière]], h = { [[La maîtresse de Valen ne traite pas gratuitement.]], [[Son prix ressemble à celui des Voleurs de l'Ombre, en plus modeste.]], [[Revenez de nuit au quartier du cimetière avec 15 000 pièces d'or.]] }, s = [[Bodhi, la maîtresse de Valen, a refusé de traiter avec vous faute de la somme demandée.
Réunissez 15 000 pièces d'or grâce aux quêtes d'Athkatla et des environs.
Retournez de nuit au quartier du cimetière et reparlez-lui pour accepter son offre. Cela lance les tâches de Bodhi et fait passer l'histoire au chapitre suivant.]] },
[74375] = { g = [[bg2]], k = [[main]], o = 39, c = [[2]], w = [[Athkatla, quartier du cimetière]], h = { [[Cette entrée note que vous avez repoussé Bodhi.]], [[Refuser Bodhi vous garde du côté des Voleurs de l'Ombre.]], [[Payez à Gaelan Bayle le prix des Voleurs de l'Ombre pour avancer.]] }, s = [[Bodhi vous a proposé de retrouver Imoen pour moins d'or que les Voleurs de l'Ombre, en échange de missions sanglantes. Vous avez refusé, et elle est maintenant votre ennemie, même si elle vous a laissé partir.
Plus rien à faire ici. Réunissez les 20 000 pièces d'or pour Gaelan Bayle, dans les bas quartiers : il vous envoie au Maître des Ombres, Aran Linvail, et sur la voie des Voleurs de l'Ombre au chapitre suivant.
Attendez-vous à recroiser Bodhi en ennemie.]] },
[74376] = { g = [[bg2]], k = [[main]], o = 37, c = [[2]], w = [[Athkatla, quartier du cimetière]], h = { [[Une femme nommée Valen vous aborde et laisse entendre que vos alliés actuels ne sont pas fiables.]], [[Sa maîtresse vous attend dans le quartier du cimetière, mais seulement la nuit.]], [[Suivez Bodhi quand elle vous emmène pour parler à l'écart.]] }, s = [[Quelque temps après votre rencontre avec Gaelan Bayle, Valen vous aborde à Athkatla et vous invite à rencontrer sa maîtresse.
Allez de nuit au quartier du cimetière. Bodhi se présente et vous demande de la suivre dans un endroit plus discret.
Elle révèle que Gaelan travaille pour les Voleurs de l'Ombre et propose la même aide pour 15 000 pièces d'or. Acceptez (avec l'or, ou revenez plus tard avec) pour travailler pour elle, ou refusez et restez avec les Voleurs de l'Ombre.
Avec certains personnages, Bodhi décide qu'elle ne peut pas vous faire confiance, disparaît dans la brume et promet de vous revoir au combat.]] },
[74377] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Franc-Marché]], h = { [[Jenia vous demande de voir son fils Tiris, dans leur maison au nord du domaine Alibakkar.]], [[Le tanneur Rejiek, du quartier du Pont, est à Franc-Marché avec une créature sans peau.]], [[Celui qui chasse le derviche peleur n'est pas forcément ce qu'il prétend ; gardez un sort de Restauration sous la main.]] }, s = [[Fait suite à la fuite de Rejiek dans le quartier du Pont. Jenia vous envoie voir Tiris : lui et Raïssa ont été enlevés et emmenés dans les bois près de la porte sud-ouest.
Dans les bois, Darsidian Moor dit chasser un derviche peleur caché dans une zone murée au nord de la porte est, dans un pavillon orange, et part devant.
Là-bas, Darsidian vous demande de tuer un « Rejiek » inconscient. Méfiance : Darsidian et la « Raïssa » secourue peuvent aussi être des derviches peleurs, et le vrai Rejiek peut être déguisé.
Tuez Rejiek et Darsidian. La vraie Raïssa a été changée en derviche peleur : lancez vite Restauration sur elle (le temple de Waukyne vend peut-être un parchemin). Sinon elle s'enfuit ou doit être tuée.
Retournez voir Tiris. Meilleure fin : Raïssa guérie, et le couple part se marier.]] },
[74378] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, bas quartiers, Couronne de Cuivre]], h = { [[Par fierté, Mazzy a défié un ogre gladiateur à la Couronne de Cuivre.]], [[Un alchimiste nommé Festule a une potion qui pourrait équilibrer le combat.]], [[Persuadez Bunkin, la petite amie de Gorf, de verser la potion de Festule dans son verre avant le duel.]] }, s = [[Avec Mazzy dans le groupe, elle défie Gorf l'Écrabouilleur, un ogre gladiateur, en duel à la Couronne de Cuivre.
Avant le combat, obtenez une potion auprès de Festule l'alchimiste. Il conseille de parler à Bunkin, la petite amie de Gorf.
Convainquez Bunkin que la potion rendra Gorf plus gentil, pour qu'elle la verse dans son verre.
Allez dans l'arène de la Couronne de Cuivre : Mazzy affronte Gorf seule. Avec la potion, elle devrait gagner. Sans aide elle peut mourir : renforcez-la avant le duel et prévoyez de quoi la ressusciter.]] },
[74379] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du cimetière]], h = { [[Voyagez avec Nalia après la libération de son donjon ; un messager viendra la trouver.]], [[Les funérailles de son père ont lieu dans le quartier du cimetière d'Athkatla.]], [[Aux funérailles, le fils du Seigneur Roenal presse Nalia au sujet de ses fiançailles.]] }, s = [[Avec Nalia dans le groupe après la mort du seigneur de'Arnise, un messager lui demande de venir aux funérailles de son père.
Allez vite dans le quartier du cimetière d'Athkatla. Aux funérailles, Isaéa Roenal exige que Nalia respecte les fiançailles arrangées par son père et se fâche quand elle refuse.
Aucun combat ici. Cela prépare l'action d'Isaéa contre Nalia plus tard (voir « Enlèvement de Nalia par Isaéa Roenal »).]] },
[74380] = { g = [[bg2]], k = [[main]], o = 50, c = [[4]], w = [[Brynnlaw]], h = { [[Après Brisesort, Saemon Havarian vous attend à la taverne de Brynnlaw avec une offre de passage.]], [[Son navire est hors d'état ; il veut que vous voliez la corne qui ouvre les portes du port.]], [[Cayia, l'amie de Desharik, garde la corne chez elle, à l'ouest au deuxième niveau, la nuit.]] }, s = [[Une fois sorti de l'asile, Saemon propose de vous faire quitter l'île. Rassemblez votre matériel et rejoignez-le à la taverne.
Il avoue que le Seigneur Pirate Desharik a mis son navire hors d'état ; il compte voler celui de Desharik. Votre rôle : voler la corne qui ouvre les portes du port chez Cayia, à l'ouest au deuxième niveau, la nuit.
Apportez-la à Saemon sur les quais. Après un court combat contre les hommes de Desharik, vous prenez la mer et Saemon vous donne une épée d'argent (des ennuis suivent, voir « Trahison sur le chemin de retour »).
Autres choix : refuser et utiliser le portail magique dans l'asile. Si Saemon meurt dans le combat contre Desharik, le portail est votre seule issue.]] },
[74381] = { g = [[bg2]], k = [[main]], o = 51, c = [[4-5]], w = [[En mer, puis la cité des sahuagins]], h = { [[L'épée d'argent que Saemon vous a donnée n'était pas à lui.]], [[Ses vrais propriétaires, les githyankis, montent à bord pour la reprendre.]], [[Survivez à l'attaque des githyankis ; le navire coule et les sahuagins vous emmènent sous la mer.]] }, s = [[Pendant la traversée depuis Brynnlaw, des githyankis abordent le navire : l'épée d'argent que Saemon vous a donnée leur avait été volée. Ils se battent pour la reprendre ; préparez-vous à un combat difficile.
Pendant la bataille, des sahuagins envahissent le navire qui coule et Saemon se téléporte.
Vous vous retrouvez dans la cité des sahuagins, sous la mer. De là, la route mène à l'Ombreterre.]] },
[74382] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla / Ombreterre]], h = { [[Une lettre chez Rejiek Mégissier nomme un artisan qui travaillait avec lui.]], [[Darcin Cole vous prend pour Rejiek et finira l'armure contre un ingrédient rare.]], [[Le sang de dragon d'argent ne peut venir que d'Adalon, dans l'Ombreterre.]] }, s = [[Fouillez la maison de Rejiek Mégissier après les meurtres des écorchés : prenez la peau inachevée et la lettre.
Trouvez l'homme cité dans la lettre et nommez-le correctement : Darcin Cole. Il vous prend pour Rejiek et demande du sang de dragon d'argent.
Dans l'Ombreterre, après avoir aidé Adalon, obtenez un peu de son sang.
Donnez la peau et le sang à Darcin Cole et revenez quatre jours plus tard. Il vous remet l'armure de cuir noir terminée, puis comprend que vous n'êtes pas Rejiek et attaque avec des magiciens convoqués. Préparez-vous au combat.]] },
[74383] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla]], h = { [[La sœur d'Anomen a été assassinée, et son père, le seigneur Cor, réclame vengeance.]], [[Vos conseils décident si Anomen laisse l'Ordre rendre justice ou se venge lui-même.]], [[Le pousser à venger Moira le lance contre la famille Saerk, avec des effets durables sur sa voie.]] }, s = [[Avec Anomen dans le groupe, il apprend que sa sœur Moira a été assassinée. Le seigneur Cor accuse son rival Saerk et exige vengeance.
Si vous poussez Anomen à agir lui-même, il attaque la maison de Saerk : Saerk et sa fille meurent, le fils Yusef s'échappe. Le seigneur Cor retrouve sa fortune et part pour Calimshan ; Anomen n'est pas satisfait.
Ce choix pèse sur l'épreuve de chevalerie d'Anomen : conseiller la patience et la confiance en l'Ordre est la voie qui le garde candidat chevalier.]] },
[74384] = { g = [[bg2]], k = [[main]], o = 59, c = [[6]], w = [[Athkatla]], h = { [[De retour à Athkatla, vous pouvez demander l'aide de groupes puissants avant d'attaquer le repaire de Bodhi.]], [[Les temples refusent pour la plupart, mais ils vous orientent vers l'Ordre du Cœur Radieux.]], [[Le prélat Wessalen ou Aran Linvail peuvent envoyer des combattants vous rejoindre sous le quartier du cimetière.]] }, s = [[Avant d'affronter Bodhi dans son repaire sous le quartier du cimetière, cherchez des alliés (facultatif).
Les temples de Heaume et de Lathandre ne peuvent pas aider et vous envoient à l'Ordre du Cœur Radieux ; Nallabir, au temple de Talos, refuse net.
Demandez au prélat Wessalen, au siège de l'Ordre dans le quartier du temple : s'il accepte, le groupe de Sire William Reirrac vous attend sous le quartier du cimetière.
Si vous avez choisi les Voleurs de l'Ombre, demandez à Aran Linvail : il peut envoyer les assassins dont il dispose.
Chacun peut refuser selon votre passé avec lui. Les alliés aident seulement au combat ; vous pouvez affronter Bodhi sans eux.]] },
[74385] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla]], h = { [[Le mage cagoulé Jermien a besoin d'un ingrédient rare pour animer son golem géant.]], [[C'est du sang de mimique qu'il demande.]], [[Soyez prêt quand le golem s'éveille : il se retourne contre son créateur, et la fille de Jermien est dans la pièce.]] }, s = [[Jermien, un mage cagoulé, veut du sang de mimique pour activer son golem géant. Daar, amoureux de Colette, la fille de Jermien, est aussi mêlé à l'affaire.
Apportez le sang de mimique à Jermien. Le golem s'anime et attaque son créateur.
Tuez le golem vite. Si vous êtes assez rapide, Jermien survit et vous remercie. S'il meurt, sauvez au moins Colette ; elle part tristement avec Daar.]] },
[74386] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du temple]], h = { [[Anomen est convoqué devant l'Ordre du Cœur Radieux pour être jugé.]], [[Accompagnez-le au siège de l'Ordre, dans le quartier du temple, dans les deux jours.]], [[Le verdict dépend de la conduite passée d'Anomen, surtout face au meurtre de sa sœur.]] }, s = [[Avec Anomen dans le groupe, l'heure de son jugement arrive. Il doit se présenter au siège de l'Ordre, dans le quartier du temple, dans les deux jours.
Accompagnez-le et entrez pour assister au jugement. Si vous refusez de venir, il part seul, furieux, et ne reviendra sans doute pas.
S'il a su se retenir et laisser la vengeance à l'Ordre, il est fait chevalier. S'il s'est vengé lui-même, il est jugé indigne, part en colère et prend une voie plus sombre.]] },
[74387] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines de Lancevent]], h = { [[C'est la fin heureuse de la recherche de l'enfant de Garren.]], [[Une fois l'enfant libéré du donjon de Firkraag, Garren attend à sa cabane.]], [[Retournez à la cabane de Garren ; tuer Firkraag est un bonus, pas une obligation.]] }, s = [[Libérez l'enfant de Garren de la cellule à serrure magique du donjon de Firkraag (la clef est sur un mage voisin). L'enfant rentre chez lui.
Retournez à la cabane de Garren, dans les Collines de Lancevent. Il vous remercie et vous offre le gîte chaque fois que vous passez.
Que Firkraag soit vivant ou mort, la quête s'arrête là. Firkraag reste un combat de dragon facultatif et très difficile.]] },
[74388] = { g = [[bg2]], k = [[main]], o = 48, c = [[4]], w = [[Brisesort, monde du rêve]], h = { [[Dans le rêve, suivez la voix d'Imoen : elle dit que vous ne pouvez pas combattre seul.]], [[Chaque porte vers le fond de votre esprit exige un sacrifice de vous-même.]], [[Trouvez la créature de Bhaal et ramenez-la jusqu'à Imoen pour l'affronter ensemble.]] }, s = [[Irenicus lance son rituel à Brisesort et vous sombrez dans un rêve.
Trouvez Imoen dans le rêve. Elle vous dit de chercher la « créature de Bhaal », votre instinct, et de la ramener jusqu'à elle : l'affronter seul signifie la mort, victoire ou non.
Franchissez les portes vers le fond de votre esprit ; chacune vous prend un sacrifice.
Trouvez la créature, attirez-la jusqu'à Imoen et battez-la ensemble.
Vous vous réveillez : Irenicus a volé votre âme et laisse Bodhi vous achever. Frayez-vous un chemin hors de l'asile.]] },
[74389] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, quartier du gouvernement]], h = { [[Un homme nommé Madeen connaît un Mage Cagoulé qui cherche à engager quelqu'un.]], [[Tolgerias attend dans le bâtiment principal du gouvernement.]], [[Tolgerias promet des nouvelles d'Imoen en échange de la capture de Valygar Corthala.]] }, s = [[Madeen vous apprend que le Mage Cagoulé Tolgerias veut engager quelqu'un.
Allez au bâtiment principal du gouvernement, dans le quartier du gouvernement, et parlez à Tolgerias.
Il promet des informations sur Imoen si vous lui rendez service : retrouver Valygar Corthala. Accepter lance « À la poursuite de Valygar Corthala » ; refuser fâche les Mages Cagoulés.]] },
[74390] = { g = [[bg2]], k = [[main]], o = 43, c = [[3]], w = [[Athkatla]], h = { [[Vous avez payé pour retrouver Imoen : les Voleurs de l'Ombre ou Bodhi attendent maintenant vos services.]], [[Voie des Voleurs de l'Ombre : apportez la clef de Gaelan à Aran Linvail, sous le quartier général de la guilde, quartier des quais.]], [[Voie de Bodhi : accomplissez ses missions contre les Voleurs de l'Ombre depuis les cryptes du quartier du cimetière.]] }, s = [[Le chapitre 3 commence quand vous payez pour retrouver Imoen.
Voleurs de l'Ombre : Gaelan vous donne une clef pour rencontrer le Maître des Ombres, Aran Linvail, dans son repaire sous le quartier général des Voleurs de l'Ombre, quartier des quais. Il vous demande de frapper la guilde des vampires dans le quartier du cimetière, puis organise votre passage vers l'île où Imoen est détenue.
Bodhi : travaillez pour elle depuis les cryptes sous le quartier du cimetière. Elle vous envoie contre les Voleurs de l'Ombre : une cargaison sur les quais, une deuxième tâche, puis tuer Aran Linvail. Elle paie ensuite votre passage vers l'asile.
Dans les deux cas, le chapitre se termine quand vous partez pour Brynnlaw.]] },
[74391] = { g = [[bg2]], k = [[main]], o = 47, c = [[4]], w = [[Brisesort]], h = { [[À Brisesort, l'aimable coordinateur propose une visite et de voir Imoen.]], [[Lonk le Lucide, un employé, vous dit où est Imoen et combien elle a changé.]], [[Voir Imoen déclenche le piège d'Irenicus : préparez-vous à la suite.]] }, s = [[Une fois à Brisesort, parlez au coordinateur : il propose une visite et de vous mener à Imoen.
Parlez à l'employé Lonk le Lucide : Imoen est au bout du couloir, perdue et violente. Il semble surpris que vous connaissiez Irenicus.
Trouvez Imoen ; elle n'est visiblement plus elle-même.
Irenicus se montre alors : c'était un piège depuis le début. Il vous capture pour prendre votre âme divine, comme il l'a fait avec Imoen, elle aussi enfant de Bhaal.
La suite est la séquence du rêve (« La transformation et le rêve »).]] },
[74392] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, bas quartiers, Couronne de Cuivre]], h = { [[Le patron de la Couronne de Cuivre laisse certains clients entrer dans ses « arrière-salles ».]], [[Derrière se trouve un enclos à esclaves, où Hendak supplie qu'on l'aide à s'évader.]], [[Aider Hendak est la voie bonne ; le trahir auprès de Lehtinan vous vaut des rabais chez Bernard.]] }, s = [[À la Couronne de Cuivre, dans les bas quartiers, le patron Lehtinan vous autorise à visiter ses arrière-salles.
Vous y trouvez l'enclos des esclaves. L'esclave Hendak vous demande de l'aider à s'évader.
Voie bonne : acceptez, libérez Hendak et combattez Lehtinan et ses hommes.
Voie mauvaise : refusez, dénoncez Hendak à Lehtinan, prenez la clef qu'il vous donne et tuez Hendak dans sa cellule. Lehtinan vous récompense, avec entre autres des prix réduits chez Bernard, son commis.]] },
[74393] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Collines d'Umar, ruines du temple]], h = { [[Le maire Lloyd d'Imnesvale cherche quelqu'un pour arrêter les meurtres dans les Collines d'Umar.]], [[La piste mène à des ruines d'un temple d'Amaunator dans les collines.]], [[Le Seigneur des ombres se cache au fond du donjon du temple ; préparez-vous aux morts-vivants et aux ombres.]] }, s = [[Le maire Lloyd vous engage pour faire cesser les meurtres autour d'Imnesvale.
Enquêtez dans les Collines d'Umar et rendez-vous aux ruines du temple d'Amaunator, où les ombres ont envahi les terres.
Traversez le donjon du temple et tuez le Seigneur des ombres en son cœur.
Retournez voir le maire Lloyd à Imnesvale pour ses remerciements et une récompense. Mazzy, que l'on croise près du temple, peut vous rejoindre.]] },
[74394] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Donjon de'Arnise]], h = { [[Nalia, à Athkatla, supplie qu'on l'aide : des trolls ont envahi le donjon de sa famille.]], [[Frayez-vous un chemin dans le donjon et cherchez son père, le seigneur de'Arnise.]], [[Le chef troll TorGal tient le donjon ; prévoyez du feu ou de l'acide pour achever les trolls.]] }, s = [[Acceptez la demande de Nalia et rendez-vous avec elle au donjon de'Arnise. Le capitaine Arat, à l'entrée, vous explique la situation.
Nettoyez le donjon pièce par pièce. Les trolls ne restent morts qu'avec du feu ou de l'acide.
Trouvez et tuez le chef troll TorGal. Le seigneur de'Arnise ne peut être sauvé : TorGal l'a tué.
Une fois le donjon libéré, la quête se termine. L'avenir de Nalia au donjon reste incertain, et son histoire continue avec les funérailles de son père. Un protagoniste guerrier peut ensuite se voir offrir le donjon comme forteresse.]] },
[74395] = { g = [[bg2]], k = [[companion]], o = 0, c = [[any]], w = [[Nature, campement des muloups]], h = { [[Coran dit que Safana a été enlevée par des muloups installés non loin à l'est.]], [[L'enlèvement n'est pas ce qu'il semble : Safana veut la prime sur votre tête.]], [[Gardez Coran en vie pendant le combat contre la mulouve Lanfear, qui le veut pour elle.]] }, s = [[Coran vous dit que des muloups ont enlevé Safana et vous demande de venir à leur camp, un peu à l'est. Si vous refusez, il part seul ; vous pouvez encore le suivre.
Au camp, la vérité éclate : Safana et la mulouve Lanfear ont tout manigancé, Safana pour la prime sur votre tête, Lanfear pour gagner Coran.
Lanfear tue Safana. Combattez Lanfear et ses muloups, et protégez Coran.
Meilleure issue : Lanfear meurt et Coran survit. Si Coran est tué, par vous ou par Lanfear, la quête se termine quand même ; un sort de résurrection peut le ramener.]] },
[74396] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, bas quartiers (sphère planaire) / collines d'Umar]], h = { [[L'étrange sphère de métal enfoncée dans les bas quartiers est liée à la famille de Valygar, que les Mages Cagoulés recherchent.]], [[Seul quelqu'un du sang de Valygar peut ouvrir la sphère planaire : emmenez-le.]], [[Au fond de la sphère attend Lavok, l'ancêtre de Valygar ; battez-le pour lever la malédiction et gagner la sphère.]] }, s = [[Les Mages Cagoulés vous demandent de leur amener Valygar, qui vit dans une cabane des collines d'Umar. Parlez-lui plutôt et recrutez-le : il explique que son ancêtre Lavok, un nécromancien, a bâti la sphère planaire des bas quartiers.
Avec Valygar dans le groupe, entrez dans la sphère. Explorez-la, venez à bout de ses gardiens et des prisonniers qui s'y trouvent, et trouvez le chemin du cœur de la sphère.
Affrontez Lavok, un mage puissant, et battez-le. Attendez-vous à un combat contre un Mage Cagoulé et ses alliés à la sortie.
Ensuite, Valygar n'est plus pourchassé. Gardez-le dans le groupe ou laissez-le partir (il attend chez lui). La sphère devient votre base.]] },
[74397] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre, cité illithide]], h = { [[D'autres prisonniers de l'arène des flagelleurs mentaux haïssent les illithids encore plus que vous.]], [[Écoutez Simyaz, le chef des githyankis : ses hommes peuvent troubler les flagelleurs pour que vous ouvriez la porte de l'arène.]], [[Les githyankis se téléporteront sans vous : préparez-vous à vous frayer seul un chemin hors de la cité.]] }, s = [[Capturé par des flagelleurs mentaux dans l'Ombre-Terre, vous devez combattre dans leur arène. Un groupe de prisonniers githyankis mené par Simyaz s'y trouve aussi (ceux qui ont attaqué le bateau de Saemon, si vous les avez croisés).
Parlez à Simyaz et acceptez son plan : ses hommes bloquent le pouvoir mental des illithids, ce qui vous permet d'ouvrir la porte de l'arène. Vous pouvez aussi tuer les githyankis, mais il faudra alors forcer la porte seul.
Une fois dehors, les githyankis se téléportent et vous abandonnent. Avancez prudemment dans la cité illithide : les flagelleurs étourdissent et drainent l'Intelligence, protégez-vous contre les attaques mentales et éliminez-les vite.
Plus loin, une étrange porte bloque le passage ; il faut une grande puissance pour la forcer. Vous recroiserez peut-être les githyankis.]] },
[74398] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier des quais (Bonté Marine)]], h = { [[Parcourez Athkatla avec Keldorn et une vieille connaissance à lui va se présenter.]], [[Vakola accuse Keldorn de trahison ; vous le reverrez à la Bonté Marine, dans le quartier des quais.]], [[Vakola était un membre corrompu de l'Ordre que Keldorn a dénoncé, et il vient pour se battre.]] }, s = [[Avec Keldorn dans le groupe, un homme nommé Vakola l'aborde et l'accuse de trahison. Keldorn nie.
Plus tard, entrez à la Bonté Marine, dans le quartier des quais, avec Keldorn. Vakola y est avec ses amis. La vérité éclate : tous deux servaient dans l'Ordre du Cœur Radieux et Keldorn a dénoncé Vakola qui acceptait des pots-de-vin.
Vakola et ses compagnons attaquent. Battez-les ; l'affaire se termine par la mort de Vakola.]] },
[74399] = { g = [[bg2]], k = [[main]], o = 52, c = [[5]], w = [[Ombre-Terre, Ust Natha]], h = { [[Irenicus a fui Brisesort vers les profondeurs ; vous devez le suivre sous la surface.]], [[Dans l'Ombre-Terre, cherchez le dragon d'argent Adalon, qui peut vous faire passer pour un drow.]], [[Gagnez la confiance des drows d'Ust Natha, récupérez les œufs volés d'Adalon et elle vous guidera vers la surface.]] }, s = [[Après Brisesort, Irenicus et Bodhi sont partis dans l'Ombre-Terre. Vous l'atteignez soit directement depuis les profondeurs de l'asile, soit en partant avec Saemon (ce qui fait un détour).
Dans l'Ombre-Terre, explorez prudemment (tyrannœils, flagelleurs mentaux) et trouvez le dragon d'argent Adalon. Les drows ont volé ses œufs ; elle déguise votre groupe en drows pour que vous entriez dans la cité d'Ust Natha.
À Ust Natha, acceptez les missions des chefs drows pour monter en grade, gardez votre déguisement et découvrez où sont gardés les œufs. Récupérez-les et rendez-les à Adalon.
Adalon vous montre alors le chemin de la surface, où commence le chapitre suivant.]] },
[74400] = { g = [[bg2]], k = [[main]], o = 57, c = [[6]], w = [[Forêt du Téthyr / Athkatla, quartier du cimetière]], h = { [[De retour à la surface, les elfes près de la sortie de l'Ombre-Terre ont besoin de vous pour atteindre leur cité.]], [[Leur chef Elhan dit que Bodhi détient ce qu'il leur faut : retournez à Athkatla.]], [[Le repaire de Bodhi se trouve dans les catacombes du quartier du cimetière ; détruisez-la et rapportez ce qu'elle a pris.]] }, s = [[En quittant l'Ombre-Terre, vous rencontrez l'armée elfe d'Elhan dans la forêt. Irenicus a scellé Suldanessellar, et seul un artefact magique peut révéler le chemin, mais c'est Bodhi qui l'a.
Retournez à Athkatla et préparez-vous bien : Bodhi et ses vampires sont redoutables, et elle frappe votre groupe avant le combat final. En chemin, vous pouvez croiser Drizzt, qui peut se joindre à la bataille.
Entrez dans le repaire de Bodhi, dans les catacombes du quartier du cimetière. Battez ses serviteurs, vainquez Bodhi et assurez-vous qu'elle ne puisse pas revenir (détruisez-la dans son cercueil).
Récupérez l'artefact et rapportez-le à Elhan pour ouvrir la voie de la cité elfe.]] },
[74401] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Collines de Lancevent, donjon de Firkraag]], h = { [[La piste de l'enfant enlevé de Garren Lancevent mène au donjon sous les collines de Lancevent.]], [[L'homme qui vous a envoyé là était un dragon rouge déguisé, et il vous attend tout au fond.]], [[Vous pouvez laisser Firkraag tranquille, ou bien vous protéger du feu et l'affronter pour son trésor.]] }, s = [[En suivant la quête de Garren Lancevent, descendez dans le donjon des collines de Lancevent. Tout au fond, vous rencontrez le vrai Firkraag, un énorme dragon rouge qui s'est joué de vous à cause d'une vieille rancune contre Gorion.
Il ne s'intéresse plus à vous et laisse un de ses serviteurs garder l'enfant de Garren. Battez ce serviteur et libérez l'enfant pour finir la quête de Garren.
Vous pouvez aussi défier Firkraag. C'est l'un des combats les plus durs du jeu : prévoyez résistance au feu, protection contre la peur et sorts de soutien, et attendez-vous à son souffle et à ses sorts. Le vaincre rapporte beaucoup d'XP et un riche trésor.]] },
[74402] = { g = [[bg2]], k = [[side]], o = 0, c = [[6]], w = [[Route depuis la forêt du Téthyr]], h = { [[Sur le chemin du retour vers Athkatla depuis la forêt des elfes, vous pourriez croiser un célèbre rôdeur drow.]], [[Parlez calmement à Drizzt et racontez-lui votre combat contre Bodhi.]], [[S'il accepte, il vous attendra dans les catacombes du quartier du cimetière.]] }, s = [[Au chapitre 6, en revenant de la forêt du Téthyr vers Athkatla, Drizzt Do'Urden et ses compagnons peuvent vous arrêter.
Parlez-lui sans hostilité et demandez son aide contre Bodhi. Il accepte de vous retrouver dans les catacombes du quartier du cimetière.
Quand vous entrez dans le repaire de Bodhi, Drizzt et ses amis apparaissent et combattent à vos côtés, ce qui facilite beaucoup la bataille.
Attaquer Drizzt est au contraire un combat très difficile qui coûte de la réputation.]] },
[74403] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-4]], w = [[Athkatla]], h = { [[Après les ennuis avec les Ménestrels, l'ancien précepteur de Jaheira, Dermin, viendra la confronter.]], [[Quand Jaheira renonce aux Ménestrels, votre réaction décide si elle reste.]], [[Soutenez sa décision et laissez-lui du temps ; la pousser ou la presser la fait partir pour de bon.]] }, s = [[C'est une partie de la quête des Ménestrels de Jaheira, après les événements avec Galvarey au Cercle des Ménestrels. Gardez Jaheira dans le groupe et Dermin, son ancien précepteur, se présente : il a été envoyé pour l'exécuter à cause des morts du Cercle.
Il n'attaque pas, et Jaheira renonce à sa vie de Ménestrel.
Choisissez bien vos mots. Acceptez son choix comme le sien et soutenez-la : elle reste dans le groupe. Si vous semblez la pousser ou vous montrez impatient, elle pense que vous ne lui faites pas confiance et quitte le groupe définitivement.
Plus tard, l'homme appelé Terminsel vient la juger (voir la quête liée).]] },
[74404] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-4]], w = [[Athkatla]], h = { [[L'inconnu qui vous avait apporté le message de Jaheira reviendra à la fin de ses ennuis avec les Ménestrels.]], [[Terminsel veut seulement savoir si Jaheira regrette ses actes.]], [[Si Jaheira reste ferme dans sa réponse, les Ménestrels classent l'affaire et la récompensent.]] }, s = [[Dernière étape de la quête des Ménestrels de Jaheira, après Galvarey et Dermin. Gardez Jaheira dans le groupe et Terminsel, l'homme qui avait apporté son message, apparaît et lui demande si elle regrette ses actes.
L'issue dépend du déroulement de sa quête et de votre relation. Si elle n'a aucun regret, les Ménestrels considèrent l'affaire close, ne vous poursuivent plus et remettent à Jaheira une Épingle des Ménestrels. Terminsel se révèle être Elminster en personne.
Si elle hésite, il repart déçu en disant que ses doutes sont une punition suffisante ; rien de plus ne se passe.]] },
[74405] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla]], h = { [[Un gnome bavard qui vend des navets à Athkatla se fait arrêter sous vos yeux.]], [[L'amende de Jan Jansen est de 800 pièces d'or, à payer au gardien de la prison.]], [[S'il vous manque de l'or, le geôlier peut vous en prêter une partie ; annoncez ensuite à Jan qu'il est libre.]] }, s = [[Dans les rues d'Athkatla, le gnome Jan Jansen essaie de vous vendre des navets et se fait arrêter pour vente de marchandises illégales. Il vous supplie de payer son amende de 800 po.
Allez à la prison et parlez au geôlier. Payez l'amende. S'il vous manque de l'argent, il a tellement hâte de se débarrasser de Jan qu'il vous prête 200 po, à lui rembourser plus tard.
Parlez à Jan dans sa cellule pour lui dire qu'il est libre. Prenez-le dans le groupe, ou refusez et retrouvez-le plus tard chez lui, dans les bas quartiers.]] },
[74406] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, domaine Delryn]], h = { [[Voyagez quelque temps avec Anomen et il recevra une grave nouvelle à propos de sa sœur.]], [[Son père, le seigneur Cor, veut qu'Anomen tue le marchand Saerk ; le magistrat ne trouve aucune preuve.]], [[Poussez Anomen à respecter la loi et à pardonner ; ce choix décide de son avenir.]] }, s = [[Avec Anomen dans le groupe, il apprend le meurtre de sa sœur. Accompagnez-le au domaine de son père. Le seigneur Cor, amer, exige qu'Anomen tue Saerk, un marchand rival qu'il accuse.
Anomen refuse et se fait chasser. Allez voir le magistrat Bylanna : il n'y a pas assez de preuves contre Saerk ni contre quiconque.
Conseillez à Anomen d'oublier l'affaire et de renoncer à la vengeance. Il reste triste mais fidèle, et cette voie le mène à la chevalerie dans l'Ordre du Cœur Radieux (s'il a réussi son épreuve).
Si au contraire vous le poussez à se venger, il tue Saerk et se détourne de l'Ordre.]] },
[74407] = { g = [[bg2]], k = [[main]], o = 45, c = [[4]], w = [[Brynnlaw / Brisesort]], h = { [[Le bateau de Saemon Havarian vous emmène sur l'île pirate de Brynnlaw, près de l'asile.]], [[Entrer à Brisesort est tout le défi ; écoutez Saemon et les habitants pour trouver un moyen.]], [[Dans l'asile, trouvez Imoen et affrontez Irenicus ; les internés peuvent vous aider à renverser la situation.]] }, s = [[Après avoir payé Aran Linvail ou Bodhi, vous embarquez avec le corsaire Saemon Havarian pour Brynnlaw. Saemon n'est pas digne de confiance, mais il connaît l'île.
À Brynnlaw, explorez la ville et suivez les pistes que donnent Saemon et les habitants pour vous faire admettre à Brisesort.
Dans l'asile, Irenicus tend son piège : il révèle qu'Imoen est elle aussi une enfant de Bhaal, vous prend votre âme et lance Bodhi à vos trousses dans le donjon de l'asile. Survivez à ses épreuves et libérez les internés.
Avec leur aide, repoussez Irenicus. Il s'enfuit dans les profondeurs, ce qui ouvre le chapitre 5.]] },
[74408] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-4]], w = [[Athkatla, Cercle des Ménestrels]], h = { [[Après la mort de Galvarey, les Ménestrels n'en ont pas fini avec Jaheira.]], [[Un inconnu apporte un message : Jaheira est partie seule au Cercle des Ménestrels, suivez-la quand même.]], [[Les Ménestrels du Cercle sont un groupe dissident assoiffé de vengeance ; libérez Jaheira et reprenez-la dans le groupe.]] }, s = [[Après l'incident avec Galvarey, Dermin prévient Jaheira que les Ménestrels ont ordonné son exécution et que les attaques empireront si elle ne se rend pas.
Peu après, un homme étrange vous remet un message : Jaheira est partie seule au Cercle des Ménestrels d'Athkatla et vous interdit de la suivre.
Allez-y quand même. Combattez les Ménestrels sur place : l'absence de spectres à l'étage montre qu'il ne s'agit que d'un groupe dissident en quête de vengeance.
Trouvez Jaheira et proposez-lui de revenir dans le groupe pour poursuivre sa quête. Si vous refusez de la reprendre, elle s'enfuit seule et vous la perdez pour de bon.]] },
[74409] = { g = [[bg2]], k = [[main]], o = 44, c = [[3]], w = [[Athkatla, quartier du cimetière]], h = { [[Si vous avez choisi le camp de la vampire Bodhi, accomplissez toutes les tâches qu'elle vous confie.]], [[Ses derniers ordres frappent au cœur des Voleurs de l'Ombre.]], [[Retournez voir Bodhi après ses tâches : elle révèle la vérité sur Irenicus et réserve votre traversée vers Brisesort.]] }, s = [[C'est la voie de la vampire au chapitre 3. Après avoir payé Bodhi, accomplissez ses tâches contre les Voleurs de l'Ombre, jusqu'à l'attaque de leur guilde et la mort du Maître des Ombres, Aran Linvail. Ce sont des actes mauvais qui nuisent à votre réputation.
Retournez voir Bodhi dans son repaire du quartier du cimetière. Elle tient parole : Irenicus est son frère, il vous a enlevé parce que vous êtes un enfant de Bhaal, et lui comme Imoen ont été envoyés à l'asile de Brisesort.
Bodhi veut libérer Irenicus pour ses propres desseins et a réservé votre traversée vers l'île de l'asile. Rendez-vous aux quais pour commencer le chapitre 4.]] },
[74410] = { g = [[bg2]], k = [[side]], o = 0, c = [[any]], w = [[Inconnu]], h = { [[Ce n'est qu'une note de rappel sur l'entraînement au combat, pas une vraie quête.]], [[Aucun dialogue ni script du jeu n'est indiqué comme l'écrivant : elle n'apparaît peut-être jamais.]] }, s = [[Cette entrée du journal dit seulement que Belt vous rappelle de terminer votre entraînement martial. Aucun dialogue ni script connu ne l'ajoute : elle ressemble à un reste de tutoriel.
Il n'y a rien à faire et aucune récompense. Si elle apparaît dans votre journal, vous pouvez l'ignorer.]] },
[74411] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, égouts]], h = { [[Un receleur nommé Roger tient boutique dans les égouts d'Athkatla.]], [[Roger est harcelé par un troll de mer qui rôde dans les égouts.]], [[Tuez le troll et achevez-le au feu ou à l'acide pour qu'il ne se régénère pas, puis revenez voir Roger.]] }, s = [[Trouvez Roger le receleur dans les égouts d'Athkatla. On le rencontre en général en cherchant le gong de Dennis pour la quête de Vittorio.
Il accepte de vous aider (et de vous parler du gong) si vous tuez un troll de mer qui le harcèle.
Fouillez les tunnels voisins pour trouver le troll de mer. Quand il tombe, achevez-le avec des dégâts de feu ou d'acide, sinon il se relève.
Retournez voir Roger pour faire votre rapport et obtenir ce qu'il a promis.]] },
[74412] = { g = [[bg2]], k = [[main]], o = 35, c = [[2]], w = [[Athkatla]], h = { [[Imoen a été emmenée là où les Mages Cagoulés ont conduit Irenicus, et il vous faut une aide puissante pour la suivre.]], [[Gaelan Bayle, dans les bas quartiers, propose l'aide des Voleurs de l'Ombre, à un prix exorbitant.]], [[Rassemblez l'or grâce à des missions dans Athkatla et au-delà, puis payez les Voleurs de l'Ombre ou une offre rivale.]] }, s = [[Vous vous échappez du donjon d'Irenicus sur la Promenade de Waukyne, à Athkatla, et voyez les Mages Cagoulés emmener Irenicus et Imoen.
Dans les bas quartiers, Gaelan Bayle vous aborde : ses maîtres, les Voleurs de l'Ombre, vous aideront à retrouver Imoen pour 20 000 pièces d'or.
Explorez Athkatla et ses environs, acceptez des quêtes et les demandes de vos compagnons, et économisez. En cours de route, Bodhi propose une offre rivale depuis le quartier du cimetière, pour moins d'or.
Une fois la somme réunie, payez Gaelan (ou Bodhi). Le chapitre 3 commence alors : votre nouveau protecteur vous confie des tâches avant de réserver votre traversée.]] },
[74413] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Collines d'Umar, ruines du temple]], h = { [[Le donjon du Seigneur des Ombres, sous les ruines du temple des collines d'Umar, retient une guerrière halfeline.]], [[Mazzy Fentan est enfermée dans une cellule du repaire du Seigneur des Ombres.]], [[Libérez-la ; si vous n'avez pas de place pour elle, elle attend chez elle à Franc-Marché.]] }, s = [[En enquêtant sur les disparitions des collines d'Umar, descendez dans le donjon du Seigneur des Ombres, sous les ruines du temple.
Dans une de ses cellules se trouve Mazzy Fentan, une guerrière halfeline dont les compagnons sont tombés face au Seigneur des Ombres. Ouvrez sa cellule pour la libérer.
Cette entrée correspond au cas où vous lui dites ne pas avoir besoin d'elle pour l'instant : elle vous remercie et rentre chez elle à Franc-Marché, où vous pourrez la recruter plus tard.
Si vous la prenez avec vous, elle vous aide à combattre le Seigneur des Ombres.]] },
[74414] = { g = [[bg2]], k = [[main]], o = 33, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[Imoen vous a libéré ; explorez cet étrange donjon et rassemblez vos anciens amis.]], [[Aidez les captifs et les créatures que vous rencontrez : beaucoup ouvrent la voie ou vous donnent du matériel.]], [[La sortie se trouve au niveau supérieur ; avancez et vous déboucherez à Athkatla.]] }, s = [[Vous vous réveillez dans une cage du donjon d'Irenicus, et Imoen vous libère. Fouillez la pièce et regardez les cellules de Jaheira et de Minsc.
Explorez le premier niveau : libérez le djinn grâce à sa bouteille, aidez les dryades, trouvez la pierre d'activation du golem des égouts pour qu'il ouvre les portes scellées, et trouvez la clef de la cage de Jaheira. Minsc se libère tout seul.
D'autres prisonniers et expériences, comme Rielev, peuvent être interrogés ou libérés. Reposez-vous quand c'est possible.
Montez au niveau suivant, combattez les duergars, méphites et autres gardiens, et atteignez la sortie. Vous débouchez à Athkatla en pleine bataille, ce qui ouvre le chapitre 2.]] },
[74415] = { g = [[bg2]], k = [[side]], o = 0, c = [[1-2]], w = [[Donjon d'Irenicus / collines de Lancevent]], h = { [[Trois dryades prisonnières du donjon d'Irenicus rêvent d'être libres.]], [[Un nain nommé Ilyich, ailleurs dans le donjon, porte leurs glands.]], [[Prenez les glands à Ilyich et apportez-les plus tard à la reine des fées, dans les collines de Lancevent.]] }, s = [[Dans le donjon d'Irenicus, parlez aux trois dryades. Elles vous demandent de récupérer leurs glands et de les apporter à la reine des fées.
Les glands sont portés par le nain Ilyich, qui garde une partie du donjon avec ses duergars. Battez-le et prenez les glands.
Une fois sorti et libre de voyager, allez aux collines de Lancevent et trouvez la reine des fées, Vaelasa. Donnez-lui les glands.
Les dryades sont libérées et partent replanter leurs arbres, et Vaelasa vous remercie. Vous gagnez de l'expérience.]] },
[74416] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[Le djinn Malaaq, dans le donjon d'Irenicus, est lié à une bouteille et garde des affaires de son maître.]], [[La bouteille jumelle est gardée près de son maître : dans ses appartements, ou chez les dryades ou les golems.]], [[Ce sont les dryades qui ont la bouteille ; apportez-la à Malaaq pour le libérer.]] }, s = [[Parlez au djinn Malaaq dans le donjon d'Irenicus. Il garde du matériel pour Irenicus mais ne peut pas s'en séparer tant qu'il est lié à sa bouteille. Pour le libérer, il vous faut la bouteille jumelle.
Allez voir les trois dryades du donjon et obtenez la bouteille auprès d'elles.
Retournez voir Malaaq et donnez-la-lui. Il est libéré et vous remet en échange le matériel qu'il gardait, bien utile pour la suite du donjon.]] },
[74417] = { g = [[bg2]], k = [[companion]], o = 0, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[La cage de Jaheira a une serrure magique impossible à crocheter.]], [[Explorez le reste du premier niveau du donjon ; la clef s'y trouve quelque part.]], [[Une fois la clef en main, retournez dans la salle de votre réveil et ouvrez sa cage.]] }, s = [[Jaheira est enfermée dans une cage de la salle où vous vous êtes réveillé. Sa serrure magique ne peut pas être crochetée.
Explorez le premier niveau du donjon, en combattant ses gardiens et en fouillant pièces et contenants, jusqu'à trouver la clef.
Retournez à sa cage et utilisez la clef : Jaheira est libérée et peut rejoindre le groupe.]] },
[74418] = { g = [[bg2]], k = [[companion]], o = 0, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[La cellule de Minsc est soudée : pas de clef ni de serrure à chercher.]], [[Ne perdez pas de temps à chercher un moyen de l'ouvrir.]], [[Reparlez à Minsc : sa colère et Bouh suffisent à briser la cage.]] }, s = [[Minsc est enfermé dans la même salle que vous à votre réveil, et sa cellule est soudée.
Il n'y a rien à trouver. Parlez-lui : furieux d'être enfermé, il brise lui-même sa cage avec les encouragements de Bouh.
Il peut ensuite rejoindre le groupe.]] },
[74419] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[Certaines portes du donjon sont scellées par magie, et un golem des égouts détient la solution.]], [[Le golem a besoin d'une pierre d'activation pour reprendre son travail.]], [[La pierre est posée sur une table près d'un homme torturé nommé Rielev.]] }, s = [[Parlez au golem des égouts dans le donjon d'Irenicus. Il ouvrira les portes scellées de ce niveau si vous lui apportez une pierre d'activation.
Trouvez la salle de Rielev, l'une des expériences torturées d'Irenicus, et prenez la pierre sur la table près de lui.
Revenez voir le golem avec la pierre. Il reprend son travail et ouvre les portes scellées, ce qui vous permet de continuer l'exploration.]] },
[74420] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[Un prisonnier nommé Frennedan est enfermé dans une cage de verre du donjon d'Irenicus.]], [[La clef de sa cage est dans un coffre de la salle principale, juste à côté.]] }, s = [[Parlez à Frennedan, retenu dans une cage de verre du donjon d'Irenicus, et acceptez de le libérer.
Fouillez les coffres de la salle principale voisine jusqu'à trouver la clef.
Utilisez-la sur sa porte pour le libérer.
Le libérer ne coûte rien et constitue une petite bonne action sur le chemin de la sortie.]] },
[74421] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, Promenade de Waukyne]], h = { [[Ceux qui entrent sous le chapiteau de la Promenade de Waukyne n'en ressortent pas ; le garde vous laisse entrer.]], [[À l'intérieur, rien n'est ce qu'il semble ; une elfe ailée en cage a besoin d'une épée détenue par des paysans illusoires.]], [[Trouvez et tuez Kalah, le gnome illusionniste derrière tout cela, pour rendre le chapiteau normal.]] }, s = [[Parlez au garde devant le chapiteau de la Promenade de Waukyne et entrez. Le chapiteau est devenu un labyrinthe d'illusions.
Explorez-le et parlez à ses étranges habitants. Une elfe ailée en cage vous demande une épée portée par des paysans illusoires ; obtenez-la pour la délivrer de l'illusion. C'est Aerie.
Dissipez ou percez les illusions et frayez-vous un chemin jusqu'à l'illusionniste, le gnome Kalah. Battez-le : il use d'illusions et d'images miroir, prévoyez de quoi les percer.
Kalah mort, le chapiteau redevient normal et ses victimes sont libérées. Aerie peut rejoindre le groupe.]] },
[74422] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, Promenade de Waukyne]], h = { [[Un petit garçon pleure devant le chapiteau de la Promenade de Waukyne : sa mère est restée à l'intérieur.]], [[Vous la trouverez, mais transformée par la magie de l'illusionniste.]], [[Seule la mort de Kalah, le gnome illusionniste, lui rend sa vraie forme.]] }, s = [[Parlez au garçon perdu devant le chapiteau de la Promenade de Waukyne : sa mère est entrée sous le chapiteau et n'en est jamais ressortie.
Entrez sous le chapiteau (voir la quête du chapiteau). Vous trouvez la mère, mais elle a été transformée comme le reste du cirque.
Battez Kalah, le gnome illusionniste. Sa mort brise le sort : la mère retrouve sa forme normale et part aussitôt retrouver son fils.]] },
[74423] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, bas quartiers (Couronne de Cuivre)]], h = { [[La Couronne de Cuivre, dans les bas quartiers, utilise des esclaves comme combattants dans son arène.]], [[Le belluaire, de l'autre côté de l'arène, détient la clef de la cellule de Hendak.]], [[D'autres esclaves, des enfants, sont détenus dans un bateau en cale sèche à l'est des bas quartiers, via un tunnel des égouts.]] }, s = [[À l'auberge de la Couronne de Cuivre (bas quartiers), descendez vers l'arène et parlez à l'esclave Hendak dans sa cellule. Acceptez de libérer les siens.
Traversez l'arène jusqu'au belluaire et prenez sa clef, de force si nécessaire. Libérez Hendak et les gladiateurs ; ils se retournent contre le propriétaire, Lehtinan, et ses gardes. Aidez-les à tuer Lehtinan.
Hendak vous parle alors d'autres esclaves détenus dans un bateau en cale sèche à l'est des bas quartiers. Trouvez le tunnel des égouts qui relie l'auberge au repaire des esclavagistes.
Combattez les esclavagistes et libérez les enfants. Retournez voir Hendak, désormais à la tête de la Couronne de Cuivre, pour votre récompense.]] },
[74424] = { g = [[bg2]], k = [[main]], o = 36, c = [[2]], w = [[Athkatla, bas quartiers]], h = { [[Gaelan Bayle, rencontré dans les bas quartiers, sait quelque chose sur la capture d'Imoen.]], [[Sa maison est à l'extrémité est des bas quartiers ; son prix est de 20 000 pièces d'or.]], [[Une fois payé, utilisez sa clef sur la porte secrète juste à droite de l'entrée de la guilde des voleurs.]] }, s = [[Gaelan Bayle vous aborde dans les bas quartiers et vous conduit chez lui, à l'extrémité est du quartier.
À l'intérieur, il propose l'aide d'un groupe puissant, les Voleurs de l'Ombre, pour retrouver Imoen. Ils devraient s'opposer aux Mages Cagoulés, d'où un prix de 20 000 po.
Rassemblez l'or en accomplissant des quêtes dans Athkatla et les régions voisines, puis retournez voir Gaelan pour payer.
Il vous remet une clef. Allez à la guilde des Voleurs de l'Ombre, dans le quartier des quais, et utilisez la clef sur l'entrée secrète immédiatement à votre droite en entrant pour rencontrer leur chef. Le chapitre 3 commence.]] },
[74425] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, quartier des quais / guilde de Mae'Var]], h = { [[Renal Scalpesang, des Voleurs de l'Ombre, veut un espion dans la guilde de son subalterne Mae'Var.]], [[Accomplissez les missions de Mae'Var et d'Edwin pour gagner leur confiance ; épargner le traître Embarl vous donne une piste.]], [[Edwin sait qui vous êtes : prenez la lettre dans le coffre des appartements de Mae'Var et apportez-la à Renal.]] }, s = [[Renal Scalpesang, à la guilde des Voleurs de l'Ombre (quais), vous donne des papiers et vous envoie voir Gorch à la boutique de Mae'Var. Gorch vous fait passer par la porte du fond.
Première tâche de Mae'Var : voler la statuette en or du temple de Lathandre, ou l'amulette de la Maîtresse des Tempêtes de Talos (elle l'ôte la nuit).
Puis son assistant Edwin, au troisième étage, vous envoie tuer le Mage Cagoulé Rayic Gethras (maison grise, ouest des quais ; allez-y quand sa porte est ouverte) et récupérer les documents de Marcus à la Bonté Marine.
Enfin, Mae'Var ordonne la mort d'Embarl, au deuxième étage de la Bonté Marine. Rapportez sa dague ; l'épargner révèle le complot de Mae'Var contre Renal.
Edwin vous donne alors la clef, ou vous rejoint : prenez la lettre dans le coffre des appartements de Mae'Var (deuxième étage) et portez-la à Renal. Tuez Mae'Var comme Renal le demande, puis touchez votre récompense.]] },
[74426] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du gouvernement / quartier du pont]], h = { [[Sire Ryan Trawl, de l'Ordre du Cœur Radieux, veut que vous infiltriez les Paladins déchus.]], [[Leur membre Reynald de Châtillon, au quartier du pont, veut une coupe que l'Ordre conserve encore.]], [[Demandez la coupe d'Anarg à sire Ryan, servez-vous-en pour approcher Anarg, et réglez le sort de son groupe.]] }, s = [[À l'Ordre du Cœur Radieux, sire Ryan Trawl vous engage pour trouver les Paladins déchus, menés par l'ancien chevalier Anarg, dans le quartier du pont.
Au quartier du pont, trouvez Reynald de Châtillon. Il vous mènera à Anarg si vous lui apportez la coupe d'Anarg, encore détenue par l'Ordre.
Retournez voir sire Ryan, qui vous remet la coupe à contrecœur. Donnez-la à Reynald et suivez-le jusqu'à la cachette d'Anarg.
Les Paladins déchus sont une menace : combattez Anarg et ses hommes (plusieurs guerriers à la fois, soyez prêt). Faites votre rapport à sire Ryan et rendez la coupe.
Récompense : réputation et la bienveillance de l'Ordre.]] },
[74427] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du pont]], h = { [[Le lieutenant Aegisfield, au quartier du pont, enquête sur les meurtres de l'écorcheur et cite trois témoins.]], [[Rose se souvient d'une odeur et Rampah a trouvé un cuir étrange ; le marchand Bel peut identifier les deux.]], [[L'écorce de chêne et la peau d'éléphant désignent le tanneur du quartier ; ne laissez pas le lieutenant y aller seul.]] }, s = [[Parlez au lieutenant Aegisfield au quartier du pont. Il cite le garçon Faraji, le mendiant Rampah et la courtisane Rose.
Faraji soupçonne madame Rochelune, une magicienne inoffensive : fausse piste. Rampah vous donne un morceau de cuir étrange. Rose se souvient d'une odeur proche des baies de guril.
Montrez le cuir au marchand Bel : de la peau d'éléphant. Parlez-lui de l'odeur : il vous donne trois échantillons. Rose choisit l'écorce de chêne, utilisée pour tanner.
Les indices désignent le tanneur Rejiek. Si vous prévenez Aegisfield, il y va seul et se fait tuer. Mieux vaut aller vous-même à la tannerie.
À la tannerie, Rejiek et le magicien Vellin Dahn vous attaquent ; le mage fait disparaître Rejiek. Fouillez les lieux, puis faites votre rapport à Aegisfield (ou à ses supérieurs) pour clore l'affaire.]] },
[74428] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, auberge de Delosar]], h = { [[Un ivrogne nommé Vittorio vous arrête dans la rue en prétendant que le capitaine Dennis lui doit de l'argent.]], [[Accompagnez Vittorio au deuxième étage de l'auberge de Delosar pour confronter Dennis.]], [[Écoutez Dennis avant de vous battre : la dette est inverse, et vous pouvez l'aider à la place.]] }, s = [[Vittorio, un ivrogne, vous demande de l'aide pour récupérer une dette auprès du capitaine Dennis. Accompagnez-le au deuxième étage de l'auberge de Delosar.
Dennis explique que Vittorio a volé le gong de sa mère. À vous de choisir :
Prendre le parti de Vittorio et combattre Dennis et ses hommes ; Vittorio s'enfuit une fois qu'ils sont morts.
Laisser Dennis régler son compte à Vittorio, qui finit tué.
Ou, meilleure issue, proposer de retrouver le gong pour Dennis : cela lance la quête du gong, et Dennis garde Vittorio jusqu'à votre retour.]] },
[74429] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, égouts / près de Franc-Marché]], h = { [[Vittorio a vendu le gong de Dennis à Roger, un receleur des égouts d'Athkatla.]], [[Le gong est passé de main en main : une chamane troll près de Franc-Marché, puis un mage ogre voisin.]], [[Drush le mage ogre échangera le gong contre n'importe quelle baguette de givre.]] }, s = [[Le capitaine Dennis garde Vittorio pendant que vous cherchez le gong de sa mère. Trouvez Roger le receleur dans les égouts d'Athkatla ; tuez pour lui un troll de mer (achevez-le au feu ou à l'acide), et il vous dit avoir vendu le gong à la chamane troll Grae.
Allez au tertre troll près de Franc-Marché. Grae est gardée par des trolls ; prévoyez feu et acide. Elle a vendu le gong à Drush, un mage ogre qui vit dans une tour voisine.
Drush se sert du gong comme pelle et veut une baguette de givre en échange. Apportez-lui n'importe quelle baguette de givre (il cite une sorcière nommée Adratha comme source possible).
Rapportez le gong malodorant à Dennis, à l'auberge de Delosar d'Athkatla. Il libère Vittorio et vous récompense.]] },
[74430] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du cimetière / quartier du pont]], h = { [[Tirdir, tout juste sorti d'une tombe, a été enterré vivant par trois ravisseurs.]], [[Le gardien du cimetière, Sethle, ferme les yeux ; interrogez-le sur l'homme en rouge.]], [[Trouvez l'homme en rouge au quartier du pont, suivez-le dans sa maison et réglez son compte aux ravisseurs.]] }, s = [[Au quartier du cimetière, parlez à Tirdir, un homme enterré vivant par des ravisseurs. Il vous donne un morceau du manteau rouge de l'un d'eux et soupçonne le gardien du cimetière.
Interrogez le gardien Sethle : il avoue fermer les yeux et dit qu'on peut trouver l'homme en rouge au quartier du pont.
Au quartier du pont, trouvez l'homme vêtu de rouge. Il s'enfuit dans une maison : suivez-le jusqu'à la cachette des ravisseurs.
Battez les ravisseurs et libérez leur victime du moment, Dame Elgea. Vous pouvez aussi tenter d'encaisser la rançon au lieu de simplement la libérer, un choix moins honorable.]] },
[74431] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du cimetière / Couronne de Cuivre]], h = { [[La nuit, le fantôme d'un garçon halfelin erre dans le cimetière.]], [[Wellyn veut son ours en peluche, Petit Homme, pris par le voleur qui l'a tué.]], [[Le voleur Llynis loge à la Couronne de Cuivre ; rapportez l'ours au fantôme.]] }, s = [[Allez au quartier du cimetière la nuit et parlez à l'esprit de Wellyn, un enfant halfelin assassiné. Il réclame son ours en peluche, Petit Homme.
Rendez-vous à la Couronne de Cuivre, dans les bas quartiers, et trouvez le voleur Llynis dans l'une des chambres. Obtenez l'ours, par la parole ou par la force.
Retournez au cimetière la nuit et donnez l'ours à Wellyn. Son esprit peut enfin reposer en paix. Vous gagnez de l'expérience.]] },
[74432] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du cimetière]], h = { [[Arenthis, un prêtre de Lathandre au cimetière, cherche un tuteur pour l'orpheline Risa.]], [[Quelqu'un d'autre dans le même quartier pleure la perte d'un enfant.]], [[Parlez à Arenthis du paladin Kamir, puis réunissez-les.]] }, s = [[Au quartier du cimetière, parlez à Arenthis, un prêtre de Lathandre qui veille sur l'orpheline Risa. Il cherche quelqu'un de noble pour l'élever.
Toujours au cimetière, parlez à Kamir, un paladin qui pleure le fils adoptif qu'il n'a pas su protéger.
Retournez voir Arenthis et parlez-lui de Kamir. Arenthis pense que le paladin ferait un excellent tuteur.
Réunissez-les : Kamir accepte d'élever Risa, et ils partent ensemble. Cela apaise aussi le chagrin de Kamir.]] },
[74433] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du cimetière]], h = { [[Un paladin brisé nommé Kamir pleure son fils adoptif au cimetière.]], [[Un prêtre tout proche cherche un tuteur pour une petite orpheline.]], [[Confier à Kamir un enfant à protéger pourrait lui permettre de se racheter.]] }, s = [[Parlez à Kamir au quartier du cimetière. Il n'a pas su protéger son fils adoptif, a rompu son vœu et est rongé par le chagrin.
Cela se règle avec la quête de l'orpheline Risa : parlez à Arenthis, le prêtre de Lathandre tout proche, qui veille sur Risa. Parlez-lui de Kamir.
Réunissez Kamir et Risa. Le paladin accepte d'élever la fillette et trouve un nouveau but.]] },
[74434] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier des temples]], h = { [[Un prêtre sans yeux prêche l'Œil Aveugle dans le quartier des temples.]], [[Les temples établis s'inquiètent de ce nouveau culte ; interrogez leurs prêtres.]], [[Le vrai maître du culte se cache sous la ville, dans les égouts du quartier des temples.]] }, s = [[Dans le quartier des temples, vous voyez un prêtre sans yeux, Gaal, prêcher à la foule l'arrivée d'un nouveau dieu, l'Œil Aveugle. Cette entrée ne note que cette première rencontre.
Pour aller plus loin, parlez aux prêtres des temples du quartier, qui veulent qu'on enquête sur le culte.
La piste mène aux égouts du quartier des temples, où le culte vénère un tyrannœil. Préparez-vous à un combat difficile : rayons du tyrannœil et nombreux fidèles.]] },
[74435] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, bas quartiers (maison des Jansen)]], h = { [[Voyagez avec Jan et son cousin Beeloo le rappellera chez lui, dans les bas quartiers.]], [[La fille de Lissa se meurt ; l'oncle de Jan, Gerhardt, vous envoie vers Dame Jysstev et un être nommé l'Obscur.]], [[L'Obscur veut que deux chasseurs soient tués : dites être un « Ascète » à la Bonté Marine, puis allez aux Cinq Chopes.]] }, s = [[Avec Jan dans le groupe, son cousin Beeloo lui dit qu'on a besoin de lui chez lui, dans les bas quartiers. Allez-y avec lui : son ancien amour Lissa est venue avec sa fille malade, Jaella. Parlez à Lissa dans l'ancienne chambre de Jan.
À la cave, l'oncle Gerhardt affirme que seul l'Obscur peut la guérir, et que Dame Jysstev, dans sa propriété du quartier du gouvernement, peut organiser une rencontre. Vous avez environ dix jours.
Convainquez Dame Jysstev, puis allez dans les égouts sous la Couronne de Cuivre rencontrer l'Obscur. Il veut que deux chasseurs soient tués.
À la Bonté Marine (quais), dites être un « Ascète ». Le tavernier vous envoie au deuxième étage des Cinq Chopes (quartier du pont) : les chasseurs sont des githyankis. Tuez-les, retournez voir l'Obscur, puis Jan.
Jaella est guérie, mais Lissa retourne auprès de son mari Vaelag. Gardez Jan ou laissez-le chez lui. Si vous arrivez trop tard, Jaella meurt.]] },
[74436] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du gouvernement]], h = { [[Keldorn n'a pas vu sa famille depuis longtemps : emmenez-le chez lui avant qu'il n'y aille seul.]], [[Sa femme Maria fréquente un autre homme, Sire William de Thorpe, un habitué du Bonrepos.]], [[Poussez Keldorn au pardon et à la réconciliation plutôt qu'à la justice ou à la vengeance.]] }, s = [[Après un moment dans le groupe, Keldorn demande à visiter son domaine du quartier du gouvernement. Allez-y vite avec lui, sinon il part seul et vous attend dans les locaux du Cœur Radieux.
Chez lui, il apprend que Maria fréquente Sire William de Thorpe. Il veut alors l'affronter au Bonrepos, sur la Promenade de Waukyne.
L'issue dépend de vos conseils :
- Poussez-le à se réconcilier et à se remettre en cause : il parle à Maria puis vous rejoint (meilleure issue).
- Prônez la loi : Maria et William sont emprisonnés, sa famille le quitte.
- Prônez la vengeance : il tue William et Maria part avec les enfants.
- Conseillez-lui de rester avec sa famille pour de bon : il quitte le groupe.]] },
[74437] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Franc-Marché]], h = { [[Avec Mazzy dans le groupe, rendez visite à sa sœur Pala à Franc-Marché.]], [[Le filtre d'amour vient de Wallace, un camelot gnome de la place du marché, mais il ne l'a pas préparé.]], [[Demandez au supérieur du temple de Waukyne de fouiller les appartements de l'acolyte Barl.]] }, s = [[Emmenez Mazzy à Franc-Marché : elle apprend que Pala a été empoisonnée par un filtre d'amour acheté par son fiancé Danno.
Allez sur la place du marché et trouvez Wallace, le camelot gnome. Il révèle son nouveau fournisseur : Barl, un acolyte du temple de Waukyne de Franc-Marché.
Parlez au supérieur du temple. Il peut d'abord exiger un don de 300 pièces d'or. Il fouille les appartements de Barl et y trouve du matériel d'alchimie et un symbole sacré de Talona.
Barl attaque : tuez-le et prenez l'antidote sur son corps. Pala est guérie.
Laissez Mazzy passer la nuit avec sa sœur. Si vous partez sans attendre, elle reste à Franc-Marché jusqu'à ce que vous reveniez la chercher.]] },
[74438] = { g = [[bg2]], k = [[side]], o = 0, c = [[any]], w = [[Inconnu]], h = { [[Aucun dialogue ni script n'écrit cette entrée : il s'agit sans doute de contenu inutilisé.]], [[La seule entrée parle des six morceaux du masque mortuaire du roi Strohm, déjà reconstitué.]] }, s = [[Cette quête n'a aucun déclencheur connu dans les fichiers du jeu : aucun dialogue ni script n'écrit son entrée de journal. Il s'agit très probablement de contenu coupé, impossible à lancer normalement.
Sa seule entrée dit que les six morceaux du masque mortuaire du roi Strohm ont été retrouvés et reconstitués, sans dire à quoi sert le masque.
Si elle apparaît dans votre journal, un mod l'a sans doute ajoutée : consultez la documentation de ce mod.]] },
[74439] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, guilde de Mae'Var]], h = { [[Un voleur qui tue Mae'Var pour Renal Scalpesang reçoit la guilde de Mae'Var à diriger.]], [[Passez à la guilde environ tous les cinq jours, affectez vos voleurs et payez toujours le questeur.]], [[Quand des voleurs à la tire volent la guilde, bloquer tous les salaires est le plus sûr ; méfiez-vous d'Ama.]] }, s = [[Quartier général des voleurs : accomplissez les missions de Renal Scalpesang et tuez Mae'Var. Renal vous confie alors la guilde de Mae'Var.
Allez-y et parlez à Jariel : chaque semaine vous choisissez les activités de vos voleurs et leur risque, puis touchez les profits. Payez le questeur environ tous les cinq jours, sinon la guilde est fermée (Renal peut vous réintégrer, très cher).
Événements :
- Ama vous demande de servir d'appât pour une embuscade, la nuit, sur la Promenade de Waukyne. C'est un piège au nom de Mae'Var : préparez-vous au combat. Vous pouvez ensuite renvoyer Lathan, qui s'était porté garant d'elle.
- Un des voleurs à la tire de Kretor vole la guilde. Bloquez tous leurs salaires : le coupable est éliminé. En tuer un est un pari ; les tuer tous ou ne rien faire pousse Kretor à démissionner.]] },
[74440] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du cimetière]], h = { [[Gardez Edwin dans le groupe : il se souviendra d'une vieille légende sur un Parchemin Néthère.]], [[Le parchemin serait caché dans l'une des tombes du quartier du cimetière.]], [[Fouillez les tombes du quartier du cimetière avec Edwin et laissez-le étudier votre trouvaille.]] }, s = [[Après un moment à Athkatla avec Edwin, il évoque le Parchemin Néthère, peut-être caché dans une tombe du quartier du cimetière.
Explorez les tombes sous le quartier du cimetière avec Edwin dans le groupe et fouillez les conteneurs jusqu'à trouver le Parchemin Néthère.
Edwin l'étudie. Le résultat n'est pas celui qu'il espérait : le parchemin le transforme, ce qui mène à la quête du magicien rouge Degardan (Les Magiciens Rouges pourchassent Edwin ?).
Il n'y a pas d'autre récompense que l'histoire qui suit.]] },
[74441] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla]], h = { [[Suite du Parchemin Néthère : un magicien rouge nommé Degardan recherche Edwin.]], [[Protégez Edwin la première fois que vous rencontrez Degardan.]], [[Continuez à voyager avec Edwin : Degardan reviendra et pourra défaire l'effet du parchemin.]] }, s = [[Après la transformation d'Edwin par le Parchemin Néthère, le magicien rouge Degardan aborde le groupe à Athkatla. Il cherche Edwin, dont la tête est mise à prix au Thay.
Protégez Edwin et éconduisez Degardan.
Gardez Edwin dans le groupe. Plus tard, Degardan revient et sa magie rend à Edwin sa vraie forme. Démasqué, Edwin l'attaque aussitôt : aidez-le à tuer Degardan.
Edwin redevient lui-même ; la raison de cette traque par les Magiciens Rouges reste un mystère.]] },
[74442] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du pont]], h = { [[Un théâtre se trouve sous l'auberge des Cinq Chopes, dans le quartier du pont.]], [[Passez en coulisses du théâtre et parlez à Raelis Shai.]] }, s = [[Entrez dans l'auberge des Cinq Chopes, dans le quartier du pont, et descendez au théâtre qui se trouve en dessous. Regardez la pièce ou non, puis passez en coulisses.
Parlez à Raelis Shai, la directrice de la troupe. Elle demande de l'aide : le barde Haer'Dalis est retenu par le magicien Mekrath, ainsi qu'une gemme qu'elle veut récupérer.
Acceptez pour lancer la quête Secourir Haer'Dalis et sa gemme des griffes de Mekrath. Raelis propose en paiement l'acte de propriété du théâtre (utile pour un barde) ou 1 000 pièces d'or.]] },
[74443] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Donjon d'Irenicus]], h = { [[Dans le donjon d'Irenicus, un homme mutilé flotte dans une cuve, maintenu en vie malgré lui.]], [[Parlez à Rielev et acceptez de mettre fin à ses souffrances en arrêtant la machine.]] }, s = [[Explorez le donjon d'Irenicus au début du jeu. Dans l'un des laboratoires se trouve Rielev, qui flotte dans une cuve de survie.
Parlez-lui : il supplie qu'on le libère. Acceptez et arrêtez la machine.
Rielev meurt en paix. Prenez le cristal qui alimentait la cuve : il dit qu'il peut activer d'autres serviteurs gardés dans des machines semblables, ce qui sert ailleurs dans le donjon.]] },
[74444] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, théâtre des Cinq Chopes]], h = { [[Raelis Shai, en coulisses du théâtre des Cinq Chopes, veut récupérer Haer'Dalis et une gemme chez Mekrath.]], [[Le magicien Mekrath garde des tieffelins à son service ; Haer'Dalis est l'un d'eux.]], [[Rapportez Haer'Dalis et la gemme à Raelis pour gagner l'acte du théâtre ou de l'or.]] }, s = [[Acceptez la demande de Raelis Shai dans le théâtre sous l'auberge des Cinq Chopes (quartier du pont).
Rendez-vous dans l'antre du magicien Mekrath. Haer'Dalis le sert sous la contrainte. Attendez-vous à un combat difficile contre Mekrath et ses gardiens invoqués ; préparez des protections magiques.
Libérez Haer'Dalis (il peut rejoindre le groupe) et prenez la gemme.
Retournez voir Raelis : choisissez l'acte de propriété du théâtre (quartier général des bardes) ou 1 000 pièces d'or.
Le journal prévoit aussi une issue égoïste où vous empochez sa récompense sans l'aider.]] },
[74445] = { g = [[bg2]], k = [[main]], o = 41, c = [[3]], w = [[Athkatla, quartier des quais et quartier du cimetière]], h = { [[L'or versé à Gaelan vous obtient une audience avec Aran Linvail, qui exige des services avant de vous aider à trouver Imoen.]], [[Gardez l'entrepôt avec Mook la nuit, puis faites-vous passer pour une recrue au dernier étage des Cinq Chopes.]], [[La guilde rivale se cache dans les tombes sous le quartier du cimetière ; emportez les pieux d'Aran.]] }, s = [[Voie des Voleurs de l'Ombre au chapitre 3.
1. Aran Linvail (quartier des quais) vous envoie la nuit sur les quais retrouver Mook près d'un entrepôt. Un inconnu la tue et vous attaque, puis s'enfuit sous forme de brume : un vampire. Faites votre rapport à Aran le matin.
2. Montez au dernier étage de l'auberge des Cinq Chopes (quartier du pont). Faites-vous passer pour une recrue auprès des traîtres Jaylos et Caehan, puis occupez-vous de leur contact Gracen. Vous apprenez que la guilde rivale est dans le quartier du cimetière.
3. Aran nomme leur chef, la vampire Bodhi, et vous donne des pieux. Dans les tombes sous le quartier du cimetière, un mage et son golem ouvrent les portes bleues au nord du nid d'araignées. Nettoyez l'antre des vampires ; prévoyez Protection contre le mal et de quoi soigner les absorptions de niveau. Bodhi s'échappe.
4. Faites votre rapport à Aran : il révèle où Imoen est retenue et organise votre traversée en bateau.]] },
[74446] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier des quais]], h = { [[Un homme empoisonné nommé Renfeld erre dans le quartier des quais en demandant de l'aide.]], [[Son ami Rylock attend devant un bâtiment au sud-ouest du quartier des quais.]], [[Conduisez-y Renfeld rapidement, sinon il meurt en chemin.]] }, s = [[Dans le quartier des quais, parlez à Renfeld, un homme empoisonné, et acceptez de le ramener à ses amis.
Conduisez-le au bâtiment du sud-ouest du quartier, devant lequel se tient Rylock. Ne traînez pas en chemin.
Si Renfeld arrive vivant, Rylock est heureux de le revoir. S'il est mort en route, Rylock vous donne quand même une petite récompense.
Le bâtiment est un fortin des Ménestrels : peu après, Xzar vous aborde, ce qui lance Découvrir ce qui est arrivé à Montaron.]] },
[74447] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier des quais, fortin des Ménestrels]], h = { [[Après avoir ramené Renfeld, Xzar vous demande de découvrir ce que les Ménestrels ont fait de Montaron.]], [[Rylock vous laisse entrer une fois les créatures de la maison du mage Prebek, au centre du quartier, éliminées.]], [[Les gardiens de l'étage épargnent ceux qui portent la broche des Ménestrels ; cherchez Montaron en hauteur.]] }, s = [[Xzar raconte que Montaron s'est introduit chez les Ménestrels sans jamais ressortir. Parlez à Rylock devant la porte.
En guise d'épreuve, allez à la petite maison de Prebek, au centre du quartier des quais, tuez les créatures qui s'y trouvent et revenez. Vous pouvez entrer dans le fortin des Ménestrels, mais seulement au rez-de-chaussée.
L'étage est protégé par de dangereux gardiens. Trouvez une broche des Ménestrels dans le fortin et portez-la pour passer.
À l'étage, un oiseau en cage serait Montaron. Le libérer est un piège : l'oiseau est un assassin destiné à Xzar, ancien Zhentarim.
Le vrai sort de Montaron reste inconnu. Cela mène plus tard aux ennuis de Jaheira avec les Ménestrels.]] },
[74448] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier des quais, fortin des Ménestrels]], h = { [[Avec Jaheira dans le groupe, les Ménestrels s'intéressent de trop près à vous.]], [[Dermin, l'ancien mentor de Jaheira, et le Ménestrel Galvarey ne sont pas ce qu'ils semblent être.]], [[Suivez la quête de Jaheira jusqu'au bout au fortin des Ménestrels et démasquez Galvarey.]] }, s = [[Il s'agit de la fin de la quête des Ménestrels de Jaheira, qui débute après un certain temps passé avec elle.
Dermin, son ancien mentor, l'aborde ; le Ménestrel Galvarey vous accuse ensuite d'être un danger parce que vous êtes un enfant de Bhaal.
Suivez les pistes que reçoit Jaheira et allez au fortin des Ménestrels, dans le quartier des quais. Le complot y éclate : Galvarey est un opportuniste qui use de son rang pour le pouvoir, et Dermin était son complice. Combattez Galvarey et ses alliés.
La quête se termine sur cette entrée ; on ignore si d'autres Ménestrels poursuivront Jaheira.]] },
[74449] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, bas quartiers]], h = { [[Un gnome bavard qui a des ennuis avec la garde peut devenir un compagnon.]], [[Si vous n'avez pas emmené Jan Jansen, cherchez-le chez sa famille dans les bas quartiers.]] }, s = [[À Athkatla, vous croisez Jan Jansen, un escroc gnome interrogé par les autorités. Menez la discussion de façon à le tirer d'affaire.
Si vous ne l'invitez pas tout de suite dans le groupe, il rentre chez lui : la maison de la famille Jansen, dans les bas quartiers, où il prétend vendre des navets.
Passez chez lui quand vous voulez et parlez à Jan pour le recruter. Sa famille et ses quêtes personnelles se trouvent là.]] },
[74450] = { g = [[bg2]], k = [[companion]], o = 0, c = [[1-2]], w = [[Donjon d'Irenicus, puis Athkatla]], h = { [[Vous avez refusé le voleur Yoshimo dans le donjon d'Irenicus, mais il s'évade lui aussi.]], [[Une fois dehors, cherchez-le dans une taverne proche de la sortie du donjon.]] }, s = [[Dans le donjon d'Irenicus, vous avez rencontré Yoshimo sans le laisser se joindre à vous. Il s'échappe par ses propres moyens.
Après votre évasion sur la Promenade de Waukyne, cherchez-le dans une taverne voisine et parlez-lui : il propose toujours de vous rejoindre.
Réfléchissez avant de compter sur lui à long terme ; son histoire est liée à l'intrigue principale.]] },
[74451] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du gouvernement]], h = { [[Cette quête note comment la crise familiale de Keldorn s'est conclue par une réconciliation.]], [[S'il a quitté le groupe, cherchez-le dans son domaine du quartier du gouvernement.]] }, s = [[Suite de Keldorn aimerait rendre visite à sa femme et à sa famille, quand il s'estime fautif et se réconcilie avec Maria.
- Si vous lui avez dit de partir pour reconstruire sa famille, il quitte le groupe. Selon le dialogue, vous pourrez le retrouver dans son domaine du quartier du gouvernement.
- S'il promet que sa mission avec vous sera la dernière avant de quitter l'Ordre, Maria accepte et il reste avec vous : la meilleure issue pour le garder.]] },
[74452] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Promenade de Waukyne]], h = { [[C'est une mauvaise fin de la quête familiale de Keldorn.]], [[Ne transformez pas la rencontre avec Sire William en un combat que vous déclenchez : l'honneur de Keldorn le pousse à le défendre.]] }, s = [[Pendant la quête familiale de Keldorn, la confrontation avec Sire William de Thorpe a mal tourné : son sens de la justice l'a poussé à défendre William, et il est mort.
Keldorn est perdu pour de bon. Pour éviter cela, rechargez avant la rencontre et orientez-le vers la réconciliation avec Maria, ou laissez la loi s'en charger au lieu d'attaquer William vous-même.]] },
[74453] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, quartier du temple]], h = { [[Un paladin du Cœur Radieux fouille les égouts sous le quartier du temple à la recherche du même culte que vous.]], [[Une fois l'affaire du culte réglée, retrouvez Keldorn dans les locaux du Cœur Radieux, dans le quartier du temple.]] }, s = [[Dans les égouts sous le quartier du temple, en enquêtant sur le culte, vous rencontrez Sire Keldorn, un paladin du Très Noble Ordre du Cœur Radieux.
Si vous ne l'emmenez pas tout de suite, il retourne à l'Ordre.
Une fois le culte réglé, ou quand vous le voulez, allez aux locaux du Cœur Radieux dans le quartier du temple et parlez à Keldorn pour le recruter.]] },
[74454] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Franc-Marché et le bosquet des druides]], h = { [[Flydian, aux portes de la ville, cherche de l'aide pour Franc-Marché, assiégée par des animaux ; on soupçonne les druides.]], [[Le Seigneur Logan Coprith veut que vous parliez au druide Cernd, emprisonné sous la maison du maire.]], [[Faldorn règne sur le bosquet au sud de la ville et ne peut être vaincue que par un défi druidique : Cernd, Jaheira ou un héros druide.]] }, s = [[Acceptez d'aider Flydian, puis rendez-vous à Franc-Marché, au sud-est d'Athkatla. Restez courtois avec la capitaine de la milice à l'entrée.
Voyez le Haut-Marchand, le Seigneur Logan Coprith. Il vous demande de parler au druide Cernd, enfermé au sous-sol de la maison du maire. Cernd soupçonne le bosquet au sud de la ville et peut vous rejoindre.
Dans le bosquet des druides, un druide vous apprend que la druidesse de l'ombre Faldorn le contrôle et s'est liée à la terre : elle est invulnérable sauf face au défi d'un druide.
Défiez-la avec Cernd, Jaheira ou votre propre druide. Gagnez le duel : les attaques cessent et Logan vous récompense. Un héros druide se voit aussi offrir le bosquet comme quartier général.
Option maléfique : le Seigneur Khellon Menold vous donne un poison pour la source sacrée des druides ; tuez alors les druides pour lui.]] },
[74455] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Collines de Lancevent]], h = { [[Le dragon Firkraag peut proposer un marché plutôt qu'un combat.]], [[Il veut le titre de propriété des Collines de Lancevent, détenu par Garren Lancevent.]], [[Prenez le titre à Garren, par la force s'il le faut, et apportez-le dans l'antre de Firkraag.]] }, s = [[Option maléfique dans les Collines de Lancevent. Dans l'antre de Firkraag, acceptez le marché du dragon rouge au lieu de le combattre.
Il veut le titre de propriété des Collines de Lancevent. Garren Lancevent, qui vit dans les Collines de Lancevent, le possède. Il refuse de le céder : prenez-le par la force.
Rapportez le titre à Firkraag dans son antre pour terminer la mission (voir La mission de Firkraag est terminée). Attendez-vous à perdre de la réputation en vous rangeant du côté du dragon.]] },
[74456] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Collines de Lancevent, antre de Firkraag]], h = { [[Cette quête clôt le marché avec le dragon Firkraag.]], [[Remettez-lui le titre de Lancevent dans son antre pour obtenir votre récompense.]] }, s = [[Après avoir pris le titre des Collines de Lancevent à Garren Lancevent, retournez dans l'antre de Firkraag et donnez-le-lui.
Il vous récompense avec une cape magique et vous conseille de partir.
À noter : un paladin du Cœur Radieux est ensuite chargé de tuer Firkraag pour sa Sainte Lame ; vous pouvez toujours revenir l'affronter.]] },
[74457] = { g = [[bg2]], k = [[side]], o = 0, c = [[4]], w = [[Brynnlaw]], h = { [[Sur l'île des pirates, la courtisane Ginia est forcée de servir parce que Chremy retient son frère.]], [[Calahan, un contrebandier près des quais, peut faire quitter l'île à Ginia et à son frère moyennant finance.]], [[Payez Calahan et occupez-vous de Chremy près de l'auberge, puis prévenez Ginia.]] }, s = [[À Brynnlaw, parlez à Ginia : Desharik s'est emparé de l'île et Chremy retient son frère pour la forcer à être courtisane. Acceptez de l'aider.
Trouvez le contrebandier Calahan près des quais et payez-lui 200 pièces d'or pour emmener Ginia et son frère.
Trouvez Chremy près de l'auberge et tuez-le, pour qu'il ne puisse pas s'y opposer.
Retournez voir Ginia une fois les deux choses faites : elle est aux anges. Si vous tuez Chremy sans payer Calahan, elle reste coincée sur l'île.]] },
[74458] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, quartier des quais]], h = { [[Un crâne doré du quartier des quais promet des richesses si vous lui rendez son corps.]], [[Ses bras, ses jambes et son torse sont dispersés dans des tombes de la ville.]], [[Réfléchissez bien : le crâne est une liche, et le reconstituer mène à un combat très difficile.]] }, s = [[Dans le quartier des quais, vous rencontrez un crâne doré parlant, Kangaxx, qui promet richesse et pouvoir si vous levez sa malédiction et lui rendez son corps.
Fouillez les tombes de la ville pour trouver ses bras, ses jambes et son torse, puis rapportez-les au crâne.
Une fois entier, il redevient une liche et attaque aussitôt avec de puissants sorts. N'acceptez que si votre groupe est prêt pour un combat magique de haut niveau ; sinon, laissez le crâne tranquille.
Le journal ne précise pas où se trouvent les morceaux du corps.]] },
[74459] = { g = [[bg2]], k = [[main]], o = 58, c = [[6]], w = [[Forêt elfique, puis Athkatla]], h = { [[Elhan a besoin du Rhynn Lanthorn pour révéler la cité cachée de Suldanessellar.]], [[Une puissante servante d'Irenicus l'a volé ; vous connaissez son ancien repaire à Athkatla.]], [[Retournez dans les tombes sous le quartier du cimetière d'Athkatla et reprenez le Lanthorn à Bodhi.]] }, s = [[Chapitre 6. Après l'Ombre-Terre, Elhan explique qu'Irenicus a caché Suldanessellar derrière des illusions. Seul le Rhynn Lanthorn peut ouvrir le chemin.
Bodhi l'a volé. Retournez à Athkatla et entrez dans son repaire, dans les tombes sous le quartier du cimetière. Prévoyez Protection contre le mal, des pieux et une protection contre l'absorption de niveau ; tuez Bodhi pour de bon dans la salle de son cercueil et prenez le Lanthorn.
Retournez auprès d'Elhan dans la forêt elfique. Le Lanthorn vous guide dans Suldanessellar pendant que ses elfes retiennent les drows. Dans la cité, cherchez la grande prêtresse Demin.
Certaines entrées listent des panneaux du Lanthorn avec des énigmes ; elles semblent venir de contenu inachevé, c'est le Lanthorn lui-même qui ouvre la cité.]] },
[74460] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Franc-Marché]], h = { [[La capitaine de la milice, à l'entrée de Franc-Marché, se méfie beaucoup des étrangers.]], [[Restez calme avec elle et demandez ce qui ne va pas : cela mène à Problème animalier à Franc-Marché.]] }, s = [[Vous êtes arrivé à Franc-Marché sans avoir été envoyé par Flydian, et la capitaine de la milice vous a accueilli avec hostilité.
Ne la combattez pas. Parlez-lui calmement et proposez votre aide : la ville subit des attaques d'animaux attribuées aux druides. Elle vous envoie au Haut-Marchand, le Seigneur Logan Coprith, ce qui lance la quête Problème animalier à Franc-Marché.]] },
[74461] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ust Natha]], h = { [[Dans la cité drow, une drow hautaine vous donne un ordre qu'il vaut mieux ne pas refuser.]], [[Une secte d'adorateurs de Ghaunadaur se cache dans l'angle sud-est d'Ust Natha.]] }, s = [[Alors que vous êtes déguisé en drow à Ust Natha, une drow autoritaire vous ordonne de détruire une secte d'adorateurs de Ghaunadaur.
Allez à l'angle sud-est de la cité, trouvez la secte cachée et tuez ses membres.
Faites votre rapport : elle ne vous donne rien d'autre que le droit de vivre. Refuser compromettrait sans doute votre déguisement.]] },
[74462] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ust Natha]], h = { [[Un drow nommé Visaj raconte une histoire sur Jarlaxle et une corde magique.]], [[Rien dans cette affaire n'est comme on le raconte ; attendez-vous à travailler pour Jarlaxle.]], [[Jarlaxle veut des gemmes de la tour de la liche Deirex, et il a un compte à régler avec la maison Jae'llat.]] }, s = [[Cette quête ne semble pas accessible dans une partie normale : Jarlaxle ne semble pas se rencontrer dans Shadows of Amn sans mod. Il s'agit sans doute de contenu coupé ou d'un ajout de mod.
D'après le journal : Visaj prétend avoir volé à Jarlaxle une corde qui protège de l'Emprisonnement, pour piller la demeure de la liche Deirex. C'est un piège : vous voilà au service de Jarlaxle, à devoir rapporter des gemmes de la tour de la liche en un jour.
Les gemmes appartiennent en fait à la maison Jae'llat, qui a refusé de payer Jarlaxle. Vous gagnez l'accès à deux demeures drows, et la corde vous ramène.]] },
[74463] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du temple (Cœur Radieux)]], h = { [[Un héros paladin reçoit une place dans l'Ordre du Cœur Radieux, avec des missions à accomplir.]], [[Foncez aux collines d'Umar secourir les chevaliers assiégés ; à Imnesvale, interrogez tout le monde avant de soutenir le Baron Metrich.]], [[Utilisez Détection du mal sur le Baron et sur celui qui vient chercher Tyrianna ; la dernière tâche est la Sainte Lame de Firkraag.]] }, s = [[Quartier général des paladins, dans les locaux du Cœur Radieux du quartier du temple.
1. Partez tout de suite au bout des collines d'Umar et sauvez les trois chevaliers assiégés. Chaque chevalier perdu pèse sur l'Ordre.
2. Le Baron Metrich veut expulser des occupants ; rendez-vous à la taverne d'Imnesvale. Parlez à Brunson, Moreno et Pardo : ce sont des fermiers et le Baron a menti. Refusez de l'aider et défendez les fermiers pour obtenir l'approbation de l'Ordre.
3. Gardez la jeune Tyrianna Auberisée dans un refuge jusqu'à l'arrivée de son parrain Hurgis Baltezan. Un faux Hurgis arrive d'abord : détectez le mal en lui et arrêtez-le. Le vrai vient ensuite.
4. Dernière tâche : tuez le dragon rouge Firkraag dans les Collines de Lancevent, prenez la Sainte Lame et faites votre rapport à Sire William Reirrac.
Un échec grave vous fait bannir de l'Ordre.]] },
[74464] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, quartier du temple]], h = { [[Un héros clerc rejoint le temple de Lathandre, de Heaum ou de Talos et doit conseiller les fidèles.]], [[Chaque réponse est jugée par votre dieu : Lathandre aime la compassion, Heaum le devoir, Talos la destruction.]], [[La dernière tâche oppose les temples de Lathandre et de Talos ; votre dieu décide de votre camp.]] }, s = [[Quartier général des clercs, offert par le temple de votre foi dans le quartier du temple. Parlez à votre acolyte (Lara pour Lathandre, Byron pour Heaum, Vilon pour Talos), puis répondez aux fidèles qui viennent vous voir.
- Glinden, mari trompé : Lathandre : libérer sa femme de ses vœux. Heaum : lui rappeler son devoir. Talos : lui dire de la tuer.
- Ti'Vael, un meurtrier : Lathandre : dédommager la famille. Heaum : se livrer. Talos : tuer les témoins.
- Rania, qui perd la foi : Lathandre : prendre le temps de méditer. Heaum : insister sur son devoir. Talos : la tuer.
- Le défi de Cotirso : Lathandre : lui céder calmement. Heaum : accepter le duel. Talos : le tuer ou le faire accuser (l'inspecteur Ardis paie pour des noms).
Tâche finale : Heaum stoppe la guerre entre les deux temples ; Lathandre attaque le temple de Talos ; Talos attaque celui de Lathandre. De mauvaises réponses peuvent vous faire bannir.]] },
[74465] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, bas quartiers, sphère planaire]], h = { [[Après la quête de la sphère planaire, les Mages Cagoulés offrent la sphère comme base à un héros mage.]], [[Guidez avec soin vos trois apprentis, et trouvez un moyen de renvoyer chez eux les Chevaliers Solamniques.]], [[Teos vous envoie contre le seigneur Ketlaar Argrim à la Grue Courbée ; refuser vous coûte la sphère.]] }, s = [[Quartier général des mages. Après avoir nettoyé la sphère planaire des bas quartiers, acceptez l'offre des Mages Cagoulés : la sphère est à vous si vous acceptez leur surveillance. Teos est votre contact.
- Apprentis : Teos vous en confie trois. Donnez-leur des instructions chaque semaine et ils fabriquent des objets magiques pour vous ; gardez-les en vie jusqu'à leur diplôme.
- Chevaliers Solamniques : ils veulent rentrer chez eux. Payez 9 000 pièces d'or à Ribald, au Marché de l'Aventure, pour qu'une mage les téléporte, ou demandez au prélat du Cœur Radieux de les accueillir.
- Une fausse convocation de Teos cache une embuscade d'un fanatique d'Argrim. Teos vous demande ensuite de neutraliser le seigneur Ketlaar Argrim à la Grue Courbée, près des portes de la ville, avec une rune d'emprisonnement. Faites-le pour être libéré de vos obligations ; refuser vous interdit la sphère.]] },
[74467] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre]], h = { [[Un duergar de l'Ombre-Terre parle d'un mage piégé par un sort d'emprisonnement.]], [[Cela s'est passé dans une caverne au nord du duergar.]], [[Lancez Liberté, en sort ou en parchemin, dans cette caverne pour libérer le mage.]] }, s = [[Dans l'Ombre-Terre, parlez à un duergar : un mage qui cherchait un trésor ou un artefact a été attaqué et piégé par un sort d'emprisonnement dans une caverne au nord.
Procurez-vous un sort ou un parchemin de Liberté. Allez dans cette caverne et lancez-le.
Le mage, Vithal, est libéré, ce qui lance La proposition d'un mage.]] },
[74468] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre, village svirfneblin]], h = { [[Vithal, le mage libéré, a perdu son livre de rituels ; il accuse les svirfneblins.]], [[Le livre est chez le tenancier du village svirfneblin, au nord.]], [[Payez le tenancier, ou allez le voir sous forme de drow, puis protégez Vithal pendant qu'il ouvre ses portails.]] }, s = [[Une fois Vithal libéré de son emprisonnement, il réclame son livre de rituels, qu'il croit pris par les svirfneblins.
Allez au village svirfneblin au nord de sa caverne et trouvez le tenancier. Il demande 300 pièces d'or de récompense. Si vous revenez sous l'illusion drow d'Adalon, il vous le donne gratuitement.
Rapportez le livre à Vithal. Il ouvre des portails vers d'autres plans en quête de trésors : tuez les gardiens qui en sortent.
Vous recevez une part des objets magiques. Vous pouvez exiger davantage, et l'obtenir.]] },
[74469] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre]], h = { [[Un étrange cristal de l'Ombre-Terre retient des personnes prisonnières.]], [[Les premiers êtres libérés sont restés conscients trop longtemps et peuvent être fous.]] }, s = [[Dans l'Ombre-Terre, vous trouvez un cristal-piège qui emprisonne des gens. Libérez ses prisonniers un par un.
Les premiers sont des hommes rendus fous par leur longue captivité. L'un divague, un autre vous attaque : soyez prêt à combattre.
Continuez à libérer les autres : la suite est dans Victimes d'emprisonnement.]] },
[74470] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre]], h = { [[Le cristal contient d'autres prisonniers, et tous ne sont pas amicaux.]], [[Avant chaque libération, préparez-vous au combat : un githyanki et même une liche s'y trouvent.]], [[Un aventurier sain d'esprit donne des indications utiles sur les kuo-toa à l'est et une cité drow au nord.]] }, s = [[Continuez à libérer les êtres piégés dans le cristal de l'Ombre-Terre.
- Un homme dont vous rétablissez l'esprit vous remercie, ou refuse de payer et doit être convaincu.
- Un githyanki attaque aussitôt.
- Une liche en sort : renforcez le groupe avant cette libération et attendez-vous à un rude combat magique.
- Un aventurier sain d'esprit, séparé de son groupe qui combattait des drows, part les retrouver. Il peut vous dire que des kuo-toa gardent un pont à l'est et qu'une cité drow se trouve au nord. S'il se montre insolent, vous pouvez le combattre.
Le cristal retient aussi un enfant svirfneblin (voir Victimes d'emprisonnement : l'enfant svirfneblin).]] },
[74471] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre, village svirfneblin]], h = { [[L'un des prisonniers du cristal de l'Ombre-Terre est Bedlen, fils du marchand Therndle Daglefodd.]], [[Annoncez à Therndle, dans son village, que vous avez sauvé son fils.]], [[Allez voir Therndle sous la même apparence que lors de la libération, forme drow ou votre propre visage.]] }, s = [[Libérez Bedlen Daglefodd du cristal-piège ; il rentre en courant au village svirfneblin.
Allez voir son père Therndle, marchand du village, et annoncez-le-lui.
Ayez la même apparence que lors de la libération : si vous l'avez sauvé en drow, revenez sous forme de drow ; avec votre propre visage, venez sans l'illusion. Si votre apparence diffère, Therndle risque de ne pas vous croire.
S'il vous croit, il vous récompense généreusement.
Si Bedlen est mort et que vous annoncez avoir trouvé son corps, Therndle peut vous soupçonner et tout le village vous attaque.]] },
[74472] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre]], h = { [[Un enfant svirfneblin libéré du cristal est rentré chez son père.]], [[Allez au village svirfneblin et trouvez son père, le marchand Therndle Daglefodd.]] }, s = [[Vous avez libéré du cristal de l'Ombre-Terre un enfant svirfneblin, Bedlen. Il est rentré chez lui et vous a conseillé de faire de même.
Rendez-vous au village svirfneblin et parlez à son père Therndle Daglefodd, marchand du village, pour obtenir votre récompense. Gardez la même apparence (drow ou non) que lors de sa libération. Voir Victimes d'emprisonnement : l'enfant svirfneblin.]] },
[74473] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre, village svirfneblin]], h = { [[Therndle Daglefodd, marchand svirfneblin, a perdu son fils Bedlen.]], [[Quelque chose dans l'Ombre-Terre emprisonne les gens ; un étrange cristal retient peut-être l'enfant.]] }, s = [[Au village svirfneblin, le marchand Therndle Daglefodd dit que son fils Bedlen a disparu depuis plusieurs jours.
Aucun indice, mais l'enfant a fâché des drows et se trouve piégé dans le cristal découvert ailleurs dans l'Ombre-Terre. Libérez les prisonniers du cristal jusqu'à ce que Bedlen en sorte, puis retournez voir Therndle pour une récompense.]] },
[74474] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre, village svirfneblin]], h = { [[C'est la fin sombre de l'enfant svirfneblin disparu.]], [[Bedlen est mort de votre main ; vous pouvez tout de même dire à Therndle que vous avez trouvé son corps.]] }, s = [[Cette entrée note une issue maléfique : vous avez tué Bedlen Daglefodd après l'avoir libéré du cristal, puis dit à son père Therndle avoir trouvé son corps dans les tunnels, en taisant votre rôle.
Therndle vous remercie de connaître le sort de son fils. Pour la bonne issue et une récompense, laissez plutôt Bedlen rentrer chez lui vivant.]] },
[74475] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombre-Terre, village svirfneblin]], h = { [[Les gardes svirfneblins vous laissent traverser leur village si vous vous tenez bien.]], [[Parlez d'abord au seigneur du village, comme le demande le chef des gardes.]] }, s = [[Dans l'Ombre-Terre, le chef des gardes svirfneblins vous arrête à l'entrée de leur petit village. Il vous laisse passer à une condition : parler d'abord à leur chef.
Allez voir Goldander Rochenoire, seigneur du village. Il a une mission pour vous et un moyen d'entrer dans la cité drow : voir Inquiétudes au village svirfneblin.]] },
[74476] = { g = [[bg2]], k = [[main]], o = 53, c = [[5]], w = [[Ombre-Terre, village svirfneblin]], h = { [[Goldander Rochenoire sait comment atteindre la cité drow : par Adalon, au pied du grand escalier.]], [[Il veut d'abord qu'on tue une créature dans une caverne inférieure.]], [[Après le combat, lisez son parchemin dans cette caverne pour l'effondrer, puis revenez chercher la pierre de lumière.]] }, s = [[Parlez à Goldander Rochenoire, seigneur du village svirfneblin. Il dit qu'Adalon, une puissante créature au pied du grand escalier, peut vous faire entrer dans la cité drow. Son antre est caché par des ténèbres magiques.
Son prix : tuer la créature déterrée par ses mineurs dans une caverne inférieure, puis effondrer la caverne avec le parchemin qu'il vous confie. Préparez-vous, le combat est difficile.
Retournez voir Goldander : il vous donne un objet magique et la pierre de lumière qui permet de franchir les ténèbres jusqu'à Adalon. Un voleur peut aussi lui dérober la pierre.
Le journal prévoit aussi une voie maléfique où vous massacrez les svirfneblins.]] },
[74477] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombreterre]], h = { [[Les githyankis rencontrés chez les flagelleurs mentaux ne sont pas restés là où vous les avez laissés.]], [[Après avoir fui la cité illithide, cherchez-les au repos dans une caverne de l'Ombreterre.]], [[Ils réclament l'Épée d'argent et aucun discours ne leur fera renoncer au combat.]] }, s = [[Après avoir survécu à la cité illithide en Ombreterre, explorez les cavernes jusqu'à trouver le groupe de githyankis au repos : ceux qui étaient prisonniers avec vous (et qui ont attaqué le navire de Saemon si vous les avez déjà croisés).
Parlez à leur chef. Quoi que vous répondiez, ils réclament l'Épée d'argent qu'on leur aurait volée et attaquent.
Préparez-vous à un combat difficile contre plusieurs guerriers et lanceurs de sorts githyankis, puis fouillez les corps. Le journal se clôt une fois qu'ils sont morts.]] },
[74478] = { g = [[bg2]], k = [[side]], o = 0, c = [[7]], w = [[Suldanessellar]], h = { [[Une boîte elfique verrouillée à Suldanessellar ne s'ouvre que si l'on presse ses cinq runes dans le bon ordre.]], [[La pierre presbytérale de la pièce du dessus donne l'indice ; le couvercle annonce que l'Ordre Naturel prévaudra.]], [[Commencez par Corellon, puis Rillifane, et finissez par la rune de Suldanessellar.]] }, s = [[Examinez la boîte à énigme elfique trouvée dans un bâtiment de Suldanessellar. Lisez la pierre presbytérale de la pièce du dessus pour l'indice.
Une mauvaise rune vous tire une fléchette acide et remet la boîte à zéro ; pressez donc dans cet ordre :
1. Corellon Larethian.
2. Rillifane.
3. Le symbole elfique de l'eau.
4. L'Arbre de Vie.
5. La rune de Suldanessellar.
La boîte s'ouvre et vous donne le talisman de Rillifane.]] },
[74479] = { g = [[bg2]], k = [[side]], o = 0, c = [[4]], w = [[Spellhold, souterrains sous l'asile]], h = { [[Le vampire que vous venez d'abattre était une victime de Bodhi, et son âme réclame une vraie mort.]], [[Un chaman kobold qui craint le vampire garde un pieu en bois dans une pièce secrète près du Grimoire de la folie.]], [[Plantez le pieu dans le corps du cercueil de Dace ; sa main est la moitié de la clef pour sortir d'ici.]] }, s = [[Dans le labyrinthe sous Spellhold, après avoir vaincu le vampire Dace Sontan, son esprit tourmenté apparaît. Acceptez de l'aider.
Trouvez la pièce secrète près du Grimoire de la folie, où le chaman kobold vénère un éclat de cristal. Prenez-lui le pieu en bois (par la force si besoin).
Retournez au cercueil de Dace et utilisez le pieu sur son corps : son âme est libérée.
Prenez la main de Dace dans le cercueil. Avec le cristal, c'est la clef qui ouvre la sortie de ce niveau : ne l'oubliez pas.]] },
[74480] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ombreterre, Ust Natha]], h = { [[Un aboleth captif dans un réservoir d'Ust Natha lit dans votre esprit et voit à travers votre déguisement.]], [[Il veut le cerveau de la prêtresse Qilue, qui vit à la Société des Combattantes.]], [[Sa chambre est derrière la deuxième porte à partir du bas ; frappez vite, prenez le cerveau, rapportez-le.]] }, s = [[Dans la cité drow d'Ust Natha, parlez à l'aboleth enfermé dans un réservoir. Il menace de révéler que vous venez de la surface si vous n'obéissez pas. Acceptez (un refus alerte toute la cité).
Allez à la Société des Combattantes et entrez par la deuxième porte à partir du bas. Tuez vite la prêtresse Qilue et prenez son cerveau sur le corps.
Retournez voir l'aboleth et donnez-le-lui. Il garde votre secret, et le groupe gagne de l'expérience (10 000 PX). Il n'y a pas d'autre récompense.]] },
[74481] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, quartier des taudis]], h = { [[Deux ravisseurs, Camitis et Reti, retenaient Dame Elgea contre rançon, et quelqu'un vient encore payer.]], [[Une note trouvée sur les ravisseurs indique le lieu du rendez-vous : devant la Couronne de Cuivre.]], [[Faites-vous passer pour le ravisseur auprès de Welther pour toucher la rançon ; c'est la voie intéressée.]] }, s = [[Cette entrée fait suite à l'enlèvement de Dame Elgea par Camitis et Reti dans le quartier des taudis. Après vous être occupé des ravisseurs, gardez leur note.
Allez devant la Couronne de Cuivre et parlez à Welther, le serviteur de Dame Elgea. Montrez la note et prétendez être le ravisseur.
Il vous remet la rançon convenue (un objet, pas de l'or) et vous lui indiquez où se trouve la dame.
Welther connaît désormais la maison où elle est retenue : mieux vaut ne pas y retourner.]] },
[74482] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau du labyrinthe]], h = { [[Un cambion amical dans le labyrinthe préfère jouer avec vous plutôt que se battre.]], [[Il mise une gemme contre votre symbole sacré de Helm, sur des tirages de cartes merveilleuses.]], [[Gagnant ou perdant, ne partez pas sans le symbole et attendez-vous à un combat s'il résiste.]] }, s = [[Au niveau du labyrinthe de la Tour de Garde, rencontrez le cambion et sa suite. Parlez au lieu d'attaquer.
Il propose une partie de cartes merveilleuses : votre symbole sacré de Helm (sa porte de sortie) contre une gemme qu'il a trouvée. Chaque tirage peut avoir des effets bons ou mauvais.
S'il gagne sa liberté, il tient parole : il vous rend le symbole sacré et vous donne quand même la gemme.
S'il refuse de vous laisser partir avec le symbole, l'affaire finit en combat contre lui et ses fidèles.]] },
[74483] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau du labyrinthe]], h = { [[Deux fiélons de la Guerre du Sang sont piégés dans le labyrinthe, chacun voulant la mort de l'autre.]], [[Le balor Tahazzar et le diantrefosse Ka'rashur vous demandent chacun le cœur de l'autre.]], [[Choisissez un camp, tuez l'autre fiélon et rapportez son cœur pour la récompense.]] }, s = [[Dans le labyrinthe de la Tour de Garde, vous pouvez croiser le balor tanar'ri Tahazzar et le diantrefosse baatezu Ka'rashur dans des parties différentes du niveau.
Acceptez la mission de l'un d'eux : trouvez l'autre fiélon et détruisez-le, puis prenez son cœur.
La cible est un fiélon très puissant ; préparez des protections contre le feu et la magie de haut niveau.
Rapportez le cœur à votre employeur. À la surprise générale, il tient parole et vous donne sa récompense.]] },
[74484] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau du temple]], h = { [[Le portail miroir au centre du temple s'ouvre grâce à un rituel sur l'autel.]], [[Le spectre de l'archiviste vous oriente vers le vieux prêtre distrait, mort depuis longtemps quelque part dans le temple.]], [[Le chapitre et le verset sont tissés dans la manche de la cape du vieux prêtre : cloche, cloche, bougie, livre, cloche.]] }, s = [[Au premier niveau de la Tour de Garde, réunissez les objets du rituel trouvés dans le temple (une cloche, une bougie et le livre sacré) et utilisez l'autel.
Parlez au spectre de l'archiviste : il vous dit de trouver le vieux prêtre distrait. Trouvez ses restes et sa cape : le chapitre et le verset sont tissés dans la manche.
À l'autel, dans cet ordre : sonnez la cloche, sonnez-la encore, allumez la bougie, ouvrez le livre (il s'ouvre alors à la bonne page), sonnez une troisième fois.
Le portail miroir au centre du temple s'active et vous fait descendre quand vous le voulez.
Si vous quittez l'autel en cours de route, recommencez le rituel.]] },
[74485] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau des magiciens]], h = { [[Le démon chromatique de la cage centrale contrôle la porte vers le niveau suivant.]], [[Quatre magiciens élémentaires ont chacun fabriqué un sceptre ; fouillez leurs laboratoires sur ce niveau.]], [[Placez les quatre sceptres dans les emplacements autour de la cage, et soyez prêt : le démon libéré attaque.]] }, s = [[Au deuxième niveau de la Tour de Garde, parlez au démon chromatique enfermé dans sa cage élémentaire. Il n'ouvrira la descente que si vous le libérez.
Acceptez, puis explorez les quatre laboratoires des magiciens (air, vase, froid et feu). Mettez d'abord le ventilateur en marche et lisez les notes des magiciens pour vaincre leurs créatures (voir les entrées liées).
Récupérez les quatre sceptres et placez-les dans les quatre emplacements autour de la cage.
Le démon est libéré et vous attaque aussitôt. Tuez-le pour descendre au niveau inférieur.]] },
[74486] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau de Carston]], h = { [[Un apprenti mourant torturé par les illithides connaît l'histoire de Carston et le secret de sa cage de verre.]], [[La machine de Lum le Fou, dans la bulle de verre de Carston, commande la porte du nord-est.]], [[Chaque levier et chaque cadran a un effet aléatoire, bon ou mauvais ; le bouton rouge n'ouvre la porte qu'au bon moment.]] }, s = [[Au troisième niveau de la Tour de Garde, parlez à l'apprenti mourant de Carston. Il explique que le magicien fou Carston est piégé dans une bulle de verre par la machine de Lum le Fou, seule voie vers le bas. Des illithides, des githyankis et le dragon Saladrex vivent aussi à ce niveau.
Trouvez un moyen de franchir la bulle de verre de Carston et occupez-vous de lui.
Utilisez la machine : trois leviers et deux cadrans ont des effets aléatoires, parfois permanents (gains de caractéristiques, soins, monstres invoqués, feu, pétrification, perte de niveau).
Quand le bouton rouge fonctionne, la porte magique du coin nord-est s'ouvre vers le niveau suivant. Sauvegardez avant d'expérimenter.]] },
[74487] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau de la prison]], h = { [[Le dernier sceau avant la crypte de l'Emprisonné demande trois clefs : l'esprit, le cœur et l'âme.]], [[Chaque clef se gagne dans sa propre épreuve à ce niveau.]], [[L'esprit, c'est l'énigme des globes colorés ; le cœur, l'épreuve du parcours ; l'âme, le défi du Guerrier Éternel.]] }, s = [[Au dernier niveau de la Tour de Garde, l'escalier vers la crypte de l'Emprisonné est bloqué par le dernier sceau.
Réussissez les trois épreuves, dans l'ordre de votre choix :
- Esprit : résolvez l'énigme des globes colorés.
- Cœur : passez l'épreuve du parcours, qui prouve persévérance et courage.
- Âme : relevez le défi du Guerrier Éternel.
Chaque épreuve donne une clef. Avec les clefs du cœur, de l'esprit et de l'âme, ouvrez le dernier sceau ; la voie de la crypte est libre.
Préparez-vous bien avant de descendre : Démogorgon attend en bas.]] },
[74488] = { g = [[tob]], k = [[main]], o = 68, c = [[8]], w = [[Saradush]], h = { [[Mélissanne veut qu'on arrête le général paranoïaque Gromnir, enfermé dans le château de Saradush, avant de briser le siège.]], [[La porte du château reste close : renseignez-vous à l'Arbre à Chopines, au temple de Waukyne et dans les rues pour trouver un passage secret.]], [[Sœur Farielle a la clef de la prison abandonnée de l'autre côté de la rue, qui cache un passage vers le château.]] }, s = [[Après avoir parlé à Mélissanne, trouvez un moyen d'entrer dans le château de Gromnir. Trois pistes :
- Pyrgam Bièritage, à l'Arbre à Chopines, parle d'une prison abandonnée ; Sœur Farielle, au temple de Waukyne, vous en donne la clef. La porte est de l'autre côté de la rue. Emportez de l'eau bénite contre les morts-vivants et cherchez la zone secrète menant au château.
- Une serveuse que vous sauvez de soldats brutaux dit que les égouts scellés mènent au château.
- Peltje parle de vampires déguisés en prostituées, installés dans les égouts.
À l'intérieur, Gromnir n'entend pas raison : tuez-le, ainsi que ses gardes. Retournez ensuite voir Mélissanne pour la suite.]] },
[74489] = { g = [[tob]], k = [[main]], o = 67, c = [[8]], w = [[Saradush]], h = { [[Saradush est assiégée par l'armée de Yaga-Shura ; trouvez Mélissanne, la protectrice des enfants de Bhaal.]], [[Selon Mélissanne, il faut d'abord régler le cas du général fou Gromnir.]], [[Une fois Gromnir mort, quittez la ville par votre Antichambre et allez chercher Yaga-Shura lui-même.]] }, s = [[Vous arrivez à Saradush, assiégée par l'enfant de Bhaal et géant du feu Yaga-Shura. Personne ne peut sortir, même par magie.
Parlez à Mélissanne. Elle promet de vous expliquer pourquoi on traque les enfants de Bhaal si vous aidez à briser le siège.
Occupez-vous d'abord de Gromnir Il-Khan, retranché dans le château (voir « Le cas Gromnir »). Les quêtes secondaires de la ville valent la peine avant de partir.
Après la mort de Gromnir, Mélissanne dit que le seul espoir est de tuer Yaga-Shura. Utilisez votre capacité Antichambre pour quitter la ville, puis suivez « Vaincre Yaga-Shura ».]] },
[74490] = { g = [[tob]], k = [[side]], o = 0, c = [[8]], w = [[Saradush]], h = { [[Le capitaine Samand détient un jeune homme, Mateo, accusé de comploter l'ouverture d'un passage secret à l'ennemi.]], [[La comtesse Santele l'a accusé parce que le marchand Kiser Jhaeri a enlevé son fils Ardic.]], [[Interrogez le magicien Errard au lieu de le tuer : Ardic est caché dans la maison de Kiser.]] }, s = [[Parlez au capitaine Samand, puis à Mateo au quartier général de la milice : il clame son innocence.
Rendez visite à la comtesse Santele : Kiser Jhaeri a enlevé son fils Ardic et l'a forcée à accuser Mateo.
Parlez à Kiser. Il vous demande de tuer le magicien Errard, voire la comtesse, contre de l'or et la clef de la cellule secrète d'Ardic dans sa cave.
Voie bonne : parlez plutôt à Errard. Il confirme qu'Ardic est chez Kiser. Retournez-y, tuez Kiser et libérez Ardic ; son témoignage innocente Mateo et la comtesse vous récompense.
Voies mauvaises : tuer Errard (les défenses de Saradush en pâtissent) ou la comtesse pour la paie de Kiser. Ardic peut aussi mourir dans le combat.]] },
[74491] = { g = [[tob]], k = [[main]], o = 69, c = [[8]], w = [[Forêt de Mir / Monts de la Marche]], h = { [[Yaga-Shura est immunisé contre les armes et la magie ; son secret se trouve dans la Forêt de Mir ou dans les Monts de la Marche.]], [[La sorcière Nyalee, dans les ruines d'un temple de Bhaal de la Clairière Hantée, l'a élevé et sait pourquoi son cœur brûle.]], [[Prenez son cœur embrasé sur le brasier de son repaire et le coffre doré de son lit de pierre, puis apportez les deux à Nyalee.]] }, s = [[Mélissanne prévient que Yaga-Shura est invulnérable en l'état. Quittez Saradush par l'Antichambre.
Dans la Forêt de Mir, gagnez la Clairière Hantée et le temple de Bhaal en ruine. La sorcière Nyalee explique que Yaga-Shura garde son cœur hors de son corps, embrasé. Elle l'éteindra si vous lui rapportez aussi son propre cœur, qu'il lui a volé.
Dans les Monts de la Marche, entrez dans le repaire de Yaga-Shura. Libérez la femme enchaînée dans ses quartiers : elle vous parle du petit coffre doré caché dans son lit de pierre (il contient le cœur de Nyalee).
Prenez le cœur de Yaga-Shura sur le brasier et le coffre, retournez voir Nyalee et donnez-lui les deux. Elle éteint son cœur.
Allez ensuite au campement du siège pour affronter Yaga-Shura.]] },
[74492] = { g = [[tob]], k = [[main]], o = 70, c = [[8]], w = [[Campement du siège devant Saradush]], h = { [[Une fois son cœur éteint par Nyalee, Yaga-Shura peut enfin être blessé.]], [[Il attend au milieu de son armée, au campement du siège devant Saradush.]], [[Frayez-vous un chemin parmi ses géants et tuez-le ; Saradush elle-même ne peut être sauvée.]] }, s = [[Cette entrée clôt l'histoire de Yaga-Shura.
Après que Nyalee a éteint le cœur de Yaga-Shura, rendez-vous au campement du siège devant Saradush. Attendez-vous à une longue bataille contre son armée de géants et de soldats avant de l'atteindre.
Yaga-Shura est maintenant vulnérable : tuez-le.
Entre-temps, Saradush a été rasée : Yaga-Shura l'a détruite en vous y cherchant. L'histoire continue avec Mélissanne et le plan d'attaque des enclaves de Sendaï et d'Abazigal.]] },
[74493] = { g = [[tob]], k = [[main]], o = 72, c = [[9]], w = [[Amkethran et les enclaves]], h = { [[Mélissanne vous envoie au village d'Amkethran, où Balthazar détient les cartes des enclaves.]], [[Détruisez Sendaï et Abazigal dans leurs enclaves ; une vision montre ensuite Balthazar combattant Mélissanne.]], [[Saemon Havarian peut vous faire entrer dans le monastère gardé, avec un mot de passe et des uniformes volés.]] }, s = [[Après la mort de Yaga-Shura, Mélissanne vous envoie à Amkethran. Rencontrez Balthazar, le chef du monastère : il vous donne les cartes des enclaves.
Attaquez l'enclave de Sendaï et celle d'Abazigal, dans l'ordre de votre choix (voir leurs propres entrées).
Une fois les deux morts, une vision montre Balthazar combattant Mélissanne. Retournez à Amkethran : la ville grouille des mercenaires de Balthazar.
Saemon propose un moyen d'entrer. Refusez et traversez la ville en combattant, ou acceptez : il finit par vous donner un mot de passe et des déguisements pour entrer dans le monastère.
Affrontez Balthazar. Il révèle qu'il est un des doigts de la Main et veut la mort de tous les enfants de Bhaal, lui compris, et vous avertit que Mélissanne vous manipule depuis le début.]] },
[74494] = { g = [[tob]], k = [[main]], o = 73, c = [[9]], w = [[Enclave de Sendaï]], h = { [[À l'emplacement de Sendaï sur la carte, vous ne trouvez qu'un simple forestier.]], [[Il parle d'événements étranges sur sa propriété ; le forestier est un agent drow déguisé.]], [[L'entrée de l'enclave de Sendaï est cachée dans sa cabane.]] }, s = [[Rendez-vous à l'enclave de Sendaï grâce aux cartes de Balthazar. Un forestier vous accueille et parle d'étranges événements sur sa propriété.
C'est en fait un drow déguisé au service de Sendaï. Démasquez-le ou tuez-le, puis fouillez sa cabane pour trouver l'entrée de l'enclave souterraine.
Traversez les rangs des drows de Sendaï et leurs pièges. Attendez-vous à beaucoup de lanceurs de sorts et à quelques énigmes.
Tuez Sendaï, un autre doigt de la Main. Le solaire vous rappellera dans l'Antichambre pour une nouvelle révélation.]] },
[74495] = { g = [[tob]], k = [[main]], o = 74, c = [[9]], w = [[Enclave d'Abazigal]], h = { [[Draconis, le fils d'Abazigal, garde l'entrée de ses cavernes.]], [[Un moine mourant de Balthazar explique qu'un Parchemin d'inversion rompt le sortilège du dragon gardien et du sceau intérieur.]], [[Les grottes sont reliées par des tunnels sous-marins ; le sorcier fou Iycanth échange le parchemin contre un pédoncule.]] }, s = [[Rendez-vous à l'enclave d'Abazigal. À l'entrée, vous rencontrez son fils Draconis : tuez-le (il se change en dragon).
À l'intérieur, trouvez le moine prisonnier de Balthazar. Avant de mourir, il vous donne une corde et des potions de respiration aquatique, et explique qu'il vous faut le Parchemin d'inversion.
Explorez les cavernes par les tunnels sous-marins. Obtenez le parchemin auprès du sorcier Iycanth (voir « Pédoncule oculaire d'Iycanth »).
Utilisez-le pour rompre le sortilège du dragon gardien et ouvrir l'antre intérieur d'Abazigal.
Tuez Abazigal, un demi-dragon bleu ; prévoyez une protection contre l'électricité.]] },
[74496] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau des magiciens]], h = { [[Le diablotin de la bibliothèque dit qu'un ventilateur magique alimente tous les laboratoires de ce niveau.]], [[Commencez par le laboratoire de l'Air, juste derrière le diablotin.]], [[Le ventilateur a deux réglages, fort et faible ; passer de l'un à l'autre compte ailleurs sur le niveau.]] }, s = [[Au deuxième niveau de la Tour de Garde, parlez au diablotin des bibliothèques. Dites-lui que ses maîtres sont morts : il explique que les ventilateurs se sont arrêtés et que les laboratoires sont vides sans eux.
Allez au laboratoire de l'Air, juste derrière le diablotin, et mettez en marche le ventilateur magique.
Le ventilateur a un réglage fort et un réglage faible. Essayez les deux en explorant : les laboratoires ne s'animent qu'avec le ventilateur en marche, et le courant d'air influe sur ce que vous pouvez faire ailleurs.
Une fois les laboratoires actifs, cherchez les sceptres des magiciens (voir « Réunir les quatre sceptres »).]] },
[74497] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Tour de Garde, niveau des magiciens]], h = { [[Quatre magiciens de l'air, de la vase, du froid et du feu avaient chacun ici une bibliothèque et un laboratoire.]], [[Leurs créatures sont presque invincibles si l'on ne sait pas comment les blesser.]], [[Lisez les notes de chaque bibliothèque : chaque magicien utilisait son élément contre la créature d'un autre.]] }, s = [[Le diablotin du deuxième niveau de la Tour de Garde vous parle des quatre magiciens élémentaires (air, vase, froid et feu), qui complotaient les uns contre les autres.
Visitez les quatre bibliothèques et lisez les notes des magiciens avant d'entrer dans leurs laboratoires. Chaque note explique comment détruire la créature d'un rival.
Dans chaque laboratoire, utilisez l'élément ou l'objet indiqué dans les notes contre son gardien ; les attaques normales n'y font presque rien.
Une fois les gardiens vaincus, fouillez les laboratoires pour trouver les sceptres réclamés par le démon chromatique.]] },
[74498] = { g = [[tob]], k = [[side]], o = 0, c = [[9]], w = [[Enclave d'Abazigal]], h = { [[Le sorcier fou Iycanth échangera le Parchemin d'inversion contre le pédoncule d'un gauth.]], [[Le gauth a disparu dans un des bassins à l'est de son laboratoire.]], [[Allez-le chercher vous-même, ou rendez vie aux aventuriers pétrifiés tout proches et laissez-les s'en charger.]] }, s = [[Dans les cavernes d'Abazigal, rencontrez le sorcier Iycanth. Il veut le pédoncule d'un gauth (un petit tyrannœil) caché dans un des bassins à l'est de son laboratoire.
Option 1 : plongez dans les bassins (il faut pouvoir respirer sous l'eau), trouvez et tuez le gauth, prenez son pédoncule.
Option 2 : Iycanth conseille de sous-traiter. Tout près, Bondari et ses compagnons (Nanoc, Tim et les autres) ont été pétrifiés. Lancez Pierre en chair sur eux et confiez-leur la « Quête » : ils rapportent le pédoncule.
Retournez au laboratoire d'Iycanth et échangez le pédoncule contre le Parchemin d'inversion, nécessaire pour rompre le sortilège et entrer dans l'antre d'Abazigal.]] },
[74499] = { g = [[tob]], k = [[side]], o = 0, c = [[9]], w = [[Amkethran]], h = { [[Un garçon devant la grotte scellée du cimetière accuse un homme étrange d'avoir attiré les morts-vivants.]], [[Marlowe, un marchand de Calimshan, dit que la liche Vongoethe a volé l'âme de sa fille Malla.]], [[Écoutez la version de la liche dans la grotte du cimetière : Marlowe a vendu sa propre âme et n'a jamais payé.]] }, s = [[Parlez au garçon près de la grotte scellée du cimetière, au nord d'Amkethran, puis à Marlowe dans sa maison sur la falaise est. Il dit que la liche Vongoethe a pris l'âme de sa fille Malla.
Acceptez de l'aider : le garde vous laisse franchir le sceau magique.
Dans la grotte, Vongoethe raconte que Marlowe a échangé son âme contre vingt ans de prospérité et s'est enfui sans payer.
Choix :
- Tuer Vongoethe et ses morts-vivants (combat de liche difficile). Si vous obtenez la pierre d'âme, donnez-la à Marlowe ou gardez-la.
- Amener Marlowe à la liche (en le lui demandant ou par la ruse). Vongoethe prend Marlowe et vous donne l'âme de la fille ; utilisez-la pour rendre la vie à Malla.
- Attaquer sans la pierre peut laisser Malla mourir.]] },
[74500] = { g = [[tob]], k = [[side]], o = 0, c = [[8]], w = [[Saradush]], h = { [[Lazarus, le marchand de parchemins de Saradush, s'est fait voler son livre de sorts et soupçonne Hectan.]], [[De petites empreintes boueuses partent de la fenêtre de l'échoppe vers un gamin des rues, Squip.]], [[Hectan veut un parchemin de téléportation contre le livre ; Lazarus prévient qu'il tuera celui qui s'en sert.]] }, s = [[Parlez à Lazarus dans son échoppe de parchemins de Saradush. Son livre de sorts a disparu ; il soupçonne Hectan, qui était saoul à l'auberge ce soir-là.
Examinez l'indice : de petites empreintes boueuses près de la fenêtre. Trouvez le gamin Squip, qui avoue avoir volé le livre pour Hectan.
Confrontez Hectan. Il n'échangera le livre que contre un parchemin de téléportation pour fuir la ville assiégée.
Retournez voir Lazarus : il vous donne le parchemin, en prévenant que quiconque le lira rebondira sur la barrière magique de Saradush.
Échangez le parchemin contre le livre (Hectan y laisse la vie en s'en servant).
Rendez le livre : Lazarus rouvre son échoppe.]] },
[74501] = { g = [[tob]], k = [[side]], o = 0, c = [[9]], w = [[Amkethran]], h = { [[Un homme effrayé nommé Marlowe vous arrête à Amkethran.]], [[Il vous demande de le retrouver chez lui, en haut de la falaise est.]], [[Allez-y et écoutez son histoire de liche ; elle lance « La liche du cimetière ».]] }, s = [[À Amkethran, Marlowe vous aborde, désespéré, et vous demande de venir chez lui, en haut de la falaise est.
Allez-y et parlez-lui. Il vous parle de la liche Vongoethe et de l'âme volée de sa fille.
L'histoire continue ensuite dans la quête « La liche du cimetière » : la grotte scellée du cimetière est au nord de la ville.]] },
[74503] = { g = [[tob]], k = [[main]], o = 65, c = [[8-10]], w = [[Antichambre]], h = { [[Cinq couloirs partent de la pièce principale de votre Antichambre ; chacun s'ouvre quand vous êtes prêt.]], [[L'esprit du destin, près de l'entrée, peut convoquer des compagnons dont le destin est lié au vôtre.]], [[Avant chaque épreuve, parlez à l'esprit du destin pour compléter votre groupe.]] }, s = [[Au début du Trône de Bhaal, l'écho de Sarevok vous explique le fonctionnement de votre Antichambre.
Les épreuves : cinq couloirs autour de la pièce principale. Le solaire les ouvre un à un à mesure que l'histoire avance (après de grands événements comme la chute de Saradush ou la mort d'un des doigts de la Main). Chacun cache un combat ou un test difficile ; vous revenez dans l'Antichambre quand on vous appelle.
L'esprit du destin : parlez-lui près de l'entrée de l'Antichambre. Il peut convoquer d'anciens compagnons dont le destin est lié au vôtre, pour reformer votre groupe à tout moment.
Utilisez-le avant chaque épreuve.]] },
[74504] = { g = [[tob]], k = [[main]], o = 71, c = [[8]], w = [[Antichambre]], h = { [[L'écho de Sarevok dans l'Antichambre vous dit où votre destin vous mène ensuite.]], [[L'Antichambre vous emmène là où vous devez être : la ville de Saradush, au Téthyr.]], [[Réunissez votre groupe avec l'esprit du destin, puis quittez l'Antichambre par sa sortie.]] }, s = [[Dans l'Antichambre au début du Trône de Bhaal, parlez à l'écho de Sarevok. Il dit que votre prochaine destination est Saradush, une ville du Téthyr.
L'Antichambre n'est pas un portail libre : elle vous envoie là où vous devez être.
Convoquez les compagnons que vous voulez grâce à l'esprit du destin, puis empruntez la sortie. Vous arrivez à Saradush, assiégée, où commence la quête « Le siège de Saradush ».]] },
[74505] = { g = [[tob]], k = [[main]], o = 75, c = [[9]], w = [[Amkethran]], h = { [[À Amkethran, les moines vous mèneront à leur maître, Balthazar.]], [[Balthazar vous laisse rester en ville si vous restez hors de son monastère.]], [[Il vous remet les cartes des enclaves de Sendaï et d'Abazigal : c'est votre prochaine étape.]] }, s = [[En arrivant à Amkethran après la chute de Saradush, vous êtes conduit devant Balthazar, chef de l'ordre monastique.
Il est froid mais vous autorise à rester en ville tant que vous n'essayez pas d'entrer dans le monastère ni de vous mêler de ses affaires.
Il vous donne les cartes des enclaves des enfants de Bhaal que Mélissanne lui a laissées. Mélissanne elle-même reste introuvable.
Utilisez ces cartes sur la carte du monde pour attaquer les enclaves de Sendaï et d'Abazigal. En attendant, la ville a des boutiques et des quêtes secondaires.]] },
[74506] = { g = [[tob]], k = [[main]], o = 66, c = [[8-10]], w = [[Antichambre]], h = { [[Après chaque grande victoire, le solaire vous rappelle dans l'Antichambre.]], [[Écoutez ses révélations : chacune ouvre un nouveau couloir d'épreuve.]], [[Réussissez chaque épreuve ; la dernière détruit votre Antichambre et ouvre la voie du Trône de Bhaal.]] }, s = [[Tout au long du Trône de Bhaal, le solaire vous convoque dans l'Antichambre après les événements clés et vous révèle votre passé et votre rôle dans la prophétie d'Alaundo (Gorion aurait pu emmener Sarevok à votre place ; c'est vous qui devez arrêter les autres enfants de Bhaal ; la Main se compose d'Illasera, Yaga-Shura, Sendaï, Abazigal et Balthazar).
Après chaque entretien, elle ouvre un nouveau couloir d'épreuve. Entrez-y, avec les compagnons de l'esprit du destin, et réussissez l'épreuve.
Après Balthazar, elle révèle que votre véritable ennemie est Mélissanne, ancienne grande prêtresse de Bhaal. L'ultime épreuve détruit votre Antichambre pour que vous puissiez la suivre jusqu'au Trône de Bhaal.]] },
[74507] = { g = [[tob]], k = [[side]], o = 0, c = [[8]], w = [[Saradush, prison abandonnée]], h = { [[Le fantôme muet d'un vieux prisonnier hante la prison abandonnée et désigne sa tombe profanée.]], [[Il mime un collier, montre les cellules voisines et se tient la tête : trouvez son collier et son crâne.]], [[Déposez le crâne et le collier dans la tombe peu profonde et aspergez-la d'eau bénite elfique.]] }, s = [[Dans la prison abandonnée de Saradush (le chemin vers le château de Gromnir), le fantôme d'un vieux mendiant apparaît plusieurs fois. Il ne peut pas parler mais vous montre que sa tombe a été profanée.
Fouillez les cellules voisines pour trouver son collier, et retrouvez son crâne.
À la tombe peu profonde, replacez le crâne et le collier, puis utilisez de l'eau bénite elfique pour sanctifier le sol.
L'esprit trouve la paix, vous donne de l'expérience et ouvre une porte qui restait close jusque-là.]] },
[88267] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Un moine excentrique parmi les captifs propose d'étranges services au nom de Lathandre.]], [[Frère Ellraish peut préparer un poison avec du quartz en poudre et des crottes de rat.]], [[Il échange aussi une clef du salon des Chasseurs contre la pierre runique du marchand illithid.]] }, s = [[Parlez à frère Ellraish.
Poison : il lui faut du quartz en poudre et des crottes de rat. Apportez-les et il vous donne un poison à utiliser contre Baladine (voir Tel est pris).
Clef : après une « vision », il réclame la pierre runique du marchand illithid. L'illithid veut en échange l'anneau de Stannel Eibor. Obtenez l'anneau, échangez-le contre la pierre et donnez celle-ci à Ellraish.
Il vous remet la clef du salon des Chasseurs, à l'étage, qui permet aussi de passer le garde de l'escalier (voir Monter).]] },
[93935] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla / Rocheprofonde]], h = { [[Des hérétiques de la Lune Noire courtisent Rasaad ; ils se réunissent dans un amphithéâtre abandonné hors d'Athkatla.]], [[Leur chef Martheaume oriente Rasaad vers Collus Darathon, fondateur du Cercle Dédoublé, dans un temple secret.]], [[Collus Darathon est Alorgoth ; une carte sur les assassins de la Lune Noire mène à Rocheprofonde et à son dernier plan.]] }, s = [[Avec Rasaad, allez à l'amphithéâtre abandonné hors de la ville et écoutez Martheaume, ancien moine de la Conscience Solaire.
Il indique à Rasaad où trouver Collus Darathon : rendez-vous au temple secret de la Dédoublée et passez les épreuves pour rejoindre le Cercle Dédoublé.
Collus Darathon est Alorgoth, qui envoie des Sharrans écraser son propre culte. Combattez aux côtés du Cercle ou fuyez avant l'attaque. Rasaad peut vaincre son ancien professeur, le Maître d'armes, et prendre la tête du Cercle.
Plus tard, des assassins de la Lune Noire attaquent ; l'un d'eux porte une carte de Rocheprofonde. Là-bas, les nains de Meems Creusefond ont besoin de sel gemme, d'une potion d'explosions et d'un grog spécial pour percer un tunnel vers les mines.
À l'intérieur, Alorgoth ouvre un portail vers le Plan des Ombres. Suivez-le avec Rasaad (il part seul si vous refusez), affrontez Alorgoth, son assistant Yxtrazzal et un dragon d'ombre, puis repassez le portail.]] },
[94033] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II, casernements]], h = { [[Brodle connaît un lieutenant de la garde qui pourrait soutenir une révolte contre Dennaton.]], [[Rencontrez Leokas dans les casernements ; il veut un petit pot-de-vin avant même de parler.]], [[Le vrai prix de ses soldats est énorme, mais il peut baisser.]] }, s = [[Parlez à Brodle et acceptez de préparer une révolte ; il organise une rencontre et vous prévient quand le lieutenant est prêt.
Allez aux casernements et rencontrez Leokas. Payez d'abord son silence (100 ou 200 pièces d'or selon la discussion).
Il demande ensuite 20 000 pièces d'or pour son soutien et celui de ses soldats ; selon la conversation, il peut descendre à 15 000.
Payez-le : au début de la révolte, Leokas s'empare des casernements pour vous et ses hommes combattent les forces de Dennaton. Si vous refusez, attendez-vous à affronter ses troupes pendant le soulèvement.]] },
[94452] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Forêt Sauvage / Refuge Caché]], h = { [[Barad Ding, un entropiste du Refuge Caché, a perdu huit chats.]], [[Ils errent dans la Forêt Sauvage ; il vous donne un sac de nourriture pour chat comme appât.]], [[Utilisez la nourriture près de chaque chat sauvage, réunissez les huit et ramenez-les au Refuge.]] }, s = [[Au Refuge Caché (le camp de Neera), parlez à Barad Ding. Ses chats Abby, Connie, Alter, Divine, Chanticleer, Eevo, Lucy et Nector sont perdus dans la Forêt Sauvage.
Prenez le sac de nourriture pour chat et fouillez la forêt. Les chats sont sauvages : utilisez la nourriture pour attirer chacun d'eux.
Retournez voir Barad Ding quand vous les avez tous les huit.
Récompense : un chat nommé Dings. S'il devient trop encombrant (il remplit vos sacs de rongeurs morts), vous pouvez le rendre à Barad Ding.]] },
[94457] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Refuge Caché / Franc-Marché]], h = { [[Mironda, l'entropiste naine du Refuge Caché, regrette une bière bien précise.]], [[Elle veut un tonneau de Providence des petites-gens, vendu à Franc-Marché.]], [[Achetez le tonneau au pub de Vyatri à Franc-Marché et rapportez-le-lui.]] }, s = [[Au Refuge Caché, parlez à Mironda, une entropiste naine. Elle demande un tonneau de Providence des petites-gens.
Rendez-vous à Franc-Marché et achetez le tonneau à Vyatri, dans son pub.
Retournez au Refuge Caché et donnez-le à Mironda.
Récompense : une chope magique portant votre nom.]] },
[94461] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Refuge Caché]], h = { [[Zaviak, un alchimiste du Refuge Caché, rêve de voir Wilson, « le meilleur ours au monde ».]], [[Wilson est un ours qui peut voyager avec vous.]], [[Revenez au Refuge avec Wilson dans le groupe et parlez à Zaviak.]] }, s = [[Au Refuge Caché, l'alchimiste Zaviak dit qu'il aimerait beaucoup voir Wilson l'ours.
Si Wilson voyage avec vous, amenez-le au Refuge et parlez à Zaviak pour de brèves retrouvailles.
Récompense : quelques potions étranges mais puissantes de Zaviak.
Si Wilson n'est pas dans votre groupe, cette quête reste ouverte.]] },
[94464] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Refuge Caché / Athkatla, quartier du pont]], h = { [[Mereth, une enfant entropiste du Refuge Caché, a perdu le serre-tête de sa mère.]], [[Elle l'a perdu quand Neera l'a sauvée de l'Ordre des Huit Bâtons à Athkatla.]], [[Fouillez dans et près des caisses à l'extrémité est du quartier du pont.]] }, s = [[Au Refuge Caché, parlez à la petite Mereth. Elle a perdu le serre-tête de sa mère juste avant que Neera la sauve.
Allez au quartier du pont d'Athkatla et fouillez les caisses à son extrémité est jusqu'à trouver le serre-tête.
Retournez au Refuge Caché et rendez-le à Mereth.
Récompense : un collier enchanté.]] },
[94474] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Promenade de Waukyne, enclave des Magiciens Rouges]], h = { [[Dans l'enclave des Magiciens Rouges, combattre tous les mercenaires n'est pas le seul moyen d'atteindre Lanneth.]], [[Leur chef Fadell se plaint d'être mal payée et de morts inutiles ; son journal dit qu'elle boit.]], [[Attisez les griefs des mercenaires et poussez une Fadell ivre à la révolte.]] }, s = [[Fait partie de la quête de Neera, après la destruction du Refuge Caché. Entrez dans l'enclave des Magiciens Rouges, dans la Promenade de Waukyne.
Parlez à Fadell, le chef des mercenaires : elle dit que « les choses vont mal ». Insistez : ses hommes sont très mal payés.
Fouillez l'enclave pour trouver le journal de Fadell : elle en veut aux Magiciens pour la mort de ses hommes et boit.
Servez-vous de ces informations pour semer la révolte parmi les mercenaires. Une fois Fadell assez ivre, elle et ses hommes se soulèvent contre les Magiciens Rouges.
Au combat final, Fadell refuse d'aider Lanneth, même quand celle-ci révèle que vous avez causé la mort de nombre de ses hommes.
Sinon, affrontez vous-même les mercenaires.]] },
[94483] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Promenade de Waukyne, enclave des Magiciens Rouges]], h = { [[Un esclave minotaure et ancien gladiateur, Ghallus, pourrait être un allié de poids dans l'enclave.]], [[Sa cellule demande une clef : Lanneth en a une, et un Magicien Rouge en porte un double.]], [[Obtenez le double, occupez-vous d'abord des mercenaires, puis libérez les esclaves avant d'affronter Lanneth.]] }, s = [[Dans l'enclave des Magiciens Rouges, regardez le minotaure Ghallus tuer un mercenaire dans l'arène, puis parlez-lui.
Il lui faut une clef pour se libérer, ainsi que les autres esclaves. Lanneth en a une, mais un Magicien Rouge détient un double : trouvez-le et prenez-le.
Ghallus préfère que vous vous occupiez d'abord des mercenaires (voir la 1re partie).
Revenez et ouvrez les cellules des esclaves. Si les mercenaires sont toujours là, Ghallus mène contre eux une révolte sanglante.
Ghallus vous aide ensuite à combattre Lanneth et ses serviteurs.]] },
[94495] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Forêt Sauvage / Athkatla]], h = { [[Neera veut vous retrouver dans la Forêt Sauvage, hors d'Athkatla, au sujet d'un camp secret d'entropistes.]], [[Au Refuge Caché, Telana vous demande de protéger l'entropiste elfe Daxus, qui se produit chez Delosar.]], [[Quand le Refuge est détruit, les survivants sont retenus dans l'enclave des Magiciens Rouges, Promenade de Waukyne.]] }, s = [[Rencontrez Neera à Athkatla ; elle vous donne rendez-vous dans la Forêt Sauvage. Si elle ne trouve pas encore le camp, revenez plus tard. Trouvez ensuite un moyen de franchir les protections du camp.
Au Refuge Caché, rencontrez Telana et Hayes, qui protègent les entropistes de l'Ordre des Huit Bâtons. Parlez aux autres réfugiés pour des quêtes secondaires.
Avec Neera, allez la nuit à l'auberge de Delosar, au quartier du pont, et parlez à Daxus après son spectacle. Donnez-lui un des Talismans de foyer ardent de Cognor, ou laissez Hayes l'escorter. Protégez-le des Magiciens Rouges.
Pendant votre absence, le Refuge est détruit. Telana dit que les captifs sont dans l'enclave des Magiciens Rouges, Promenade de Waukyne : entrez, libérez-les et vainquez Lanneth (voir L'ordre en désordre).
Retournez au Refuge pour parler à Telana et Neera.]] },
[94558] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II, cuisine]], h = { [[Les deux aides du cuisinier en ont assez de sa tyrannie.]], [[Le cuisinier est allergique au fongixyle en poudre ; le marchand Braillegosier en a peut-être.]], [[Glissez la poudre dans une marmite sur le feu, ou dénoncez les comploteurs au cuisinier.]] }, s = [[Dans la cuisine, parlez à Marduuk et Bref-Ordre. Ils vous demandent de glisser du fongixyle en poudre dans la nourriture du cuisinier.
Achetez la poudre à Braillegosier et au Concocteur, au marché (ils peuvent aussi la tirer d'une potion de peau d'écorce).
Pendant que le cuisinier regarde ailleurs, utilisez la poudre sur une marmite. Il meurt, tout comme son garde du corps, qui a la même allergie.
Autre choix : dénoncez le complot au cuisinier. Il vous en est reconnaissant, mais Dennaton l'apprend et les deux aides disparaissent.]] },
[94559] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II, cuisine]], h = { [[Le cuisinier a une faveur à vous demander.]], [[Il veut un morceau du myconide qui vend des potions au marché.]], [[Braillegosier peut fournir un morceau de son associé, le Concocteur.]] }, s = [[Parlez au cuisinier dans la cuisine ; il veut un petit morceau du myconide du marché pour une soupe spéciale.
Allez voir Braillegosier et le Concocteur au marché et obtenez un morceau du Concocteur.
Rapportez la chair de myconide au cuisinier. Il vous apprécie davantage ensuite.]] },
[94560] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Le scribe qui chronique les combats de l'arène a un air étrangement familier.]], [[Évoquez sa ressemblance avec Baeloth ; le marchand illithid veut son anneau.]], [[Son anneau s'échange contre la pierre runique de l'illithid, qui s'échange contre la clef de frère Ellraish.]] }, s = [[Parlez à Stannel Eibor, le scribe des combats. Évoquer sa ressemblance avec Baeloth l'Esthète le met mal à l'aise.
Le marchand illithid veut par-dessus tout l'anneau de Stannel ; récupérez-le auprès du scribe.
Échangez l'anneau contre la pierre runique de l'illithid, puis donnez la pierre à frère Ellraish contre la clef du salon des Chasseurs.]] },
[94561] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Baladine, l'une des Chasseurs planaires, aime boire ; plusieurs captifs la détestent.]], [[Beaucoup de gens peuvent fabriquer ou vendre un poison ; il faut aussi une boisson et un messager.]], [[Voghiln ou un Hautain peut attirer Baladine avec une boisson spéciale ou un concours de boisson.]] }, s = [[But : empoisonner Baladine pour affaiblir les gros bras de Dennaton avant les derniers combats.
1. Obtenez un poison, au choix : Braillegosier et le Concocteur (tout prêt), frère Ellraish (quartz en poudre, crottes de rat), Gezzthemin (alcool distillé, racine de lotus), Feldrak (pétales de rose, vinaigre), ou la mort-aux-rats d'un placard de la cuisine.
2. Trouvez une boisson pour le cacher : la bière de cérémonie de Molzahn, le prêtre de Tymora (il en veut à Baladine), ou des spiritueux.
3. Faites prévenir Baladine : Voghiln boit avec elle et peut transmettre une offre de boisson ou un défi de concours de boisson ; un Hautain peut le faire aussi.
Si elle boit, elle sera affaiblie lors du combat à venir. En cas d'échec, il faudra un autre moyen d'affaiblir les Chasseurs.]] },
[95658] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Le vieux mage surnommé « L'Antique Menace » vous oublie au milieu d'une phrase.]], [[Un baume pourrait éclaircir l'esprit de Dulf Ténébarbe un moment ; demandez aux marchands de l'arène.]], [[Le Concocteur peut préparer le baume de sénilité sereine de Teodgren pour une petite somme.]] }, s = [[Dulf Ténébarbe est trop sénile pour être utile.
Allez voir Braillegosier et le Concocteur au marché et achetez le baume de sénilité sereine de Teodgren (environ 100 pièces d'or).
Donnez-le à Dulf : son esprit s'éclaircit un temps et il peut alors vous aider, notamment avec le parchemin de transfert d'esprit contre Bannor (voir Marchands).]] },
[95779] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Deux scribes peuvent rédiger un parchemin qui transfère l'esprit de Bannor dans un autre être.]], [[Dulf Ténébarbe veut des ingrédients rares ; Gerrold Sombr'homme veut de l'or, mais garantit moins.]], [[Dans les deux cas, il faut un objet propre à Bannor : fouillez sa chambre à l'étage.]] }, s = [[Pour affaiblir le Chasseur planaire Bannor Kaxazel, obtenez un parchemin de transfert d'esprit.
Option 1 : Dulf Ténébarbe (lucide seulement après son baume, voir sa quête) veut une dent de wyrm, un œuf de ver charognard, un parchemin en peau d'ettin et un objet de Bannor, plus une grosse somme d'or.
Option 2 : Gerrold Sombr'homme demande seulement un objet de Bannor et 4 000 pièces d'or, mais sans garantie sur l'effet.
L'objet : un éclat du miroir brisé de la chambre de Bannor, dans les quartiers des Chasseurs planaires à l'étage (voir Monter).
Après livraison, le scribe travaille un moment puis vous remet le parchemin. Seul un lanceur de sorts peut s'en servir : lisez-le sur Bannor lors de l'affrontement.]] },
[95872] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Un gladiateur orgueilleux parmi les combattants adore parler de lui.]], [[Dire à Symm Haximus la simple vérité sur les gladiateurs le touche au vif.]], [[Combattez à ses côtés dans l'arène et il vous confiera ses secrets.]] }, s = [[Parlez à Symm Haximus, qui se dit gladiateur professionnel.
Lui dire que les gladiateurs ne sont que des esclaves le contrarie ; cela peut servir plus tard.
Il propose de vous révéler certains secrets s'il combat avec vous : prenez-le dans le groupe pour les combats de l'arène, puis reparlez-lui entre les combats.]] },
[96007] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Une justicière autoproclamée se trouve parmi les combattants.]], [[Mercy Blanche-Colombe en sait long sur la loyauté des gardes de l'arène.]], [[Combattez à ses côtés dans l'arène pour en apprendre plus sur son passé.]] }, s = [[Parlez à Mercy Blanche-Colombe.
Elle vous apprend que les gardes de l'arène ne sont guère loyaux envers Dennaton et ne peuvent tenir face aux combattants sans l'Ailée : utile pour une révolte.
Elle vous en dira plus sur son passé si elle combat avec vous : prenez-la dans le groupe pour les combats de l'arène, puis reparlez-lui.]] },
[96026] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II]], h = { [[Frère Ellraish peut vous faire entrer au salon des Chasseurs, contre un prix.]], [[Le marchand illithid cédera sa pierre runique contre un objet qu'il convoite.]], [[Il veut l'anneau de Stannel Eibor, le scribe de l'arène.]] }, s = [[Frère Ellraish veut la pierre runique du marchand illithid en échange d'une clef du salon des Chasseurs.
Parlez au marchand illithid : il accepte d'échanger la pierre contre l'anneau de Stannel Eibor.
Obtenez l'anneau de Stannel, donnez-le à l'illithid, puis apportez la pierre à Ellraish.
Il vous remet la clef du salon des Chasseurs, à l'étage.]] },
[96076] = { g = [[tob]], k = [[companion]], o = 0, c = [[8-9]], w = [[Téthyr / Thay]], h = { [[Telana fait savoir à Neera que Vicross, chef de l'Ordre des Huit Bâtons, est tout près, au Téthyr.]], [[Neera veut l'attirer dans un piège dans une clairière avec une décharge de magie entropique.]], [[Un hiatus entropique vous emporte en Thay, où Szass Tam propose de vous envoyer dans la propriété de Vicross.]] }, s = [[Avec Neera dans le groupe pendant le Trône de Bhaal, elle apprend que Vicross est proche. Allez à la clairière qu'elle propose.
Neera lance la rupture hasardeuse de Nahal ; dressez le camp et attendez Vicross et les Magiciens Rouges.
Vicross, elle-même entropiste, se téléporte en Thay, et un hiatus entropique vous entraîne avec elle dans une arène de gladiateurs. Gagnez le combat.
Le maître de l'arène, Dennaton, vous convoque en coulisse. Szass Tam, zulkir de la nécromancie, veut la mort de Vicross : reposez-vous et préparez-vous, puis il vous téléporte dans sa propriété.
Tuez Vicross, fouillez ses appartements et sonnez la Cloche de convocation.
Szass Tam vous trahit ; résistez à son attaque jusqu'à ce qu'il vous renvoie au Téthyr. L'Ordre des Huit Bâtons est fini.]] },
[96107] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-10]], w = [[Athkatla, quartier des temples / Gorge de la Résurrection]], h = { [[Le maître démoniaque de Dorn veut la mort d'un paladin de Helm : renseignez-vous au temple de Helm d'Athkatla.]], [[Telwyn sait où est parti Terpfen ; plus tard, une marilith nommée Azothet propose à Dorn une issue.]], [[Dans la Gorge de la Résurrection, réunissez toutes les pierres de convocation et la lame abyssale pour sceller Ur-Gothoz.]] }, s = [[Avec Dorn dans le groupe, Ur-Gothoz exige la mort de Terpfen, un paladin de Helm.
Allez de nuit au temple de Helm, dans le quartier des temples, et interrogez Telwyn : Terpfen escorte un prêtre de Tyr dans un camp au sud de la ville. Rendez-vous-y et tuez-le.
Plus tard, Azothet, une marilith, pousse Dorn à se libérer dans la Gorge de la Résurrection. Vous pouvez aussi dénoncer son complot à Ur-Gothoz.
Dans la gorge, la dryade Achilée vous laisse entrer mais vous demande de tuer le tanar'ri qui rôde près de son arbre. Le druide Vernus parle des pierres de convocation manquantes : l'une est derrière la cascade de Frivière (sud-ouest), les dragons en gardent une, les tanar'ris portent les autres. Rassemblez-les toutes avec la lame abyssale, puis utilisez le cercle du grand arbre pour sceller Ur-Gothoz. Combats durs contre démons et dragons.
Dans Le Trône de Bhaal, des assaillants divins vous traquent : rendez-vous à Lunia, trouvez le Pavillon du Juste Courroux, faites effacer vos noms du Parchemin de la Rétribution, puis fuyez.]] },
[96115] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-10]], w = [[Athkatla, quartier du cimetière]], h = { [[Hexxat, rencontrée à la Couronne de Cuivre, cherche un tombeau au sud-est du quartier du cimetière.]], [[Dans le Tombeau de Dragomir, le fantôme Burich et son bâton en fer ouvrent la chambre du vampire.]], [[La Hexxat que vous connaissez n'est pas la vraie ; la cape et le casque de Dragomir comptent ensuite.]] }, s = [[Recrutez Hexxat à la Couronne de Cuivre et acceptez de trouver le Tombeau de Dragomir, au sud-est du quartier du cimetière. Entrez avec elle, sinon elle quitte le groupe.
À l'intérieur, Burich l'Inflexible vous donne un bâton en fer qui ouvre la chambre de Dragomir mais vous enferme jusqu'à la mort du vampire. Détruisez Dragomir.
Le tombeau révèle alors la vérité : la femme qui vous accompagnait libère la vraie Hexxat, une vampire, qui peut vous rejoindre. Donnez-lui la Cape de Dragomir pour qu'elle supporte le jour.
Plus tard, Cabrina, la messagère de son employeur, vous envoie grâce au Casque de Dragomir dans les cryptes de Durkon, à Shou Lung. Aidez Keno, le moine spectral, contre les flagelleurs mentaux de la Crypte des Érudits, réussissez l'épreuve de Ki Chin Sang (ouvrez un sarcophage du hall) pour la clef, et rapportez la Griffe du Léopard noir en Amn.
Dans Le Trône de Bhaal, trouvez le Linceul de l'Inaccompli à Zakhara ; L forge le Casque d'Asservissement et vous envoie dans le labyrinthe de Korkorran. Détruisez la liche Korkorran pour conclure la quête.]] },
[100039] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Refuge Caché]], h = { [[Au Refuge Caché de Neera, l'artificier petite-personne n'a plus de matériaux.]], [[Cognor Crépiton a besoin d'un collier d'argent, de deux diamants et d'une somme d'or.]], [[Un talisman terminé peut aussi amener Daxus, le mari de Telana, au Refuge.]] }, s = [[Pendant la quête de Neera, rejoignez le Refuge Caché et parlez à Cognor Crépiton.
Il demande un collier d'argent, deux diamants et 3 000 pièces d'or pour fabriquer un talisman de foyer ardent, qui téléporte son porteur au Refuge.
Apportez-lui le tout ; il vous remet le talisman.
Telana veut que l'on ramène son mari Daxus d'Athkatla. Donnez-lui le talisman pour l'envoyer aussitôt au Refuge ; sinon Hayes, qui attend au sud de l'auberge de Delosar, peut l'escorter.]] },
[102771] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II, marché]], h = { [[Les vendeurs de potions du marché en veulent à l'un des Chasseurs planaires.]], [[Demandez-leur comment ils ont été capturés, et s'ils sont payés pour leur travail.]] }, s = [[Parlez à Braillegosier et au Concocteur, les marchands de potions du marché.
Interrogez-les sur leur capture : Baladine a blessé le Concocteur en les capturant, ce qui en fait des alliés contre elle (ils peuvent ensuite vous vendre un poison pour elle).
Convainquez Braillegosier qu'il mérite d'être payé pour vendre des potions aux combattants afin de compléter ce fil de dialogue.]] },
[102772] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Fosses noires II, escalier vers l'étage]], h = { [[Seuls les Chasseurs planaires et leurs serviteurs, les Hautains, peuvent emprunter l'escalier gardé.]], [[Un Hautain vend des uniformes ; la clef d'Ellraish ou un crochetage ouvrent aussi la porte.]], [[Si le capitaine de la garde vous arrête, un pot-de-vin ou une sale besogne pour lui vous ouvrira la voie.]] }, s = [[Une porte gardée bloque l'escalier des quartiers de Dennaton et des Chasseurs planaires. Moyens de passer :
- Achetez des uniformes de Hautains à l'un d'eux et passez devant le garde (remettez ensuite les uniformes en place).
- Utilisez la clef de frère Ellraish.
- Crochetez la serrure et occupez-vous du garde.
Le capitaine de la garde peut encore vous arrêter dans le couloir. Soudoyez-le, ou acceptez sa mission : tuer Branson, le neveu de Dennaton, un garde qui se repose sur sa couchette dans les quartiers des gardes.
Tuez Branson, ou épargnez-le : il vous donne son anneau de famille comme preuve. Dans les deux cas, le capitaine vous laisse passer. À l'étage, évitez d'éveiller les soupçons.]] },
[218675] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Mines de Nashkel]], h = { [[Une dague en votre possession appartient à un mineur nommé Kylee.]], [[Kylee travaille dans les niveaux inférieurs des mines de Nashkel.]], [[Trouvez le mineur Kylee au fond des mines et rendez-lui sa dague.]] }, s = [[Une fois en possession de la dague de Kylee et chargé de la lui rendre, descendez dans les mines de Nashkel.
Dans les niveaux inférieurs, cherchez le mineur Kylee parmi les ouvriers.
Parlez-lui et rendez-lui la dague. Il est soulagé et beaucoup moins nerveux ensuite.]] },
[227561] = { g = [[bg1]], k = [[main]], o = 2, c = [[1]], w = [[Auberge de Brasamical]], h = { [[La dernière instruction de Gorion était de vous rendre à l'auberge de Brasamical.]], [[Suivez les routes vers le nord-est depuis la zone aux abords de Château-Suif pour atteindre l'auberge.]], [[Trouvez Khalid et Jaheira à l'auberge de Brasamical ; méfiez-vous des inconnus hostiles qui connaissent votre nom.]] }, s = [[Après la mort de Gorion, qui vous a défendu contre l'étranger en armure aux abords de Château-Suif, Imoen vous rejoint et peut intégrer le groupe.
Traversez la nature jusqu'à l'auberge de Brasamical, une auberge fortifiée au nord-est. Attendez-vous à quelques embuscades en chemin.
À l'auberge, méfiez-vous : un assassin vous y attend. Éliminez-le.
Trouvez Khalid et Jaheira à l'auberge de Brasamical et parlez-leur. Ils vous rejoignent, et la quête principale continue vers Nashkel et ses mines à problèmes.]] },
[227633] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-5]], w = [[Enclave d'Adoy (à l'est du Pont de Flammevin)]], h = { [[Le passé de Neera la rattrape : un petit-homme l'accuse de vol, et un Magicien Rouge traque les entropistes.]], [[Neera espère que le vieil entropiste Adoy, qui vivrait à l'est du Pont de Flammevin, pourra la conseiller.]], [[Libérez Adoy du hobgobelin Rogdok, puis affrontez le Magicien Rouge Ekandor avec Neera et Adoy.]] }, s = [[Avec Neera dans le groupe, le petit-homme Meklin vous aborde et l'accuse de vol. Payez-lui ce qu'elle a dérobé pour régler l'affaire, ou laissez la situation dégénérer en combat.
Neera entend ensuite parler d'Adoy, un vieil entropiste qui vit à l'est du Pont de Flammevin. Rendez-vous à l'enclave d'Adoy.
Adoy est retenu par les gobelins qu'il a invoqués par accident, et le hobgobelin Rogdok le garde prisonnier pour se faire roi des gobelins. Vainquez Rogdok et libérez Adoy.
Le Magicien Rouge Ekandor, qui pourchasse Neera, vous y suit. Combattez-le aux côtés de Neera et d'Adoy et tuez-le pour mettre fin à sa traque des entropistes.]] },
[228607] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-7]], w = [[Nashkel / Porte de Baldur / Montagnes des Pics Brumeux]], h = { [[Rasaad, un moine de la Conscience Solaire devant l'auberge de Nashkel, est traqué par le culte de la Lune Noire, fidèle à Shar.]], [[Un certain Sorrem a désigné Rasaad aux tueurs ; cherchez-le à la Lame et les Étoiles, à la Porte de Baldur.]], [[Les chefs du culte attendent dans un temple des Montagnes des Pics Brumeux, au sud des mines de Nashkel ; le frère de Rasaad s'y trouve.]] }, s = [[Recrutez Rasaad devant l'auberge de Nashkel. Un peu plus tard, des moines de la Lune Noire tendent une embuscade au groupe pour le tuer.
À la Porte de Baldur, trouvez Sorrem à la taverne de la Lame et des Étoiles. Faites-lui pression : soit il révèle que le culte se réunit au bâtiment des Sept Soleils la nuit, soit il meurt et vous oriente vers les Montagnes des Pics Brumeux.
La nuit, réglez leur compte aux moines au bâtiment des Sept Soleils ; vous apprenez que leurs ordres viennent d'un nouveau temple dans les Pics Brumeux, au sud des mines de Nashkel.
Rendez-vous dans les Pics Brumeux. Méfiez-vous des trolls des glaces et des aspirants rejetés par le culte. Dans le temple se trouve Gamaz, le frère de Rasaad, devenu serviteur de Shar. Attendez-vous à un combat difficile contre lui et ses moines.]] },
[231092] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-5]], w = [[Nashkel / à l'est de Nashkel / abords de la Porte de Baldur]], h = { [[Dorn traque les membres de son ancien groupe d'aventuriers qui l'ont trahi.]], [[Taris, à Nashkel, sait où se trouve Kryll, mais les menaces de Dorn l'ont effrayée ; essayez la douceur.]], [[Tuez Kryll à l'est de Nashkel, puis lisez sa lettre pour trouver Simmeon aux abords de la Porte de Baldur.]] }, s = [[Recrutez le chevalier noir demi-orque Dorn Il-Khan. Il traque les membres de son ancien groupe qui lui ont causé du tort.
À Nashkel, parlez vous-même à Taris avec des réponses aimables : elle vous envoie à l'est de Nashkel, où la sorcière Kryll a ensorcelé son mari et d'autres personnes.
Allez-y et tuez Kryll et ses fidèles charmés. Elle porte une lettre de Simmeon, le dernier ennemi de Dorn.
Rendez-vous à l'entrée de la Porte de Baldur, où Simmeon attend. C'est lui aussi un chevalier noir : attendez-vous à un combat difficile.
Simmeon mort, la vengeance de Dorn est accomplie et il reste avec vous.]] },
[231270] = { g = [[bg1]], k = [[main]], o = 1, c = [[1-7]], w = [[Côte des Épées]], h = { [[Suivez la crise du fer : la piste commence à Nashkel et dans ses mines.]], [[Les lettres trouvées sur chaque méchant mènent au suivant : Tranzig, le camp des bandits, puis la mine de Bois-Manteau.]], [[À la Porte de Baldur, le Trône de Fer et Sarevok sont derrière tout ; son journal et le couronnement concluent l'affaire.]] }, s = [[Ch. 1 : après la mort de Gorion, allez au nord à l'Auberge de Brasamical retrouver Khalid et Jaheira.
Ch. 2 : à Nashkel, voyez Berrun Tuemort, puis nettoyez les mines jusqu'à Mulahey ; ses lettres désignent Tranzig à Bérégost.
Ch. 3 : Tranzig vous envoie au Bois de Lars ou à Valpeld et au camp des bandits ; fouillez la tente de Tazok.
Ch. 4 : inondez la mine de Bois-Manteau en retirant son bouchon scellé.
Ch. 5 : à la Porte de Baldur, voyez la Balafre, puis le Duc Eltan, et enquêtez sur le Trône de Fer.
Ch. 6 : à Château-Suif, on vous accuse du meurtre de Rieltar ; Tethtoril vous libère par les catacombes.
Ch. 7 : recherché par le Poing Enflammé, sauvez le Duc Eltan, prenez le journal de Sarevok, l'invitation sur Slythe et Krystin aux Caves Souterraines, démasquez Sarevok au Palais Ducal, puis poursuivez-le par le labyrinthe de la guilde jusqu'à Ombre-Ville.
Cette ligne contient aussi les entrées principales de Siege of Dragonspear.]] },
[231271] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, près du palais]], h = { [[Rinnie, la barde, habite une maison à côté du Palais Ducal.]], [[Elle veut un livre sur l'histoire de la Descente de la Licorne.]], [[Surveillez les boutiques et le butin pour trouver ce livre d'histoire, puis donnez-le-lui.]] }, s = [[Parlez à Rinnie dans l'une des maisons voisines du Palais Ducal, à la Porte de Baldur. Elle demande "L'Histoire de la Descente de la Licorne".
Trouvez un exemplaire de ce livre au cours de vos voyages (boutiques qui vendent des livres ou coffres en chemin).
Retournez voir Rinnie et donnez-le-lui pour clore la quête et recevoir sa récompense.]] },
[231272] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Bérégost]], h = { [[Un vieux mage de Château-Suif, Perleflamme Cheveux-d'Elfe, se promène dans les rues de Bérégost.]], [[Il veut un livre intitulé "L'histoire de la Pièce Fatidique".]], [[Thalantyr, le mage de la Haute-Haie à l'ouest de Bérégost, le vend.]] }, s = [[Parlez à Perleflamme Cheveux-d'Elfe à Bérégost. Il vous demande de lui acheter "L'histoire de la Pièce Fatidique".
Allez à la Haute-Haie, la zone à l'ouest de Bérégost, et achetez le livre à Thalantyr dans sa maison.
Rapportez-le à Perleflamme à Bérégost. Il vous remercie et vous donne une récompense.]] },
[231273] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Zone du phare]], h = { [[Une mère inquiète, Ardrouine, vit sur la côte près d'un vieux phare.]], [[Son fils est pris au piège dans le phare abandonné à l'ouest, encerclé par des worgs.]], [[Tuez les worgs autour du phare, puis retournez voir Ardrouine.]] }, s = [[Parlez à Ardrouine dans la zone côtière du vieux phare. Son fils est coincé dans le phare abandonné, à l'ouest.
Allez au phare et tuez les worgs qui l'encerclent. Ils attaquent en meute : gardez les personnages fragiles en retrait.
Retournez voir Ardrouine : son fils est sauf et elle vous donne ses 60 dernières pièces d'or.]] },
[231274] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, taverne du Chant de l'Elfe]], h = { [[Une noble de la Porte de Baldur est victime d'un chantage et veut que cela cesse.]], [[Le maître-chanteur, Cyrdemac, boit à la taverne du Chant de l'Elfe.]], [[Tuez Cyrdemac et retournez la voir, ou refusez, ou charmez-la pour être payé sans tuer.]] }, s = [[Une noble de la Porte de Baldur vous propose de tuer Cyrdemac, l'homme qui la fait chanter. Vous pouvez refuser net (la quête s'arrête).
Si vous acceptez, allez à la taverne du Chant de l'Elfe, trouvez Cyrdemac et tuez-le (un acte mauvais : attention à la réputation et aux gardes).
Retournez la voir pour être payé. Une option maléfique vous permet de reprendre le chantage : elle vous paie alors tous les deux jours.
Si vous la charmez, elle vous donne la récompense sans meurtre.]] },
[231275] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, au sud du Chant de l'Elfe]], h = { [[Un nécromancien qui vit près de la taverne du Chant de l'Elfe manque de cadavres.]], [[Arkion affirme que les égouts de la ville sont le meilleur endroit pour en trouver.]], [[Ramassez un corps dans les égouts de la Porte de Baldur et rapportez-le chez Arkion.]] }, s = [[Parlez à Arkion dans sa maison juste au sud de la taverne du Chant de l'Elfe, à la Porte de Baldur. Il veut un cadavre.
Descendez dans les égouts de la ville (plusieurs bouches en ville) et cherchez un corps que vous pouvez ramasser.
Rapportez-le à Arkion : il vous paie quelques pièces d'or.
Arkion est aussi mêlé à deux autres quêtes, avec Nemphré et Ordulinian.]] },
[231276] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Côte des Épées]], h = { [[Un gnome bavard, Delsvirftanyon, veut quitter le commerce de bibelots.]], [[Il vous propose d'acheter tout son stock d'un coup.]], [[Payez son prix si vous en avez les moyens et triez le fatras ; refuser met juste fin à la quête.]] }, s = [[Parlez au gnome Delsvirftanyon. Il veut arrêter la brocante et vous propose tout le contenu de sa boutique.
Vous pouvez refuser faute de place, ou parce que le prix est trop élevé : la quête s'arrête simplement.
Si vous avez l'or, achetez le tout. Les objets arrivent dans votre inventaire : faites de la place avant, puis revendez ce qui ne sert pas.]] },
[231279] = { g = [[bg1]], k = [[main]], o = 7, c = [[3-4]], w = [[Bois-Manteau]], h = { [[Les documents de la tente de Tazok, au camp des bandits, désignent une base du Trône de Fer dans le Bois-Manteau.]], [[Dans le Bois-Manteau, les druides Takiyah et Faldorn savent où la forêt est empoisonnée.]], [[Le fortin se trouve à l'est du bosquet des druides ; l'accès aux mines est dans son enceinte est.]] }, s = [[Au camp des bandits, libérez Ender Saï dans la tente de Tazok et lisez les documents du coffre de Tazok : le Trône de Fer dirige les bandits depuis une base du Bois-Manteau.
Traversez le Bois-Manteau. Takiyah vous envoie vers Faldorn, qui combat ceux qui empoisonnent la forêt ; acceptez de l'aider.
Allez au nord puis à l'est du bosquet des druides jusqu'au fortin du Trône de Fer. Combattez les gardes ; l'un d'eux révèle que l'accès aux mines est dans l'enceinte est.
Entrez dans les mines de Bois-Manteau pour poursuivre l'histoire principale.]] },
[231280] = { g = [[bg1]], k = [[main]], o = 6, c = [[3]], w = [[Camp des bandits]], h = { [[Tazok, le lieutenant des bandits, rend des comptes à un supérieur.]], [[Kivan le rôdeur traque Tazok et pourra vous en dire plus.]], [[Tazok se rend dans une mine : le camp des bandits et ses documents indiquent où.]] }, s = [[Vous l'apprenez par Kivan ou par Tazok lui-même : Tazok prévoit de se rendre sur le site d'une mine, où il ferait son rapport au véritable chef des bandits.
Poursuivez au camp des bandits : fouillez la tente de Tazok et son coffre pour trouver les documents.
Ils désignent le Trône de Fer et sa mine cachée dans le Bois-Manteau, ce qui continue dans "Une base secrète à Bois-Manteau".]] },
[231281] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-7]], w = [[Bérégost, forge de Grondemarteau]], h = { [[Taërom "Grondemarteau", le forgeron de Bérégost, sait travailler des matériaux insolites.]], [[Apportez-lui une carapace d'ankheg et il peut en faire une armure de plates.]], [[Payez son prix, attendez les jours qu'il demande, puis revenez chercher l'armure.]] }, s = [[Trouvez une carapace d'ankheg (les ankhegs et leurs terriers sur la Côte des Épées).
Parlez à Taërom "Grondemarteau" dans sa forge de Bérégost. Il propose de vous faire une armure de plates en carapace d'ankheg pour 4 000 pièces d'or.
Payez-le : selon le dialogue, l'armure est prête en un ou trois jours.
Reposez-vous ou voyagez, puis revenez voir Taërom pour récupérer votre armure en carapace d'ankheg, une armure solide en début de partie.]] },
[231283] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Tutoriel]], h = { [[Ce n'est qu'un rappel de l'instructeur de combat, Belt.]], [[Retournez voir Belt et terminez l'entraînement au combat commencé.]], [[Suivez ses instructions jusqu'au bout ; la note disparaît une fois l'entraînement fini.]] }, s = [[Cette entrée rappelle que vous n'avez pas terminé l'entraînement au combat de Belt.
Retrouvez Belt et parlez-lui, puis suivez les étapes d'entraînement qu'il vous donne jusqu'à ce qu'il dise que c'est fini.
Il n'y a pas de vraie récompense à part l'exercice ; vous pouvez l'ignorer si vous savez déjà vous battre.]] },
[231284] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Côte des Épées]], h = { [[Fergus, un soldat du Poing Enflammé, a un problème de cœur.]], [[Il lui faut un anneau particulier à offrir à sa bien-aimée.]], [[Apportez-lui un anneau en peau d'ange et donnez-le-lui.]] }, s = [[Parlez à Fergus, un soldat du Poing Enflammé. Il veut un cadeau pour la femme qu'il aime : un anneau en peau d'ange.
Gardez tout anneau en peau d'ange trouvé dans le butin ou en boutique au lieu de le vendre.
Retournez voir Fergus avec l'anneau et donnez-le-lui pour clore la quête.]] },
[231285] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-3]], w = [[Au sud de l'Auberge de Brasamical]], h = { [[Une naine clerc grincheuse, Unshey, s'est fait prendre son ceinturon par un ogre.]], [[L'ogre rôde dans la nature, juste au sud de l'Auberge de Brasamical.]], [[Tuez l'ogre, prenez le ceinturon perceur et retournez voir Unshey.]] }, s = [[Parlez à Unshey, la naine clerc. Un ogre fétichiste des ceintures lui a volé son ceinturon perceur.
Trouvez l'ogre dans la zone juste au sud de l'Auberge de Brasamical et tuez-le. Il frappe fort à bas niveau : attaquez à distance et restez mobile.
Prenez le ceinturon sur son corps et rapportez-le à Unshey. Selon le cas, elle paie 95 pièces d'or pour l'ogre mort ou 70 pour le ceinturon, avec une remarque vexante sur votre odeur.]] },
[231287] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Barbe d'Ulgoth / Tour de Durlag]], h = { [[Un bonimenteur bruyant nommé Ike vend des visites de la tour de Durlag.]], [[Fenrus, près des quais de Barbe d'Ulgoth, a déjà fait la visite.]], [[Acceptez la visite et retrouvez Ike près de la tour, mais ne vous attendez pas à un endroit sûr.]] }, s = [[Rencontrez Ike, qui propose des visites de la tour de Durlag. Vous pouvez refuser ; il reste disponible si vous changez d'avis.
Interrogez Fenrus, près des quais, sur la visite et l'histoire de la tour.
Acceptez l'offre d'Ike et retrouvez-le à l'entrée de la tour de Durlag.
La visite vous mène au danger plutôt qu'en sécurité. La pierre-sésame d'Ike ouvre certaines salles souterraines : voir "La tour de Durlag" pour la suite.]] },
[231288] = { g = [[bg1]], k = [[main]], o = 12, c = [[7]], w = [[Porte de Baldur, siège du Poing Enflammé]], h = { [[Après Château-Suif, le Poing Enflammé vous traque sur ordre de son nouveau commandant, Angelo.]], [[Évitez de tuer les gardes : vous pouvez vous rendre, ou les ralentir et fuir.]], [[Si vous finissez dans les cachots du Poing Enflammé, parlez au prisonnier Neb.]] }, s = [[De retour à la Porte de Baldur, des patrouilles du Poing Enflammé tentent de vous arrêter : Angelo Dosan a remplacé le Duc Eltan et vous a condamné.
Tuer les gardes coûte de la réputation ; immobilisez-les et fuyez, ou rendez-vous.
Si vous vous rendez, Angelo vous condamne à la pendaison et vous enferme. Dans la cellule, Neb vous apprend qu'Eltan est malade et que la Balafre est mort, puis vous fait sortir par un passage secret qu'il a caché.
Si Shar-Teel est dans le groupe, Angelo, son père, vous relâche une fois, mais ne vous faites pas reprendre.
L'histoire continue avec "L'agonie du Duc Eltan".]] },
[231289] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, Guilde des Voleurs]], h = { [[Alatos Thuibuld, maître de la Guilde des Voleurs, a un cambriolage à vous confier.]], [[Les trois filles de Shandalar, au domaine d'Obéron, détiennent les pièces d'un vaisseau aérien de Halruaa.]], [[Faites-vous d'abord des amis chez les voleurs, Narlen surtout, sinon la paie tournera au piège.]] }, s = [[Parlez à Alatos à la Guilde des Voleurs. Refuser ou l'insulter rend la guilde hostile.
Acceptez le travail : prenez un livre de sorts, une statuette et un fragment d'artefact aux trois filles de Shandalar, au domaine d'Obéron, en parlant ou en volant.
Rapportez les objets à la guilde. Alatos et Resar, le Halruaan, comptaient se débarrasser de vous.
Si vous avez déjà fait les cambriolages avec Narlen et le Rouge, Narlen tue Resar et Alatos renonce. Sinon, il faut vous battre pour sortir ; rapporter seulement une partie des objets finit aussi en combat.]] },
[231290] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Environs de Nashkel]], h = { [[Un garçon nommé Albert a perdu son chien, Rufie, aux abords de Nashkel.]], [[Albert vous donne le jouet à mâcher de Rufie pour attirer le chien.]], [[Rufie n'a rien d'un chiot ordinaire : à vous de choisir entre le ramener et l'abattre.]] }, s = [[Parlez à Albert. Si vous refusez, la quête s'arrête. Si vous acceptez, il vous donne le jouet à mâcher de Rufie.
Cherchez Rufie dans la nature aux abords de Nashkel ; avec le jouet dans l'inventaire, le "chien" vous suit.
Ramenez-le à Albert pour les réunir ; tous deux disparaissent ensuite, et mieux vaut ne pas demander où.
Si vous tuez Rufie à la place, Albert devient votre ennemi.]] },
[231291] = { g = [[bg1]], k = [[side]], o = 0, c = [[4]], w = [[Bois-Manteau]], h = { [[Dans le Bois-Manteau, un noble de la Porte de Baldur a des ennuis avec une bande de druides.]], [[Aldeth Sashenstar et le druide Séniyad veulent chacun votre aide.]], [[Combattez les druides, rangez-vous de leur côté, ou calmez les deux camps ; Aldeth peut vous inviter chez lui.]] }, s = [[Dans le Bois-Manteau, rencontrez Aldeth Sashenstar, un noble marchand de la Porte de Baldur menacé par des druides menés par Séniyad.
Aidez Aldeth : repoussez les druides par la force, ou trouvez les mots pour désamorcer le conflit. Dans les deux cas, il vous invite chez lui à la Porte de Baldur, ce qui servira plus tard en ville.
Ou rangez-vous du côté des druides et tuez Aldeth : Séniyad vous remercie.]] },
[231292] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur (nord-ouest) / Bérégost]], h = { [[Le nain Pheirkas, au nord-ouest de la Porte de Baldur, veut qu'on vole une cape.]], [[Son propriétaire, le gros Algernon, loge à l'auberge de Feldepost à Bérégost.]], [[Faites les poches d'Algernon, ou prenez la cape par la force, et rapportez-la à Pheirkas.]] }, s = [[Parlez à Pheirkas dans le quartier nord-ouest de la Porte de Baldur. Il veut la cape d'Algernon.
Allez à Bérégost et trouvez Algernon à l'auberge de Feldepost. Un voleur peut lui subtiliser la cape ; sauvegardez avant, un échec le rend hostile.
Retournez voir Pheirkas à la Porte de Baldur et donnez-la-lui : il paie bien.
Vous pouvez aussi garder la cape ; c'est un objet magique.]] },
[231293] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-7]], w = [[Bérégost, forge de Grondemarteau]], h = { [[Taërom "Grondemarteau", le forgeron de Bérégost, paie pour des morceaux de monstres rares.]], [[Il achète toutes les carapaces d'ankheg que vous lui apportez.]], [[Tuez des ankhegs, prenez leur carapace et vendez-la à Taërom pour une belle somme chacune.]] }, s = [[Parlez à Taërom "Grondemarteau" dans sa forge de Bérégost. Il offre 500 pièces d'or par carapace d'ankheg.
Chassez les ankhegs, qui creusent dans les champs et les terres agricoles, et ramassez les carapaces qu'ils laissent.
Vendez chaque carapace 500 pièces d'or à Taërom. Vous pouvez aussi lui en faire forger une en armure (voir "Une nouvelle armure").
Il mentionne aussi la prime sur Bassilus.]] },
[231294] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur (ouest) / au sud de la ville]], h = { [[Fenten, un vieux nain de l'ouest de la Porte de Baldur, veut des écailles d'ankheg.]], [[Une rôdeuse nommée Gerde surveille les ankhegs dans les plaines au sud de la ville, de l'autre côté de la rivière.]], [[Tuez exactement quatre ankhegs près de Gerde, puis retournez la voir, ainsi que Fenten.]] }, s = [[Parlez à Fenten dans la partie ouest de la Porte de Baldur. Il vous parle des ankhegs au sud de la ville et vous envoie voir Gerde.
Traversez la rivière vers les plaines au sud de la Porte de Baldur et trouvez Gerde. Elle vous montre où les ankhegs surgissent et fixe un quota de quatre victimes ; ne le dépassez pas.
Les ankhegs sont coriaces et crachent de l'acide : affrontez-les quelques-uns à la fois.
Retournez voir Gerde pour 75 pièces d'or, puis apportez les morceaux d'ankheg à Fenten, qui paie le prix convenu.]] },
[231295] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Littoral de la Côte des Épées]], h = { [[Un vieux sage qui parle en vers, Arcande Zinzin, évoque un navire sur le rivage.]], [[Un objet de valeur s'y trouve, et Arcande veut qu'on le lui rapporte sans s'en servir.]], [[Fouillez l'épave du littoral, prenez la bouteille et ne l'ouvrez pas.]] }, s = [[Parlez à Arcande Zinzin. À travers ses énigmes, il évoque un navire sur le littoral qui renferme un objet précieux, et vous demande de le lui rapporter sans vous en servir.
Fouillez la côte de cette zone pour trouver l'épave et prenez la mystérieuse bouteille.
La quête se termine avec la bouteille en votre possession. Arcande vous a déconseillé de l'ouvrir ; libre à vous, mais sauvegardez avant si vous êtes curieux.]] },
[231296] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, Bazar Magique]], h = { [[Ordulinian, du Bazar Magique, en a assez de deux nécromanciens qui se disputent.]], [[Arkion possède une amulette héliotrope et Nemphré un anneau en onyx ; tous deux vivent au sud du Chant de l'Elfe.]], [[Apportez les deux objets à Ordulinian plutôt qu'à l'un des nécromanciens.]] }, s = [[Parlez à Ordulinian au Bazar Magique, à la Porte de Baldur. Il veut l'amulette héliotrope d'Arkion et l'anneau en onyx de Nemphré pour mettre fin à leur querelle.
Allez voir Arkion et Nemphré dans leurs maisons au sud de la taverne du Chant de l'Elfe. Chacun veut l'objet de l'autre ; les obtenir peut signifier affronter des magiciens puissants.
Donnez l'anneau et l'amulette à Ordulinian : il vous offre en échange une belle cape magique.
Si vous donnez plutôt l'amulette à Nemphré, "L'amulette héliotrope d'Arkion" se termine, mais celle-ci devient impossible.]] },
[231297] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, au sud du Chant de l'Elfe]], h = { [[La nécromancienne Nemphré veut récupérer une amulette gardée par son ancien amant.]], [[Arkion, qui vit tout près, détient l'amulette héliotrope et ne la cédera pas facilement.]], [[Obtenez l'amulette d'Arkion et apportez-la à Nemphré, ou gardez-la pour Ordulinian.]] }, s = [[Parlez à Nemphré dans sa maison juste au sud de la taverne du Chant de l'Elfe, à la Porte de Baldur. Elle veut l'amulette héliotrope d'Arkion.
Arkion vit dans le même secteur. C'est un mage capable : obtenez l'amulette par le dialogue, le vol ou le combat, et préparez-vous à ses sorts.
Rapportez l'amulette à Nemphré : elle vous donne un parchemin magique.
Vous pouvez aussi la donner, avec l'anneau en onyx de Nemphré, à Ordulinian au Bazar Magique ("Arkion et Nemphré") pour une meilleure récompense.]] },
[231298] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Barbe d'Ulgoth]], h = { [[À Barbe d'Ulgoth, on dit que quelqu'un a retrouvé le navire de Baldurien, le fondateur de la ville.]], [[Une gnome nommée Dushaï vend ce qu'elle sait moyennant des "honoraires".]], [[Payez Dushaï pour apprendre le dernier voyage de Baldurien vers Anchorome ; cela mène à l'île de son épave.]] }, s = [[Écoutez les habitants de Barbe d'Ulgoth : ils parlent du navire de Baldurien et de sa dernière expédition.
Parlez à la gnome Dushaï et payez ses honoraires. Elle explique que Baldurien est parti vers Anchorome et n'est jamais revenu.
C'est un récit qui ouvre le voyage de Tales of the Sword Coast vers l'île de Baldurien, où se trouve l'épave (voir "Le livre des sorts de Dradeel").]] },
[231299] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, docks]], h = { [[Nadarin, sur les docks de la Porte de Baldur, a un animal dangereux en fuite sur les bras.]], [[Un basilic erre dans un entrepôt du port et pétrifie tout le monde.]], [[Protégez-vous contre la pétrification, tuez le basilic et revenez voir Nadarin.]] }, s = [[Parlez à Nadarin près des docks de la Porte de Baldur. Un basilic s'est échappé d'un navire et se cache dans un entrepôt voisin.
Avant d'entrer, utilisez une protection contre la pétrification (potions, sorts ou objets) si vous en avez ; son regard change les personnages en pierre.
Entrez dans l'entrepôt et tuez le basilic, de préférence à distance.
Retournez voir Nadarin pour une jolie récompense.]] },
[231300] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Bérégost / régions sauvages]], h = { [[Les habitants de Bérégost parlent d'un prêtre meurtrier qui commande aux morts-vivants.]], [[Kelddath Ormlyr, au temple de Lathandre à l'est de Bérégost, offre une prime pour Bassilus.]], [[Trouvez Bassilus et sa "famille" de morts-vivants dans la nature, tuez-le et rapportez son symbole sacré à Kelddath.]] }, s = [[Entendez parler de Bassilus par les habitants de Bérégost ou par Taërom, puis parlez à Kelddath Ormlyr au temple de Lathandre, à l'est de Bérégost : 5 000 pièces d'or pour Bassilus.
Trouvez Bassilus dans la nature. Il est fou, croit que ses morts-vivants sont sa famille et vous prend pour son parent. Footy, un garçon dérangé, rôde à côté.
Bassilus est un prêtre qui lance des sorts et commande des squelettes : occupez-vous des morts-vivants et réduisez-le au silence ou foncez sur lui.
Prenez son symbole sacré et rapportez-le à Kelddath pour la prime de 5 000 pièces d'or.]] },
[231304] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, docks]], h = { [[La petite fille de Brielbara est frappée d'une malédiction mortelle.]], [[L'homme qui l'a lancée, Yago, se trouve à bord de la Lanterne Assourdie.]], [[Prenez le livre de sorts de Yago et apportez-le à Brielbara à l'Esturgeon Sautillant.]] }, s = [[Parlez à Brielbara à la Porte de Baldur. Yago a maudit sa fille pour qu'elle meure, et son livre de sorts contient le moyen de lever la malédiction.
Allez à la Lanterne Assourdie, le navire amarré aux docks, et trouvez Yago. C'est un mage qui ne le cédera pas : attendez-vous à un duel de sorts.
Prenez le livre de sorts de Yago sur son corps.
Retrouvez Brielbara à l'Esturgeon Sautillant et donnez-lui le livre : elle peut maintenant lever la malédiction.]] },
[231306] = { g = [[bg1]], k = [[main]], o = 5, c = [[2-3]], w = [[Bérégost, auberge de Feldepost]], h = { [[Les lettres de Mulahey, trouvées dans les mines de Nashkel, citent un intermédiaire nommé Tranzig.]], [[Tranzig loge à l'auberge de Feldepost, à Bérégost.]], [[Confrontez-le et battez-le : il révèle l'emplacement du camp des bandits.]] }, s = [[Après avoir vaincu Mulahey dans les mines de Nashkel, lisez ses lettres : il rendait des comptes à Tazok par un messager nommé Tranzig.
Allez à l'auberge de Feldepost, à Bérégost, et trouvez Tranzig dans une chambre à l'étage.
C'est un mage qui attaque avec ses complices. Affaiblissez-le et il se rend, avouant qu'il portait les lettres entre Tazok et Mulahey.
Il révèle où se trouvent les bandits, ce qui vous envoie vers le Bois de Lars ou Valpeld et le camp des bandits.]] },
[231307] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Là où les Pics Brumeux rejoignent la mer]], h = { [[Un pêcheur nommé Cordyr se plaint de monstres sur son lieu de pêche.]], [[Deux sirènes hantent les eaux là où les Pics Brumeux rejoignent la mer.]], [[Venez à bout des sirènes, idéalement protégé contre le charme, puis retournez voir Cordyr.]] }, s = [[Parlez à Cordyr le pêcheur. Deux sirènes ont envahi son lieu de pêche, là où les Pics Brumeux rejoignent la mer.
Trouvez les sirènes dans cette zone. Elles peuvent charmer et embrouiller votre groupe : protégez-vous des effets mentaux si possible et attaquez-les une par une.
Retournez voir Cordyr une fois l'affaire réglée : il vous donne un parchemin magique.]] },
[231308] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Tour de Durlag]], h = { [[Un jeune aventurier, Dalton, est pris au piège dans les profondeurs de la tour de Durlag.]], [[Il a survécu à une épreuve mortelle qui l'a opposé à son propre double.]], [[Atteignez Dalton au fond de la tour et aidez-le à en sortir vivant.]] }, s = [[En explorant les niveaux inférieurs de la tour de Durlag, vous rencontrez Dalton, un jeune homme qui a tout juste survécu aux épreuves de la tour : il a dû tuer son propre double.
Parlez-lui et acceptez de l'aider à sortir.
Une fois qu'il est en sécurité, la quête se termine. Si le Chevalier Démon est vaincu, Clair, une survivante de son groupe, est soulagée qu'au moins un ami ait survécu.]] },
[231309] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Île de Baldurien, village]], h = { [[L'historienne du village de l'île, Delainie, a besoin d'un petit service.]], [[Une cape sacrée s'est envolée de la hutte du chef pendant une tempête.]], [[Cherchez la cape hors des murs du village, méfiez-vous des bêtes, puis discutez avec Delainie.]] }, s = [[Dans le village de l'île de Baldurien, parlez à Delainie, l'historienne du village (son équivalent masculin Durlyle peut apparaître à sa place). Refuser met fin à la quête.
Acceptez de retrouver la cape du village arrachée de la hutte du chef. Fouillez la nature hors des murs en vous méfiant des "bêtes" que craignent les habitants.
Rapportez la cape à Delainie. Les conversations suivantes peuvent bien ou mal tourner selon vos réponses.
Les villageois cachent un sombre secret sur l'île : restez sur vos gardes.]] },
[231310] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Île de Baldurien]], h = { [[Un mage elfe à moitié fou, Dradeel, se cache dans une vieille cabane sur l'île.]], [[Il était le navigateur de Baldurien et a perdu son livre de sorts dans le naufrage.]], [[Fouillez le coffre près de la cabine de Baldurien, dans l'épave, et rendez le livre à Dradeel.]] }, s = [[Sur l'île de Baldurien, trouvez Dradeel dans sa vieille cabane. Il raconte que l'équipage de Baldurien s'est arrêté ici au retour d'Anchorome et que des lycanthropes infestent l'île.
Il vous demande de récupérer son livre de sorts dans l'épave du navire de Baldurien, dans un coffre près de la cabine de Baldurien.
Explorez l'épave (attendez-vous à des morts-vivants et d'autres ennemis) et prenez le livre de sorts.
Rapportez-le à Dradeel : il le prend et s'en va sans un merci.]] },
[231311] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Château-Suif]], h = { [[Dreppin, le valet de ferme de Château-Suif, s'inquiète pour sa vache malade, Nessa.]], [[La vache a besoin d'une potion d'antidote, et le garde Hull en a.]], [[Obtenez la potion auprès de Hull, à la porte, et apportez-la à Dreppin.]] }, s = [[Parlez à Dreppin près des étables de Château-Suif. Nessa la vache est malade et a besoin d'une potion d'antidote.
Allez à la porte principale et parlez à Hull, le garde de faction. Il se sert de ces potions contre la gueule de bois, mais vous en donne une.
Rapportez la potion à Dreppin pour clore la quête et gagner un peu d'expérience avant de quitter Château-Suif.]] },
[231312] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Côte des Épées]], h = { [[Une fillette en larmes, Drienne, vous supplie de sauver son chat, Pixie.]], [[Le chat est tombé d'une chute d'eau dans la même zone.]], [[Ramenez le chat à Drienne, même s'il n'est plus en vie.]] }, s = [[Parlez à Drienne. Son chat Pixie est tombé dans une chute d'eau et elle vous demande de le sauver.
Cherchez près de la chute d'eau dans cette zone ; vous n'y trouverez que le corps du pauvre chat. Ramassez-le.
Rapportez-le à Drienne. Elle peut vous accuser d'avoir tué Pixie, mais elle vous paie 23 pièces d'or, ou vous donne l'un des parchemins de son père, qui semble avoir déjà ramené le chat plus d'une fois.]] },
[231313] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Pics Brumeux]], h = { [[Une dryade des Pics Brumeux craint pour son chêne.]], [[Elle vous demande de protéger son arbre de ceux qui le menacent.]], [[Aidez-la pour gagner sa faveur ; fâchez-la et elle parle quand même d'une grotte aux loups avec un trésor au sud.]] }, s = [[Dans les Pics Brumeux, rencontrez une dryade qui vous demande de protéger son arbre.
Acceptez et défendez le chêne contre ceux qui s'en approchent : elle vous accorde sa faveur.
Si vous l'insultez, elle vous chasse de son bois, mais elle évoque aussi une grotte aux loups juste au sud, avec une cachette au trésor.
Un groupe mauvais peut aussi la tuer.]] },
[231314] = { g = [[bg1]], k = [[main]], o = 14, c = [[7]], w = [[Porte de Baldur, siège du Poing Enflammé]], h = { [[Le Duc Eltan est alité dans l'enceinte du Poing Enflammé, tandis qu'Angelo commande à sa place.]], [[Kolvar, Kent et un voyant soupçonnent tous son guérisseur, Rashad.]], [[Déjouez l'attentat contre Eltan, puis escortez-le jusqu'au Maître du Port, à l'est des docks.]] }, s = [[Au chapitre 7, apprenez par les rumeurs, Kolvar, Kent, un contrebandier charmé ou le voyant Delthyr qu'Eltan est gravement malade, que la Balafre est mort et que son guérisseur Rashad est la cause de son mal.
Allez au siège du Poing Enflammé et rejoignez la chambre d'Eltan. Rashad se retourne contre vous : tuez-le pour empêcher l'assassinat.
Eltan demande à être conduit au bâtiment du Maître du Port, à l'est des docks. Escortez-le ; le Maître du Port promet de le cacher.
Allez ensuite au Trône de Fer pour traquer Sarevok.]] },
[231315] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Tour de Durlag]], h = { [[Fenrus, à Barbe d'Ulgoth, connaît l'histoire de la tour de Durlag et sa tragédie des doppelgangers.]], [[Des pierres-sésames ouvrent les verrous magiques des niveaux inférieurs ; Ike en a une.]], [[Le fantôme de Durlag veut qu'on chasse le Chevalier Démon ; Clair conseille de retourner son miroir d'opposition contre lui.]] }, s = [[Apprenez l'histoire de la tour par Fenrus : Durlag a tué des doppelgangers qui avaient le visage de sa famille, est devenu fou et a truffé sa demeure de pièges.
À la tour, Bayard vous met en garde contre les pièges mortels, les pierres-sésames et un Chevalier Démon. Emmenez un bon voleur et sauvegardez souvent.
Montez dans les étages, puis descendez dans le labyrinthe en utilisant une pierre-sésame (celle d'Ike ou une autre trouvée) pour passer les portes scellées.
Le fantôme de Durlag vous demande de comprendre les chemins de la tour en réussissant ses épreuves (faire luire une épée en est une) et de chasser le Chevalier Démon.
Dans les profondeurs, Clair décrit son miroir d'opposition, qui crée des doubles de votre groupe. Retournez le miroir contre le chevalier, puis abattez-le : c'est un lanceur de sorts redoutable.]] },
[231316] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Île de Baldurien, village]], h = { [[L'historien du village de l'île, Durlyle, a besoin d'un petit service.]], [[Une cape sacrée s'est envolée de la hutte du chef pendant une tempête.]], [[Cherchez la cape hors des murs du village, méfiez-vous des bêtes, puis discutez avec Durlyle.]] }, s = [[Dans le village de l'île de Baldurien, parlez à Durlyle, l'historien du village (son équivalente féminine Delainie peut apparaître à sa place). Refuser met fin à la quête.
Acceptez de retrouver la cape du village arrachée de la hutte du chef. Fouillez la nature hors des murs en vous méfiant des "bêtes" que craignent les habitants.
Rapportez la cape à Durlyle. Les conversations suivantes peuvent en faire un ami ou le laisser froid, selon vos réponses.
Les villageois cachent un sombre secret sur l'île : restez sur vos gardes.]] },
[231317] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-3]], w = [[Ouest de Nashkel, bastion gnoll]], h = { [[Près de Nashkel, un Sorcier Rouge nommé Edwin veut la mort d'une sorcière.]], [[Dynahéir est retenue dans le bastion gnoll à l'ouest de Nashkel.]], [[Emmenez Edwin au bastion et tuez Dynahéir, ou refusez et libérez-la plutôt.]] }, s = [[Rencontrez Edwin près de Nashkel. Il vous demande de tuer Dynahéir, une sorcière, et vous rejoint si vous acceptez. Refuser met fin à la quête.
Allez à l'ouest jusqu'au bastion gnoll et frayez-vous un chemin parmi les gnolls jusqu'à Dynahéir.
Tuez-la pour exaucer Edwin. C'est une voie mauvaise, et Minsc, son protecteur, ne l'acceptera pas.
Vous pouvez aussi renvoyer Edwin et rompre l'alliance. Si vous libérez Dynahéir à la place, elle peut vous rejoindre.]] },
[231318] = { g = [[bg1]], k = [[companion]], o = 0, c = [[4-5]], w = [[Bois-Manteau / Porte de Baldur]], h = { [[Un barde qui boit seul dans le Bois-Manteau mijote un plan autour de la fille d'un duc.]], [[Skie vit dans la demeure de son père, le domaine Écudargent, à la Porte de Baldur.]], [[Emmenez Eldoth avec vous au domaine, sinon Skie vous prendra pour de vrais ravisseurs.]] }, s = [[Trouvez Eldoth dans la forêt du Bois-Manteau, près du pont où attend aussi Coran. Buvez un verre avec lui et acceptez son plan : il rejoint le groupe.
Quand la Porte de Baldur s'ouvre, allez au domaine Écudargent avec Eldoth dans le groupe et parlez à Skie à l'étage. Elle veut fuir de son plein gré.
Invitez-la dans le groupe pour garder les deux compagnons. Si vous refusez de la prendre, Eldoth part avec elle et vous les perdez tous les deux.
Sans Eldoth, Skie refuse de vous suivre.]] },
[231319] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2]], w = [[Bérégost, zone au nord de Bérégost]], h = { [[Kagain, le nain qui tient boutique à Bérégost, a perdu une caravane qui transportait le fils d'un noble.]], [[La caravane attaquée se trouve dans la nature, juste au nord de Bérégost.]], [[Menez Kagain jusqu'à la caravane détruite vers le milieu de cette carte, et ne lui donnez pas d'ordre pendant qu'il parle.]] }, s = [[Kagain vous engage dans sa boutique de Bérégost : une caravane en route vers la Porte de Baldur a été attaquée, et le fils du grand-duc Entar Écudargent était à bord. En acceptant, il rejoint le groupe.
Allez vite dans la zone juste au nord de Bérégost et cherchez la caravane incendiée vers le milieu de la carte. Kagain commente la scène, le fils est retrouvé mort et la quête se termine.
Faites-le tôt : la piste se perd si vous attendez trop. Si Kagain est interrompu par un ordre au moment où il commence à parler, la quête peut ne pas se clore.]] },
[231320] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Balduran (île des loups-garous)]], h = { [[Evalt, un villageois de l'île, craint que son frère Evan ait été attiré au loin par un chant.]], [[La « sorcière bleue » est une sirine qui hante la côte ouest, dans le nord de l'île.]], [[Parlez aimablement à la Dame bleue et elle vous remettra peut-être le corps d'Evan sans combat.]] }, s = [[Au village de l'île (carte sud), Evalt vous demande de chercher son frère Evan, enlevé par une « sorcière bleue » qui chante sur la côte ouest.
Rendez-vous dans le nord de l'île et suivez le rivage ouest jusqu'à la Dame bleue, une reine sirine. Evan est déjà mort. Soyez courtois et elle vous donne son corps ; insultez-la ou attaquez-la et il faudra la tuer pour le récupérer.
Rapportez le corps d'Evan à Evalt. Il est en deuil mais reconnaissant, et vous gagnez de l'expérience.]] },
[231321] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Bois des Dents Acérées (forêt à l'est de Larswood)]], h = { [[Un prêtre étrange, Fahrington, erre dans le Bois des Dents Acérées, infesté d'araignées.]], [[Son parchemin volé est parti vers l'est, emporté par un tasloï jusqu'à un ettercap.]], [[Tuez l'ettercap à l'est, rapportez le parchemin et ne le lisez surtout pas.]] }, s = [[Fahrington se trouve dans le Bois des Dents Acérées, la forêt à l'est de Larswood. Un tasloï lui a volé son « parchemin de sagesse » en partant vers l'est.
Traversez les bois vers l'est : la zone grouille d'araignées et d'ettercaps, et leurs repaires sont souvent piégés, cherchez les pièges. L'ettercap qui porte le parchemin est dans la partie est.
Revenez voir Fahrington avec le parchemin. Il vous le laisse et vous gagnez de l'expérience.
Attention : c'est un parchemin maudit de bêtise. Le lire ruine la Sagesse et baisse l'Intelligence ; vendez-le ou gardez-le dans un sac.]] },
[231323] = { g = [[bg1]], k = [[side]], o = 0, c = [[1]], w = [[Au nord de l'auberge de Brasamical]], h = { [[Un fermier inquiet, Brun, se tient devant sa ferme au nord de l'auberge de Brasamical.]], [[Brun a vu des traces étranges partant à l'ouest de la ferme.]], [[Le corps de Nathan gît dans le repaire d'ankhegs à l'ouest ; fouillez-en le coin le plus éloigné.]] }, s = [[Dans la zone au nord de l'auberge de Brasamical, parlez au fermier Brun devant sa ferme et acceptez de chercher son fils Nathan.
Allez à l'ouest de la ferme et entrez dans le repaire d'ankhegs. Les ankhegs frappent fort et crachent de l'acide à bas niveau, entrez reposé. Le corps de Nathan est dans le coin nord-est du repaire, avec un bon butin.
Rapportez le corps à Brun pour de l'expérience. Si vous lui offrez ensuite un peu d'or sans que cela ressemble à de la charité, vous gagnez de l'expérience en plus.
Si vous l'ignorez, la quête est abandonnée.]] },
[231324] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Balduran (île des loups-garous)]], h = { [[La petite Farthing, au village de l'île, a perdu sa poupée.]], [[Quelqu'un dans la moitié nord de l'île la porte sur lui.]], [[La poupée est sur le corps de Palin, qui vous entraîne dans une embuscade d'muloups au nord.]] }, s = [[Au village dans le sud de l'île, parlez à la fillette Farthing ; elle vous demande de rapporter sa poupée si vous la trouvez. Répondez gentiment, une réplique brusque peut faire échouer la quête.
Dans le nord de l'île, vous rencontrez Palin. Que vous le suiviez ou non, il appelle des muloups contre vous : préparez-vous à un combat rude, avec des armes capables de les blesser.
Prenez la poupée de Farthing sur le cadavre de Palin et rapportez-la-lui au village pour une belle récompense en expérience.]] },
[231326] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Gullykin / Pont de Flammevin]], h = { [[Gandolar au Pied Chanceux, le maire halfelin de Gullykin, connaît une entrée dérobée vers les ruines de Flammevin.]], [[Cherchez une porte cachée dans la cave d'un terrier halfelin, pas au temple.]], [[La cave de Jenkal cache une porte secrète derrière une bibliothèque ; Jenkal lui-même est le traître.]] }, s = [[Parlez à Gandolar au Pied Chanceux à Gullykin. Des kobolds attaquent le village depuis les ruines de Flammevin, et il vous apprend qu'une entrée secrète part de l'un des terriers halfelins.
Allez chez Jenkal et descendez dans sa cave. C'est lui qui laisse entrer les kobolds, attendez-vous à un combat. Fouillez derrière la bibliothèque pour trouver la porte secrète vers les ruines.
Ce passage mène près du mage ogre à l'origine des raids et évite beaucoup de commandos kobolds. Un second passage relie les ruines à la cave du temple.
Tuez le mage ogre, puis revenez voir Gandolar pour une récompense en or.]] },
[231327] = { g = [[bg1]], k = [[main]], o = 8, c = [[4]], w = [[Mines de Bois-Manteau]], h = { [[Les esclaves, les gardes et le nain Yeslick savent tous qui dirige la mine du Trône de Fer.]], [[Le maître de la mine, le mage Davaëorn, vit au quatrième niveau et détient la clé d'un bouchon magique.]], [[Tuez Davaëorn, prenez la clé dans le coffre de sa chambre et utilisez-la sur le bouchon du premier niveau.]] }, s = [[Entrez dans la mine du Trône de Fer dans le Bois-Manteau. Parlez aux esclaves mineurs et à Yeslick, un nain retenu au deuxième niveau qui peut vous rejoindre : un bouchon magique retient une rivière souterraine.
Descendez au quatrième niveau et vainquez Davaëorn, un mage qui se téléporte et appelle des renforts ; prévoyez des protections contre les sorts. Lisez ses papiers : ils comptent pour le chapitre suivant.
Prenez la clé dans le coffre de sa chambre, remontez au premier niveau et utilisez-la sur le bouchon. Courez vers la sortie pendant que l'eau envahit la mine.
L'inondation est facultative. Prévenez d'abord les esclaves pour les épargner ; les noyer est la voie maléfique.
La mort de Davaëorn termine le chapitre 4 et ouvre la Porte de Baldur.]] },
[231328] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Balduran, village]], h = { [[Delainie, une villageoise aimable, voudrait des fleurs qui poussent hors des murs du village.]], [[Cherchez hors des murs ; un coffre verrouillé dans une cabane au nord contient aussi des fleurs.]], [[Rapportez les fleurs ; votre façon de la traiter ensuite décide si elle reste votre amie.]] }, s = [[Cette version apparaît pour un personnage principal masculin. Au village de l'île, parlez à Delainie et acceptez d'aller chercher les fleurs qu'elle désire ; elles poussent hors des murs du village.
Cherchez hors des murs. Si vous ne les trouvez pas, un coffre verrouillé dans la cabane de Dradeel, au nord de l'île, contient des fleurs de belladone.
Offrez-lui les fleurs : elle vous embrasse. Lui proposer de vous suivre sur le continent la trouble ; elle refuse mais reste votre amie.
Choix maléfique : jouer avec ses sentiments et la laisser tomber une fois servi.]] },
[231329] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Balduran, village]], h = { [[Durlyle, un villageois aimable, voudrait des fleurs qui poussent hors des murs du village.]], [[Cherchez hors des murs ; un coffre verrouillé dans une cabane au nord contient aussi des fleurs.]], [[Rapportez les fleurs ; votre façon de le traiter ensuite décide s'il reste votre ami.]] }, s = [[Cette version apparaît pour un personnage principal féminin. Au village de l'île, parlez à Durlyle et acceptez d'aller chercher les fleurs qu'il désire ; elles poussent hors des murs du village.
Cherchez hors des murs. Si vous ne les trouvez pas, un coffre verrouillé dans la cabane de Dradeel, au nord de l'île, contient des fleurs de belladone.
Offrez-lui les fleurs : il vous embrasse. Lui proposer de vous suivre sur le continent le trouble ; il refuse mais reste votre ami.
Choix maléfique : jouer avec ses sentiments et le laisser tomber une fois servie.]] },
[231330] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, la Lame et les Étoiles]], h = { [[Un diseur de bonne aventure hésitant, à l'auberge de la Lame et les Étoiles, lira votre avenir contre paiement.]], [[G'axir veut une gemme sphène ; marchands de gemmes et monstres dangereux peuvent en avoir une.]], [[Le basilic tapi dans un entrepôt de la Porte de Baldur laisse une gemme sphène derrière lui.]] }, s = [[Dans le sud-est de la Porte de Baldur, entrez à l'auberge de la Lame et les Étoiles et parlez à G'axir l'augure. Il prédit un avenir sombre et demande une gemme sphène.
N'importe quelle gemme sphène convient. Une source sûre est le grand basilic d'un entrepôt de la ville, lié à la demande du nain Nadarin ; protégez-vous contre la pétrification avant ce combat.
Donnez la gemme à G'axir. Sa prophétie est brève et vague, mais l'échange vous rapporte de l'expérience.]] },
[231331] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Tour de Durlag, abords]], h = { [[Le pierre-sésame acheté à Galken pourrait ouvrir une porte quelque part dans la tour de Durlag.]], [[Gardez-le dans votre sac pendant l'exploration ; la plupart des pierres de garde achetées servent peu.]], [[Les vraies pierres de garde dont vous avez besoin se trouvent dans la tour elle-même.]] }, s = [[Cette entrée fait suite à « Les marchandises de Galken » : quand vous achetez le pierre-sésame de Galken, dans un bâtiment près de la tour de Durlag, il prévient que son ancien propriétaire pourrait le réclamer.
Il n'y a pas de vraie tâche. Gardez la pierre en explorant la tour et ses souterrains. Les pierres de garde nécessaires pour franchir les niveaux du labyrinthe et la porte de la salle du trône se trouvent dans la tour, ne comptez donc pas sur celle-ci.
Elle ne se revend pas : jetez-la à la fin si elle ne sert à rien.]] },
[231332] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Tour de Durlag, abords]], h = { [[Un individu louche nommé Galken a quelque chose à vendre près de la tour de Durlag.]], [[Visitez les bâtiments autour de la tour pour le retrouver.]], [[Sa marchandise est un pierre-sésame ; l'acheter est facultatif et rarement rentable.]] }, s = [[Dans la zone devant la tour de Durlag, Galken attend dans l'un des bâtiments et vous propose quelque chose à vendre.
Parlez-lui et payez si vous le voulez : il vend un pierre-sésame censé ouvrir une porte au fond de la tour. L'acheter ajoute l'entrée « La pierre-sésame de Galken ».
L'achat est facultatif. Les pierres de garde réellement utiles se trouvent dans la tour, et un autre vendeur voisin, Delsvirftanyon, en propose aussi.]] },
[231333] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1-2]], w = [[Bérégost]], h = { [[Un barde errant cherche de l'aide à Bérégost.]], [[Garrick travaille pour une actrice, Silke, dont la « représentation » n'est pas ce qu'elle paraît.]], [[Réglez le cas de Silke et Garrick propose de vous rejoindre.]] }, s = [[Garrick est un barde qu'on rencontre à Bérégost. Il sert l'actrice Silke, qui veut votre aide pour un spectacle qui cache en fait une embuscade.
Parlez à Garrick et à Silke. Refuser Silke et la combattre, ou régler l'affaire autrement, libère Garrick, qui propose alors de voyager avec vous.
L'entrée du journal note seulement votre rencontre ; acceptez-le dans le groupe quand vous voulez. C'est un barde neutre, avec ses chants et quelques sorts.]] },
[231334] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur]], h = { [[Cette entrée conclut l'histoire de Ghorak, l'homme maudit.]], [[Si sa malédiction est levée, il n'y a plus rien à faire.]], [[Revoyez Ghorak une fois le crâne remis au Maison de la Dame pour obtenir ce dénouement.]] }, s = [[Voici le dénouement de « Ghorak le Malade ».
Après avoir remis le crâne de Kereph à Agnasia, prêtresse de Tymora au Maison de la Dame (ouest de la Porte de Baldur), retournez voir Ghorak et annoncez-le-lui. La malédiction de Tymora est levée et les deux frères trouvent la paix.
Si vous ne l'avez pas commencée, voyez « Ghorak le Malade » : le crâne est caché derrière un tableau aux Trois Vieilles Chopes.]] },
[231335] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur]], h = { [[Ghorak souffre d'une malédiction qui le ronge, liée à la mort de son frère Kereph.]], [[Le crâne de Kereph est caché derrière un tableau à l'auberge des Trois Vieilles Chopes, dans le nord de la ville.]], [[Donnez le crâne à Agnasia au Maison de la Dame, puis retournez voir Ghorak.]] }, s = [[Parlez à Ghorak à la Porte de Baldur et proposez de le guérir. Tymora l'a maudit pour le meurtre de son frère Kereph.
Allez aux Trois Vieilles Chopes, dans le nord de la Porte de Baldur. Le crâne de Kereph est caché derrière un tableau à l'étage, près de l'escalier.
Apportez-le à Agnasia, prêtresse de Tymora au Maison de la Dame, dans l'ouest de la Porte de Baldur.
Retournez voir Ghorak : la malédiction est levée et la quête se termine sous le nom « Ghorak le Guéri! ».]] },
[231336] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Ruines de Flammevin]], h = { [[Les chevaliers fantômes des ruines de Flammevin ne peuvent reposer tant que leur camarade perdu ne les a pas rejoints.]], [[Leur frère disparu hante encore les ruines sous la forme d'un chevalier mort-vivant.]], [[Détruisez le chevalier mort-vivant et apportez son ancienne armure de plates aux fantômes.]] }, s = [[Dans les ruines de Flammevin, sous le Pont de Flammevin et Gullykin, parlez aux chevaliers fantômes. Ils disent ne pas pouvoir partir tant que tous ne seront pas réunis.
Cherchez dans les ruines leur camarade traître, un chevalier mort-vivant. Vainquez-le (armes magiques et protection contre les morts-vivants conseillées) et prenez son ancienne armure.
Apportez l'armure aux fantômes. Vous pouvez la leur remettre pour une grosse récompense en expérience et leur rendre la paix, ou l'échanger contre l'épée Vampire's Revenge, qui blesse son porteur.
Ne provoquez pas les fantômes : les combattre est long et difficile.]] },
[231337] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Bérégost et les fermes alentour]], h = { [[C'est une rumeur entendue à Bérégost, pas une vraie mission.]], [[Les « insectes géants » sont des ankhegs qui creusent sous les terres agricoles de la région.]], [[Les nids d'ankhegs près des fermes, comme celui à l'ouest de la ferme de Brun, cachent du butin et des combats rudes.]] }, s = [[Les habitants de Bérégost se plaignent d'insectes géants. Il s'agit d'ankhegs, de grosses bêtes fouisseuses qui surgissent du sol dans les terres agricoles de la Côte des Épées.
Cette rumeur n'a ni donneur de quête ni récompense. Chasser les ankhegs rapporte de l'expérience et des carapaces d'ankheg, qu'un forgeron de Bérégost peut transformer en bonne armure.
Les ankhegs crachent de l'acide et frappent fort : partez reposé, les attaques à distance aident. Leur repaire à l'ouest de la ferme de Brun, au nord de l'auberge de Brasamical, abrite aussi le fils de Brun.]] },
[231338] = { g = [[bg1]], k = [[side]], o = 0, c = [[6]], w = [[Château-Suif, bibliothèque]], h = { [[De retour à Château-Suif, Tethtoril vous rappelle que Gorion vous a laissé quelque chose.]], [[L'ancienne chambre de Gorion se trouve dans la bibliothèque, à l'un des étages.]], [[Fouillez chaque contenant de la chambre de Gorion pour trouver sa lettre et son équipement.]] }, s = [[Quand vous revenez à Château-Suif au chapitre 6, montez dans la bibliothèque et parlez à Tethtoril. Il vous dit que Gorion vous a laissé des affaires dans sa chambre.
Trouvez la chambre de Gorion dans la bibliothèque et fouillez les contenants : vous obtenez une lettre d'héritage, un anneau de protection +1 et une baguette de projectiles magiques.
Prenez-les avant que la situation ne tourne mal dans la bibliothèque : une fois l'intrigue lancée, repartir avec devient plus difficile.]] },
[231339] = { g = [[bg1]], k = [[side]], o = 0, c = [[4]], w = [[Bérégost / Bois-Manteau]], h = { [[Gurke, un nain grincheux au Jongleur Jovial de Bérégost, a perdu sa précieuse cape.]], [[Des tasloïs l'ont emportée dans la première zone de la forêt du Bois-Manteau.]], [[Les tasloïs qui la portent rôdent dans le coin sud-est de cette carte de forêt.]] }, s = [[Parlez à Gurke dans le Jongleur Jovial, à Bérégost. Une bande de tasloïs lui a volé sa cape dans le Bois-Manteau.
Rendez-vous dans la première zone de forêt du Bois-Manteau et cherchez dans le coin sud-est. Tuez les tasloïs (ils fuient quand ils perdent) et prenez la cape de non-détection.
Retournez voir Gurke pour de l'expérience. Selon le déroulement, il vous paie ou, devenu héros local, vous laisse garder la cape.]] },
[231340] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Bérégost / montagnes au sud-sud-ouest]], h = { [[Un paladin blessé, Bjornin, se repose à l'auberge du Jongleur Jovial à Bérégost.]], [[Les demi-ogres se sont retranchés quelque part au sud-sud-ouest de la ville.]], [[Ils sont quatre et se déplacent ; traquez-les tous avant de revenir.]] }, s = [[Parlez à Bjornin au Jongleur Jovial, à Bérégost. Il vous demande d'éliminer une bande de demi-ogres dans les montagnes au sud-sud-ouest de la ville.
Rendez-vous dans cette zone sauvage et cherchez-les près d'une maison abandonnée. Ils sont quatre ; ils frappent fort et se dispersent, il faudra peut-être chercher le dernier.
Retournez voir Bjornin. Il vous offre son bouclier, un bouclier moyen magique, plus de l'expérience et un peu de réputation.]] },
[231341] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Barbe d'Ulgoth, auberge]], h = { [[Un nain, Hurgan Lamepierre, veut vous engager à l'auberge de Barbe d'Ulgoth.]], [[Sa mission vous envoie tout au fond de la tour de Durlag.]], [[Il veut la dague de son grand-père, Soultaker, mais des cultistes tenteront de vous la prendre.]] }, s = [[Entrez dans l'auberge de Barbe d'Ulgoth : Hurgan Lamepierre vous aborde et propose du travail. Écoutez-le ; vous pouvez négocier la récompense.
Il veut la dague de son grand-père, Soultaker, gardée au niveau le plus profond de la tour de Durlag.
Une fois récupérée et de retour à Barbe d'Ulgoth, des cultistes s'emparent de la dague : en général vous ne la rendez jamais à Hurgan et n'êtes pas payé. Un bon voleur peut quand même lui faire les poches pour un bel objet.
La tour est très dangereuse : prévoyez de quoi détecter les pièges et de solides protections.]] },
[231342] = { g = [[bg1]], k = [[main]], o = 9, c = [[5]], w = [[Porte de Baldur, bâtiment du Trône de Fer]], h = { [[Rumeurs, ivrognes et fonctionnaires charmés désignent tous le nouveau siège du Trône de Fer, au sud-ouest de la Porte de Baldur.]], [[Le duc Eltan, du Poing Enflammé, veut que vous infiltriez cette tour.]], [[Montez jusqu'au cinquième étage, faites parler les dirigeants, puis faites votre rapport au duc Eltan.]] }, s = [[À la Porte de Baldur, rassemblez des indices : Husam, à la taverne du Chant de l'Elfe, nomme les dirigeants (Brunos, Thaldorn, Rieltar), le Maître du Port suit les arrivages de fer, et le nom de Sarevok revient sans cesse.
Terminez les missions de Scar au Poing Enflammé et rencontrez le duc Eltan à leur quartier général ; il vous demande d'infiltrer le bâtiment du Trône de Fer, au sud-ouest de la ville.
Gravissez la tour étage par étage. Dra'tan, Triadore et l'émissaire Tar révèlent les accords sur les mines et une secte des fidèles de Sarevok au cinquième étage. Attendez-vous à des combats durs dans les étages supérieurs.
Au dernier étage, battez ou menacez les dirigeants : Thaldorn révèle que Rieltar et Brunos sont partis pour Château-Suif.
Retournez voir le duc Eltan ; il vous donne de quoi entrer à Château-Suif, ce qui lance le chapitre 6.]] },
[231343] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, domaine de la Consortium des Marchands]], h = { [[Aldeth Sashenstar, que vous avez peut-être aidé au Bois-Manteau, s'inquiète de ses associés.]], [[Brandilar, le capitaine des gardes, soupçonne Zorl et Irlenarbre ; le bureau de Zorl au deuxième étage mérite une fouille.]], [[Montrez à Brandilar les lettres du bureau de Zorl, puis tuez tous les doppelgangers, y compris ceux de la fête du troisième étage.]] }, s = [[Cette quête n'est proposée que si vous avez soutenu Aldeth contre les druides au Bois-Manteau. Retrouvez-le au domaine de la Consortium des Marchands, à la Porte de Baldur ; il attend au deuxième étage.
Parlez à Brandilar, le commandant des gardes, qui se méfie de Zorl et d'Irlenarbre. Fouillez le bureau verrouillé de Zorl, au deuxième étage, pour trouver trois lettres et montrez-les à Brandilar.
Zorl se change en doppelganger : tuez-le. Irlenarbre vous invite à la fête d'anniversaire d'Aldeth au troisième étage, où d'autres doppelgangers se démasquent.
Nettoyez tout le bâtiment, puis faites votre rapport à Aldeth. Il vous offre Kondar, une épée bâtarde redoutable contre les métamorphes, et de l'expérience.]] },
[231344] = { g = [[bg1]], k = [[main]], o = 3, c = [[2]], w = [[Mines de Nashkel]], h = { [[Les gardes des mines de Nashkel vous envoient d'abord voir le contremaître, Emerson.]], [[Les mineurs parlent de « hommes-chiens » dans les niveaux inférieurs : les coupables sont des kobolds qui gâtent le minerai.]], [[Descendez au niveau le plus profond, réglez son compte à Mulahey, puis faites votre rapport à Emerson et au maire de Nashkel.]] }, s = [[À l'est de Nashkel, parlez à Emerson devant la mine ; il vous laisse entrer. Interrogez mineurs et gardes sur les créatures d'en bas.
Descendez les niveaux. Kobolds et pièges se multiplient en chemin ; au niveau 3, cherchez le corps de Joseph pour une autre quête.
Au niveau le plus bas, traversez l'eau et affrontez Mulahey, un prêtre demi-orque qui contrôle les kobolds et gâte le fer. Combattez-le (il invoque des squelettes) ou charmez-le pour le faire parler. Libérez l'elfe Xan de sa cellule si vous voulez un compagnon.
Lisez les papiers de Mulahey : ils mènent aux bandits.
Sortez de la mine, prévenez Emerson, puis réclamez votre récompense au maire de Nashkel. Le chapitre 3 commence.]] },
[231345] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1]], w = [[Auberge de Brasamical / Nashkel]], h = { [[Jaheira et Khalid, vieux amis de Gorion, vous attendent à l'auberge de Brasamical.]], [[Ils veulent enquêter sur les problèmes de fer à Nashkel, loin au sud.]], [[Partez pour Nashkel sans trop tarder, sinon ils râleront et risquent de partir.]] }, s = [[Gagnez l'auberge de Brasamical et trouvez Jaheira et Khalid ; Gorion avait arrangé la rencontre. Ils vous rejoignent ensemble et demandent à aller à Nashkel.
Descendez vers le sud par Bérégost jusqu'à Nashkel puis aux mines de Nashkel, l'objectif principal du chapitre 2. Si vous traînez trop ailleurs, ils protestent et peuvent partir.
Une fois le mystère de Nashkel entamé, leur demande est satisfaite, et ils restent avec vous tant que votre réputation leur convient.]] },
[231346] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Zone sauvage au nord de la forteresse gnoll]], h = { [[Un marchand apeuré, Jared, se cache dans les montagnes au nord de la forteresse gnoll.]], [[L'ours qui lui barre la route attend de l'autre côté du pont.]], [[Tuez l'ours et prévenez Jared ; une bonne réputation vous vaut une meilleure récompense.]] }, s = [[Dans la zone sauvage infestée d'ogres au nord de la forteresse gnoll, rencontrez Jared près d'un pont. Un ours s'est approprié l'autre rive.
Traversez le pont et tuez l'ours, un adversaire costaud qui rapporte beaucoup d'expérience.
Retournez voir Jared. Il paie selon votre réputation : les bottes du Nord si elle est haute, un peu d'or si elle est moyenne, rien si elle est basse. Un voleur peut lui dérober les bottes, ou un groupe maléfique peut simplement le tuer.]] },
[231347] = { g = [[bg1]], k = [[side]], o = 0, c = [[1]], w = [[Auberge de Brasamical]], h = { [[Joïa, une vieille femme dans l'auberge de Brasamical, a perdu un anneau précieux.]], [[Des hobgobelins l'ont volé juste au nord de l'auberge, hors des murs.]], [[Tuez les hobgobelins au nord-ouest du domaine de l'auberge et rapportez-lui l'anneau danse-flamme.]] }, s = [[Parlez à Joïa dans l'auberge de Brasamical. Des hobgobelins lui ont pris son anneau danse-flamme juste au nord de l'auberge.
Sortez de l'enceinte et fouillez le nord-ouest de la carte. Tuez les hobgobelins et prenez l'anneau sur leurs restes ; vérifiez que c'est bien le sien.
Rendez-le à Joïa. Elle n'a pas d'or à offrir, mais vous gagnez de l'expérience et de la réputation.]] },
[231348] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Balduran, nord]], h = { [[Une femme en deuil, Kryla, vous demande de venger Jondal, tué par des muloups.]], [[Son histoire tombe un peu trop bien sur cette île de métamorphes.]], [[La suivre mène droit à une embuscade d'muloups : préparez vos protections et vos armes magiques.]] }, s = [[Dans le nord de l'île, Kryla vous raconte que des muloups ont tué Jondal et vous supplie de les poursuivre.
C'est un piège. Jondal fait partie des muloups, et Kryla vous mène dans une embuscade.
Préparez-vous avant de la suivre : il faut des armes magiques ou en argent pour blesser ces créatures, et plusieurs attaquent à la fois. Vainquez la meute pour clore la quête et gagner l'expérience du combat. Vous pouvez aussi refuser et l'attaquer sur place.]] },
[231349] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel / mines de Nashkel]], h = { [[Une jeune femme, dans une maison de Nashkel, attend son mari mineur disparu.]], [[Joseph a disparu dans les mines ; il portait un anneau de néphrite.]], [[Son corps et son anneau se trouvent au troisième niveau des mines de Nashkel.]] }, s = [[À Nashkel, entrez dans la maison au sud-est de la route du pont et parlez à la femme qui s'y trouve. Son mari Joseph a disparu dans les mines ; il porte un anneau de néphrite.
Explorez les mines de Nashkel jusqu'au troisième niveau. Le cadavre de Joseph s'y trouve, avec son anneau un peu plus au nord.
Rapportez l'anneau à sa femme et annoncez-lui la nouvelle. Vous ne pouvez pas le sauver, mais vous gagnez de l'expérience.
Ramassez l'anneau dès que vous le voyez : certains joueurs le voient disparaître plus tard.]] },
[231350] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2]], w = [[Bérégost, zone au nord de Bérégost]], h = { [[Kagain, le nain marchand de Bérégost, vous rejoint pour retrouver une caravane perdue.]], [[La caravane transportait le fils d'Entar Écudargent et a été attaquée au nord de Bérégost.]], [[Menez vite Kagain jusqu'à la caravane incendiée, vers le milieu de la zone au nord de Bérégost.]] }, s = [[C'est la même histoire que « Le fils d'Entar ».
Dans sa boutique de Bérégost, Kagain demande de l'aide pour retrouver un noble disparu, le fils du grand-duc Entar Écudargent, dont la caravane a été attaquée. Acceptez et il rejoint le groupe.
Allez dans la zone sauvage juste au nord de Bérégost et rendez-vous à la caravane détruite, vers le milieu de la carte. Kagain réagit, le fils est retrouvé mort et la quête se clôt.
Faites-le tôt, car attendre trop longtemps peut tout gâcher, et ne donnez pas d'ordre à Kagain au moment où il va parler.]] },
[231351] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Balduran (île des loups-garous)]], h = { [[Les villageois craignent les hommes-loups du nord, menés par une brute nommée Karoug.]], [[Parler ne mène à rien avec Karoug ; seul un combat règlera l'affaire.]], [[Préparez armes magiques ou en argent et protections avant d'affronter Karoug et ses muloups.]] }, s = [[Sur l'île, des villageois comme Jorin parlent des muloups du nord et de leur chef, Karoug.
Partez vers le nord et trouvez Karoug. Quoi que vous disiez, il refuse de reculer, et la rencontre finit en combat.
Les muloups ne sont blessés que par des armes magiques ou en argent et attaquent en meute ; reposez-vous et protégez-vous avant l'affrontement.
Tuer Karoug débarrasse l'île d'une grande menace et vous aide auprès des habitants et pour la suite de l'histoire de l'île.]] },
[231352] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, nord-ouest]], h = { [[Des jumelles, dans une grande maison du nord-ouest de la Porte de Baldur, sont épiées la nuit.]], [[Gervisse et la druidesse Voltine s'accusent mutuellement ; écoutez les deux avant d'agir.]], [[Voltine dit la vérité : le « croque-mitaine », c'est Gervisse.]] }, s = [[Dans le nord-ouest de la Porte de Baldur, rendez visite aux jumelles Laerta et Louise dans leur grande maison. Elles parlent d'un croque-mitaine à leur fenêtre.
Le vieux Gervisse vous demande de tuer Voltine, une druidesse métamorphe. Rencontrez aussi Voltine : malgré un début houleux, elle affirme que Gervisse est un voyeur qui s'en prend aux fillettes.
Bonne voie : tuez Gervisse. Voltine vous remercie avec une baguette de métamorphose. Reparlez ensuite à Laerta pour de l'expérience et un parchemin de protection.
Si vous tuez plutôt Voltine, Gervisse vous remercie sans récompense et vous gagnez peu.]] },
[231355] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Auberge de Brasamical / Bérégost]], h = { [[Une gnome, Landrin, à l'auberge de Brasamical, a fui sa maison de Bérégost.]], [[Sa maison se trouve juste à l'ouest du Jongleur Jovial ; des araignées géantes envahissent la cave.]], [[Rapportez-lui le corps de la plus grosse araignée, les vieilles bottes de son mari et sa bouteille de vin pour trois paiements.]] }, s = [[Parlez à Landrin à l'étage de l'auberge de Brasamical. Des araignées l'ont chassée de sa maison de Bérégost, juste à l'ouest de l'auberge du Jongleur Jovial.
À Bérégost, entrez chez elle et descendez à la cave. Tuez les araignées ; leurs morsures sont empoisonnées, prévoyez des antidotes ou Ralentissement du poison. Prenez le corps de la plus grosse araignée, puis fouillez la cave pour trouver les vieilles bottes de son mari et sa bouteille de vin.
Retournez voir Landrin à l'auberge de Brasamical. Elle paie chaque objet : de l'or pour le vin, plus pour le corps d'araignée, le plus pour les bottes. Rapporter les trois termine ses tâches.]] },
[231357] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, Chant de l'Elfe / Maison des Merveilles]], h = { [[Un gnome, Brevlik, au Chant de l'Elfe, veut un « télescope » exposé à la Maison des Merveilles.]], [[La Maison des Merveilles est bondée et gardée le jour ; essayez de nuit.]], [[Volez le télescope discrètement, sans effusion de sang, et apportez-le à Brevlik au Chant de l'Elfe.]] }, s = [[Au Chant de l'Elfe, le gnome Brevlik vous engage pour voler un télescope à la Maison des Merveilles, le musée près du temple de Gond.
Allez-y de nuit, quand la salle est presque vide. Faites voler le télescope dans sa vitrine par un voleur habile. La nuit, vous pouvez aussi y croiser la voleuse halfeline Alora, qui peut vous rejoindre.
Retournez voir Brevlik au Chant de l'Elfe pour votre récompense.
Si vous l'avez obtenu d'une façon qui lui déplaît, par exemple en provoquant un combat, il refuse de payer ; vous pouvez partir ou régler l'affaire avec lui par la force.]] },
[231358] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Zone sauvage au sud de Haute-Haie]], h = { [[Kissiq, un voyageur secoué dans les terres sauvages près de Haute-Haie, jure qu'une poule lui a parlé.]], [[La « poule diabolique » se trouve quelque part à l'est de l'endroit où vous avez vu Kissiq.]], [[La poule est Mélicamp, un mage victime d'un sort ; voyez sa propre quête.]] }, s = [[Kissiq, un marchand errant dans les terres sauvages au sud de Haute-Haie, vous parle d'une poule qui parle, à l'est de chez lui.
Allez vers l'est sur la même carte. La poule est Mélicamp, un jeune magicien changé en poule ; un loup le traque, et il ne parlera pas tant que la bête vit.
Cette entrée n'est qu'une piste : continuez avec « Mélicamp, poule de son état ». Elle ne se termine pas seule, et reste ouverte si Mélicamp a déjà été guéri ou est mort.]] },
[231359] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Balduran, village]], h = { [[Une villageoise, Maralée, pleure devant la porte du village son enfant disparu.]], [[Des sortes de loups venus de l'extérieur ont emporté l'enfant.]], [[Fouillez les terres de l'île tenues par les muloups et ramenez l'enfant à Maralée.]] }, s = [[Près de la porte principale du village de l'île, Maralée vous supplie de sauver son enfant, capturé par des sortes de loups. Refuser clôt la quête.
Explorez l'île hors des murs, où rôdent les muloups. Attendez-vous à des combats qui exigent des armes magiques ou en argent. Trouvez l'enfant et ramenez-le.
Retournez voir Maralée. Folle de joie, elle vous offre son amitié et vous gagnez de l'expérience, ce qui aide auprès des villageois méfiants.]] },
[231360] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur]], h = { [[Lothandre, un assassin du Trône de Fer, affirme que son associé Marek vous a empoisonné.]], [[Pour lever le sort de quête de Lothandre, consultez le devin de la place du marché, puis Jalantha au temple d'Umberlie.]], [[Rapportez à Jalantha le livre saint de la Maison de la Dame, puis obtenez les deux moitiés de l'antidote.]] }, s = [[À la Porte de Baldur, Lothandre vous apprend que Marek vous a empoisonné : il vous reste une semaine ou deux. Il offre l'antidote si vous le libérez d'un sort de quête.
Payez le devin sous sa tente de la place du marché : seule Jalantha Mistmyr, à la Maison de la Reine des Eaux (temple d'Umberlie), peut le lever.
Jalantha veut un livre saint gardé à la Maison de la Dame, le temple de Tymora. Persuadez le prêtre ou payez-le, puis apportez-lui le livre.
Retrouvez Lothandre à l'auberge de la Lame et les Étoiles. Il vous donne la moitié de l'antidote ; Marek détient l'autre à la Sirène Rougissante.
Tuez Marek ou dupez-le pour qu'il vous la remette. Sans les deux moitiés, le poison vous tue.]] },
[231362] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Zone sauvage au sud de Haute-Haie / Haute-Haie]], h = { [[Une poule qui parle, dans les terres sauvages au sud de Haute-Haie, est en fait un magicien maudit.]], [[Tuez le loup qui le traque, puis escortez Mélicamp chez le mage Thalantyr à Haute-Haie, à l'ouest de Bérégost.]], [[Thalantyr a besoin d'un crâne : les squelettes autour de Haute-Haie en laissent tomber.]] }, s = [[Dans les terres sauvages au sud de Haute-Haie, trouvez Mélicamp, un magicien coincé sous la forme d'une poule. Tuez d'abord le loup qui le traque, puis parlez-lui.
Emmenez-le chez Thalantyr à Haute-Haie, à l'ouest de Bérégost. Thalantyr réclame un crâne pour défaire le sort.
Tuez des squelettes aux abords de Haute-Haie ; ils laissent tomber des crânes. Apportez-en un à Thalantyr et restez pour assister au rituel : si vous le laissez faire seul, pas de récompense.
Le sort a une chance sur deux de réussir. Sauvegardez avant de remettre le crâne. Si Mélicamp survit, vous gagnez beaucoup d'expérience et de la réputation (voir « La transformation de Mélicamp »).]] },
[231363] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Haute-Haie]], h = { [[Cette entrée note l'issue du sort lancé par Thalantyr sur Mélicamp.]], [[Le résultat dépend uniquement du hasard ; vos paroles n'y changent rien.]], [[Sauvegardez avant de donner le crâne à Thalantyr et rechargez si Mélicamp meurt.]] }, s = [[Une fois le crâne apporté à Thalantyr à Haute-Haie (voir « Mélicamp, poule de son état »), il lance son sort sur Mélicamp sous vos yeux.
Réussite : Mélicamp redevient humain, promet de tirer les leçons de ses erreurs, et vous gagnez expérience et réputation.
Échec : son corps ne supporte pas une nouvelle transformation et il meurt. Thalantyr dit que c'était une simple question de chance.
Le tirage est aléatoire : sauvegardez avant de remettre le crâne si vous voulez la bonne fin.]] },
[231364] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Bérégost]], h = { [[Une épouse inquiète de Bérégost attend des nouvelles de son mari, parti au sud vers l'Amn.]], [[Les nouvelles de Roe viendront de la route du sud, vers l'Amn.]], [[Apportez à Mirianne la lettre trouvée sur un messager petite-personne mort.]] }, s = [[Parlez à Mirianne chez elle, à Bérégost : son mari Roe est parti en Amn et elle s'inquiète. Promettez-lui d'ouvrir l'œil.
Sur la route du sud vers l'Amn, une bande d'ogres s'en prend à un messager petite-personne. Chassez-les ou tuez-les, puis fouillez le corps : une lettre de Roe est cousue dans son gilet (voir Une lettre pour Mirianne).
Retournez voir Mirianne et remettez-lui la lettre. Elle apporte de bonnes nouvelles, et Mirianne vous remercie avec un simple anneau protecteur.]] },
[231365] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Route de l'Amn / Bérégost]], h = { [[Des ogres sur la route de l'Amn viennent de tuer un petit voyageur.]], [[Fouillez bien le corps du messager petite-personne une fois les ogres partis.]], [[La lettre est pour Mirianne de Bérégost : portez-la-lui.]] }, s = [[Dans la nature, le long de la route du sud vers l'Amn, vous tombez sur des ogres qui attaquent un messager petite-personne. Repoussez-les ; les ogres frappent fort, gardez vos personnages fragiles en retrait.
Fouillez le petit-homme mort : une lettre de Roe, adressée à Mirianne de Bérégost, est cousue dans son gilet.
Apportez-la à Mirianne à Bérégost. Cela termine aussi L'époux de Mirianne et vous vaut son anneau.]] },
[231366] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, égouts est]], h = { [[La Balafre, du Poing Enflammé, s'inquiète de disparitions dans l'est de la ville.]], [[La réponse se trouve sous les rues, dans les égouts des quartiers est de la Porte de Baldur.]], [[Un ogre mage se terre là-dessous : tuez-le et faites votre rapport à la Balafre.]] }, s = [[La Balafre, qui attend devant les baraquements du Poing Enflammé au sud-ouest de la Porte de Baldur, vous demande d'enquêter sur les disparitions dans l'est de la ville.
Descendez dans les égouts par une grille des quartiers est et explorez-les. Au fond, vous trouvez le coupable, un ogre mage, avec ses sbires. Il lance des sorts et peut devenir invisible : révélez-le et concentrez vos attaques sur lui.
Retournez voir la Balafre devant les baraquements du Poing Enflammé pour faire votre rapport et toucher votre récompense.]] },
[231367] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-3]], w = [[Peldvale]], h = { [[Un soldat du Poing Enflammé traque quelqu'un dans les bois à l'est de la route principale.]], [[Sa cible est une prêtresse drow ; charmez-le et il vous dira pourquoi.]], [[Quand il attaque la drow, choisissez votre camp : elle vous rejoint si vous l'aidez.]] }, s = [[Dans le Peldvale, vous rencontrez la drow Viconia, bientôt suivie d'un mercenaire du Poing Enflammé qui veut sa mort.
Si vous le charmez avant le combat, il explique que son unité poursuit une elfe noire qui a massacré une famille. C'est tout ce qu'ajoute cette entrée du journal.
Vous pouvez tuer le soldat et laisser Viconia rejoindre le groupe (elle est mauvaise), ou le laisser l'affronter. Tuer un membre du Poing Enflammé peut coûter de la réputation : décidez avant que les armes ne parlent.]] },
[231368] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur]], h = { [[Une mère de la Porte de Baldur veut faire livrer un porte-bonheur à son fils fugueur.]], [[Euric traîne dans l'une des nombreuses tavernes de la ville.]], [[Donnez l'amulette à Euric, puis rapportez son message à Nadine.]] }, s = [[Nadine, de la Porte de Baldur, vous confie une amulette pour son fils Euric, qui s'est encore enfui.
Faites le tour des tavernes de la ville jusqu'à trouver Euric. Remettez-lui l'amulette ; il l'accepte sans enthousiasme et vous demande de dire à sa mère qu'elle lui manque.
Retournez voir Nadine et dites-lui qu'il va bien. Elle vous récompense avec une autre amulette.]] },
[231369] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur]], h = { [[Un voleur nommé Narlen Marchombre cherche un partenaire aux doigts agiles ; seul un voleur peut traiter avec lui.]], [[Gardez le reste du groupe hors de vue, et ne blessez jamais un garde de la ville pendant le coup.]], [[Au premier coup, donnez l'alerte en cas de problème ; au second, c'est vous qui volez.]] }, s = [[Un voleur de votre groupe rejoint Narlen Marchombre près de l'Esturgeon Sautillant ; les autres doivent rester cachés, sinon il annule.
Coup 1 : chez les De'Mallonblade, Narlen et le Rouge entrent pendant que vous faites le guet. Quand un garde arrive, donnez l'alerte et fuyez, sans combattre. Si vous ne prévenez pas, le Rouge meurt et Narlen se retourne contre vous ; tuer un garde met fin à l'association.
Retrouvez-les à la Guilde des Voleurs. Si tout s'est bien passé, Narlen prépare un second coup : rendez-vous à la Lame et les Étoiles, toujours avec seulement le voleur en vue, puis entrez vous-même chez Gantolandan pour voler sa précieuse pierre.
Revenez à la Guilde des Voleurs pour partager le butin et gagner le respect de la guilde.]] },
[231370] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur]], h = { [[Un jeune dans les rues de la Porte de Baldur paie bien juste pour un rendez-vous.]], [[Acceptez l'offre de Niklos et suivez-le jusqu'au bâtiment où il vous mène.]], [[Si l'on vous demande un mot de passe, répondez Fafhrd.]] }, s = [[À la Porte de Baldur, un jeune nommé Niklos vous aborde et vous offre 50 pièces d'or pour rencontrer son maître.
Si vous refusez, l'affaire s'arrête là. Si vous acceptez, prenez l'or et suivez-le jusqu'à un bâtiment anodin.
Quand on vous demande le mot de passe, répondez Fafhrd pour être admis auprès de son maître. Libre à vous ensuite d'accepter ou non ce qu'il vous propose.]] },
[231371] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, port]], h = { [[Une demi-elfe qui travaille au port a perdu ses gantelets neufs.]], [[Elle les a perdus quelque part entre le port et son entrepôt.]], [[Fouillez le sol et les conteneurs le long des quais, puis rapportez-les à Noralee.]] }, s = [[Noralee, une demi-elfe qui travaille dans le quartier du port de la Porte de Baldur, a perdu ses gantelets neufs entre le port et l'entrepôt où elle travaille.
Parcourez les quais entre ces deux endroits et examinez le sol et les conteneurs voisins jusqu'à trouver une paire de gantelets.
Rapportez-les à Noralee pour une petite récompense.]] },
[231372] = { g = [[bg1]], k = [[side]], o = 0, c = [[3-4]], w = [[Bérégost]], h = { [[Une fille nommée Chloé vous apporte un message du Poing Enflammé.]], [[L'officier Vaï vous attend au Jongleur Jovial, à Bérégost.]], [[Vaï paie une prime pour les scalps de bandits : gardez ceux que vous trouvez.]] }, s = [[Chloé vous apprend que l'officier Vaï du Poing Enflammé veut vous voir au Jongleur Jovial, à Bérégost.
Allez à l'auberge et parlez à Vaï. Elle offre des primes contre les bandits qui écument la région et paie chaque scalp de bandit que vous lui apportez.
Les bandits tués sur la Côte des Épées portent souvent des scalps : gardez-les et vendez-les à Vaï à chaque passage à Bérégost.]] },
[231373] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Nature de la Côte des Épées]], h = { [[Une combattante naine un peu confuse, Sarhedra, a un avertissement au sujet d'ogres.]], [[Le campement d'ogres se trouve au sud de l'endroit où vous la rencontrez.]], [[Tuez les ogres et revenez la voir, sans espérer grand-chose en échange.]] }, s = [[Parlez à Sarhedra, une combattante naine un peu confuse rencontrée dans la nature. Elle vous signale un campement d'ogres vers le sud.
Descendez au sud et exterminez les ogres. Ils frappent fort : laissez vos guerriers les retenir et utilisez armes à distance et sorts.
Retournez voir Sarhedra. Elle s'embrouille tant à chercher une autre tâche pour vous qu'elle oublie de vous payer ; l'expérience tirée des ogres est votre seule vraie récompense.]] },
[231374] = { g = [[bg1]], k = [[main]], o = 13, c = [[7]], w = [[Porte de Baldur, Caves Souterraines]], h = { [[Cythandria, la maîtresse de Sarevok, sait où il passe son temps.]], [[Elle vous oriente vers les Caves Souterraines, une maison close cachée.]], [[On atteint les Caves Souterraines par les égouts de la Porte de Baldur.]] }, s = [[En fouillant la base de Sarevok à la Porte de Baldur, vous affrontez Cythandria. Elle révèle qu'on peut trouver Sarevok aux Caves Souterraines, une maison close accessible par les égouts de la ville.
Descendez dans les égouts et trouvez le chemin des Caves Souterraines. Sarevok lui-même ne vous y attend pas, mais ses assassins Slythe et Krystin, si (voir Slythe et Krystin), et leurs papiers vous mènent ensuite vers le palais ducal.]] },
[231375] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel]], h = { [[Le collecteur de primes de Nashkel vous prend pour un chasseur nommé Loup-Gris.]], [[Prendre son argent maintenant se paie plus tard.]], [[Détrompez-le et refusez les 200 pièces d'or si vous voulez toute la prime sur Prisme.]] }, s = [[Dans son bureau de Nashkel, Oublek vous prend pour Loup-Gris, un chasseur de primes qu'il a engagé, et vous offre de l'argent.
Choix honnête : dites-lui qu'il se trompe de personne. Vous renoncez à l'or facile, mais il vous paiera plus tard la prime entière pour les émeraudes volées par Prisme (voir Prisme le sculpteur).
Choix cupide : prenez les 200 pièces d'or. L'argent est facile, mais quand vous rapportez les émeraudes, Oublek refuse de vous payer (voir Récompense refusée !), et vous y perdez.]] },
[231376] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Côte des Épées]], h = { [[Un jeune homme enthousiaste, Palin, veut de l'aide pour chasser des monstres.]], [[Laissez-le vous guider, mais restez sur vos gardes.]], [[C'est une embuscade : soyez prêt à combattre dès votre arrivée.]] }, s = [[Parlez à Palin, un jeune homme qui affirme qu'il faut chasser des monstres avant qu'ils ne fassent du mal. Acceptez de l'aider et il ouvre la marche.
Préparez le groupe avant de le suivre : sorts de protection, personnages fragiles en arrière.
Arrivés sur place, les créatures vous tendent une embuscade et se battent avec ruse. Venez-en à bout pour clore l'épisode.]] },
[231377] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel]], h = { [[Cette entrée apparaît quand Oublek refuse de vous verser une prime.]], [[Il se souvient des 200 pièces d'or qu'il vous a données par erreur.]], [[La prochaine fois, refusez l'argent destiné à Loup-Gris.]] }, s = [[C'est la mauvaise issue de Oublek, le collecteur de primes. Si vous avez accepté les 200 pièces d'or destinées à Loup-Gris, Oublek refuse de payer la prime quand vous lui rapportez les émeraudes de Prisme, à Nashkel.
Impossible de récupérer la récompense ensuite. Pour l'éviter, refusez l'argent quand Oublek vous prend pour Loup-Gris, puis réclamez la prime entière pour les émeraudes.]] },
[231378] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Bérégost / près de Haute-Haie]], h = { [[Un petit-homme nommé Perdué s'est fait voler son épée courte par des gnolls.]], [[Les gnolls rôdent dans les plaines à l'ouest de Bérégost, près de Haute-Haie.]], [[Tuez les gnolls, prenez l'épée et décidez si vous la lui rendez.]] }, s = [[Parlez à Perdué le petit-homme ; quelle que soit votre attitude, vous pouvez accepter de récupérer l'épée courte que des gnolls lui ont volée.
Rendez-vous dans les plaines à l'ouest de Bérégost, près de Haute-Haie, la demeure de Thalantyr. Trouvez la bande de gnolls et tuez-les ; ils frappent fort à bas niveau, combattez groupés.
Ramassez l'épée courte dans leur butin et rendez-la à Perdué. Ses remerciements et sa récompense sont maigres. L'épée est une bonne arme de voleur : la garder est un choix valable.]] },
[231379] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur]], h = { [[Une orpheline nommée Pétrine a perdu son chat Ange, et un certain Bheren déteste un chat près de chez lui.]], [[Ange traîne chez Bheren, avec l'anneau qui lui sert de jouet.]], [[Apportez l'anneau à Pétrine pour la fin heureuse, ou tuez le chat pour Bheren.]] }, s = [[Pétrine, une orpheline de la Porte de Baldur, a perdu son chat Ange ; il est chez son oncle Bheren, où elle refuse d'aller. Si elle récupère l'anneau qui sert de jouet à Ange, le chat reviendra vers elle.
Bheren, chez lui, est excédé par un chat qui rôde et vous offre une récompense pour le tuer.
Voie charitable : cherchez l'anneau d'Ange dans la maison de Bheren et apportez-le à Pétrine. Sa joie est votre seule récompense.
Voie cruelle : tuez Ange et prévenez Bheren, qui vous paie.]] },
[231380] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, Chant de l'Elfe]], h = { [[Un barde petit-homme nommé Bellamy a un avertissement au sujet d'un paladin.]], [[Le paladin Phandalyn attend derrière la taverne du Chant de l'Elfe, et il a entendu parler de vous.]], [[Avec une mauvaise réputation, attendez-vous à un combat ; Bellamy conseille d'y aller de nuit.]] }, s = [[Bellamy, un mystérieux barde petit-homme de la Porte de Baldur, vous met en garde contre Phandalyn, un paladin qui traîne derrière la taverne du Chant de l'Elfe, près du port, et qui connaît votre réputation.
C'est surtout un avertissement. Si votre réputation est basse, Phandalyn vous juge mauvais et vous attaque : préparez-vous à un guerrier coriace aux sorts de paladin. Avec une bonne réputation, il ne représente aucune menace.
Bellamy conseille de se rendre au Chant de l'Elfe de nuit pour l'éviter.]] },
[231381] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Château-Suif]], h = { [[L'étourdie Phlydia a encore perdu un livre quelque part à Château-Suif.]], [[Sa propre histoire de foin est le meilleur indice sur l'endroit où finissent ses livres.]], [[Trouvez L'Histoire de Halruaa dans l'enceinte et rendez-le-lui.]] }, s = [[Dans la cour de Château-Suif, Phlydia vous demande de retrouver son livre, L'Histoire de Halruaa. Elle a déjà perdu une série entière dans le foin des vaches.
Fouillez les bâtiments et l'enceinte de Château-Suif, en commençant par les endroits que son histoire évoque, jusqu'à trouver le livre.
Rapportez-le à Phlydia. Elle semble avoir à moitié oublié sa demande, mais vous récompense avec une gemme.]] },
[231383] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel et ses environs]], h = { [[À Nashkel, on parle de Prisme, un sculpteur disparu avec les émeraudes d'un investisseur.]], [[Oublek, le collecteur de primes de Nashkel, paie pour le retour des émeraudes.]], [[Trouvez Prisme qui sculpte une immense statue dans la nature ; un chasseur de primes viendra bientôt.]] }, s = [[Les rumeurs de Nashkel parlent de Prisme, un sculpteur introuvable depuis un mois. Oublek, le collecteur de primes, offre une forte récompense pour les émeraudes qu'il a volées. Refusez l'argent qu'Oublek veut vous donner par erreur (voir Oublek, le collecteur de primes).
Trouvez Prisme dans la nature, en train de sculpter une statue géante. Les émeraudes ont servi à son œuvre, et son histoire est triste.
Loup-Gris, le chasseur de primes engagé par Oublek, arrive et cela tourne à la violence. Loup-Gris est un guerrier redoutable : préparez-vous avant de parler à Prisme.
Rapportez les émeraudes à Oublek, à Nashkel, pour toucher la prime.]] },
[231384] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[À l'ouest de Nashkel, forteresse gnoll]], h = { [[Un gnoll banni nommé Lingot sait qu'une prisonnière est retenue par les siens.]], [[La femme est gardée dans la forteresse gnoll à l'ouest.]], [[C'est Dynahéir, la sorcière que cherche Minsc.]] }, s = [[Parlez à Lingot, un gnoll banni par sa tribu qui craignait qu'il ne dévore leur captive. Il vous apprend qu'une femme est retenue vivante dans la forteresse gnoll à l'ouest.
La captive est Dynahéir. Rendez-vous à la forteresse des gnolls, loin à l'ouest de Nashkel, frayez-vous un chemin parmi les gnolls et libérez-la (voir Au secours de Dynahéir).
Dynahéir peut ensuite vous rejoindre, surtout si Minsc est déjà dans le groupe.]] },
[231385] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur / au nord de chez Tenya]], h = { [[Un jeune gnome en deuil, au nord-ouest de la Porte de Baldur, a perdu son ami à cause d'ankhegs.]], [[Les ankhegs sont en amont de la ville, sur la rive, juste au nord de chez la sorcière Tenya.]], [[Trouvez la dague avec laquelle Nester a frappé l'ankheg et apportez-la à Quinn.]] }, s = [[Quinn, un jeune gnome du nord-ouest de la Porte de Baldur, vous apprend que son ami Nester a été tué par des ankhegs et vous demande de rapporter quelque chose à enterrer.
Quittez la ville et remontez le fleuve, le long de la rive, jusqu'à la zone juste au nord de chez la sorcière Tenya. Les ankhegs surgissent du sol et crachent de l'acide : combattez groupés.
Fouillez les restes pour trouver la dague de Nester, puis rapportez-la à Quinn. Il vous donne la gemme que Nester et lui comptaient vendre.]] },
[231386] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Barbe d'Ulgoth / Tour de Durlag]], h = { [[Un nain de Barbe d'Ulgoth veut récupérer un héritage de famille dans la Tour de Durlag.]], [[La dague Buveuse d'Âmes se trouve au plus profond de la tour, dans la chambre funéraire de Durlag, et d'autres la convoitent.]], [[Des inconnus prendront la dague à votre retour ; Hurgan vous enverra ensuite contre la maison de leur culte, au village.]] }, s = [[À Barbe d'Ulgoth, Hurgan Lamepierre vous demande de récupérer la Buveuse d'Âmes, une dague enchantée et héritage familial, dans la Tour de Durlag.
La Tour de Durlag est un long donjon mortel, plein de pièges et d'énigmes : venez bien préparé. La dague repose dans la chambre funéraire de Durlag, tout en bas.
De retour à Barbe d'Ulgoth, des cultistes exigent la dague : donnez-la, ou refusez et ils attaquent pour la voler.
Prévenez Hurgan. Il révèle que la dague renferme le démon qui a tué son grand-père, et que le culte veut le libérer dans sa maison du village.
Prenez d'assaut la maison du culte et venez à bout des cultistes et du démon, un combat difficile. Hurgan quitte alors le village, sa tâche accomplie.]] },
[231387] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Château-Suif]], h = { [[Reevor, à Château-Suif, a encore besoin d'aide pour son entrepôt.]], [[Des rats ont envahi l'entrepôt et les chats ne servent à rien.]], [[Éliminez tous les rats à l'intérieur, puis retournez voir Reevor.]] }, s = [[Parlez à Reevor, près de son entrepôt à Château-Suif. Les rats ont pris le contrôle et il vous enrôle une fois de plus.
Entrez dans l'entrepôt et tuez tous les rats. Ils sont faibles, mais au niveau 1 ne vous laissez pas encercler.
Retournez voir Reevor. Il vous paie la somme ridicule de 5 pièces d'or, plus un peu d'expérience, un bon début avant de quitter Château-Suif.]] },
[231388] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-3]], w = [[Nashkel / forteresse gnoll]], h = { [[Un rôdeur bruyant nommé Minsc, à Nashkel, a perdu la sorcière qu'il protège.]], [[Dynahéir est retenue par les gnolls dans leur forteresse, loin à l'ouest de Nashkel.]], [[N'attendez pas trop : Minsc s'impatiente et peut partir.]] }, s = [[À Nashkel, Minsc vous demande de secourir sa protégée, la sorcière Dynahéir, capturée par des gnolls. Acceptez et il rejoint le groupe.
Rendez-vous à l'ouest de Nashkel, à la forteresse gnoll. Des gnolls gardent les sentiers qui montent sur les falaises ; grimpez jusqu'en haut en les combattant. Dynahéir est retenue dans la partie haute de la forteresse.
Libérez-la et invitez-la à vous rejoindre, ou laissez-la repartir. Minsc se plaint si vous traînez, et part si vous l'ignorez trop longtemps.
Si Edwin est dans le groupe, attention : il veut la mort de Dynahéir, et ils ne s'entendent pas.]] },
[231389] = { g = [[bg1]], k = [[main]], o = 11, c = [[6]], w = [[Château-Suif]], h = { [[De retour à Château-Suif, parlez à vos vieux amis : plusieurs visiteurs ne sont pas ce qu'ils semblent être.]], [[Lisez les prophéties d'Alaundo, parlez à Koveras et surveillez les chefs du Trône de Fer à l'étage.]], [[On vous accusera de meurtre ; fuyez par les cryptes sous la forteresse et écoutez Diarmid à la sortie.]] }, s = [[À la porte, le garde vous laisse entrer : ne sortez aucun livre des salles, et vous ne pouvez rester que dix jours.
Parlez à Bendalis, Karan, le Chantre et aux lecteurs : ils évoquent de faux marchands, les chefs du Trône de Fer qui reçoivent des Chevaliers de l'Écu à l'étage, et un sage nommé Koveras qui étudie les prophéties d'Alaundo. Démasquez le doppelganger qui se fait passer pour Shistal.
Lisez les prophéties, puis rencontrez Koveras : il vous pousse à tuer les chefs du Trône de Fer. Charmer Rieltar ou Brunos révèle le plan du Trône de Fer.
Les chefs sont assassinés et Ulraunt vous accuse. Vous vous retrouvez dans les cryptes sous Château-Suif : traversez-les malgré doppelgangers et morts-vivants jusqu'à la sortie.
Dehors, Diarmid vous prend pour le groupe de Prat et révèle les plans de Sarevok. Retournez à la Porte de Baldur.]] },
[231391] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Auberge de Brasamical]], h = { [[Une femme nommée Léna cherche quelqu'un pour conduire Samuel à une guérisseuse.]], [[La guérisseuse est Gellana Ombremiroir, au Temple de la Sagesse, à l'auberge de Brasamical.]], [[Allez-y directement avec Samuel : si vous traînez, il meurt.]] }, s = [[Parlez à Léna et promettez de conduire Samuel au Temple de la Sagesse, à l'auberge de Brasamical.
Rendez-vous-y sans détour, ni repos, ni quête annexe : le temps compte.
Dans le temple, parlez à Gellana Ombremiroir et confiez-lui Samuel. Si vous arrivez à temps, il est sauvé ; si vous avez trop tardé, Gellana ne peut rien faire et il meurt.]] },
[231392] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, Poing Enflammé]], h = { [[La Balafre, du Poing Enflammé, est votre contact à la Porte de Baldur.]], [[Il attend au sud-ouest de la ville, juste devant le bâtiment du Poing Enflammé.]], [[Retournez le voir chaque fois que vous terminez une tâche qu'il vous a confiée.]] }, s = [[Cette entrée indique seulement où trouver la Balafre, l'officier du Poing Enflammé qui vous guide à la Porte de Baldur au chapitre 5.
Il se tient au sud-ouest de la ville, juste devant le bâtiment du Poing Enflammé. Parlez-lui là pour recevoir ses missions (comme Des citoyens disparus et l'enquête sur le Trône de Fer) et lui faire vos rapports.]] },
[231393] = { g = [[bg1]], k = [[main]], o = 10, c = [[5]], w = [[Porte de Baldur, Poing Enflammé]], h = { [[La Balafre veut vous parler du Trône de Fer.]], [[Il attend devant les baraquements du Poing Enflammé, au sud-ouest de la ville.]], [[Écoutez-le : sa mission vous envoie au quartier général même du Trône de Fer.]] }, s = [[La Balafre vous fait savoir qu'il veut vous parler du Trône de Fer. Rejoignez-le devant les baraquements du Poing Enflammé, au sud-ouest de la Porte de Baldur.
Il vous demande d'enquêter sur le quartier général du Trône de Fer en ville. Entrez dans le bâtiment et montez les étages en affrontant gardes et mercenaires pour découvrir ce que préparent ses dirigeants.
Vos découvertes font avancer l'histoire principale, vers le duc Eltan et Château-Suif.]] },
[231394] = { g = [[bg1]], k = [[side]], o = 0, c = [[7]], w = [[Porte de Baldur, Sirène Rougissante]], h = { [[Pendant votre absence, la Balafre a été assassiné ; une femme de joie nommée Sucre d'Orge en sait plus.]], [[Le seul témoin est Ivanne, dans un coin de la taverne de la Sirène Rougissante.]], [[Payez 10 pièces d'or à Ivanne et prenez le temps d'écouter tout son récit.]] }, s = [[À votre retour à la Porte de Baldur, Sucre d'Orge, une femme de joie des rues, vous apprend la mort de la Balafre et vous envoie voir Ivanne à la Sirène Rougissante.
Allez à la taverne et trouvez Ivanne dans son coin. Payez-lui 10 pièces d'or pour entendre l'histoire ; si vous partez trop tôt, revenez plus tard.
Il raconte comment un doppelganger a attiré la Balafre vers une mort rapide, sans doute pour le Trône de Fer, même si Angelo avait aussi beaucoup à y gagner. C'est un récit seulement : ni combat ni récompense.]] },
[231395] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, Esturgeon Sautillant]], h = { [[Le patron de l'Esturgeon Sautillant vous propose un marché bien arrosé.]], [[Confiez-lui 100 pièces d'or et il promet de les doubler si vous tuez les limons cachés dans sa taverne.]], [[Traquez les vases à l'intérieur de l'auberge, puis réclamez votre argent ; ne comptez pas sur la somme entière.]] }, s = [[À l'Esturgeon Sautillant, à la Porte de Baldur, Lusselyn vous fait boire et vous convainc de lui confier 100 pièces d'or. Il prétend que des limons et des vases traînent quelque part dans sa taverne et promet de doubler votre or si vous les tuez.
Fouillez les pièces et les étages de l'auberge pour trouver les limons et détruisez-les. Ils sont lents : armes à distance et sorts épargnent vos combattants.
Retournez voir Lusselyn. Il ne vous verse qu'une partie de ce qu'il avait promis.]] },
[231396] = { g = [[bg1]], k = [[main]], o = 15, c = [[7]], w = [[Porte de Baldur, Caves Souterraines]], h = { [[Deux assassins de Sarevok, Slythe et Krystin, se cachent en ville.]], [[Ils logent aux Caves Souterraines, un bordel clandestin ; le duc Eltan et Husam veulent tous deux leur mort.]], [[Tuez-les, fouillez leurs corps pour trouver les plans de Sarevok, puis filez vite au palais ducal.]] }, s = [[Le duc Eltan, ou Husam, vous apprend que Slythe et Krystin, les assassins de Sarevok, comptent peut-être tuer les Grands-Ducs Belt et Liia. Si Eltan est avec vous, il veut aussi être escorté jusqu'à la bâtisse du Maître du Port, du côté est du port.
Rendez-vous aux Caves Souterraines, un bordel clandestin, et trouvez le duo. Ils sont redoutables : Slythe est un tueur furtif et Krystin lance des sorts. Préparez-vous, révélez les invisibles et concentrez-vous sur Krystin.
Fouillez leurs corps pour trouver des papiers sur les plans de Sarevok.
Rapportez-les à Husam : Sarevok peut prendre la ville à tout moment, entrez au palais ducal au plus vite.]] },
[231397] = { g = [[bg1]], k = [[side]], o = 0, c = [[4]], w = [[Bois-Manteau]], h = { [[Un homme nommé Tiber, dans le Bois-Manteau, s'inquiète pour son frère.]], [[Chelak est parti dans la forêt exterminer les araignées et n'est jamais revenu.]], [[Son corps repose dans l'antre de Centéol, un nid d'araignées plus loin dans le Bois-Manteau.]] }, s = [[Dans le Bois-Manteau, Tiber vous demande de retrouver son frère Chelak, parti détruire les araignées qui infestent la forêt.
Enfoncez-vous dans le Bois-Manteau jusqu'à l'antre de Centéol, grouillant d'araignées géantes et de toiles. Emportez des antidotes et de quoi résister aux toiles ; Centéol elle-même est dangereuse.
Nettoyez l'antre et récupérez le corps de Chelak.
Rapportez-le à Tiber, qui vous offre l'épée Fléau d'Araignées.]] },
[231398] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Nature de la Côte des Épées]], h = { [[Une jeune femme nommée Tamah est figée en statue après avoir croisé un basilic.]], [[Il vous faut une magie qui change la pierre en chair.]], [[Rendez vie à Tamah et elle vous offre sa maison vide au bord du lac, au sud de Bérégost.]] }, s = [[Tamah a été victime du regard pétrifiant d'un basilic et n'est plus qu'une statue de pierre.
Procurez-vous un sort ou un parchemin de Pierre en chair, puis utilisez-le sur sa statue. Attention aux basilics des environs : protégez votre groupe de leur regard.
Une fois libérée, Tamah vous remercie et vous offre sa maison au bord du lac, au sud de Bérégost, vide depuis longtemps.]] },
[231399] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur / Ombre-Ville]], h = { [[Une femme mystérieuse nommée Tamoko vous met en garde contre le guérisseur du duc Eltan.]], [[Plus tard, elle vous retrouve près du quartier général du Poing Enflammé et vous demande d'épargner Sarevok.]], [[À Ombre-Ville, elle vous barre la route ; refuser de la combattre peut éviter le sang.]] }, s = [[Tamoko vous aborde à la Porte de Baldur : il ne faut pas se fier au guérisseur du duc Eltan, qui serait la cause de sa maladie. Elle dit qu'elle attendra près du quartier général du Poing Enflammé.
Retrouvez-la plus tard. Elle vous demande d'épargner la vie de Sarevok. Promettez-le et elle vous apprend beaucoup : Slythe et Krystin ont tué le duc Entar Écudargent et se cachent aux Caves Souterraines, Cythandria travaille avec le Trône de Fer, et Sarevok et vous êtes tous deux enfants de Bhaal. Refusez et elle en dit peu.
À Ombre-Ville, vers la fin, Tamoko vous barre la route pour regagner la faveur de Sarevok. Refusez de la combattre et elle renonce à lui et s'en va. Sinon, vous devez la tuer.]] },
[231402] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, Caves Souterraines]], h = { [[L'elfe Vail sait ce qu'est devenue la cape de Baldurien.]], [[Il l'a donnée à sa maîtresse Quenash, qu'on trouve aux Caves Souterraines.]], [[Trouvez Quenash aux Caves Souterraines et demandez-lui la cape.]] }, s = [[Parlez à l'elfe Vail, à la Porte de Baldur. Il vous apprend qu'il a donné la cape de Baldurien à sa maîtresse, Quenash, qui se trouve aux Caves Souterraines.
Rendez-vous aux Caves Souterraines, le bordel souterrain accessible par les égouts de la ville, et trouvez Quenash.
Parlez-lui : elle vous remet la cape de Baldurien sans difficulté. Elle donne aussi un indice sur le heaume (voir Le Heaume de Baldurien).]] },
[231403] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-5]], w = [[Pont de Flammevin / Gullykin]], h = { [[Un chasseur sur la route recommande les ruines du pont de Flammevin aux aventuriers.]], [[Les kobolds y sont étrangement organisés ; les petites-personnes de Gullykin subissent leurs raids.]], [[Un ogre mage, dans les ruines sous le pont, les commande : tuez-le et prévenez Gandolar à Gullykin.]] }, s = [[Un chasseur vous conseille d'explorer le pont de Flammevin, dernier vestige d'une ville commerçante elfique détruite il y a deux siècles. Les petites-personnes de Gullykin, tout près, sont harcelées par les kobolds des ruines.
Entrez dans les ruines sous le pont de Flammevin. Les kobolds y combattent en groupes organisés, certains avec des flèches enflammées : restez groupés et tuez d'abord les archers.
Au fond, venez à bout de l'ogre mage qui envoie les kobolds. Il utilise sorts et invisibilité.
Retournez voir Gandolar à Gullykin, qui vous remercie d'avoir délivré son village.]] },
[231404] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-6]], w = [[Château-Suif]], h = { [[Shaella, une prêtresse de Leira, vous envoie en pèlerinage vers votre ancien foyer.]], [[Le Grand Livre de l'Ignorance se trouverait à Château-Suif.]], [[Une fois revenu de Château-Suif, reparlez à Shaella ; ne comptez pas vous souvenir du livre.]] }, s = [[Parlez à Shaella, une prêtresse de Leira, déesse de la tromperie. Elle évoque le Grand Livre de l'Ignorance de Château-Suif, qui prive de savoir quiconque le touche, et vous demande de le chercher.
Vous ne pouvez retourner à Château-Suif que lorsque l'histoire principale vous y mène. Après cette visite, reparlez à Shaella.
Elle vous assure que vous avez bien trouvé le livre, mais bien sûr vous n'en avez aucun souvenir. C'est une plaisanterie digne de Leira : il n'y a rien à trouver et pas de vraie récompense.]] },
[231405] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur]], h = { [[Le magicien Degrodel, au nord-ouest de la ville, veut le Heaume de Baldurien.]], [[Sa piste : des aventuriers pétrifiés détenus par un marchand d'art, dans une propriété juste à l'ouest du champ de foire.]], [[Le parchemin de Vail et l'énigme de Quenash désignent un bâtiment dont le nom évoque un heaume et une cape.]] }, s = [[Degrodel, un magicien qui vit au nord-ouest de la Porte de Baldur, vous demande le Heaume de Baldurien. Selon lui, il se trouve sur les corps pétrifiés d'aventuriers détenus par un marchand d'art, dans une propriété juste à l'ouest du champ de foire.
L'elfe Vail vous donne un parchemin censé révéler l'emplacement du heaume, et Quenash, aux Caves Souterraines, ajoute que la cachette de Vail porte un nom tout trouvé.
Suivez l'une ou l'autre piste, récupérez le heaume et préparez-vous à combattre si vous rendez vie aux aventuriers pétrifiés.
Apportez le heaume chez Degrodel. Il vous récompense généreusement, puis vous prie de partir.]] },
[231406] = { g = [[bg1]], k = [[main]], o = 4, c = [[2]], w = [[Mines de Nashkel]], h = { [[Un prisonnier au fond des mines de Nashkel détient des informations utiles.]], [[Libérez l'elfe Xan de ses geôliers.]], [[Charmez Xan pour en apprendre plus sur le Trône de Fer.]] }, s = [[Au niveau le plus profond des mines de Nashkel, près du repaire de Mulahey, vous trouvez l'elfe Xan prisonnier. Battez ses geôliers et libérez-le ; il peut rejoindre le groupe.
Si vous charmez Xan avec un sort, il révèle qu'une organisation marchande, le Trône de Fer, sème le trouble sur la Côte des Épées, sans savoir dans quel but.
C'est la première mention du Trône de Fer, le fil que suivra l'histoire principale.]] },
[231407] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Ruines d'Ulcaster]], h = { [[Les habitants de Bérégost parlent d'une antique école de magie pleine de trésors.]], [[L'école en ruine d'Ulcaster se trouve dans la nature, non loin de Bérégost.]], [[Explorez les ruines et le souterrain qui les accompagne, et méfiez-vous des morts-vivants et des gardiens magiques.]] }, s = [[Un habitant de Bérégost évoque la rumeur d'une antique école de magie remplie de trésors.
La rumeur désigne les ruines de l'école d'Ulcaster, dans la nature, non loin de Bérégost.
La rumeur n'est qu'une piste : allez-y pour explorer les ruines et le souterrain. Attendez-vous à des morts-vivants et à des ennemis magiques ; emmenez un prêtre pour les repousser et quelques armes magiques.]] },
[231408] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Porte de Baldur, bâtiment des Sept Soleils]], h = { [[La Balafre, commandant en second du Poing Enflammé, veut qu'on enquête sur le consortium des Sept Soleils.]], [[Le personnel du bâtiment des Sept Soleils n'est pas ce qu'il paraît, et le vrai chef a disparu.]], [[Trouvez Jhasso retenu dans le bâtiment, tuez tous les doppelgangers, puis faites votre rapport à la Balafre pour une prime doublée.]] }, s = [[Au chapitre 5, la Balafre, du Poing Enflammé, vous engage pour enquêter sur le siège des Sept Soleils, au sud-ouest de la ville. Louvet, l'ancien marchand croisé dans les rues, trouve lui aussi leur attitude étrange.
Entrez dans le bâtiment des Sept Soleils : un marchand terrorisé vous parle de métamorphes, et le personnel se change en doppelgangers. Attendez-vous à plusieurs combats.
Trouvez Jhasso, le vrai chef du consortium, qui confirme la prise de pouvoir.
Faites votre rapport à la Balafre, au siège du Poing Enflammé juste à l'ouest du bâtiment. Il propose de doubler la récompense si vous retournez tuer tous les doppelgangers. Éliminez-les tous et revenez pour la prime, ou refusez et gardez le paiement de base.]] },
[231409] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Bérégost / école d'Ulcaster]], h = { [[Certains habitants de Bérégost connaissent un secret, mais ne le confient qu'à quelqu'un en qui ils ont toute confiance.]], [[Un sort de charme fait parler certains roturiers d'une école de magie en ruine.]], [[L'école abandonnée est celle d'Ulcaster, à l'est sur la carte du monde ; explorez ses ruines et son souterrain pour le trésor.]] }, s = [[Ce n'est qu'une rumeur. À Bérégost, charmez des roturiers comme Galteran ou Berden (Charme-personne ou un objet de charme) : ils vous parlent d'une école de magiciens abandonnée à l'est, pleine de trésors.
Il s'agit de l'École d'Ulcaster, une zone de la carte du monde accessible même sans la rumeur. Rendez-vous-y et explorez les ruines et le souterrain qui se trouve dessous. Attendez-vous à des morts-vivants et d'autres monstres.
Le fantôme d'Ulcaster lui-même y erre, ce qui lance les quêtes liées à ses livres perdus.]] },
[231410] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, nord]], h = { [[Deux mages de la Porte de Baldur se disputent une nymphe nommée Abela.]], [[Ramazith vous paie pour la ramener de chez Ragevite, mais Ragevite raconte une autre histoire.]], [[Libérez Abela pour une issue bienveillante, ou livrez-la à Ramazith pour sa récompense, au prix de votre conscience.]] }, s = [[La quête commence soit avec le mage Ramazith, dans sa tour au nord de la ville, qui vous demande de lui ramener une nymphe captive, soit avec dame Hannah, qui accuse Ragevite d'en retenir une.
Allez chez Ragevite, dans le quartier nord-ouest, au nord-est de la Maison des Merveilles. Écoutez-le : il pense que Ramazith veut Abela pour de mauvaises raisons, et vous apprenez que Ramazith compte tirer d'elle des composantes de sorts.
Voie bienveillante : libérez Abela ; elle s'en va, enfin libre.
Voie maléfique : amenez-la à Ramazith et touchez sa récompense.]] },
[231411] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-5]], w = [[Rives du Chionthar / pont menant à la Porte de Baldur]], h = { [[Des pêcheurs au bord du Chionthar, au nord de l'auberge de Brasamical, veulent se débarrasser d'une prêtresse d'Umberlie.]], [[La prêtresse, qui vit près du pont menant à la Porte de Baldur, n'est qu'une enfant avec sa propre version.]], [[Prendre le parti de Tenya implique d'affronter les pêcheurs de Talos et de reprendre un bol ; refuser les deux est aussi possible.]] }, s = [[Des pêcheurs au bord du fleuve, au nord de l'auberge de Brasamical, vous demandent de tuer une prêtresse d'Umberlie qui vit juste à l'est du pont menant à la Porte de Baldur. Ils augmentent leur offre étrangement vite.
Trouvez la prêtresse Tenya : c'est une fillette d'une douzaine d'années qui affirme que les pêcheurs ont tué sa mère. Vous apprenez que les pêcheurs servent Talos.
Voie de Tenya : affrontez les pêcheurs, vainquez-les et rapportez à Tenya le bol qu'elle cherche. Elle promet une récompense future ; vous la retrouverez plus tard au temple d'Umberlie de la Porte de Baldur (voir « Le fils de Tremain »).
Voie des pêcheurs : tuez Tenya et touchez leur paiement.
Vous pouvez aussi refuser les deux camps.]] },
[231412] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Tour de Durlag, souterrains]], h = { [[Quatre esprits portant le nom des défauts d'un guerrier gardent l'ascenseur de la tour de Durlag ; chacun récite une énigme.]], [[Prenez chaque énigme au pied de la lettre : une chose qui brille, un grand bruit, une boisson rouge et des chroniques écrites.]], [[Fouillez les salles de ce niveau pour trouver les objets correspondants ; le gardien de l'Amour détient la pierre-sésame de l'ascenseur.]] }, s = [[Dans les souterrains de la tour de Durlag, quatre gardiens (l'Avarice, la Peur, l'Amour et la Fierté) bloquent l'ascenseur vers les niveaux inférieurs. Chacun apparaît sous forme d'apparition et récite une énigme que le journal note.
L'Avarice a faim de ce qui brille le plus : offrez-lui quelque chose de précieux.
La Peur dort : réveillez-la avec un grand bruit, par exemple un gong ou quelque chose de semblable trouvé à proximité.
L'Amour a soif d'une boisson douce et cramoisie : trouvez ou préparez du vin à ce niveau.
La Fierté veut que ses exploits soient honorés : trouvez et lisez les chroniques de ses faits d'armes cachées à ce niveau.
Une fois les quatre satisfaits, l'Amour remet la pierre-sésame et l'ascenseur vous fait descendre.]] },
[231413] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Bear River]], h = { [[Une paladine nommée Laurel mène une guerre sans fin contre les grouilleux dans les terres sauvages.]], [[Elle conseille de préparer le plus de magie du feu possible avant de la rejoindre.]], [[Aidez-la à repousser les vagues de grouilleux, puis reposez-vous et revenez pour une autre chasse.]] }, s = [[Rencontrez la paladine Laurel dans la zone de Bear River. Elle vous invite à participer aux batailles incessantes de la région contre les hordes grouilleuses.
Acceptez et suivez son conseil : mémorisez des sorts de feu et prenez des flèches de feu ou d'autres sources de dégâts de feu, car ces créatures craignent les flammes. Les grouilleux sont faibles seuls mais arrivent en grand nombre : protégez vos lanceurs de sorts.
Repoussez les hordes avec elle. Ensuite, Laurel en fait un sport et vous propose de vous reposer, de vous réarmer et de revenir la voir pour une nouvelle chasse.]] },
[231414] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Île de Baldurien (île des loups-garous)]], h = { [[Sur l'île, tout le monde vous conseille de parler d'abord à la meneuse du village, Kaïshas Gan.]], [[Kaïshas veut que vous détruisiez les bêtes menées par Karoug, qui vivent dans l'épave du navire de Baldurien.]], [[Les villageois sont eux-mêmes des loups-garous ; une fois Karoug mort, fuyez par une porte secrète dans la hutte du chef.]] }, s = [[Une fois débarqué sur l'île de Baldurien par le bateau de Mendas, allez au village. Parlez aux villageois (Lahl, Jorin, Evalt, Farthing, Taloun, l'ancien marin amnien) pour le contexte, puis à la meneuse Kaïshas Gan.
Acceptez sa mission : tuer Karoug et les muloups qui vivent dans l'épave du navire de Baldurien. Attendez-vous à des combats durs ; les armes d'argent ou magiques aident. Le navire de Baldurien contient un beau butin.
Retournez au village. Les villageois révèlent qu'ils sont des loups-garous, vous transmettent la lycanthropie et attaquent. Tuez Kaïshas, qui vous met en garde contre Sélaad, et prenez les cartes maritimes.
Fuite : une porte secrète au nord de la hutte du chef mène sous terre jusqu'au navire des loups-garous. Maralée, ou Delainie / Durlyle si vous avez gagné leur affection, peut vous la montrer.
Rentrez par la mer et réglez le cas de Mendas.]] },
[231415] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Barbe d'Ulgoth / Porte de Baldur]], h = { [[Un savant distant nommé Mendas vient de s'installer à Barbe d'Ulgoth, et il a une course à confier.]], [[Il veut les cartes maritimes du Consortium des Marchands de la Porte de Baldur, puis le journal de bord du dernier voyage de Baldurien.]], [[Mendas n'est pas celui qu'il prétend ; préparez-vous à le combattre à votre retour de l'île.]] }, s = [[À Barbe d'Ulgoth, les habitants parlent de Mendas, un nouveau venu qui dit venir d'Eauprofonde. Calahan remarque qu'il n'a pas l'accent aquafondais et qu'il s'absente souvent.
Parlez à Mendas chez lui. Il vous demande de vous procurer les cartes maritimes du Bureau des Comptes du Consortium des Marchands, au nord-est de la Porte de Baldur (voir « Les cartes maritimes »).
Rapportez-lui les cartes. Il les recopie, loue un bateau et vous demande de rapporter le journal de bord de Baldurien. Retrouvez-le aux quais de Barbe d'Ulgoth pour embarquer.
Survivez à l'île mystérieuse et revenez. Mendas se révèle être Sélaad, le chef des loups-garous, qui voulait les cartes pour sa meute. Attendez-vous à le combattre à votre retour.]] },
[231416] = { g = [[bg1]], k = [[main]], o = 16, c = [[7]], w = [[Porte de Baldur]], h = { [[Sarevok fait campagne pour devenir Grand-Duc, et il vous faut des preuves solides avant de l'accuser.]], [[Cherchez des preuves dans le bâtiment du Trône de Fer et au siège du Poing Enflammé, où commande Angelo.]], [[Apportez les preuves aux Ducs restants au palais ducal avant le couronnement de Sarevok.]] }, s = [[Au chapitre 7, vous revenez à la Porte de Baldur, toujours recherché pour les meurtres du Trône de Fer. Entar Écudargent et la Balafre sont morts, le Duc Eltan agonise et Angelo Dosan dirige le Poing Enflammé pour Sarevok, favori de l'élection ducale.
Écoutez les rumeurs et vos alliés (Grégor, Delthyr le Ménestrel, l'émissaire Kalessia) pour le contexte.
Fouillez le bâtiment du Trône de Fer, comme le suggère Delthyr, pour trouver les écrits de Sarevok, et les baraquements du Poing Enflammé pour la preuve de ses accords avec Angelo.
Apportez les preuves au palais ducal pendant la fête du couronnement et présentez-les aux Ducs Belt et Liia. Attendez-vous à des assassins. Sarevok s'enfuit sous la ville, où la confrontation finale a lieu dans le temple de Bhaal.]] },
[231417] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, Consortium des Marchands / Sirène Rougissante]], h = { [[Les cartes maritimes voulues par Mendas sont au Bureau des Comptes du Consortium des Marchands, surveillées par le capitaine Tollar Kieres.]], [[Kieres est un ivrogne qui réclame une bière spéciale que De'Tranion lui garde à la Sirène Rougissante.]], [[Réglez son ardoise de 900 pièces d'or pour la bière Baalor, baratinez-le, ou passez par la ruse ou la force jusqu'aux cartes.]] }, s = [[Allez au Bureau des Comptes du Consortium des Marchands, au nord-est de la Porte de Baldur. Le capitaine Tollar Kieres vous empêche de chercher les cartes maritimes.
Voie pacifique : il veut de la bière Baalor. Trouvez De'Tranion à la taverne de la Sirène Rougissante ; il ne la cède que si vous réglez l'ardoise de Kieres, 900 pièces d'or. Apportez la bière à Kieres et il vous laisse fouiller.
Vous pouvez aussi le persuader en discutant, car il est rarement sobre.
Autres voies : passer discrètement ou le tuer, mais un combat en ville peut vous attirer des ennuis.
Prenez les cartes maritimes et rapportez-les à Mendas à Barbe d'Ulgoth.]] },
[231418] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel / Ancient Ruins]], h = { [[Brage, le capitaine de la garde de Nashkel, s'est livré à des meurtres sanglants puis a disparu.]], [[Volo et les habitants remarquent que Brage a changé juste après avoir acquis une nouvelle épée.]], [[Réglez le cas de Brage dans la nature, puis choisissez entre la garnison et le Temple de Heaum de Nashkel.]] }, s = [[À Nashkel, la garnison offre une forte récompense pour Brage, le capitaine de la garde qui a tué plusieurs personnes. Les rumeurs (Volo, les habitants) accusent une nouvelle épée maudite. Nalin, au Temple de Heaum, pense qu'une force maléfique est à l'œuvre.
Trouvez Brage dans la nature hors de Nashkel, dans la zone des Ancient Ruins. C'est un combattant dangereux. Selon le déroulement de la rencontre, vous le tuez ou le capturez vivant.
Retournez à Nashkel. À la garnison, vous touchez la prime, mais un Brage vivant sera exécuté. Au Temple de Heaum, Nalin le prend en charge pour qu'il expie ses crimes, l'issue la plus clémente.
Méfiez-vous de son épée : elle est maudite.]] },
[231419] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Barbe d'Ulgoth / Tour de Durlag]], h = { [[Une mère inquiète de Barbe d'Ulgoth veut des nouvelles de son fils, parti à l'aventure.]], [[Dalton a rejoint le groupe de Bayard et est entré dans la tour de Durlag.]], [[Retrouvez Dalton vivant dans la tour et ramenez-le à Thérella pour une récompense.]] }, s = [[À Barbe d'Ulgoth, Thérella vous demande de chercher son fils Dalton, parti pour la tour de Durlag.
Rendez-vous à la tour de Durlag et explorez-la. Vous y rencontrez l'aventurier Bayard, dont Dalton faisait partie du groupe. Les compagnons de Bayard n'ont pas eu de chance.
Trouvez Dalton plus loin dans la tour et sauvez-le ; il survit à ses compagnons.
Retournez voir Thérella à Barbe d'Ulgoth. Si Dalton est vivant, elle est ravie et vous récompense. S'il est mort, elle a le cœur brisé et il n'y a pas de récompense.]] },
[231420] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[École d'Ulcaster]], h = { [[Le fantôme du magicien Ulcaster hante les ruines de son ancienne académie.]], [[Ses précieux livres sont ensevelis sous les décombres de l'académie et de son souterrain.]], [[Fouillez soigneusement les ruines pour trouver ses livres et montrez-les au fantôme.]] }, s = [[Rendez-vous dans la zone de l'école d'Ulcaster et trouvez le fantôme d'Ulcaster près des ruines. Il espère que quelqu'un déterrera les livres ensevelis sous les décombres.
Explorez les ruines et le souterrain en dessous. Utilisez le bouton d'indice ou fouillez conteneurs et tas de gravats ; attendez-vous à des morts-vivants et d'autres monstres.
Quand vous trouvez l'un de ses livres perdus, apportez-le au fantôme. Cela l'aide à retrouver un peu de lucidité (voir « Le fantôme d'Ulcaster »).]] },
[231421] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur, Maison d'Umberlie]], h = { [[Tremain Belde'ar, qui vit au nord de la Maison des Merveilles, a perdu son fils dans les flots.]], [[Le corps du garçon a été emporté à la Maison d'Umberlie, près des docks, et le temps presse.]], [[Récupérez vite le corps au temple ; la prêtresse enfant Tenya y règne, donc votre passé avec elle compte.]] }, s = [[Tremain Belde'ar, dans une maison juste au nord de la Maison des Merveilles, vous supplie de récupérer le corps de son fils Casson à la Maison d'Umberlie, près des docks.
Allez-y sans tarder : si vous traînez, le garçon ne pourra pas être sauvé.
À l'intérieur, la prêtresse enfant Tenya dirige le temple. Si vous l'avez aidée contre les pêcheurs, elle vous rend le corps et peut vous offrir l'hospitalité. Si vous l'avez trahie, elle peut se retourner contre vous et il faut combattre.
Ramenez Casson à Tremain à temps : le garçon est ramené à la vie et se fait gronder, et Tremain vous remercie.]] },
[231423] = { g = [[bg1]], k = [[side]], o = 0, c = [[Tutorial]], w = [[Zone du tutoriel]], h = { [[Belt veut que vous rapportiez un saphir étoilé du sous-sol.]], [[La recherche fait appel à plusieurs compétences : repérez coffres et objets avec le bouton d'indice.]], [[Prenez le saphir étoilé, remontez à l'étage et parlez à Belt pour terminer l'initiation.]] }, s = [[C'est le tutoriel du jeu, lancé depuis le menu principal.
Parlez à Belt, puis descendez au sous-sol. Progressez en utilisant les compétences présentées par le tutoriel : se déplacer, combattre, ouvrir les conteneurs, gérer serrures et pièges. Appuyez sur le bouton d'indice pour mettre en évidence les coffres et autres objets utilisables.
Trouvez le saphir étoilé, remontez et parlez à Belt pour terminer.
Si vous êtes bloqué après être entré dans le sous-sol, chargez la sauvegarde automatique pour recommencer.]] },
[231424] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[École d'Ulcaster]], h = { [[Le fantôme d'Ulcaster divague près des ruines de son académie.]], [[Il s'apaise quand on lui montre un objet qui lui appartenait de son vivant.]], [[Donnez-lui l'un de ses livres perdus trouvés dans les ruines.]] }, s = [[Dans la zone de l'école d'Ulcaster, parlez au fantôme d'Ulcaster ; au début, son esprit est très confus.
Explorez les ruines et le souterrain pour trouver l'un de ses livres perdus (voir « Les livres magiques »).
Présentez le livre au fantôme. Il retrouve un peu de lucidité et peut parler plus clairement de son académie et de son sort.]] },
[231425] = { g = [[bg1]], k = [[side]], o = 0, c = [[3-4]], w = [[Bérégost, Jongleur Jovial]], h = { [[Une officière du Poing Enflammé coincée à Bérégost paie pour toute preuve de bandits tués.]], [[Les bandits que vous tuez sur les routes et dans leurs camps portent souvent des scalps.]], [[Apportez les scalps de bandits à l'officier Jessa Vaï au Jongleur Jovial, contre de l'or pour chacun.]] }, s = [[À l'auberge du Jongleur Jovial, à Bérégost, l'officier Jessa Vaï du Poing Enflammé est bloquée avec ses hommes. Elle offre 50 pièces d'or par scalp de bandit.
Tuez les bandits où que vous les rencontriez (embuscades, camp des bandits, forêts) et récupérez leurs scalps.
Retournez voir Vaï au Jongleur Jovial et remettez-les-lui, 50 pièces d'or chacun. Une fois les bandits réglés, elle promet de parler en bien de vous à ses supérieurs du Poing Enflammé.]] },
[231426] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Nashkel]], h = { [[Un marchand de Nashkel tient à acheter un type de fourrure bien précis.]], [[Les loups des glaces sont rares sur la Côte des Épées ; gardez leurs peaux quand vous en tuez un.]], [[Vendez les peaux de loups des glaces à ce marchand de Nashkel pour un bon prix.]] }, s = [[Un marchand de Nashkel vous dit qu'il recherche des peaux de loups des glaces.
Il n'y a pas de cible précise : chaque fois que vous tuez un loup des glaces, récupérez sa peau. Ils sont plus coriaces que les loups ordinaires et ont un souffle glacé, la résistance au froid aide donc.
Rapportez les peaux au marchand de Nashkel et vendez-les ; il les paie bien.]] },
[231427] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2]], w = [[Mines de Nashkel]], h = { [[Quelqu'un est retenu prisonnier au fond des mines de Nashkel.]], [[L'elfe Xan enquêtait comme vous sur les problèmes de la région, et il a été capturé.]], [[Libérez Xan au niveau le plus profond des mines, puis acceptez ou refusez sa proposition de vous rejoindre.]] }, s = [[Descendez dans les mines de Nashkel jusqu'au niveau le plus profond, où le chef des kobolds garde ses prisonniers.
Trouvez et libérez l'elfe Xan, un enchanteur mélancolique qui enquêtait lui aussi sur la crise du fer.
Une fois libre, il propose de vous rejoindre. Acceptez pour le recruter, ou refusez et il s'en va. Le journal note votre choix.]] },
[231429] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1-2]], w = [[Route au sud de l'auberge de Brasamical / Nashkel]], h = { [[Un duo étrange, un mage et un petit-homme, vous aborde sur la route au début de votre voyage.]], [[Xzar et Montaron veulent enquêter sur les problèmes de Nashkel.]], [[Emmenez-les avec vous à Nashkel et dans ses mines.]] }, s = [[Au début du chapitre 1, le nécromancien Xzar et le petit-homme Montaron vous rencontrent sur la route au sud de l'auberge de Brasamical. Ils proposent de vous rejoindre.
S'ils vous rejoignent, ils vous demandent d'aller à Nashkel, où les mines posent problème. Cela rejoint la quête principale : dirigez-vous simplement vers le sud, à Nashkel et ses mines.
Ne traînez pas trop : ils n'aiment pas les longs détours et s'entendent mal avec les compagnons bons. Tous deux sont mauvais, ce qui compte si votre groupe est bon.]] },
[231430] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Bérégost, Burning Wizard]], h = { [[Un voleur de la taverne du Burning Wizard, à Bérégost, vous fait les poches chaque fois que vous lui parlez.]], [[Zhurlong s'est fait voler des bottes par des hobgobelins dans les amas rocheux au sud de Bérégost.]], [[Tuez ces hobgobelins, prenez les bottes et rendez-les à Zhurlong pour récupérer votre or.]] }, s = [[À la taverne du Burning Wizard, à Bérégost, Zhurlong vous fait les poches chaque fois que vous lui parlez. Il parle de bottes volées par des hobgobelins dans les amas rocheux au sud de la ville.
Allez au sud de Bérégost, trouvez les hobgobelins, tuez-les et récupérez les bottes.
Rapportez les bottes à Zhurlong. Il vous rend tout l'or volé et ajoute 100 pièces d'or, qu'il appelle en plaisantant une avance sur votre bourse.]] },
[231431] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Upper Chionthar (bord du fleuve)]], h = { [[Des colons au bord du fleuve sont terrorisés par des morts-vivants.]], [[Le vieux fermier Wenric a compté vingt zombies qui errent sur la rive.]], [[Détruisez jusqu'au dernier des vingt zombies, puis retournez voir Wenric pour 150 pièces d'or.]] }, s = [[Dans la zone d'Upper Chionthar, au bord du fleuve, le vieux fermier Wenric vous demande de détruire une invasion de zombies : il en a compté vingt. Il offre 150 pièces d'or.
Ratissez la zone et tuez tous les zombies. Ils sont lents mais peuvent épuiser un groupe faible ; les prêtres capables de repousser les morts-vivants et les armes contondantes aident.
Retournez voir Wenric quand les vingt ont disparu pour toucher les 150 pièces d'or.]] },
[231604] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Château-Suif, caserne]], h = { [[Hull, l'une des sentinelles de Château-Suif, a oublié quelque chose ce matin.]], [[Son épée est restée à la caserne.]], [[Prenez-la dans le coffre contre le mur de droite de la caserne et rapportez-la à Hull.]] }, s = [[À Château-Suif, parlez à Hull, une sentinelle de garde. Il a oublié son épée à la caserne.
Allez à la caserne et ouvrez le coffre contre le mur de droite pour prendre l'épée.
Rapportez-la à Hull. Il vous donne 10 ou 20 pièces d'or selon son humeur, avec quelques remarques bougonnes.]] },
[231605] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Château-Suif, caserne et auberge]], h = { [[Fuller, qui se remet de sa cuite à la caserne de Château-Suif, a besoin qu'on lui fasse une course.]], [[Il veut des carreaux d'arbalète de chez Winthrop, l'aubergiste.]], [[Prenez les carreaux chez Winthrop à l'auberge et rapportez-les à Fuller.]] }, s = [[À la caserne de Château-Suif, parlez à Fuller, qui se remet d'une nuit à l'hydromel. Après un peu d'insistance, il vous demande d'aller chercher des carreaux d'arbalète chez Winthrop.
Allez à l'auberge, parlez à Winthrop et récupérez les carreaux.
Retournez voir Fuller. Selon son humeur, il vous donne la vieille dague de son père ou 10 pièces d'or.]] },
[231606] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Château-Suif, auberge et jardins intérieurs]], h = { [[Le vieux Perleflamme Cheveux-d'Elfe, de passage depuis Bérégost, attend un objet à l'auberge de Château-Suif.]], [[Il a confié un parchemin d'identification à Téthtoril, dans les jardins intérieurs.]], [[Récupérez le parchemin auprès de Téthtoril et rapportez-le à Perleflamme à l'auberge.]] }, s = [[À l'auberge de Château-Suif, parlez à Perleflamme Cheveux-d'Elfe. Il a besoin du parchemin d'identification qu'il a laissé à Téthtoril.
Allez dans les jardins intérieurs près de la bibliothèque et parlez à Téthtoril pour obtenir le parchemin.
Retournez à l'auberge et remettez-le à Perleflamme. Pour vous remercier, il vous lance un sort de protection qui dure pour la nuit.]] },
[231607] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Gibberling Mountains]], h = { [[Le Poing Enflammé offre une prime de 50 pièces d'or pour un déserteur nommé Samuel.]], [[Samuel se cache dans les terres sauvages des Gibberling Mountains.]], [[Trouvez Samuel et livrez-le au soldat du Poing Enflammé pour toucher la prime.]] }, s = [[Un soldat du Poing Enflammé vous apprend qu'un certain Samuel a déserté son poste, et offre 50 pièces d'or pour sa capture.
Cherchez Samuel dans la zone des Gibberling Mountains et confrontez-le.
Livrez-le au soldat du Poing Enflammé pour toucher la prime de 50 pièces d'or.]] },
[231988] = { g = [[bg1]], k = [[companion]], o = 0, c = [[3-4]], w = [[Bois-Manteau / Temple de Lathandre]], h = { [[Un elfe nommé Coran, dans le Bois-Manteau, chasse une wiverne dont la tête est mise à prix.]], [[Les wivernes nichent plus loin dans le Bois-Manteau ; rapportez leur tête comme preuve.]], [[Apportez la tête de wiverne à Kelddath, au Temple de Lathandre à l'est de Bérégost, pour la récompense.]] }, s = [[Dans la première zone du Bois-Manteau, rencontrez Coran, un archer elfe. Il propose de chasser une wiverne ensemble ; si vous acceptez, il vous rejoint.
Enfoncez-vous dans le Bois-Manteau et trouvez l'antre des wivernes. Les wivernes sont venimeuses : prévoyez des antidotes ou une protection contre le poison.
Récupérez une tête de wiverne après le combat.
Rendez-vous au Temple de Lathandre juste à l'est de Bérégost et remettez la tête à Kelddath, bailli de Bérégost et chef du temple. Il vous paie 2 000 pièces d'or.]] },
[232148] = { g = [[bg1]], k = [[companion]], o = 0, c = [[3]], w = [[Camp des bandits]], h = { [[Le rôdeur Kivan veut se venger d'un ogre nommé Tazok qui a tué l'un de ses proches.]], [[Tazok est l'un des chefs des bandits ; on le trouve à leur camp.]], [[Emmenez Kivan au camp des bandits ; la suite dépend de votre façon d'entrer et de la présence de Tazok.]] }, s = [[Avec Kivan dans le groupe, il vous apprend qu'il traque le demi-ogre Tazok, qui a tué son épouse.
Au chapitre 3, trouvez le camp des bandits et entrez-y avec Kivan.
Issues : si Tazok est là, Kivan l'attaque. Tazok peut ignorer la tentative et même vous laisser rester au camp, ou s'enfuir et retourner tout le camp contre vous. Si Tazok est absent, vous ne trouvez que ses laquais.
Dans tous les cas, Kivan ne peut pas achever sa vengeance ici ; Tazok réapparaît plus tard dans l'histoire principale.]] },
[232202] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-5]], w = [[Enclave d'Adoy, grottes des gobelins]], h = { [[Le rôdeur Magreb pleure son amie Rilsa, tuée par des gobelins révoltés.]], [[Les gobelins occupent une série de grottes au nord-est de l'endroit où vous le rencontrez.]], [[Trouvez le corps de Rilsa dans les grottes, offrez-lui une sépulture et rapportez son anneau à Magreb.]] }, s = [[Dans la zone de l'enclave d'Adoy, le rôdeur Magreb vous parle d'un soulèvement de gobelins. Son amie Rilsa a été tuée en tentant de prendre contact avec eux.
Entrez dans les grottes au nord-est et frayez-vous un chemin parmi les gobelins.
Trouvez le corps de Rilsa. Prenez l'anneau qu'elle porte et choisissez de lui offrir une sépulture.
Rapportez l'anneau à Magreb. Si vous l'avez enterrée, il est réconforté. Sinon, il vous remercie mais part l'enterrer lui-même, contrarié.]] },
[232218] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Porte de Baldur / Bois des Dents Acérées]], h = { [[Un rôdeur nommé Shilo Chen cherche de l'aide à la Porte de Baldur.]], [[Des ogres-mages massacrent la faune du Bois des Dents Acérées.]], [[Allez dans le coin sud-ouest du Bois des Dents Acérées et détruisez les ogres-mages.]] }, s = [[À la Porte de Baldur, le rôdeur Shilo Chen demande de l'aide : une bande d'ogres-mages massacre la faune du Bois des Dents Acérées.
Rendez-vous au Bois des Dents Acérées et dirigez-vous vers son coin sud-ouest.
Affrontez les ogres-mages. Ils lancent des sorts et peuvent devenir invisibles : prévoyez de quoi voir ou dissiper l'invisibilité. Shilo enverra peut-être d'autres aventuriers en renfort.]] },
[232759] = { g = [[bg1]], k = [[companion]], o = 0, c = [[3]], w = [[Camp des bandits]], h = { [[Kivan tient beaucoup à chasser les bandits avec vous.]], [[Sa vraie cible est Tazok, un chef des bandits qui a torturé et tué sa femme.]], [[Emmenez Kivan au camp des bandits au chapitre 3 pour voir comment se déroule sa vengeance.]] }, s = [[Kivan vous demande de chasser les bandits ensemble. Cette entrée double « Kivan et Tazok ».
Trouvez le camp des bandits (chapitre 3) et entrez-y avec Kivan dans le groupe. Il révèle que Tazok a torturé et tué sa femme.
Issues : Tazok ignore l'attaque et vous laisse rester, ou il s'enfuit et retourne le camp contre vous, ou il est absent et seuls ses laquais restent. Kivan n'obtient pas sa vengeance au camp.]] },
[232802] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Nashkel / Bérégost, forge de Grondemarteau]], h = { [[Une fiole de liquide étrange venue des mines pourrait expliquer pourquoi le fer devient cassant.]], [[Berrun Tuemort, bailli de Nashkel, pense qu'un forgeron de Bérégost pourrait l'étudier.]], [[Remettez la fiole à Taërom à la forge de Grondemarteau, puis revenez deux jours plus tard.]] }, s = [[Après avoir trouvé une fiole de liquide mystérieux liée aux kobolds des mines de Nashkel, montrez-la à Berrun Tuemort à Nashkel. Il conseille de l'apporter à Taërom Fuiruim à Bérégost.
Allez à la forge de Grondemarteau, à Bérégost, et remettez la fiole à Taërom.
Attendez deux jours, puis revenez. Taërom a trouvé comment neutraliser le poison des kobolds et vend désormais des armes qui ne cassent pas.]] },
[232866] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1-3]], w = [[Côte au sud de Château-Suif]], h = { [[Safana, rencontrée au bord de la mer, veut de l'aide pour un trésor.]], [[Le trésor se trouve dans une crique de la côte juste au sud de Château-Suif, gardé par un monstre.]], [[Allez à la crique avec Safana, vainquez son gardien et prenez le trésor.]] }, s = [[Rencontrez Safana, une voleuse charmeuse, et acceptez de l'aider à récupérer un trésor détenu par un monstre.
Rendez-vous sur la côte juste au sud de Château-Suif et trouvez la crique au trésor.
Entrez avec Safana et vainquez la créature qui le garde ; préparez votre groupe avant d'entrer.
Prenez le trésor. Safana reste ensuite dans le groupe si vous le souhaitez.]] },
[249477] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Grottes souterraines]], h = { [[Murs a entendu des cris qui sortent des murs des grottes.]], [[Cherchez au sud-ouest de l'ancien camp des ogres, là où le bruit semble piégé dans la roche.]], [[Derrière la roche se trouve une grotte scellée ; ce qui y vit ne peut plus être sauvé.]] }, s = [[Parlez à Murs : il évoque des cris venant des murs des grottes, au sud-ouest de l'ancien camp des ogres.
Allez-y et fouillez les parois pour trouver un passage vers une grotte scellée.
À l'intérieur vit une couvée de vers albinos aveugles, déformés par une magie infecte et rendus fous par des années à se dévorer entre eux. Impossible de raisonner avec eux : ils attaquent.
Tuez-les tous pour abréger leurs souffrances et terminer la quête.]] },
[249478] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Inconnu]], h = { [[Cette quête n'a aucune entrée de journal dans les tables du jeu.]], [[Son titre évoque des personnes ou des choses égarées ; écoutez les gens que vous croisez dans les contrées sauvages.]], [[Si vous n'obtenez jamais d'entrée pour elle, vous ne ratez rien.]] }, s = [[La table des quêtes du jeu contient ce titre, mais aucune entrée de journal n'y est rattachée : il n'y a donc rien à suivre ni à terminer.
Il s'agit très probablement d'une quête inutilisée ou retirée de Siege of Dragonspear. Vous pouvez l'ignorer sans risque.]] },
[251953] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Grottes souterraines]], h = { [[Drows et croisés se battent à cause de deux jeunes drows disparus ; Shapur mène les drows.]], [[Fouillez les grottes voisines pour trouver les deux fugueurs avant que le sang ne coule davantage.]], [[Leur sort dépend de vous : ramenez-les, faites croire à leur mort avec leurs insignes de maison, ou arrivez trop tard.]] }, s = [[Sur le lieu où drows et croisés s'affrontent, parlez à Shapur : deux adolescents drows ont fugué et les drows accusent les croisés.
Fouillez les grottes voisines pour trouver les fugueurs. Issues :
- Convainquez-les de rentrer : ils vous retrouvent sur le champ de bataille et Shapur vous remercie à contrecœur avant que les drows ne partent.
- Acceptez de les faire passer pour morts : ils vous donnent leurs insignes de maison à montrer à Shapur.
- Si un ankheg les tue, annoncez leur mort.
Quand vous dites à Shapur qu'ils sont morts, elle peut l'accepter et partir, ou vous attaquer : soyez prêt à combattre.]] },
[257689] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Sous le château de Vougedragon, près de Kanaglym]], h = { [[Le dragon fantôme qui garde les portes de Kanaglym profère des menaces, mais une autre force la manipule.]], [[Passez devant le dragon et entrez dans la salle suivante, où une cabale de magiciens pratique la magie noire.]], [[Tuez le magicien Kherriun, qui détient l'essence du dragon, puis reparlez à Halatathlaer.]] }, s = [[Un énorme dragon fantôme, Halatathlaer, garde une double porte à l'entrée de Kanaglym. Elle vous menace mais n'attaque pas : un pouvoir extérieur la contrôle. Si vous avez trouvé plus tôt le journal qui parle de ses œufs, vous pouvez lui dire ce qu'ils sont devenus.
Passez devant elle et entrez dans la salle suivante, où une cabale de magiciens accomplit un rituel. Tuez leur chef, Kherriun, pour libérer l'essence du dragon ; une fois libre, Halatathlaer vous aide à achever la cabale.
Parlez-lui ensuite : elle révèle ce qu'elle sait d'Hephernaan et de Caelar, puis rejoint le Plan de la Fugue par la fontaine de Népenthès.
Si vous lui avouez avoir tué sa progéniture mutante, elle part, folle de rage. Vous pouvez aussi combattre et détruire le dragon fantôme.]] },
[258034] = { g = [[sod]], k = [[side]], o = 0, c = [[Boareskyr Bridge]], w = [[Fort-du-Pont]], h = { [[Les croisés qui assiègent Fort-du-Pont apprécieraient un traître derrière les murs.]], [[Convainquez le lieutenant nain Kharm que vous servez la croisade, puis entrez dans le fort.]], [[Seule la garde Mari détient la clef du pont-levis : persuadez-la de l'abaisser ou prenez-lui la clef.]] }, s = [[C'est une option maléfique qui livre Fort-du-Pont à la croisade au prix de nombreuses vies.
Devant Fort-du-Pont, du côté des croisés, parlez au lieutenant nain Kharm et convainquez-le que vous appartenez à la croisade. Il vous demande de vous infiltrer dans le fort et d'abaisser le pont-levis.
À l'intérieur, l'unique clef du mécanisme est détenue par la garde Mari. Convainquez-la d'abaisser le pont ou obtenez sa clef d'une autre façon, puis actionnez le mécanisme.
Les croisés prennent le fort. Vous êtes jeté avec les prisonniers et devez vous frayer un chemin dehors, sauf si vous déclinez votre identité : vous partez alors sans mal, mais tous les autres occupants de Fort-du-Pont sont faits prisonniers.]] },
[258475] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Grotte arachnéenne]], h = { [[Des œufs d'araignée sont dispersés dans une grotte infestée d'araignées ; ramassez-en.]], [[Seuls certains insectes géants aiment se nourrir d'œufs d'araignée.]], [[Une fois les œufs en main, quelque chose de gros remue dans les grottes : allez voir d'où vient le bruit.]] }, s = [[Dans la grotte infestée d'araignées, ramassez les œufs dispersés dans la caverne (attendez-vous à ce que les araignées défendent leur nid).
Ensuite, le journal signale que quelque chose de gros est entré dans la grotte. Suivez le bruit.
Il vient d'un scarabée-rhinocéros géant. Les œufs d'araignée sont justement le genre de nourriture que ces insectes recherchent : gardez-les sur vous en le rencontrant et voyez sa réaction.
Trouver le scarabée termine la quête.]] },
[258697] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp des croisés près du château de Vougedragon]], h = { [[Pendant que vous êtes déguisé parmi les croisés, cherchez une prêtresse qui s'occupe des trolls du camp.]], [[Sindret veut qu'on lui rapporte des menottes spéciales pour trolls, rangées dans un coffre du camp.]], [[Avec les menottes, parlez au troll Ulori, ou poussez Sindret à faire le travail elle-même.]] }, s = [[Dans le camp des croisés, Sindret, prêtresse de Shevarash et dompteuse de trolls adjointe, vous demande de trouver des menottes pour trolls rangées dans un coffre du camp.
Rapportez les menottes et acceptez de les passer au troll Ulori. Parlez au troll et convainquez-le de se laisser menotter, puis faites votre rapport à Sindret.
Autres issues : persuadez Sindret de le menotter elle-même (cela tourne mal pour les croisés), refusez et finissez par la combattre, ou tuez le troll, par accident ou exprès. Le tuer fâche Sindret, mais la croisade aura un troll de moins à lancer contre la coalition.]] },
[258713] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp des croisés près du château de Vougedragon]], h = { [[Deux rôdeurs croisés s'opposent, et leur commandant Leopas veut un regard extérieur pour trancher.]], [[Écoutez Valis et Corinth, puis les croisés Ravoc, Damarr et le gnome Delton.]], [[Corinth a bien prévenu le hameau d'Innisfall ; rendez votre verdict à Leopas ou proposez un duel judiciaire.]] }, s = [[Dans le camp des croisés, la rôdeuse Valis accuse son collègue Corinth de trahison, et leur commandant Leopas vous demande de découvrir la vérité.
Parlez à Valis, à Corinth, à l'orque Ravoc, à Damarr et au magicien gnome Delton. Ravoc et Delton défendent Corinth, Damarr juge la peine trop lourde, et Corinth reste évasif.
La vérité : Corinth a alerté le hameau d'Innisfall, ce qui a coûté des recrues et des provisions à la croisade.
Retournez voir Leopas et déclarez Corinth innocent ou coupable, ou convainquez-le de trancher par un duel judiciaire, ce qui retire un croisé des rangs de Caelar. Vos compagnons peuvent réagir à votre choix.]] },
[258806] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp des croisés près du château de Vougedragon]], h = { [[L'officier du moral de la croisade veut que les recrues comprennent pourquoi elles se battent.]], [[Deneld vous envoie discuter avec Ravoc, Sindret, Zare et Tristian dans le camp.]], [[Écoutez les raisons de chacun de suivre Caelar, puis répondez aux questions de Deneld en conséquence.]] }, s = [[Dans le camp des croisés, l'officier du moral Deneld vous demande de parler à quelques croisés, puis de lui montrer ce que vous avez appris.
Parlez à l'orque Ravoc (les âmes de sa tribu sont piégées dans les Neuf Enfers), à Sindret (prêtresse de Shevarash, chasseuse de drows, conquise par la foi de Caelar), à la recrue Zare (dévoué à Caelar sans réserve) et à Tristian (clerc de la Cavalière Rouge, conscrit de force et désormais heureux de servir de stratège).
Retournez voir Deneld et répondez à ses questions d'après leurs propos. S'il est satisfait, la quête se termine et vous comprenez mieux vos ennemis.]] },
[259541] = { g = [[sod]], k = [[companion]], o = 0, c = [[any]], w = [[Tout au long de l'expédition]], h = { [[Neera entend la voix de l'entropiste Adoy et veut une potion pour la faire taire.]], [[Il lui faut une patte d'araignée à sept pattes, une plume de planétaire, de la belladone, une potion de perception et du jus de navet.]], [[Donnez-lui les ingrédients, puis reposez-vous pour qu'elle prépare la potion ; ou cherchez la fontaine de Népenthès dans les grottes profondes.]] }, s = [[Quand Neera est dans le groupe, elle demande cinq ingrédients pour chasser Adoy de son esprit : une patte d'araignée à sept pattes, une plume d'aile de planétaire, de la belladone, une potion de perception et du jus de navet.
Rassemblez-les au fil du voyage. Le barde Voghiln peut vous dire que l'araignée vit dans une grotte à l'est ; le jus de navet est vendu par un gnome très dévoué.
Quand elle a tout (ou si vous la laissez essayer sans tout), dressez le camp et elle prépare la potion. Une potion complète la libère ; une potion incomplète fonctionne, mais elle en paie le prix, plus ou moins lourd.
Elle peut aussi choisir de libérer Adoy pour de bon : cherchez alors le portail vers le Plan de la Fugue, la fontaine de Népenthès, dans les grottes sous Vougedragon, et aidez-la à libérer son esprit.]] },
[259567] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Tombeau de Korlasz]], h = { [[Cette quête n'a aucune entrée de journal propre dans ce jeu.]], [[Elle concerne très probablement les restes des partisans de Sarevok dans le tombeau de Korlasz, au début de la campagne.]], [[Explorez toutes les salles du tombeau avec le Poing Enflammé avant de partir.]] }, s = [[La table des quêtes du jeu contient cette quête sans aucune entrée de journal : il n'y a rien de précis à suivre.
Elle appartient très probablement au début de Siege of Dragonspear : avec le Poing Enflammé, vous nettoyez le tombeau où se cachent Korlasz et les derniers partisans de Sarevok.
Explorez tout le donjon, réglez le sort de Korlasz et occupez-vous des affaires annexes qui s'y trouvent (la fillette secourue, la momie Fanegonorom) avant de remonter à la surface.]] },
[259568] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Tombeau de Korlasz]], h = { [[Les prisonniers du tombeau de Korlasz ne sont pas tous ce qu'ils semblent être.]], [[Une fillette semble être captive de Korlasz ; Imoen pourrait aussi apparaître là où elle ne devrait pas être.]], [[Des doppelgangers rôdent dans le tombeau : guettez les détails étranges et préparez-vous à combattre.]] }, s = [[Dans le tombeau de Korlasz, vous trouvez une fillette qui prétend avoir été torturée par Korlasz.
Vous pouvez la libérer et laisser le Poing Enflammé la guider vers la surface, ou percer la ruse à jour : c'est un doppelganger, que vous combattez et tuez.
Plus tard, une fausse Imoen apparaît, parfois alliée à Korlasz. Elle se révèle être un doppelganger et vous devez la détruire. Si vous avez libéré la fillette, vous vous demandez alors si c'était vraiment une enfant.]] },
[259569] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Tombeau de Korlasz]], h = { [[Une chose ancienne dort dans une salle du tombeau de Korlasz et n'aime pas le bruit.]], [[La momie Fanegonorom veut que les intrus disparaissent pour retrouver le repos.]], [[Vainquez Korlasz, puis remontez à la chambre de la momie.]] }, s = [[Dans le tombeau de Korlasz, vous dérangez la momie Fanegonorom. Au lieu de combattre, elle vous ordonne de régler le cas de Korlasz, dont les partisans bruyants l'empêchent de dormir.
Poursuivez l'exploration du tombeau et vainquez Korlasz au niveau inférieur.
Retournez ensuite dans la chambre de la momie, au niveau supérieur, et reparlez-lui. Elle vous récompense pour ce service et la quête se termine.]] },
[259615] = { g = [[sod]], k = [[main]], o = 20, c = [[Coast Way Crossing]], w = [[Pont de la Voie Côtière]], h = { [[La route prévue de l'expédition vers le nord est coupée.]], [[Le pont de la Voie Côtière étant détruit, le Poing Enflammé doit faire un détour.]], [[Dirigez-vous vers le Pont de Boreskyr et le fort qui le garde, Fort-du-Pont.]] }, s = [[Après avoir quitté la Porte de Baldur, l'expédition campe près du pont de la Voie Côtière. Explorez la zone, réglez le sort des croisés présents et terminez vos affaires avec les officiers du Poing Enflammé au camp.
Le pont sur le fleuve est détruit : l'armée ne peut plus passer par là.
Le nouvel itinéraire mène jusqu'au Pont de Boreskyr, le lieu de la mort de Bhaal, gardé par Fort-du-Pont. Rendez-vous-y quand vous êtes prêt à poursuivre l'histoire principale.]] },
[259618] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Porte de Baldur, Palais Ducal]], h = { [[L'or que vous aviez à la fin de votre dernière aventure a été mis en sûreté au palais.]], [[Le trésorier Ophyllis travaille dans une petite pièce, côté sud, au sous-sol du palais.]], [[S'il annonce que l'or est perdu, retrouvez-le dehors et suivez sa piste jusqu'aux Trois Vieilles Chopes.]] }, s = [[Votre or a été déposé dans la chambre forte du Palais Ducal. Descendez au sous-sol et parlez au trésorier Ophyllis, dans la petite pièce côté sud, pour le récupérer. Il installe aussi un coffre dans vos quartiers.
Dans une variante, il avoue avoir perdu l'or et promet de vous rembourser devant le palais. Il réapparaît blessé devant la Grande-Maison : des voleurs ont pris l'argent. Leur repaire est au deuxième étage des Trois Vieilles Chopes. Ils l'ont dépensé pour les réfugiés qui fuient Caelar ; vous pouvez les pardonner, les tuer ou les livrer au Poing Enflammé. L'or est perdu dans tous les cas.
Ophyllis peut ensuite vous offrir un buste en or à votre effigie. S'il meurt sous les coups de croisés, retrouvez-les pour récupérer votre fortune.]] },
[259620] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate - Dragonspear Castle]], w = [[Porte de Baldur, puis l'expédition]], h = { [[Skie, la fille du Grand Duc Entar Écudargent, veut vous parler en privé au palais.]], [[Elle a rejoint le Poing Enflammé en secret sous un faux nom ; décidez si vous prévenez son père.]], [[Gardez un œil sur elle pendant la marche vers le nord et cherchez-la dans le château de Vougedragon après la bataille.]] }, s = [[Au Palais Ducal, vous croisez Skie Écudargent, qui laisse entendre qu'elle veut vous parler seule. Attendez : elle vient dans votre chambre la nuit et révèle qu'elle a rejoint le Poing Enflammé sous un faux nom.
Gardez son secret ou prévenez le Grand Duc Entar Écudargent. Dans les deux cas, elle part avec l'expédition ; Entar demande qu'elle soit traitée comme n'importe quel soldat.
Pendant le voyage, des rumeurs sur son identité et ses liens avec Bence Duncan circulent dans les camps ; vous pouvez la trouver au camp de la coalition, devant le château de Vougedragon.
Après la chute du château, Skie, un temps capturée par les croisés, est retrouvée cachée sur place. Elle vous apprend que Caelar est descendue à la chambre forte sous le château, et le Poing Enflammé veille sur elle.
Son sort est lié à la fin de l'histoire principale, à la Porte de Baldur.]] },
[259621] = { g = [[sod]], k = [[main]], o = 19, c = [[Baldur's Gate]], w = [[Porte de Baldur]], h = { [[Avant la marche vers le nord, vous pouvez rassembler de vieux amis de vos aventures passées.]], [[Le capitaine Schael Corwin vous accompagne en ville pendant que vous cherchez des compagnons.]], [[Essayez les Trois Vieilles Chopes, la taverne du Chant de l'Elfe, l'ancien bâtiment du Trône de Fer et le quartier général du Poing Enflammé, puis retournez au palais.]] }, s = [[Le capitaine Schael Corwin vous accompagne dans la Porte de Baldur pour recruter des compagnons en vue du voyage vers Vougedragon.
Minsc et Dynahéir logent aux Trois Vieilles Chopes. Garrick, Safana et Coran sont à la taverne du Chant de l'Elfe. Rasaad travaille dans un camp de réfugiés, dans l'ancien bâtiment du Trône de Fer. Tiax est détenu au quartier général du Poing Enflammé.
Invitez qui vous voulez. Une fois terminé, Corwin conseille de retourner au Palais Ducal, ce qui fait avancer l'histoire et met fin à votre séjour en ville.
Les compagnons que vous n'avez pas pris rejoignent quand même l'expédition : vous les retrouverez au camp du Poing Enflammé, près du pont de la Voie Côtière.]] },
[259623] = { g = [[sod]], k = [[companion]], o = 0, c = [[any]], w = [[Tout au long de l'expédition]], h = { [[Cette quête de compagnon n'a aucune entrée de journal propre dans ce jeu.]], [[Le capitaine Schael Corwin, du Poing Enflammé, peut vous rejoindre dès la Porte de Baldur.]], [[Gardez-la dans le groupe et parlez-lui souvent pour en apprendre davantage sur elle et sa famille.]] }, s = [[La table des quêtes du jeu contient cette entrée sans aucun texte de journal : il n'y a pas d'étapes à suivre.
Schael Corwin, capitaine du Poing Enflammé, vous est affectée à la Porte de Baldur et peut vous accompagner pendant toute la campagne.
Emmenez-la et répondez-lui quand elle engage la conversation ; son histoire personnelle se dévoile au fil de ces discussions, pendant la marche vers le nord et au camp de la coalition.]] },
[259626] = { g = [[sod]], k = [[main]], o = 31, c = [[Baldur's Gate - Epilogue]], w = [[Palais Ducal, Pont de Boreskyr, Porte de Baldur]], h = { [[Un étranger encapuchonné apparaît partout où vous allez et semble vous connaître.]], [[Il se montre de nouveau après votre malaise sur le Pont de Boreskyr et vous met en garde contre Caelar.]], [[Après la nuit où Skie meurt, préparez votre défense : le Duc Belt entendra tous ceux que vous avez croisés vers le nord.]] }, s = [[Un étrange homme à capuche apparaît d'abord dans vos quartiers du Palais Ducal. Pendant le voyage, d'autres vous disent qu'il pose des questions sur vous.
Lorsque vous perdez connaissance en traversant le Pont de Boreskyr, vous vous réveillez au milieu d'un symbole de Bhaal tracé par les flammes ; il prétend vous avoir sauvé, affirme que votre pouvoir peut être endigué ou extrait, et vous avertit que Caelar n'est pas ce qu'elle semble être.
Après la campagne, de retour à la Porte de Baldur, vous voyez Skie se changer en monstre et vous vous réveillez les mains en sang, accusé de son meurtre et emprisonné au quartier général du Poing Enflammé.
Vous apprenez que l'homme à la capuche a tué Skie. Le Duc Belt entend ensuite vos compagnons, les commandants de la coalition et d'autres : vos actes durant l'expédition pèsent sur le verdict.]] },
[259645] = { g = [[sod]], k = [[companion]], o = 0, c = [[Dragonspear Castle]], w = [[Camp des croisés près du château de Vougedragon]], h = { [[Edwin a ses propres raisons de craindre, et d'affronter, la croisade de la Dame Étincelante.]], [[Un ancien compagnon de route d'Edwin, un Magicien Rouge, sert désormais parmi les croisés.]], [[Trouvez le Magicien Rouge Vichand dans le camp des croisés avec Edwin dans le groupe, et tuez-le.]] }, s = [[Quand Edwin est dans le groupe, il finit par expliquer pourquoi il veut affronter Caelar Argent.
Dans le camp des croisés, vous rencontrez le Magicien Rouge Vichand, ancien compagnon de route d'Edwin devenu son ennemi juré. Edwin veut le tuer à la première occasion.
Le moment venu, combattez Vichand en présence d'Edwin. Attendez-vous à un lanceur de sorts redoutable et préparez vos protections. Sa mort venge un camarade disparu d'Edwin et clôt la quête ; Edwin vous en est aussi reconnaissant qu'il peut l'être.]] },
[259711] = { g = [[sod]], k = [[main]], o = 21, c = [[Boareskyr Bridge]], w = [[Pont de Boreskyr, Fort-du-Pont]], h = { [[La nouvelle route de l'expédition passe par le Pont de Boreskyr, là où Bhaal est mort.]], [[Traverser le pont réveillera quelque chose dans votre sang, sous les yeux de vos alliés.]], [[Assurez Fort-du-Pont à la coalition avant que l'armée reprenne la route vers Vougedragon.]] }, s = [[L'expédition arrive au Pont de Boreskyr et à Fort-du-Pont, que menace la croisade.
En traversant le pont, vous êtes frappé par une vision de la mort de votre père, Bhaal, et vous vous effondrez devant vos alliés ; les rumeurs sur votre ascendance pourraient vous causer des ennuis plus tard. L'homme à la capuche apparaît ensuite.
Aidez à tenir Fort-du-Pont face à la croisade et explorez la région alentour. Une fois le fort sécurisé, la coalition peut poursuivre vers le nord jusqu'au château de Vougedragon.
L'option maléfique, abaisser le pont-levis pour les croisés, est traitée dans la quête « À bas le pont-levis ».]] },
[259716] = { g = [[sod]], k = [[companion]], o = 0, c = [[Coast Way Crossing - later]], w = [[Pont de la Voie Côtière, ville naine souterraine]], h = { [[Avec M'Khiin dans le groupe, guettez des gobelins tués près du pont de la Voie Côtière.]], [[Leurs esprits, rappelés par M'Khiin, parlent d'une planque cachée à l'ouest du pont.]], [[Plus tard, dans une ville naine souterraine, une armure de gobelin possédée attend ; décidez si M'Khiin la porte.]] }, s = [[Avec M'Khiin dans le groupe, vous trouvez près du pont de la Voie Côtière les corps de quatre gobelins mercenaires tués récemment. M'Khiin rappelle leurs esprits, qui révèlent une planque de marchandises à l'ouest du pont de la Voie Côtière. Fouillez cet endroit pour la trouver.
Plus tard, dans la ville naine souterraine, vous trouvez une armure de gobelin possédée par son ancien propriétaire, Kruntur.
Convainquez M'Khiin de la porter pour se protéger, ou laissez-la suivre sa voie de lanceuse de sorts : elle prend alors des robes et un bâton.]] },
[259717] = { g = [[sod]], k = [[main]], o = 25, c = [[Dragonspear Castle]], w = [[Château de Vougedragon]], h = { [[Les gardes de la croisade ne laissent pas un inconnu entrer dans le château de Vougedragon.]], [[Il vous faut l'un des sceaux de Caelar ; les patrouilles de croisés en portent peut-être.]], [[Montrez le sceau aux gardes de la porte, puis jouez toujours le rôle d'un croisé à l'intérieur.]] }, s = [[Pour entrer dans le château de Vougedragon sans donner l'alerte, il vous faut l'un des sceaux de Caelar.
Tendez une embuscade à une patrouille de croisés hors du château, ou réglez son sort, et prenez-lui un sceau.
Présentez-vous à la porte et convainquez les gardes de vous laisser entrer. Vous pouvez alors explorer la cour, mais gardez secrets votre nom et votre but : répondez en croisé dans chaque conversation, sinon toute la garnison pourrait se retourner contre vous.]] },
[259718] = { g = [[sod]], k = [[main]], o = 27, c = [[Dragonspear Castle]], w = [[Château de Vougedragon, camp de la coalition]], h = { [[Torsin de Lancie vous confie une mission secrète à l'intérieur de la forteresse ennemie.]], [[Une fois dans le château de Vougedragon, trouvez les réserves de nourriture et d'eau de la croisade.]], [[Empoisonnez-les, fuyez le château à l'arrivée d'Hephernaan et faites votre rapport à de Lancie.]] }, s = [[Au camp de la coalition, Torsin de Lancie vous demande de saboter la croisade depuis l'intérieur du château de Vougedragon.
Entrez dans le château (voir « Entrer dans le château de Vougedragon ») et gagnez les réserves. Empoisonnez la nourriture, l'eau, ou les deux : chacune affaiblit la croisade pour la bataille à venir.
Alors que vous poursuivez vers les sous-sols, Hephernaan arrive et votre couverture tombe. Quittez immédiatement le château avant que toute la garnison ne vous tombe dessus, et retournez voir de Lancie au camp de la coalition pour faire votre rapport.]] },
[259722] = { g = [[sod]], k = [[main]], o = 29, c = [[Avernus - Epilogue]], w = [[Avernus, puis Porte de Baldur]], h = { [[En Avernus, rejoignez Caelar et arrêtez ce qu'Hephernaan a déclenché.]], [[Une fois la croisade brisée, l'expédition rentre à la Porte de Baldur.]], [[Vos ennuis ne sont pas finis en ville : l'homme à la capuche attend son heure.]] }, s = [[En Avernus, frayez-vous un chemin jusqu'à la Tour de Basalte et affrontez Hephernaan et les forces de l'Enfer. Vos choix envers Caelar décident de son sort.
Une fois Hephernaan vaincu, la croisade est terminée et vous rentrez à la Porte de Baldur en héros.
C'est alors que commence la dernière partie : Skie Écudargent meurt, vous êtes accusé de son meurtre et emprisonné au quartier général du Poing Enflammé. Suivez les quêtes « Implications troublantes » et « Ce n'était pas moi » pour atteindre le dénouement.]] },
[259731] = { g = [[sod]], k = [[side]], o = 0, c = [[Avernus]], w = [[Avernus, devant la Tour de Basalte]], h = { [[Un diable barre l'accès à la Tour de Basalte et adore les paris.]], [[Thrix le Profane vous laisse passer si vous gagnez son jeu ; l'enjeu peut être un compagnon ou votre propre âme.]], [[Vous pouvez aussi refuser de parier et le combattre.]] }, s = [[En Avernus, le diable Thrix le Profane garde l'entrée de la Tour de Basalte et propose un pari pour vous laisser passer.
Acceptez et choisissez l'enjeu : l'un de vos compagnons, ou votre propre âme. Répondez à son défi avec soin. Si vous gagnez, vous passez sans rien perdre.
Si vous perdez, vous passez quand même, mais le compagnon misé est condamné à être réclamé un jour par Thrix, ou bien il revendique votre âme.
Vous pouvez aussi refuser de marchander et le défier : soit vous le détruisez au combat, soit il s'enfuit en laissant ses larbins vous affronter, et jure de se venger. Préparez-vous à un combat difficile dans les deux cas.]] },
[259732] = { g = [[sod]], k = [[main]], o = 28, c = [[Dragonspear Castle - Avernus]], w = [[Château de Vougedragon, sous-sols]], h = { [[Le château est pris, mais Caelar ne fait pas partie des prisonniers.]], [[Suivez sa piste jusqu'aux sous-sols du château et à la chambre forte en dessous.]], [[Caelar a franchi un portail vers Avernus à la suite d'Hephernaan : vous devez la suivre en Enfer.]] }, s = [[Après la bataille, le château de Vougedragon est aux mains de la coalition, mais Caelar s'est échappée.
Fouillez le château ; si vous trouvez Skie, elle vous apprend que Caelar s'est dirigée vers la chambre forte du sous-sol pendant que les croisés fuyaient par les tunnels.
Descendez à travers les sous-sols. Vous y apprenez que Caelar a suivi Hephernaan par un portail vers Avernus, la première strate des Neuf Enfers, et que son plan a terriblement mal tourné.
Préparez le groupe (repos, provisions, choix des compagnons) et franchissez le portail pour la poursuivre.]] },
[259734] = { g = [[sod]], k = [[main]], o = 30, c = [[Epilogue]], w = [[Porte de Baldur, quartier général du Poing Enflammé et égouts]], h = { [[Emprisonné pour le meurtre de Skie, vous devez vous évader ou être libéré par le Conseil des Quatre.]], [[Si un étranger vous propose une issue, récupérez votre équipement dans la pièce centrale et suivez-le au sous-sol.]], [[Le tunnel secret mène aux égouts ; votre seule issue est de passer par-dessus la cascade.]] }, s = [[Accusé du meurtre de Skie, vous êtes détenu au quartier général du Poing Enflammé.
Si vos actes passés convainquent la majorité du Conseil des Quatre, vous êtes libéré mais banni : récupérez vos affaires au quartier général, puis quittez la ville sous escorte. Le père de Skie jure de se venger.
Sinon, un étranger vous propose de fuir. Prenez votre équipement sur la table de la pièce centrale et suivez-le jusqu'au tunnel secret du sous-sol. Dans les égouts, le Poing Enflammé vous accule ; vous devrez peut-être combattre Corwin ou Bence Duncan et leurs hommes.
Courez jusqu'à la chute d'eau et passez par-dessus la cascade pour vous enfuir. Vous comprenez ensuite que ce n'est pas Imoen qui vous a libéré : l'homme à la capuche a tout manigancé.]] },
[260258] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp de la coalition et camp des croisés]], h = { [[Une gnome receleuse du camp de la coalition paie bien pour des souvenirs du camp ennemi.]], [[Waizahb veut cinq objets : la chevalière d'un commandant, un étendard, un symbole sacré, un gage de foi et la carte annotée par Caelar.]], [[Prévoyez un remplacement pour le symbole aux yeux de rubis, effrayez le commandant Dreon en parlant d'honnête labeur, et faites vite avant la bataille.]] }, s = [[Waizahb, receleuse au camp de siège de la coalition, veut cinq objets du camp des croisés.
Chevalière : le commandant Dreon est difficile d'approche ; gagnez sa confiance et évoquez un travail honnête, il vous la cède.
Étendard : dans un coffre du camp des croisés.
Symbole sacré : Tristian, clerc de la Cavalière Rouge, en porte un aux yeux de rubis. Sa disparition se remarquerait, alors apportez un objet de remplacement pour l'échanger.
Gage de foi : certaines recrues portent des gages de dévotion faits main ; obtenez-en un.
Carte : la carte annotée par Caelar est accrochée dans le camp.
Apportez les objets à Waizahb au fur et à mesure ; les cinq donnent la récompense complète. La quête se ferme au début de la bataille, alors terminez tôt.]] },
[261101] = { g = [[sod]], k = [[companion]], o = 0, c = [[Coast Way Crossing - Dragonspear Castle]], w = [[Fort-du-Pont, camp de la coalition, camp des croisés]], h = { [[Le gnome Glint s'est glissé dans la caravane pour savoir ce qu'il est advenu de sa famille en territoire croisé.]], [[Son oncle cordonnier est à Fort-du-Pont, son cousin Pritchard agace la milice de Gué-de-la-Dague, et une autre cousine coud pour la croisade.]], [[Demandez à Glint quoi faire de Pritchard : le rosser, le chasser ou l'épargner, chaque choix règle l'affaire.]] }, s = [[Glint Gardnersonson, un gnome passager clandestin de la caravane du Poing Enflammé, vous rejoint pour retrouver sa famille.
À Fort-du-Pont, son oncle Hoach Moinefougueux, cordonnier, peut réparer la botte et demie trouvée près du pont de la Voie Côtière ; revenez un jour plus tard. Les Bottes de rapidité ratent lamentablement : demandez-lui un remboursement.
Au camp de la coalition, Pritchard Gardnersonson pose problème à la milice de Gué-de-la-Dague et au général Main-de-pierre ; deux miliciens offrent des potions pour régler cela. Parlez à Glint : il vous demande de rosser Pritchard pour lui sauver la vie. Vous pouvez le battre, le chasser (il laisse un poignard de famille à Glint), simuler sa mort ou le laisser tranquille. Il peut aussi mourir.
Dans le camp des croisés, vous trouvez Rhonda, cousine de Glint, forcée de travailler comme couturière.]] },
[261301] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp des croisés près du château de Vougedragon]], h = { [[Deux croisés, Nan et Pedro, ont un camarade ivre incapable de faire son devoir.]], [[Le commandant Dreon attend le rapport matinal de l'officier du moral Deneld, ainsi que du vin.]], [[Portez un uniforme de croisé avant de demander le rapport à Deneld, et remplissez une flasque de vin.]] }, s = [[Dans le camp des croisés, Nan et Pedro expliquent que leur camarade Sallo est trop ivre pour porter le rapport matinal au commandant Dreon.
Trouvez une flasque et remplissez-la de vin.
Obtenez le rapport auprès de l'officier du moral Deneld. Il refuse si vous ne portez pas d'uniforme de croisé : trouvez-en un ou inventez une excuse convaincante.
Apportez le vin et les papiers au commandant Dreon et convainquez-le d'accepter la livraison.
Retournez voir Nan et Pedro : ils vous récompensent avec quelques potions.]] },
[261432] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp de la coalition et forêt voisine]], h = { [[La guérisseuse Dosia, au camp de la coalition, s'inquiète d'une maladie qui se répand.]], [[Examinez les trois patients, puis intéressez-vous aux rats du camp avec un druide ou un rôdeur.]], [[Les remèdes possibles sont dans la forêt : l'écorce d'un prunellier, ou l'aide d'un druide ermite qui veut une griffe de basilic.]] }, s = [[Une maladie se répand au camp de la coalition. Parlez à la guérisseuse Dosia, puis examinez les patients Xerra, Yestimell et Zidrand (Yestimell vous attaque). Des compagnons doués en soins ou en nature sont utiles. Faites votre rapport à Dosia.
Piste : les rats du camp. Un homme-rat les a pris pour meute et vous attaque ; une fois mort, un druide ou un rôdeur peut parler à un rat.
Remèdes : trouvez un prunellier dans la forêt près du camp et prenez son écorce moisie, ou cherchez-y le druide ermite Onoroth ; il vous demande de tuer un basilic malade et de rapporter sa griffe, puis vous donne un remède.
Apportez le remède à Dosia pour soigner les soldats. Si elle refuse de payer, vous pouvez le garder. Vous pouvez aussi lui conseiller d'isoler, ou de tuer, les malades.]] },
[261449] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp de la coalition]], h = { [[L'intendante Doubletranchant veut que vous compreniez ce que les soldats de la coalition pensent de la guerre.]], [[Parlez à la guérisseuse Dosia, à la justicière Halasan et au quartier-maître Belegarm.]], [[Retrouvez ensuite Doubletranchant près des tentes de commandement et racontez-lui ce que vous avez appris.]] }, s = [[Au camp de la coalition, l'intendante Simonetta Doubletranchant vous demande d'interroger des gens du camp sur leur expérience de la guerre.
Parlez à Dosia (enfant, elle a survécu à l'attaque de Gué-de-la-Dague et croit que le destin l'a menée ici), à la justicière Halasan (elle veut ramener ses soldats vivants, alors qu'un ami d'enfance, Tristian, sert la croisade) et au quartier-maître Belegarm (passionné d'histoire, avide de gloire).
Retournez voir Doubletranchant près des tentes de commandement et discutez de ce que vous avez entendu pour clore la quête. Vous pouvez aussi abandonner l'exercice, ce qui y met fin sans la conversation complète.]] },
[261502] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp de la coalition, Défilé du Trépassé]], h = { [[Le nain Helvdar a perdu son porte-bonheur et ne peut pas combattre sans.]], [[Une nouvelle paire de bottes en peau d'ours pourrait convenir ; le quartier-maître Belegarm peut les fabriquer.]], [[Chassez un ours au Défilé du Trépassé, apportez la peau à Belegarm et revenez un jour plus tard.]] }, s = [[Le nain Helvdar a perdu son porte-bonheur et en a besoin d'un nouveau.
Rendez-vous au Défilé du Trépassé et chassez un ours. Apportez sa peau au quartier-maître Belegarm, qui râle mais accepte de fabriquer des bottes ; elles sont prêtes un jour plus tard.
Récupérez les bottes et remettez-les à Helvdar pour terminer la quête.
Si vous essayez de lui faire passer des bottes ordinaires pour des bottes porte-bonheur, ou si vous gardez les nouvelles bottes, Helvdar raconte partout que vous êtes un voleur de bottes, ce qui nuit à votre réputation au camp.]] },
[261529] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp de la coalition]], h = { [[Le général Main-de-pierre, des forces de Gué-de-la-Dague, soupçonne une guilde de voleurs de prospérer au camp.]], [[Commencez par la gnome receleuse Waizahb : convainquez-la d'organiser une rencontre, ou suivez-la.]], [[La guilde se réunit à la pointe nord du camp ; affrontez sa chef Rhynwis, puis faites votre rapport à Main-de-pierre.]] }, s = [[Au camp de la coalition, le général Main-de-pierre vous demande de démasquer la guilde de voleurs qui s'y installe.
Interrogez la gnome Waizahb, receleuse de la guilde. Persuadez-la d'organiser une rencontre ou, si elle vous perce à jour, suivez-la quand elle part vers le nord.
À la pointe nord du camp, rencontrez les représentants de la guilde et leur chef, Rhynwis. Menacez-la : soit elle accepte d'aider le camp le moment venu, soit elle s'enfuit et laisse le camp tranquille.
Retournez faire votre rapport au général Main-de-pierre. Elle vous remercie et commence à vous voir comme une influence positive sur le camp.]] },
[261592] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camps de la région de Vougedragon]], h = { [[Un homme abattu nommé Jospil demande qu'on le laisse seul un instant.]], [[Revenez lui parler de la croisade et de la Dame Étincelante.]], [[Choisissez des réponses encourageantes pour lui remonter le moral ; meilleure est son humeur, meilleur est son cadeau.]] }, s = [[Un homme déprimé, Jospil, vous demande de lui laisser un moment avant de parler.
Reparlez-lui. Il vous parle de la croisade et de Caelar Argent, et de ses sombres perspectives.
Essayez de lui remonter le moral avec des réponses encourageantes et compréhensives. Si vous le faites complètement changer d'état d'esprit, il vous donne un bouclier et un bâton. Si vous ne l'égayez qu'un peu, il vous donne un bâton. Si vous échouez, vous apprenez seulement des choses sur la croisade.]] },
[261597] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Porte de Baldur, Trois Vieilles Chopes]], h = { [[Deux équipages sont sur le point d'en venir aux mains aux Trois Vieilles Chopes.]], [[Le tavernier Nantrin Bellowglym vous fait confiance pour régler cela ; vous pouvez aussi parler aux deux officiers.]], [[Prenez parti pour Lucilla, du Délice Amnien, ou pour Autinn, du Fils de Chiondar, puis demandez une récompense.]] }, s = [[Aux Trois Vieilles Chopes, à la Porte de Baldur, une bagarre se prépare entre deux équipages.
Parlez au tavernier Nantrin Bellowglym, qui vous reconnaît et vous demande d'intervenir, ou adressez-vous directement aux deux meneurs.
Vous pouvez calmer la situation pacifiquement, ou prendre parti : pour Lucilla, navigatrice du Délice Amnien, ou pour Autinn, premier lieutenant du Fils de Chiondar.
Si vous avez pris parti, reparlez ensuite à votre allié : Lucilla vous donne un gourdin enchanté, Autinn un cimeterre enchanté.]] },
[261604] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Porte de Baldur, Trois Vieilles Chopes]], h = { [[Trois nobles ont loué une seule chambre à l'étage des Trois Vieilles Chopes ; ce n'est pas une fête.]], [[Trouvez la preuve de leur complot contre la ville, ou gagnez leur confiance en feignant d'être d'accord.]], [[Prévenez le capitaine Corwin à la porte principale, puis poussez les conspirateurs à répéter leurs plans pendant que ses hommes écoutent.]] }, s = [[À l'étage des Trois Vieilles Chopes, trois nobles partagent une chambre et complotent contre la Porte de Baldur.
Parlez-leur en feignant de partager leurs idées, ou trouvez la lettre séditieuse que l'un d'eux porte sur lui.
Allez voir le capitaine Corwin, qui attend à la porte principale au rez-de-chaussée. Elle poste une équipe du Poing Enflammé dans le couloir ; revenez et poussez les nobles à reparler de leurs plans. Si vous réussissez, ils sont arrêtés. S'ils ne se trahissent pas, Corwin doit les relâcher.
Autres options : extorquer de l'argent aux traîtres, ou les tuer vous-même.]] },
[261611] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Porte de Baldur, Trois Vieilles Chopes]], h = { [[Entrer dans la mauvaise chambre aux Trois Vieilles Chopes peut rapporter gros.]], [[La noble vaniteuse Delenda vous ordonne de sortir, protégée par son garde du corps.]], [[Soutirez-lui son collier par la ruse, faites-les fuir, ou combattez le garde du corps.]] }, s = [[Dans une chambre des Trois Vieilles Chopes, vous tombez sur Delenda, une noble vaniteuse, qui vous ordonne avec colère de sortir.
Utilisez des réponses rusées pour la convaincre de vous donner un collier de grande valeur.
Vous pouvez aussi l'effrayer, elle et son garde du corps : ils s'enfuient en abandonnant la chambre. Ou combattre : tuer le garde du corps vous rapporte son wakizashi.]] },
[261612] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate - Avernus]], w = [[Taverne du Chant de l'Elfe, puis tout le voyage]], h = { [[Un elfe excentrique de la taverne du Chant de l'Elfe distribue d'étranges lunettes.]], [[Les lunettes de scrutation de Zaviak révèlent des êtres extraplanaires et peuvent en attirer jusqu'à trois dans ce monde.]], [[Choisissez bien où utiliser les charges : certains visiteurs vous récompensent, d'autres attaquent.]] }, s = [[Parlez à Zaviak, l'elfe excentrique de la taverne du Chant de l'Elfe, pour obtenir les lunettes de scrutation. Portez-les pour voir les créatures extraplanaires ; vous pouvez en attirer trois dans ce monde.
Apparitions connues : un élémentaire de feu au Chant de l'Elfe (il attaque) ; un gauth près du pont de la Voie Côtière (tuez-le ou envoyez-le vers le camp des croisés) ; une tieffeline, Raeanndra, aux prises avec un élémentaire de terre (attirez-la pour un anneau magique) ; le djinn Nazramu ; le rakshasa Vidyadhar (résolvez son énigme pour un cœur de modron) ; une ombre dans une grotte de gobelours (lâchez-la sur eux) ; la liche Zhadroth emprisonnée à Kanaglym (une Sentinelle Éternelle la poursuit) ; une déva ou un démon en Avernus (le démon donne une épée).
La quête se termine quand les lunettes n'ont plus de charges.]] },
[261617] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Porte de Baldur, taverne du Chant de l'Elfe et Palais Ducal]], h = { [[Une petite-personne qui travaille à la taverne du Chant de l'Elfe est à court d'un vin particulier.]], [[Irina veut un tonneau de vin rubis, au parfum très épicé, de la cave du Palais Ducal.]], [[Dérobez un tonneau dans la cave du palais, ou proposez-lui un substitut convaincant.]] }, s = [[À la taverne du Chant de l'Elfe, la petite-personne Irina est à court de vin rubis et vous demande de voler un tonneau dans la cave du Palais Ducal.
Descendez dans la cave du palais et cherchez le tonneau au parfum très épicé. Rapportez-le à Irina pour obtenir une récompense.
Vous pouvez aussi lui fournir un substitut, qui rapporte également une récompense.
Un druide peut tenter une solution magique, mais elle peut mal tourner et changer Irina en écureuil ; une fois redevenue elle-même, elle ne s'intéresse plus au vin.]] },
[261618] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Inconnu (là où vous rencontrez Ammon)]], h = { [[Une femme nommée Ammon est bloquée sur une potion faute de lichen de cobalt.]], [[Suggérez-lui un ingrédient de substitution, ou apportez-lui du lichen de cobalt si vous en trouvez.]], [[Sa potion fait partie d'un plan pour entrer à Château-Suif ; ayant grandi là-bas, vous pouvez signer sa lettre ou refuser.]] }, s = [[Ammon a besoin de lichen de cobalt pour terminer une potion.
Suggérez-lui un substitut : elle l'essaie aussitôt ; reparlez-lui peu après. Ou revenez si vous trouvez du lichen de cobalt.
Une fois la potion terminée, elle vous récompense.
Vous apprenez que la potion fait partie de son plan pour entrer à Château-Suif. Si vous lui dites y avoir grandi, elle vous demande de signer une lettre expliquant son but. Signer ou refuser ne change pas grand-chose : la lettre a peu de chances de lui ouvrir les portes.]] },
[261625] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Porte de Baldur, sous-sols du Palais Ducal]], h = { [[Une vieille ennemie capturée au début de la campagne s'est libérée dans le Palais Ducal.]], [[Korlasz veut se venger de vous et de la ville.]], [[Descendez aux sous-sols du palais, prêt à affronter une magicienne, et achevez-la.]] }, s = [[Korlasz, servante de Sarevok et ancien lieutenant du Trône de Fer, s'échappe et erre dans le Palais Ducal, décidée à se venger de sa capture et de la mort de Sarevok.
Descendez aux sous-sols du palais pour la trouver. Préparez-vous contre une lanceuse de sorts (protections contre les sorts, moyens de briser ses défenses) avant d'engager le combat.
Cette fois, pas de quartier : vainquez et tuez Korlasz pour clore la quête.]] },
[261628] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Porte de Baldur, Palais Ducal]], h = { [[Un officier du Poing Enflammé s'est retrouvé enfermé dans une cellule du palais.]], [[Trouvez un moyen d'ouvrir la cellule pour le faire sortir.]], [[Préparez-vous à combattre : le prisonnier n'est peut-être pas ce qu'il semble être.]] }, s = [[Au Palais Ducal, un officier du Poing Enflammé a été enfermé par accident dans une cellule.
Trouvez un moyen de l'ouvrir, avec une clef ou en crochetant la serrure, et libérez-le.
Dans un cas, c'est un véritable officier malchanceux qui repart simplement. Dans l'autre, l'« officier » est un doppelganger qui attaque une fois libéré : tuez-le pour clore la quête.]] },
[261630] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, Palais Ducal / bâtiment du Trône de Fer]], h = { [[L'un des prisonniers des cachots du Palais Ducal n'est pas celui qu'il prétend être.]], [[Le faux officier du Poing Enflammé est un doppelganger qui promet une récompense en échange de sa liberté.]], [[Libérez-le, attendez quelques heures puis descendez aux sous-sols du bâtiment du Trône de Fer.]] }, s = [[Dans les cachots sous le Palais Ducal, parlez au prisonnier vêtu en officier du Poing Enflammé. C'est un doppelganger qui vous demande de le libérer contre une récompense.
Acceptez et libérez-le. Il vous donne rendez-vous aux sous-sols du bâtiment du Trône de Fer dans trois heures.
Patientez, puis rendez-vous au bâtiment du Trône de Fer (rempli de réfugiés) et descendez au sous-sol. Le doppelganger tient parole et vous remet une réserve d'or, d'armes et de potions.
Ensuite, vous pouvez le laisser partir, ou l'attaquer et le tuer pour qu'aucun métamorphe ne reste en liberté en ville.]] },
[261636] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur]], h = { [[Cette quête n'a aucune entrée de journal dans le jeu ; elle n'apparaît peut-être jamais en partie normale.]], [[Si elle apparaît, cherchez dans les rues de la Porte de Baldur pendant le prologue de Siege of Dragonspear.]] }, s = [[Le jeu définit ce titre de quête mais n'écrit aucune entrée de journal, il s'agit donc très probablement de contenu inutilisé ou coupé.
Il n'y a rien à faire. Si elle apparaît un jour dans votre journal, elle appartient à la partie Porte de Baldur de Siege of Dragonspear : parlez aux habitants et aux réfugiés dans les rues de la ville avant de partir avec l'armée de la coalition.]] },
[261650] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, devant la prison du Poing Enflammé]], h = { [[Passez devant la prison du Poing Enflammé et soyez attentif aux disputes.]], [[Des mercenaires malmènent un groupe de jeunes nobles qui ont enfreint le couvre-feu.]], [[Intervenez pour prendre la défense des jeunes.]] }, s = [[Devant la prison du Poing Enflammé à la Porte de Baldur, vous croisez plusieurs mercenaires qui s'en prennent à de jeunes nobles.
Parlez-leur et prenez le parti des jeunes. Remettre les mercenaires à leur place suffit à terminer la quête ; soyez prêt au cas où ils deviendraient hostiles.
Si vous n'intervenez pas, rien d'autre ne se passe et la quête reste inachevée.]] },
[261653] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, autour du bâtiment du Trône de Fer]], h = { [[Un réfugié du bidonville autour de l'ancien bâtiment du Trône de Fer raconte une drôle d'histoire de chat perdu.]], [[Le vrai problème de Byzon est un officier du Poing Enflammé, Riggs, qui rackette les réfugiés.]], [[Reprenez l'or volé à Riggs, par la parole ou par la force, et donnez-le à Byzon.]] }, s = [[Dans le bidonville autour de l'ancien bâtiment du Trône de Fer, observez Byzon parlant de son « chat perdu » avec un mercenaire du Poing Enflammé. Parlez ensuite à Byzon : le chat n'est qu'un prétexte, et il avoue que l'officier Riggs extorque de l'argent aux réfugiés.
Trouvez Riggs non loin et confrontez-le. Avec le capitaine Corwin dans le groupe, elle peut l'obliger à rendre l'or ; sinon il peut refuser et se battre, et vous prenez l'or sur son corps.
Rendez l'or à Byzon, qui le partagera entre les victimes. Vous pouvez aussi le garder pour vous, la fin égoïste.]] },
[261663] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, près du Palais Ducal]], h = { [[Un propriétaire près du Palais Ducal prend tout ce que possèdent les réfugiés en échange d'un lit.]], [[Garachen ouvrira sa maison si vous lui apportez des provisions de la taverne du Chant de l'Elfe.]], [[Ou racontez au quartier général du Poing Enflammé ce que le réfugié Perren a dit des pensionnaires partis.]] }, s = [[Parlez à Garachen devant sa grande maison près du Palais Ducal, ainsi qu'au réfugié Perren non loin. Garachen dit ne pouvoir accueillir plus de monde que si quelqu'un fournit de la nourriture.
Voie bienveillante : allez à la taverne du Chant de l'Elfe, obtenez une semaine de provisions et rapportez-les à Garachen. Il continue d'aider les réfugiés.
Voie impitoyable : allez au quartier général du Poing Enflammé et servez-vous de la remarque de Perren pour accuser Garachen de vendre des réfugiés comme esclaves. Il est arrêté, et les réfugiés peuvent utiliser sa maison. Parlez ensuite aux réfugiés devant la maison pour clore la quête.]] },
[261669] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, au sud du Palais Ducal / Bazar Magique]], h = { [[Une marchande au sud du Palais Ducal cherche quelqu'un pour porter ses recettes du jour.]], [[La banquière de Teera travaille en face du Bazar Magique ; surveillez vos poches en chemin.]], [[Si la bourse est volée, payez vous-même la banquière ou avouez tout à Teera.]] }, s = [[Parlez à Teera à son étal au sud du Palais Ducal et acceptez de porter sa bourse à sa banquière, en face du Bazar Magique.
En chemin, une voleuse vous prend pour cible. Si vous la repérez, ou si vous la charmez pour qu'elle rende l'or, continuez. Si elle s'enfuit avec, vous pouvez donner votre propre or à la banquière pour couvrir la somme, ou retourner prévenir Teera.
Une fois la bourse déposée, retournez à l'étal de Teera devant le palais. Elle est contente si l'argent est arrivé, et contrariée si vous l'avez perdu.]] },
[261676] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, devant le Bazar Magique]], h = { [[Une officier du Poing Enflammé devant le Bazar Magique retient un groupe de réfugiés.]], [[L'officier Vida a besoin de renforts du quartier général du Poing Enflammé.]], [[Au quartier général, vous décidez si les réfugiés auront droit à l'indulgence ou à un châtiment sévère.]] }, s = [[Parlez à l'officier Vida devant le Bazar Magique : elle a arrêté des réfugiés agités et a besoin de renforts.
Allez au quartier général du Poing Enflammé et transmettez sa demande. Sur place, vous pouvez plaider l'indulgence pour les réfugiés, soutenir Vida et réclamer un châtiment sévère, ou simplement transmettre le message.
Retournez voir Vida pour lui annoncer l'arrivée des renforts et clore la quête.]] },
[261681] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, Trois Vieilles Chopes]], h = { [[Le crieur public devant les Trois Vieilles Chopes s'est desséché à force de crier.]], [[Demandez à Katheera, dans l'auberge, d'envoyer à boire à Robel.]], [[Convainquez-la de le faire tout de suite, puis prévenez Robel.]] }, s = [[Parlez à Robel, le crieur devant les Trois Vieilles Chopes ; il meurt de soif.
Entrez et parlez à Katheera. Elle est débordée mais accepte de lui envoyer une boisson plus tard ; avec les bons arguments, vous pouvez la convaincre de le faire immédiatement.
Ressortez et transmettez sa réponse à Robel pour terminer cette petite course.]] },
[261686] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, ruelle derrière les Trois Vieilles Chopes]], h = { [[Une femme derrière les Trois Vieilles Chopes collecte de l'argent pour un enterrement.]], [[Examinez le corps dans le chariot d'Aileen et demandez qui il était vraiment.]], [[Gardez son secret, faites-le-lui payer, ou dénoncez-la au quartier général du Poing Enflammé.]] }, s = [[Dans la ruelle derrière les Trois Vieilles Chopes, Aileen dit qu'il lui manque 15 pièces d'or pour enterrer son cousin. Vous pouvez simplement lui donner les 15 po et en rester là.
Si vous l'interrogez davantage, elle avoue que le mort dans le chariot est son mari, un ivrogne violent tué par accident pendant une dispute. Choisissez alors :
- promettre de garder son secret ;
- ne le garder qu'en échange de tout l'argent qu'elle a récolté ;
- aller au quartier général du Poing Enflammé et la dénoncer à un officier.]] },
[261693] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, Bazar Magique]], h = { [[Le Bazar Magique est débordé de clients ; son propriétaire aurait besoin d'aide.]], [[Toubazar Drin veut une caisse de bouteilles à potions vides rangée à l'étage.]], [[À l'étage vous trouverez plus que des bouteilles : occupez-vous des cambrioleurs, puis prévenez Drin.]] }, s = [[Entrez au Bazar Magique et parlez à Toubazar Drin au rez-de-chaussée. Il vous demande d'aller chercher une caisse de bouteilles à potions vides à l'étage.
Montez : des voleurs sont en train de piller le stock. Battez-les et prenez les bouteilles.
Redescendez et remettez les bouteilles à Drin. Parlez-lui du cambriolage et il vous récompense ; vous pouvez aussi vous taire, mais vous n'obtenez alors pas de récompense supplémentaire.]] },
[261696] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Porte de Baldur, bâtiment du Trône de Fer]], h = { [[Parmi les réfugiés du bâtiment du Trône de Fer, un homme nommé Lon est accusé de vol.]], [[L'amulette volée est un symbole sacré de Séluné, et Lon réagit mal quand on le presse.]], [[Démasquez Lon, tuez ce qu'il devient, puis parlez à Berta.]] }, s = [[Au bâtiment du Trône de Fer, les réfugiés vous demandent de juger Lon, accusé d'avoir volé une amulette.
Si vous jugez les preuves insuffisantes, Lon est libéré et la quête s'arrête là.
Si vous le pressez, il s'avère qu'il a pris le symbole sacré de Séluné de Berta ; démasqué, il se transforme en loup-garou. Tuez-le (des armes en argent ou magiques aident).
Parlez ensuite à Berta : reconnaissante, elle vous offre son symbole sacré en récompense.]] },
[261707] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Voie Côtière, auberge incendiée]], h = { [[Une petite-personne est assise dans les cendres de son auberge, le long de la Voie Côtière.]], [[Takos a perdu un bouclier, un miroir et une cape ; deux d'entre eux sont près des ruines.]], [[Les chasseurs de morts-vivants Isabella et Ikros ont le bouclier.]] }, s = [[Parlez à Takos dans les ruines de son auberge incendiée sur la Voie Côtière. Des soldats agités l'ont brûlée et trois objets de famille ont disparu : un bouclier, un miroir et une cape.
Fouillez les ruines de l'auberge pour trouver le miroir de poche. La cape est enfermée dans un coffre usé près des ruines.
Le bouclier poli est chez Isabella et Ikros, les chasseurs de morts-vivants installés dans la même zone ; vous l'obtenez en traitant avec eux (voir leur quête).
Rapportez les trois objets à Takos pour ses remerciements et une récompense. Si vous les gardez, il vous attaque.]] },
[261708] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Voie Côtière, camp des chasseurs et grotte du vampire]], h = { [[Deux chasseurs de morts-vivants campés près de la Voie Côtière veulent de l'aide contre un vampire, mais seulement la nuit.]], [[Vaincu, Tsolak fuit sous forme de brume ; son repaire est au-delà d'un chemin piégé à l'ouest.]], [[Plantez un pieu dans son corps dans la grotte, ou écoutez sa version et acceptez son offre.]] }, s = [[Parlez à Isabella et Ikros à leur camp. Ils vous demandent de revenir à la nuit tombée pour combattre le vampire Tsolak.
Revenez la nuit et combattez-le avec les chasseurs. Vaincu, il se change en brume et s'enfuit ; parlez à Isabella.
Suivez le chemin piégé vers l'ouest (faites désamorcer les pièges par un voleur) jusqu'à sa grotte. Plantez un pieu dans son corps pour le détruire, puis retournez au camp des chasseurs pour votre récompense, dont le bouclier poli que cherche Takos.
Autre choix : quand Tsolak donne sa version, rangez-vous de son côté contre les chasseurs. Un messager vous apporte ensuite sa récompense.
Vous pouvez aussi trouver et empaler le vampire avant de rencontrer les chasseurs, puis passer les voir pour une récompense.]] },
[261718] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Voie Côtière]], h = { [[De vieilles pierres dressées parsèment les terres autour de la Voie Côtière ; l'une vibre quand on lui chante.]], [[Il y a six menhirs dans la zone, et il faut chanter pour chacun jusqu'à ce qu'il émette un son agréable.]], [[Une fois les six activés, le fantôme d'un troubadour s'éveille : réunissez-le avec son amour, ou détruisez-les.]] }, s = [[Explorez la zone de la Voie Côtière et cliquez sur chaque ancien menhir. Choisissez de chanter jusqu'à ce qu'il émette un son agréable ; en cas d'échec, recommencez.
Trouvez et activez les six pierres ; le journal les compte pour vous.
Quand la sixième chante, le fantôme de Crommus, un troubadour mort depuis longtemps, apparaît. Parlez-lui : il veut retrouver sa bien-aimée Carline.
Fin paisible : libérez son esprit pour qu'il la rejoigne.
Sinon, le fantôme de Carline apparaît, rendue folle par ses années de solitude, et vous devez la détruire ; vous pouvez aussi détruire les deux esprits pour qu'ils reposent en paix.]] },
[261720] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Camp de réfugiés et clairière à l'ouest]], h = { [[Des réfugiés disparaissent du camp, et l'on soupçonne une elfe arrivée récemment, Teleria.]], [[Retrouvez Teleria dans la clairière à l'ouest : les réfugiés disparus sont devenus des statues de sa collection.]], [[Arrêtez-la et rendez vie aux statues pour Herod, ou aidez-la à achever son art et achetez son golem.]] }, s = [[Au camp de réfugiés, renseignez-vous sur les disparus et parlez à Teleria. Elle accepte de vous retrouver dans une clairière à l'ouest.
Dans la clairière, vous découvrez qu'elle change les gens en statues pour sa collection d'art.
Voie bienveillante : combattez-la pour l'arrêter. Rendez vie aux réfugiés pétrifiés si vous le pouvez (magie de pierre en chair), puis faites votre rapport à Herod au camp. Acceptez son paiement ou refusez-le.
Voie maléfique : attirez un soldat et un noble dans sa clairière pour qu'elle complète sa collection, puis revenez chercher une récompense.
Vous pouvez aussi lui acheter un golem ; il vous attend au camp du Poing Enflammé et combat pour vous au château de Vougedragon.]] },
[261737] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Fort-du-Pont / camp des croisés]], h = { [[Parler à Wynan Hess, le magicien de Fort-du-Pont, laisse le fort exposé à une attaque magique.]], [[Une pierre de sort tue lentement tout le monde dans le fort ; le parchemin qui l'a créée est au camp des croisés.]], [[Un Magicien Rouge du camp porte le parchemin ; rapportez-le vite à Wynan Hess, et préparez-vous à un spectre.]] }, s = [[À Fort-du-Pont, parler au magicien Wynan Hess le distrait, et une attaque des croisés frappe le fort : une pierre de sort enchantée commence à affaiblir tous ceux qui s'y trouvent, vous compris.
Entrez dans le camp des croisés et trouvez le Magicien Rouge de Thay, Vichand. Tuez-le et prenez son parchemin.
Retournez vite voir Wynan Hess avec. Neutraliser la pierre libère un spectre sombre, piège laissé par Vichand ; détruisez-le et Fort-du-Pont est sauvé.
Si vous ne parlez jamais à Hess, il règle seul le problème pendant l'attaque contre la croisade. Si vous tardez trop, la croisade prend Fort-du-Pont et la pierre devient son problème.]] },
[261740] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Fort-du-Pont, cour]], h = { [[Deux mages dans la cour de Fort-du-Pont vivent mal le siège.]], [[Thirrim prévient que la terreur d'Elandro pourrait attirer quelque chose de maléfique, surtout la nuit.]], [[Parlez à Elandro la nuit et calmez-le, ou préparez-vous à combattre ce que sa peur fait naître.]] }, s = [[Dans la cour de Fort-du-Pont, rencontrez les mages Elandro et Thirrim. Elandro est terrifié par la croisade ; Thirrim vous demande de lui parler la nuit, quand sa peur empire.
Revenez à la nuit tombée et parlez à Elandro. Des réponses rassurantes le calment et le danger s'éloigne.
Si vous échouez ou vous moquez de lui, la magie du fort et sa peur font naître une freyeur, un monstre né de la peur. Tuez-la avant qu'elle ne massacre ceux qui l'entourent.]] },
[261747] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Fort-du-Pont]], h = { [[Cette quête n'a aucune entrée de journal dans le jeu ; elle n'apparaît peut-être jamais en partie normale.]], [[La nourriture manque parmi les réfugiés et les soldats de Siege of Dragonspear ; écoutez ceux qui ont faim.]] }, s = [[Le jeu définit ce titre de quête mais n'écrit aucune entrée de journal, il s'agit donc très probablement de contenu inutilisé ou coupé.
Il n'y a rien à faire. Si elle apparaît, elle est liée au manque de nourriture pendant le siège : parlez aux affamés de Fort-du-Pont et voyez ce qu'ils demandent.]] },
[261764] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Fort-du-Pont, cour]], h = { [[Une conductrice d'attelage demi-elfe affamée, dans la cour de Fort-du-Pont, s'inquiète pour ses chevaux malades.]], [[Senderin veut que le clerc Frair Tajik les soigne, mais vous pouvez aussi essayer de les guérir vous-même.]], [[Une fois les chevaux guéris, reparlez à Senderin ; ses projets pour eux pourraient vous surprendre.]] }, s = [[Parlez à Senderin et à son fils dans la cour de Fort-du-Pont. Leurs chevaux sont tombés malades.
Trouvez Frair Tajik, le clerc du fort, et convainquez-le de soigner les chevaux, ou guérissez-les vous-même (un sort de guérison d'un prêtre du groupe devrait suffire).
Retournez voir Senderin. Elle et son fils avouent qu'ils comptent abattre les chevaux pour leur viande, car ils meurent de faim. Elle vous offre tout de même un beau heaume en récompense.]] },
[261770] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Grotte des araignées]], h = { [[Après avoir nettoyé la grotte des araignées, on entend quelque chose de gros bouger à l'intérieur.]], [[Retournez-y et suivez le bruit.]] }, s = [[Dans la grotte des araignées, vous entendez un grand bruit : quelque chose de gros vient d'y entrer.
Explorez la grotte pour en trouver l'origine. C'est un scarabée-rhinocéros géant ; battez-le et la quête est terminée.
Il frappe fort et il est bien protégé, alors reposez-vous et préparez vos protections avant d'aller le chercher.]] },
[261774] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Camp de la coalition (camp du Poing Enflammé)]], h = { [[Le lieutenant Otilda se méfie d'une bande de mercenaires demi-orques dans le camp de la coalition.]], [[Elle veut que vous provoquiez l'unité de Rend, mais Kava vous racontera leur histoire si vous lui apportez de la bière.]], [[On trouve de la bière au camp des croisés ; décidez ensuite si les demi-orques restent, partent ou meurent.]] }, s = [[Le lieutenant Otilda vous demande de provoquer les demi-orques irréguliers pour qu'ils soient bannis du camp.
Parlez-leur d'abord. Kava veut une chope de bière avant de parler : trouvez-en une au camp des croisés et rapportez-la (refuser ses plaisanteries la rend muette). Elle explique qu'elle et Farrl sont revenus chercher un butin caché, et que Rend, ancien croisé, veut vraiment tuer des croisés.
Choisissez ensuite :
- les laisser rester pour les connaissances de Rend ; Kava vous offre une petite récompense, et vous dites à Otilda qu'ils ne sont pas une menace ;
- les défier et les vaincre pour les chasser (Otilda vous récompense), ou perdre le combat ;
- les tuer tous.
Faites votre rapport à Otilda dans tous les cas.]] },
[261777] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Fort-du-Pont, temple et bois voisins]], h = { [[Junia, prêtresse de Lathandre à Fort-du-Pont, a besoin d'aide pour porter les morts jusqu'à l'autel de son temple.]], [[Le frère d'une soldate morte, Tharantis, veut son collier ; un guérisseur disparu dans les bois fait partie du mystère.]], [[Le collier et les corps ramènent à Junia : confrontez-la dans le temple.]] }, s = [[Junia vous demande de ramasser les corps des soldats tombés et de les porter à l'autel de la salle du temple. L'une d'eux, Kendra, a un frère dans le fort : trouvez Tharantis et informez-le. Il réclame la chaîne qu'elle portait toujours ; interrogez Junia à ce sujet.
La piste mène à Ymori, un guérisseur disparu dans les bois autour de Fort-du-Pont. Vous trouvez son corps mutilé sur un lieu de rituel, et des morts-vivants surgissent quand vous l'examinez. Le collier de Kendra se trouve sur le corps d'une victime.
Donnez le collier à Tharantis (ou vendez-le-lui ; il peut attaquer), puis confrontez Junia. Elle affirme qu'Ymori était un fidèle de Velsharoon et qu'elle a utilisé son corps pour renforcer les troupes : acceptez son explication, ou combattez-la avec ses serviteurs morts-vivants.
Enfin, dites à Tharantis ce qui est arrivé à sa sœur.]] },
[261778] = { g = [[sod]], k = [[companion]], o = 0, c = [[any]], w = [[Avec Khalid dans le groupe]], h = { [[Gardez Khalid dans le groupe : son anniversaire de mariage approche et il veut faire un cadeau à Jaheira.]], [[Il lui faut d'abord de la soie d'araignée géante.]], [[Ensuite il lui faut une aigue-marine ; trouvez un accord honnête avec lui.]] }, s = [[Avec Khalid dans le groupe, il vous apprend que leur anniversaire de mariage approche et vous demande de l'aide pour fabriquer un collier pour Jaheira.
Apportez-lui d'abord de la soie d'araignée géante : tuez une araignée géante, prenez la soie et donnez-la-lui.
Ensuite, il veut une aigue-marine. Trouvez-en ou achetez-en une et donnez-la à Khalid. Si vous exigez un paiement, il peut refuser de payer ; il peut aussi renoncer pour se concentrer sur la guerre.
Une fois les deux réunis, il termine le collier et l'offre à Jaheira, ce qui clôt la quête.]] },
[261853] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Camp de la coalition]], h = { [[La justicière Halasan a une unité de recrues inexpérimentées venues de Gué-de-la-Dague.]], [[Parlez à chacun des six soldats et entraînez-les un par un.]], [[De bons conseils à chaque recrue vous valent l'approbation d'Halasan et une meilleure récompense.]] }, s = [[Parlez à la justicière Halasan au camp de la coalition. Son unité de Gué-de-la-Dague n'est pas à la hauteur et elle vous demande de l'entraîner.
Parlez à chacun des six soldats : Morlis, Danine, Hester, Garrold, Taield et Clovista. Chaque conversation est un petit exercice ; choisissez des réponses sensées et encourageantes adaptées au problème du soldat.
Une fois les six entraînés, faites votre rapport à Halasan. Si vous avez bien fait, elle est satisfaite et vous récompense ; de mauvaises réponses la laissent peu convaincue.]] },
[261863] = { g = [[sod]], k = [[companion]], o = 0, c = [[Coalition camp]], w = [[Camp de la coalition]], h = { [[Safana a fait les poches de quelqu'un au camp et trouvé un carnet plein de secrets : un espion se cache dans la coalition.]], [[Remontez la piste des trois autres objets volés : un flacon étrange, une bougie dorée et une page de glyphes.]], [[Toutes les pistes mènent à Malden Col ; réunissez des preuves, confrontez-le, puis informez le maréchal Nederlok.]] }, s = [[Avec Safana dans le groupe, elle vous montre son butin, dont un carnet prouvant qu'un espion est au camp. Interrogez les gens sur les autres objets :
- le flacon : demandez au quartier-maître Belegarm, puis à Helvdar le nain à la barricade du nord. Il a perdu une potion aux cartes contre Malden Col.
- la bougie : Mizhena, prêtresse de Tempus, dit qu'on la lui a volée et soupçonne Col.
- les glyphes : l'intendante à la retraite Simonetta Doubletranchant, près des tentes des officiers, a prêté son livre à Col.
Certains témoins refusent d'aider si vous les froissez ; suivez une autre piste.
Confrontez Malden Col aux preuves : il avoue et il est emprisonné. Sans preuve, il nie, et vous pouvez quand même le tuer.
Faites votre rapport au maréchal Nederlok. Tuer un témoin innocent en le prenant pour le traître est possible, mais c'est une erreur.]] },
[261867] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Camp de la coalition, aire de triage]], h = { [[Un prêtre d'Ilmater malade, dans l'aire de triage, refuse tout soin.]], [[Une autre fidèle d'Ilmater, Dosia, pourrait faire changer Hyreth d'avis.]], [[Une fois que Hyreth accepte, trouvez un prêtre dans l'aire de triage pour le soigner.]] }, s = [[Dans l'aire de triage, parlez à Hyreth, un prêtre d'Ilmater malade qui refuse d'être soigné à cause de sa foi.
Trouvez Dosia, une autre fidèle d'Ilmater, et demandez-lui de lui parler. Si elle accepte, retournez voir Hyreth ; elle peut le convaincre. Elle peut aussi refuser, estimant qu'il a droit à ses croyances.
Quand Hyreth accepte l'aide, cherchez un prêtre qui travaille dans l'aire de triage pour qu'il le soigne, ce qui termine la quête.
Vous pouvez aussi le laisser à ses convictions.]] },
[261872] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Cour des croisés près de Vougedragon]], h = { [[Deux recrues de la croisade prient devant une icône brisée de Tempus dans un coin de la cour.]], [[Les deux fragments manquants sont dans les décombres au nord, ou l'officier du moral Deneld en a entendu parler.]], [[Un prêtre de Tempus doit bénir les fragments ; Mizhena, parmi vos alliés, peut le faire.]] }, s = [[Dans le coin nord-ouest de la cour, parlez aux recrues Kjarvan et Qing, qui prient devant une icône de Tempus à laquelle il manque deux morceaux.
Fouillez les décombres au nord pour trouver les fragments, ou demandez à l'officier du moral Deneld. Récupérez les deux.
Il n'y a aucun prêtre de Tempus chez les croisés : portez les fragments à Mizhena, prêtresse de Tempus de la coalition, et faites-les bénir.
Rapportez les fragments bénits aux recrues, puis placez-les vous-même sur l'icône de pierre.
Tempus répond par un défi. Refusez pour en rester là sans risque, ou acceptez et remportez un combat difficile pour gagner la faveur du dieu.]] },
[261880] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Près de la rivière souterraine / ses grottes]], h = { [[Deux druides sont pris dans un piège de racines vivantes ; libérez-les.]], [[Jamven et Chorster veulent que vous détruisiez le cercle du druide sombre Ferrusk dans les grottes de la rivière souterraine.]], [[Plantez leur graine enchantée dans les racines de l'arbre souterrain, ou rangez-vous du côté de Ferrusk.]] }, s = [[Libérez les druides Jamven et Chorster des racines animées. Ils vous expliquent que le druide sombre Ferrusk les a chassés des grottes de la rivière souterraine et vous confient une graine enchantée.
Descendez dans les grottes et trouvez le cercle de Ferrusk, bâti autour des racines d'un arbre souterrain. Plantez la graine dans les racines pour détruire le cercle, puis retournez voir les druides.
Autres choix :
- leur mentir en prétendant que le cercle est détruit ;
- accepter l'offre de Ferrusk, remonter, tuer Jamven et Chorster et lui rapporter leurs têtes.
Si les druides découvrent que vous n'avez pas détruit le cercle, ils vous attaquent.]] },
[261881] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Grottes de la rivière souterraine, tour-arbre myconide]], h = { [[Un myconide mourant dans les grottes vous demande d'enquêter sur un cadavre dans une tour-arbre.]], [[Le corps se trouve dans la partie nord de l'arbre.]], [[Attendez-vous à un myconide ancien ; vous ne le comprenez pas, et il combattra.]] }, s = [[Dans les grottes souterraines, parlez au myconide mourant près de la grande tour-arbre. Il vous demande d'enquêter sur un cadavre dans la partie nord de l'arbre.
Entrez dans l'arbre et allez vers le nord jusqu'au corps. Un myconide ancien vous affronte ; faute de pouvoir le comprendre, la discussion échoue et il attaque.
Tuez l'ancien pour terminer la quête. Son bulbe reproducteur sert au druide sombre Ferrusk dans la quête Maladie du limon.]] },
[261883] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Camp des ogres, près des grottes]], h = { [[Une bande d'ogres brigands a perdu son chef Slug, capturé par la croisade, et sa « veuve » Murs veut la place.]], [[Il faut vaincre deux prétendants ogres pour décider qui commande.]], [[Combattez-les pour vous-même, ou en champion de Murs pour faire d'elle la chef et une alliée.]] }, s = [[Parlez à Murs au camp des ogres brigands. La croisade a chassé la bande des grottes et enfermé leur chef Slug ; Murs veut prendre le pouvoir.
Acceptez le défi et combattez les deux prétendants ogres. Battez-vous en votre nom pour prendre la tête de la bande, ou en champion de Murs pour qu'elle devienne chef et vous aide.
Si vous massacrez les ogres, les survivants ne vous aideront pas par la suite.
Murs vous parle aussi des fantômes et de l'accès aux grottes sous Vougedragon (voir Les égarés et Accéder aux dédales).]] },
[261889] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Grottes sous Vougedragon]], h = { [[Murs parle de fantômes qui hantent une grotte au nord-ouest de l'ancien camp des ogres.]], [[Les esprits égarés veulent que leurs dépouilles soient portées au Plan de la Fugue ; un fantôme ettin veut son gourdin.]], [[Gardez les dépouilles jusqu'à trouver plus tard un portail vers le Plan de la Fugue.]] }, s = [[Dans les grottes au nord-ouest de l'ancien camp des ogres, rencontrez un groupe de fantômes piégés entre les mondes. Prenez leurs dépouilles avec vous.
Un fantôme ettin parmi eux reste à cause de son gourdin perdu. Trouvez le gourdin dans les grottes et rendez-le-lui : il trouve la paix et vous laisse une récompense, plutôt gênante.
Gardez les autres dépouilles. Quand vous atteignez un portail vers le Plan de la Fugue, apportez-les-y pour que les esprits reposent en paix et terminer la quête.]] },
[261890] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Grottes de la rivière souterraine]], h = { [[Un druide qui règne sur les grottes vous ordonne de vous éloigner de son domaine.]], [[C'est Ferrusk, le druide sombre ; les druides Jamven et Chorster veulent la fin de son cercle.]] }, s = [[Cette entrée note seulement votre rencontre avec le druide sombre Ferrusk, qui garde une grotte de la rivière souterraine et ne laisse passer que certains.
La suite se joue dans d'autres quêtes : détruire son cercle pour Jamven et Chorster (Les bons druides), ou traiter avec lui pour un remède (Maladie du limon).]] },
[261891] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Grottes sous le château de Vougedragon, porte des dédales]], h = { [[Murs connaît un accès aux grottes juste sous Vougedragon, loin au nord-ouest du camp des ogres.]], [[La capitaine Turin Brisecuivre garde la porte des dédales.]], [[Bluffez-la avec le blason de Caelar, éloignez-la avec une explosion dans le feu de camp, ou combattez.]] }, s = [[Suivez les indications de Murs : allez au nord-ouest de l'ancien camp des ogres, jusqu'aux grottes situées juste sous le château de Vougedragon.
Devant la porte des dédales se tient la capitaine Turin Brisecuivre avec ses croisés. Pour passer :
- montrer le blason de Caelar et bluffer pour passer sans violence ;
- des croisés voisins racontent qu'une potion de souffle ardent a fait exploser leur feu : jetez une potion de souffle ardent, ou un autre objet explosif, dans le feu pour éloigner Turin de son poste ;
- l'attaquer avec ses gardes.
Une fois à l'intérieur, évitez les combats inutiles, sinon tout le château risque de vous tomber dessus.]] },
[261892] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Grottes de la rivière souterraine / camp des ogres]], h = { [[Le chef ogre Slug et deux compagnons sont enfermés dans une cage de la croisade dans les grottes.]], [[Libérez-les ; Slug pourra vous révéler une cachette ogre près d'un bassin dans les tunnels du nord.]], [[Après avoir vidé la cachette, rendez visite à Slug au camp des ogres en surface.]] }, s = [[Dans les grottes de la rivière souterraine, trouvez Slug et deux autres ogres enfermés par la croisade. Trouvez un moyen d'ouvrir la cage et libérez-les.
S'il vous fait confiance, Slug vous parle d'un trou caché dans la paroi d'une grotte, près d'un bassin dans la partie nord des tunnels. Allez-y et prenez le contenu. S'il se méfie des non-ogres, il part sans vous aider.
Retournez au camp des ogres en surface. Si Murs est en vie, le couple réuni vous remercie. Si Murs est morte, Slug devient violent et vous devez le combattre.]] },
[261896] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Inconnu]], h = { [[Cette quête n'a aucune entrée de journal dans le jeu ; elle n'apparaît peut-être jamais en partie normale.]], [[Le titre évoque quelqu'un qui ne veut pas être dérangé à sa porte.]] }, s = [[Le jeu définit ce titre de quête mais n'écrit aucune entrée de journal ; il s'agit très probablement de contenu inutilisé ou coupé de Siege of Dragonspear.
Il n'y a rien à faire, et elle ne peut pas bloquer votre progression.]] },
[261898] = { g = [[sod]], k = [[companion]], o = 0, c = [[Dragonspear]], w = [[Près de l'entrée de la rivière souterraine]], h = { [[Une sorcière de Rashéménie et son garde du corps berserker veulent rencontrer Minsc et Dynahéir.]], [[Revenez avec les deux, vivants, dans le groupe ; Julann songe à rejoindre Caelar.]], [[Trouvez dans les grottes une preuve de la corruption d'Hephernaan et montrez-la à Julann.]] }, s = [[Près de l'entrée de la rivière souterraine, rencontrez la wychlaran Julann et son berserker Rigah. Ils veulent parler à Minsc et Dynahéir : revenez avec les deux, vivants, dans le groupe.
Vous apprenez que Julann penche pour rejoindre la croisade. Vous devez la convaincre du contraire.
Dans les grottes, cherchez des preuves de la corruption d'Hephernaan et apportez-les à Julann. Avec l'aide de Rigah, elle peut être convaincue ; Rigah vous offre alors son épée.
Si elle refuse la vérité, Rigah peut vous aider à la tuer, ou tous deux partent vers le château de Vougedragon, ou vous les tuez tous les deux. Vous pouvez aussi les tuer dès le départ.]] },
[261910] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Rivière souterraine, entrepôt des croisés]], h = { [[Ladle, un gnome à l'entrepôt des croisés, a un travail pour vous.]], [[Portez ses sacs de grains jusqu'aux caisses vides au bord de la rivière.]], [[Faites ensuite ce qu'il demande, même si cela semble inutile.]] }, s = [[Parlez à Ladle à l'entrepôt des croisés au bord de la rivière souterraine. Il vous demande de déplacer les sacs de grains près de lui dans les caisses vides sur la berge.
Prenez les sacs et mettez-les dans les caisses, puis revenez le voir. Il veut maintenant que le grain retourne à sa place.
Faites-le et reparlez-lui. Il avoue que c'était juste une corvée pour vous occuper, du genre qui empêche les croisés oisifs de se battre entre eux. Pas de vraie récompense, juste un sourire.]] },
[261914] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Rivière souterraine]], h = { [[Un magicien de la croisade, au bord de la rivière souterraine, soumet des élémentaires d'eau pour la bataille.]], [[Vous pouvez arrêter Strunk en le tuant ou en tuant les élémentaires.]], [[Aider les élémentaires contre lui plaît à la néréide de la rivière.]] }, s = [[Au bord de la rivière souterraine, trouvez Strunk, un magicien de la croisade qui soumet des élémentaires d'eau pour la bataille du château de Vougedragon.
Meilleure issue : quand Strunk perd le contrôle des élémentaires, rangez-vous de leur côté et aidez-les à le tuer. Une néréide qui vit dans la rivière vous récompense.
Si vous tuez plutôt les élémentaires, Strunk et la néréide vous attaquent tous les deux.
Tuer simplement Strunk libère aussi les élémentaires et met fin à son plan.]] },
[261915] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Grottes sous Vougedragon]], h = { [[Des croisés blessés dans les grottes sont empoisonnés par un champignon, et quelqu'un qui connaît ces lieux pourrait aider.]], [[Le druide sombre Ferrusk a un remède, contre 2 000 pièces d'or ou le bulbe reproducteur d'un myconide ancien.]], [[Apportez le remède au chef des croisés avant qu'il ne soit trop tard.]] }, s = [[Dans les grottes sous Vougedragon, trouvez un groupe de croisés empoisonnés par un champignon souterrain. Ils se transforment peu à peu en limons.
Allez voir le druide sombre Ferrusk. Il échange un remède contre 2 000 pièces d'or, ou contre le bulbe reproducteur d'un myconide ancien (voir La Tour Myconide).
Rapportez vite le remède et donnez-le au chef des croisés. Si vous tardez trop, ils deviennent tous des limons.
Si vous exigez un paiement qu'ils refusent et gardez le remède, la maladie les consume aussi.]] },
[261917] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Grottes sous Vougedragon]], h = { [[Une bande de drows menée par Shapur affronte la croisade dans les tunnels.]], [[Deux jeunes amoureux drows se sont enfuis ; trouvez-les quelque part dans les grottes.]], [[Renvoyez-les chez eux, simulez leur mort avec leurs insignes de maison, ou livrez-les aux croisés.]] }, s = [[Dans les tunnels, vous croisez Shapur et ses drows aux prises avec des croisés. Parlez-lui : deux adolescents drows se sont enfuis et elle les recherche.
Explorez les grottes pour trouver le couple, des amoureux maudits. Choisissez ensuite :
- les convaincre de rentrer ; ils vous retrouvent là où les drows affrontent les croisés, et Shapur vous remercie et se retire ;
- accepter de simuler leur mort : apportez leurs insignes de maison à Shapur, et les siens repartent vers l'Ombre-Terre (elle peut aussi vous combattre) ;
- les mener aux croisés, qui les escortent vers la surface ou les gardent prisonniers ;
- les tuer, ou éliminer d'abord la bande de Shapur et annoncer aux jeunes qu'ils sont libres.
Si un ankheg tue le couple, annoncez leur mort à Shapur.]] },
[261935] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Château de Vougedragon, sous-sol]], h = { [[Quelqu'un relève les morts dans les profondeurs du château de Vougedragon.]], [[Une assemblée de magiciens sombres pratique ses rituels dans les niveaux inférieurs du château.]], [[Le fantôme d'un dragon hante ces mêmes profondeurs et peut vous aider contre la cabale.]] }, s = [[Explorez les niveaux situés sous le château de Vougedragon. Une cabale de magiciens sombres y réanime des cadavres pour grossir les rangs de la croisade.
Préparez-vous à un combat difficile contre plusieurs lanceurs de sorts soutenus par des morts-vivants : protection contre le mal, renvoi des morts-vivants et interruption des sorts sont utiles.
Si vous avez rencontré le fantôme du dragon Halatathlaer dans ces lieux, il peut combattre à vos côtés.
Tuez tous les magiciens pour terminer la quête. Cela affaiblit la croisade.]] },
[261940] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Château de Vougedragon]], h = { [[Le dragon fantôme Halatathlaer a laissé un message pour son vieil ami Daeros.]], [[Daeros Vougedragon est mort depuis longtemps, mais son esprit hante peut-être encore le château qu'il dirigeait.]], [[Quand vous croisez le fantôme de Daeros, dites-lui qu'Halatathlaer l'attend dans le Plan de la Fugue.]] }, s = [[La quête commence quand le fantôme du dragon Halatathlaer s'en va (par la fontaine de Népenthès, ou en quittant simplement ce monde) et vous demande de dire à son ami Daeros où le trouver.
Continuez d'explorer le château de Vougedragon et les lieux qui y sont liés. Le fantôme de Daeros Vougedragon, l'ancien seigneur du château mort depuis longtemps, s'y trouve.
Parlez-lui et transmettez le message d'Halatathlaer : il l'attend dans le Plan de la Fugue.
Son esprit est libéré et part rejoindre le dragon, ce qui termine la quête.]] },
[261945] = { g = [[sod]], k = [[side]], o = 0, c = [[Underground River]], w = [[Rivière souterraine, grottes sous Vougedragon]], h = { [[Deux sahuagins bloquent les grottes de la rivière souterraine sous Vougedragon.]], [[Vous n'êtes pas obligé de les combattre : parlez-leur d'abord.]], [[Une bonne histoire, ou assez d'intimidation, vous permet de passer sans verser de sang.]] }, s = [[Dans les grottes de la rivière souterraine sous Vougedragon, deux sahuagins, Glouglou et Curdent, empêchent les croisés de passer.
Parlez-leur. Trois issues :
- Racontez-leur une histoire qui leur plaît : ils vous laissent passer.
- Effrayez-les suffisamment et ils s'enfuient.
- Attaquez : ils ne sont que deux et le combat est bref.
Chacune de ces solutions termine la quête et ouvre la suite du chemin dans les grottes.]] },
[261963] = { g = [[sod]], k = [[side]], o = 0, c = [[Epilogue]], w = [[Porte de Baldur, égouts sous le quartier général du Poing Enflammé]], h = { [[Pendant votre évasion par les égouts sous le quartier général du Poing Enflammé, fouillez les corps que vous croisez.]], [[Un évadé mort porte une note et une clef menant à une cachette.]], [[La cachette se trouve près d'une mare souterraine alimentée par les égouts de la ville.]] }, s = [[À la fin de la campagne, pendant votre évasion par les égouts sous le quartier général du Poing Enflammé à la Porte de Baldur, fouillez le cadavre d'un évadé malchanceux.
Prenez sa note et sa clef, puis lisez la note.
Explorez les tunnels jusqu'à une mare souterraine alimentée par les égouts. La cachette s'y trouve : ouvrez-la avec la clef et prenez le butin.
Ces objets sont bienvenus, car vous commencez l'évasion mal équipé.]] },
[262483] = { g = [[sod]], k = [[main]], o = 22, c = [[Bridgefort]], w = [[Fort-du-Pont]], h = { [[Une fois dans Fort-du-Pont, découvrez la vraie force des défenseurs.]], [[Deux personnes comptent : Wynan Hess, qui parle pour les défenseurs, et le forgeron Jegg Sculptecolline.]], [[Après leur avoir parlé à tous les deux, retournez faire votre rapport à Khalid.]] }, s = [[Dans Fort-du-Pont assiégé, parlez à Wynan Hess : les défenseurs sont peu nombreux, surtout des marchands et des voyageurs, et doivent se coordonner avec le Poing Enflammé pour attaquer la croisade.
Parlez au forgeron, Jegg Sculptecolline (l'ordre est libre). Les provisions du fort renforceraient la croisade à Vougedragon ; si vous négociez une capitulation, elle veillera à en détruire la plus grande partie.
Une fois les deux entretiens faits, retournez voir Khalid et rapportez-lui ce que vous avez appris. Cela compte pour la façon dont vous mettez fin au siège de Fort-du-Pont.]] },
[264446] = { g = [[sod]], k = [[main]], o = 23, c = [[Bridgefort]], w = [[Fort-du-Pont, camp des croisés et temple en ruine à l'est]], h = { [[Le garde à l'entrée du camp des croisés n'accepte aucune recrue qui n'a pas fait ses preuves.]], [[Une patrouille de croisés disparue, dont Keherrem, le neveu du recruteur, a été vue près d'un temple en ruine à l'est.]], [[Libérez la patrouille en cage avec la clef que porte quelqu'un à cet étage, ou tirez le levier et rapportez l'insigne de leur chef.]] }, s = [[Parlez au garde à l'entrée du camp des croisés près de Fort-du-Pont. Pour vous y infiltrer, vous devez retrouver une patrouille disparue, sans doute dans un temple en ruine à l'est.
Entrez dans le temple, tenu par des Cyriquistes, et progressez jusqu'aux croisés en cage.
- Clémence : prenez la clef de la cage sur un cultiste de cet étage, libérez-les et retournez au camp vous en attribuer le mérite.
- Cruauté : tirez le levier du mur ; des piques les tuent. Prenez l'insigne de leur chef et dites au camp que les Cyriquistes en sont responsables.
Dans les deux cas, vous accédez au camp des croisés, d'où vous pourrez agir pour lever le siège. Si vous avez déjà un autre moyen d'entrer, le sort des prisonniers ne change rien.]] },
[264473] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way Crossing]], w = [[Pont de la Voie Côtière, site de fouilles nain]], h = { [[Près du pont de la Voie Côtière, un nain combat des zombies ; aidez-le et écoutez son histoire.]], [[Dans le site de fouilles caché, aidez les clercs de Dumathoin, cherchez Gurn Âtrefroid et épargnez le géant Semahl.]], [[Âtrefroid est devenu une liche : détruisez son phylactère dans une salle secrète avant de l'affronter, ou acceptez son marché.]] }, s = [[Près du pont de la Voie Côtière, sauvez Daran Hautmarteau des zombies. Il vous demande de voir ce que deviennent les clercs nains qui l'ont embauché, dans leur site de fouilles secret.
Sur le site, aidez les clercs contre les morts-vivants. Leur meneur, Auchlin Veineprofonde, vous demande de retrouver son ami Gurn Âtrefroid. Dans un coin reculé, sauvez le géant Semahl et envoyez-le rejoindre les survivants : son témoignage appuiera votre rapport.
Plus bas, dans une forteresse enfouie, vous voyez Âtrefroid devenir une liche. Ne l'affrontez pas tout de suite : faites votre rapport à Veineprofonde, qui vous remet l'arme Secret dévoilé.
Trouvez le phylactère dans une salle secrète près de la salle de la transformation, détruisez-le, puis tuez la liche. Les nains pourront vous rejoindre au château de Vougedragon.
Option maléfique : la liche promet une grande récompense contre les cinq amulettes du Gardien que portent les clercs. Apportez-les toutes les cinq, jamais moins.]] },
[264506] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue / Bridgefort]], w = [[Tombeau de la famille de Korlasz, puis temple de Cyric près de Fort-du-Pont]], h = { [[Sarevok a laissé des notes de recherche dans le tombeau de la famille de Korlasz ; lisez-les attentivement.]], [[Elles mènent à une chambre secrète dans un ancien temple de Bhaal, que vous visiterez plus tard.]], [[Le temple de Bhaal en ruine est devenu un temple de Cyric : utilisez les marques dans l'ordre 3, 1, 4.]] }, s = [[Dans le tombeau de la famille de Korlasz (prologue), trouvez les anciennes notes de Sarevok sur la prophétie de Bhaal. Elles évoquent une chambre secrète dans un ancien temple de Bhaal et les marques du Seigneur des Ombres : 3, 1 et 4.
Plus tard, près de Fort-du-Pont, vous explorez le temple en ruine de Bhaal occupé par des Cyriquistes (le même donjon que celui de la patrouille disparue).
Cherchez les emplacements marqués et activez-les dans l'ordre 3, 1, 4 indiqué par Sarevok. La chambre secrète s'ouvre ; prenez son contenu.]] },
[264981] = { g = [[sod]], k = [[main]], o = 24, c = [[Bridgefort]], w = [[Fort-du-Pont]], h = { [[Fort-du-Pont est scellé pendant que la croisade l'assiège ; il vous faut un moyen spécial d'entrer.]], [[Une pierre-sésame permet de pénétrer dans le fort.]], [[Une fois la pierre-sésame en main, utilisez-la au fort pour entrer et rencontrer les défenseurs.]] }, s = [[Pendant le siège de Fort-du-Pont, impossible d'entrer dans le fort normalement.
Procurez-vous la pierre-sésame de Fort-du-Pont, puis utilisez-la pour pénétrer dans le fort.
Une fois à l'intérieur, la quête se termine et vous pouvez parler aux défenseurs : la suite est la quête Les défenseurs désespérés (Wynan Hess et le forgeron Jegg Sculptecolline).]] },
[264982] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Temple en ruine de Bhaal (temple de Cyric), près de Fort-du-Pont]], h = { [[Une prisonnière aveugle du temple en ruine de Bhaal affirme en avoir été la grande prêtresse.]], [[Quelque chose cloche dans le temple ; la grande prêtresse de Cyric, Akanna, s'est enfermée dans la salle du rituel.]], [[L'esprit d'Akanna ne lui appartient plus : le vrai maître attend dans le reliquaire.]] }, s = [[Dans le temple en ruine de Bhaal près de Fort-du-Pont, occupé par des Cyriquistes, rencontrez Madele, ancienne grande prêtresse de Bhaal enfermée dans une cellule. Lisez ses notes : une voix lui promet la chute d'Akanna. Vous pouvez la libérer si vous trouvez comment ouvrir sa cellule, ou l'y laisser.
Des créatures ont attaqué le temple : avancez prudemment et trouvez un moyen d'entrer dans la salle du rituel où s'est enfermée la grande prêtresse Akanna.
Akanna avoue qu'une voix l'a forcée à laisser entrer des monstres. Continuez jusqu'au reliquaire et vainquez le flagelleur mental à l'origine de tout, avec ses serviteurs à tentacules. Attendez-vous à des attaques mentales : protégez-vous contre le charme et l'étourdissement.]] },
[266700] = { g = [[sod]], k = [[main]], o = 18, c = [[Prologue]], w = [[Porte de Baldur, palais ducal]], h = { [[Des assassins ont frappé le palais ducal ; repoussez-les.]], [[Les tueurs ont été envoyés par Caelar Argent, dont la croisade menace les terres au nord du Fleuve Sinueux.]], [[Parlez aux ducs et préparez-vous à partir vers le nord avec la coalition.]] }, s = [[Après avoir nettoyé le tombeau de la famille de Korlasz, vous vous reposez au palais ducal de la Porte de Baldur. Pendant la nuit, des assassins attaquent.
Traversez le palais avec vos compagnons et tuez les assassins. Le combat est rude à ce niveau : gardez des potions de soins à portée.
Une fois le palais sécurisé, les ducs révèlent que les assassins venaient de la croisade de Caelar Argent.
Parlez aux ducs et aux chefs du Poing Enflammé, préparez votre groupe et vos provisions, puis quittez la ville avec la coalition pour marcher vers le nord.]] },
[266743] = { g = [[sod]], k = [[main]], o = 26, c = [[Dragonspear Castle]], w = [[Château de Vougedragon]], h = { [[Explorez le château de Vougedragon aussi loin que possible, jusqu'au sous-sol.]], [[Prendre la route de la rivière souterraine et le sous-sol donne un avantage à la coalition.]], [[À votre retour, les commandants ont disparu : Caelar a demandé à négocier.]] }, s = [[Entrez dans le château de Vougedragon avec la coalition, par la cour ou par les grottes de la rivière souterraine.
Explorez le château et son sous-sol en éliminant les croisés et les horreurs d'en bas. Quêtes annexes sur place : les pilleurs (Prises de guerre), les magiciens sombres (La cabale) et les prisonniers de la cour.
À votre retour, les commandants sont partis : Caelar Argent a demandé à négocier. Préparez-vous bien avant d'y aller, car l'histoire franchit bientôt un point de non-retour.]] },
[266957] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Tombeau de la famille de Korlasz]], h = { [[Un esprit tourmenté hante un sarcophage pillé et cherche son bâton volé.]], [[Les voleurs ont abandonné le bâton dans le tombeau, brisé en deux : le manche et le pommeau sont dans des salles différentes.]], [[Replacez les deux morceaux dans le sarcophage de l'esprit, à cet étage.]] }, s = [[Dans le tombeau, des voleurs ont dérobé un simple bâton non magique dans un sarcophage, et l'esprit de son propriétaire le hante désormais.
Fouillez les salles de cet étage : l'une contient le bâton brisé, une autre son pommeau. Vous pouvez les assembler pour reconstituer le bâton.
Retournez au sarcophage hanté et placez-y le bâton. L'esprit repose en paix et la quête se termine.]] },
[267432] = { g = [[sod]], k = [[main]], o = 17, c = [[Prologue - coalition camp]], w = [[Porte de Baldur, puis camp de la coalition près de Vougedragon]], h = { [[En quittant la Porte de Baldur, une foule se rassemble : vos paroles décident de l'image qu'elle a de vous.]], [[Au camp de la coalition devant le château de Vougedragon, la croisade va attaquer : tenez le camp.]], [[Une fois l'attaque repoussée, allez voir le Maréchal Nederlok à l'entrée du camp.]] }, s = [[En quittant la Porte de Baldur, une foule vous interpelle sur l'ascendance que vous partagez avec Sarevok. Un discours rassurant la rallie ; une attitude plus dure la laisse méfiante. Aucune des deux ne bloque l'histoire.
Plus tard, au camp de siège de la coalition devant le château de Vougedragon, la croisade lance un assaut. Défendez le camp avec les troupes de la coalition jusqu'à repousser les assaillants.
Allez ensuite voir le Maréchal Nederlok à l'entrée du camp pour poursuivre vers la vraie bataille du château de Vougedragon.]] },
[269214] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Château de Vougedragon, intérieur]], h = { [[Des soldats de la coalition se remplissent les poches avec des trésors trouvés dans le château.]], [[Ordonnez-leur d'arrêter, ou signalez-les à un officier du Poing Enflammé au même étage.]], [[Vous pouvez aussi vous taire en échange d'une part du butin.]] }, s = [[Dans le château de Vougedragon, vous surprenez des soldats de la coalition en train de piller des trésors. Parlez-leur :
- Ordonnez-leur de laisser les objets de valeur : ils peuvent obéir à contrecœur.
- S'ils refusent, trouvez un officier du Poing Enflammé à cet étage et dénoncez-les ; il s'en charge.
- Ou proposez de garder le secret contre une part : ils vous donnent un anneau de valeur.
Chacune de ces issues termine la quête.]] },
[269686] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Camp de la coalition, devant le château de Vougedragon]], h = { [[Le Maréchal Nederlok ne trouve Skie Écudargent nulle part dans le camp de la coalition.]], [[Lassée de la vie de camp, Skie est partie seule repérer l'ennemi, vers le château de Vougedragon.]], [[Sauvez-la des mercenaires de la croisade, puis dites à Nederlok qu'elle est en sécurité.]] }, s = [[Dans le camp de la coalition, le Maréchal Nederlok vous apprend que Skie Écudargent a disparu.
Elle a été vue pour la dernière fois en direction du château de Vougedragon. Fouillez les environs entre le camp et le château.
Vous la trouvez attaquée par des mercenaires de la croisade : tuez-les vite avant qu'elle ne tombe.
Parlez à Skie : elle partait en reconnaissance par ennui et promet de rentrer au camp.
Retournez faire votre rapport à Nederlok. Il la met à remplir des sacs de sable, et la quête se termine.]] },
[271143] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Camp de la coalition, devant le château de Vougedragon]], h = { [[Deux miliciens de Gué-de-la-Dague se plaignent de leur officier gnome dans le camp de la coalition.]], [[Trouvez Pritchard Gardnersonson et réglez le problème, d'une façon ou d'une autre.]], [[Dire à Pritchard ce que ses hommes pensent vraiment de lui fait intervenir le général Main-de-pierre.]] }, s = [[Dans le camp de la coalition, deux miliciens de Gué-de-la-Dague vous disent que leur officier, le gnome Pritchard Gardnersonson, pose problème.
Cherchez Pritchard et parlez-lui. Lui dire ce que ses soldats pensent vraiment de lui pousse le général Main-de-pierre, de la milice de Gué-de-la-Dague, à s'en occuper en personne. La chance peut aussi régler l'affaire à votre place.
Une fois Pritchard hors d'état de nuire, retournez voir les deux miliciens. Ils vous remercient avec plusieurs potions.]] },
[271314] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Camp de la coalition et bois voisins]], h = { [[Mizhena, clerc de Tempus dans le camp de la coalition, a perdu un souvenir en combattant des croisés.]], [[Cherchez des traces de combat dans les bois près du camp.]], [[Rapportez l'amulette à Mizhena ; elle vous confiera ensuite une demande plus importante.]] }, s = [[Parlez à Mizhena, clerc de Tempus dans le camp de la coalition. Elle a perdu une amulette à valeur sentimentale lors d'un combat contre des croisés.
Fouillez les bois près du camp pour trouver le lieu du combat et ramassez l'amulette (vous l'avez peut-être déjà trouvée).
Rendez-la à Mizhena. Reconnaissante et désormais en confiance, elle vous demande de l'aide pour retrouver son père, ce qui lance la quête Le père de Mizhena.]] },
[271319] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Camp de la coalition, puis cour du château de Vougedragon]], h = { [[Le père de Mizhena a été capturé quand sa troupe a attaqué le château.]], [[La croisade garde ses prisonniers dans la cour du château de Vougedragon.]], [[Libérez-le avec les autres prisonniers, puis rapportez la nouvelle à Mizhena.]] }, s = [[Après lui avoir rendu son amulette, Mizhena vous demande de chercher son père parmi les prisonniers de la croisade.
Prenez d'assaut la cour du château de Vougedragon et trouvez les captifs. Libérez son père avec les autres prisonniers.
Retournez annoncer la bonne nouvelle à Mizhena : soulagée, elle part le rejoindre.
